import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { ProductionEntry } from '../../types';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';
import { 
  ClipboardList, CheckCircle, RefreshCw, CalendarOff, List, Calendar, 
  ArrowUpRight, TrendingUp, Filter, Download, Users as UsersIcon, X
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { formatDisplayDate, getTodayISO } from '../../utils/dateUtils';

export const Dashboard: React.FC = () => {
  const { category, refreshKey, triggerRefresh } = useDashboard();
  const { hasPermission } = useAuth();

  const [viewMode, setViewMode] = useState<'daily' | 'monthly'>('daily');
  const [selectedMonth, setSelectedMonth] = useState<string>(() => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
  });

  // Date Range Filter State
  const [dateRange, setDateRange] = useState({ start: '', end: '' });

  // Fetch data
  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays()
    };
  }, [refreshKey]);

  // Comprehensive Data Aggregation
  const dashboardData = useMemo(() => {
    const relevant = productionData.filter(d => d.category === category);

    // Monthly & Process breakdown for ALL time (for the summary table)
    const monthlyProcessStats: Record<string, Record<string, { plan: number, actual: number }>> = {};

    // Aggregates for the SELECTED month (for the top cards and charts)
    let selectedMonthPlan = 0;
    let selectedMonthActual = 0;
    const selectedMonthProcessMap = new Map<string, {process: string, Plan: number, Actual: number}>();

    relevant.forEach(d => {
      const monthKey = d.date.substring(0, 7); // YYYY-MM

      // Global monthly/process mapping
      if (!monthlyProcessStats[monthKey]) monthlyProcessStats[monthKey] = {};
      if (!monthlyProcessStats[monthKey][d.process]) monthlyProcessStats[monthKey][d.process] = { plan: 0, actual: 0 };
      monthlyProcessStats[monthKey][d.process].plan += d.planQuantity;
      monthlyProcessStats[monthKey][d.process].actual += d.actualQuantity;

      // Stats for the specific selected month filter
      if (monthKey === selectedMonth) {
        selectedMonthPlan += d.planQuantity;
        selectedMonthActual += d.actualQuantity;

        if (!selectedMonthProcessMap.has(d.process)) {
          selectedMonthProcessMap.set(d.process, { process: d.process, Plan: 0, Actual: 0 });
        }
        const p = selectedMonthProcessMap.get(d.process)!;
        p.Plan += d.planQuantity;
        p.Actual += d.actualQuantity;
      }
    });

    // Sort monthly stats for the table
    const sortedSummary = Object.entries(monthlyProcessStats)
      .flatMap(([month, processes]) => 
        Object.entries(processes).map(([process, stats]) => ({
          month,
          process,
          plan: stats.plan,
          actual: stats.actual,
          efficiency: stats.plan > 0 ? (stats.actual / stats.plan) * 100 : 0
        }))
      )
      .sort((a, b) => b.month.localeCompare(a.month) || a.process.localeCompare(b.process));

    return {
      filteredData: relevant.sort((a,b) => b.date.localeCompare(a.date)),
      selectedMonthStats: { 
        plan: selectedMonthPlan, 
        actual: selectedMonthActual,
        efficiency: selectedMonthPlan > 0 ? (selectedMonthActual / selectedMonthPlan) * 100 : 0
      },
      chartData: Array.from(selectedMonthProcessMap.values()),
      monthlySummary: sortedSummary
    };
  }, [productionData, category, selectedMonth]);

  // Grouped Daily View Rows
  const dailyGroups = useMemo(() => {
    const baseData = dashboardData.filteredData;
    const baseOffDays = offDays;

    // Apply filters
    const filteredEntries = baseData.filter(d => {
        const inMonth = d.date.startsWith(selectedMonth);
        const matchStart = !dateRange.start || d.date >= dateRange.start;
        const matchEnd = !dateRange.end || d.date <= dateRange.end;
        return inMonth && matchStart && matchEnd;
    });

    const filteredOffDays = baseOffDays.filter(od => {
        const inMonth = od.date.startsWith(selectedMonth);
        const matchStart = !dateRange.start || od.date >= dateRange.start;
        const matchEnd = !dateRange.end || od.date <= dateRange.end;
        return inMonth && matchStart && matchEnd;
    });

    // Combine all dates involved
    const dates = new Set<string>();
    filteredEntries.forEach(d => dates.add(d.date));
    filteredOffDays.forEach(od => dates.add(od.date));

    const sortedDates = Array.from(dates).sort((a, b) => b.localeCompare(a));

    return sortedDates.map(date => ({
        date,
        offDay: filteredOffDays.find(od => od.date === date),
        entries: filteredEntries.filter(d => d.date === date)
    }));
  }, [dashboardData.filteredData, offDays, selectedMonth, dateRange]);

  const handleDelete = (id: string) => {
      if(!window.confirm("Delete this record?")) return;
      const newData = productionData.filter(p => p.id !== id);
      StorageService.saveProductionData(newData);
      triggerRefresh();
  };

  const getMonthName = (monthKey: string) => {
    const [y, m] = monthKey.split('-');
    return new Date(parseInt(y), parseInt(m) - 1).toLocaleString('default', { month: 'long', year: 'numeric' });
  };

  const downloadCSV = () => {
    let headers: string[] = [];
    let rows: (string | number)[][] = [];
    let filename = '';

    if (viewMode === 'daily') {
        headers = ["Date", "Category", "Process", "Product", "Plan", "Actual", "Efficiency %", "Batch No", "Manpower"];
        rows = dailyGroups.flatMap(group => 
            group.entries.map(d => [
                d.date, 
                d.category, 
                d.process, 
                `"${d.productName}"`, 
                d.planQuantity, 
                d.actualQuantity, 
                (d.planQuantity > 0 ? (d.actualQuantity / d.planQuantity) * 100 : 0).toFixed(1), 
                d.batchNo || '', 
                d.manpower || ''
            ])
        );
        filename = `${category}_daily_report_${getTodayISO()}.csv`;
    } else {
        headers = ["Month", "Process", "Total Plan", "Total Actual", "Overall Efficiency %"];
        rows = dashboardData.monthlySummary.map(m => [
            m.month,
            m.process,
            m.plan,
            m.actual,
            m.efficiency.toFixed(2)
        ]);
        filename = `${category}_monthly_summary_${getTodayISO()}.csv`;
    }

    const csvContent = "data:text/csv;charset=utf-8," 
      + [headers.join(','), ...rows.map(e => e.join(','))].join('\n');

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6">
      {/* Dashboard Top Bar & Month Selector */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white dark:bg-slate-800 p-4 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700">
        <div>
          <h2 className="text-sm font-bold text-gray-400 uppercase tracking-wider">Production Overview</h2>
          <div className="flex items-center gap-2">
            <p className="text-xl font-extrabold text-slate-800 dark:text-white">{getMonthName(selectedMonth)}</p>
            <span className="text-xs font-bold px-2 py-0.5 bg-indigo-50 dark:bg-indigo-900/40 text-indigo-600 dark:text-indigo-400 rounded-lg border border-indigo-100 dark:border-indigo-800">{category}</span>
          </div>
        </div>
        <div className="flex items-center gap-3 w-full md:w-auto">
          <div className="relative flex-1 md:flex-none">
            <Filter className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input 
              type="month" 
              value={selectedMonth} 
              onChange={(e) => setSelectedMonth(e.target.value)}
              className="pl-10 pr-4 py-2 bg-slate-900 border border-slate-700 rounded-xl text-sm font-bold text-white focus:ring-2 focus:ring-indigo-500 outline-none w-full appearance-none"
            />
          </div>
          <button 
            onClick={triggerRefresh} 
            className="p-2.5 bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 rounded-xl hover:bg-indigo-100 transition shadow-sm"
          >
            <RefreshCw className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* KPI Cards (Selected Month) */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="glass-panel p-6 rounded-2xl border-l-4 border-blue-500 flex justify-between items-center transform transition hover:translate-y-[-2px]">
            <div>
                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Plan Quantity</p>
                <h3 className="text-3xl font-black mt-1 text-blue-600 dark:text-blue-400">
                  {dashboardData.selectedMonthStats.plan.toLocaleString()}
                </h3>
                <p className="text-[10px] text-slate-400 mt-1 flex items-center gap-1">
                  <TrendingUp className="w-3 h-3 text-blue-500" /> MONTH TOTAL
                </p>
            </div>
            <div className="w-14 h-14 bg-blue-100 dark:bg-blue-900/50 rounded-2xl flex items-center justify-center text-blue-600 dark:text-blue-400 shadow-inner">
                <ClipboardList className="w-7 h-7" />
            </div>
        </div>
        <div className="glass-panel p-6 rounded-2xl border-l-4 border-emerald-500 flex justify-between items-center transform transition hover:translate-y-[-2px]">
            <div>
                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Actual Quantity</p>
                <h3 className="text-3xl font-black mt-1 text-emerald-600 dark:text-emerald-400">
                  {dashboardData.selectedMonthStats.actual.toLocaleString()}
                </h3>
                <p className="text-[10px] text-slate-400 mt-1 flex items-center gap-1">
                  <TrendingUp className="w-3 h-3 text-emerald-500" /> MONTH TOTAL
                </p>
            </div>
            <div className="w-14 h-14 bg-emerald-100 dark:bg-emerald-900/50 rounded-2xl flex items-center justify-center text-emerald-600 dark:text-emerald-400 shadow-inner">
                <CheckCircle className="w-7 h-7" />
            </div>
        </div>
        <div className="glass-panel p-6 rounded-2xl border-l-4 border-indigo-500 flex justify-between items-center transform transition hover:translate-y-[-2px]">
            <div>
                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Avg Efficiency</p>
                <h3 className="text-3xl font-black mt-1 text-indigo-600 dark:text-indigo-400">
                  {dashboardData.selectedMonthStats.efficiency.toFixed(1)}%
                </h3>
                <div className="w-full bg-gray-200 dark:bg-slate-700 rounded-full h-1.5 mt-2">
                  <div 
                    className={`h-1.5 rounded-full ${dashboardData.selectedMonthStats.efficiency >= 80 ? 'bg-emerald-500' : 'bg-red-500'}`} 
                    style={{ width: `${Math.min(dashboardData.selectedMonthStats.efficiency, 100)}%` }}
                  ></div>
                </div>
            </div>
            <div className="w-14 h-14 bg-indigo-100 dark:bg-indigo-900/50 rounded-2xl flex items-center justify-center text-indigo-600 dark:text-indigo-400 shadow-inner">
                <ArrowUpRight className="w-7 h-7" />
            </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Chart Section */}
        <div className="lg:col-span-2 glass-panel rounded-2xl p-6 shadow-sm">
            <h3 className="font-extrabold text-lg mb-6 flex items-center gap-2 text-slate-700 dark:text-slate-200 uppercase tracking-tight">
                <TrendingUp className="w-5 h-5 text-indigo-500" /> Process Efficiency <span className="text-sm font-normal text-slate-400">({getMonthName(selectedMonth)})</span>
            </h3>
            <div className="h-80">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={dashboardData.chartData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" opacity={0.5} />
                  <XAxis 
                    dataKey="process" 
                    tick={{fontSize: 10, fill: '#94a3b8', fontWeight: 700}} 
                    axisLine={false} 
                    tickLine={false} 
                    dy={10}
                  />
                  <YAxis tick={{fontSize: 10, fill: '#94a3b8'}} axisLine={false} tickLine={false} />
                  <Tooltip 
                      contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)', background: 'rgba(255,255,255,0.95)' }}
                      cursor={{fill: 'rgba(0,0,0,0.02)'}}
                  />
                  <Legend verticalAlign="top" height={36}/>
                  <Bar name="Plan" dataKey="Plan" fill="#3b82f6" radius={[6, 6, 0, 0]} barSize={32} />
                  <Bar name="Actual" dataKey="Actual" fill="#10b981" radius={[6, 6, 0, 0]} barSize={32} />
                </BarChart>
              </ResponsiveContainer>
            </div>
        </div>

        {/* Process Quick Summary */}
        <div className="lg:col-span-1 glass-panel rounded-2xl p-6 shadow-sm flex flex-col">
            <h3 className="font-extrabold text-lg mb-4 text-slate-700 dark:text-slate-200 uppercase tracking-tight">Monthly Totals by Process</h3>
            <div className="space-y-3 overflow-y-auto max-h-[300px] pr-2 custom-scrollbar">
              {dashboardData.chartData.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-10 opacity-40">
                  <ClipboardList className="w-10 h-10 mb-2" />
                  <p className="text-xs font-bold">No data for this month</p>
                </div>
              ) : dashboardData.chartData.map(p => {
                const eff = p.Plan > 0 ? (p.Actual / p.Plan) * 100 : 0;
                return (
                  <div key={p.process} className="p-3 bg-gray-50 dark:bg-slate-900/40 rounded-xl border border-gray-100 dark:border-slate-700/50 flex flex-col gap-2">
                    <div className="flex justify-between items-center">
                      <span className="text-sm font-black text-indigo-600 dark:text-indigo-400">{p.process}</span>
                      <span className={`text-[10px] font-black px-2 py-0.5 rounded-full ${eff >= 80 ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'}`}>
                        {eff.toFixed(1)}% EFF
                      </span>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <p className="text-[10px] font-bold text-slate-400">PLAN</p>
                        <p className="text-sm font-bold text-slate-700 dark:text-slate-200">{p.Plan.toLocaleString()}</p>
                      </div>
                      <div className="text-right">
                        <p className="text-[10px] font-bold text-slate-400">ACTUAL</p>
                        <p className="text-sm font-bold text-emerald-600 dark:text-emerald-400">{p.Actual.toLocaleString()}</p>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
        </div>
      </div>

      {/* Production Log Table */}
      <div className="glass-panel rounded-2xl overflow-hidden min-h-[400px] flex flex-col shadow-sm">
        <div className="p-5 border-b border-gray-100 dark:border-slate-700/50 flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4 bg-white/50 dark:bg-slate-800/50">
            <div className="flex flex-wrap items-center gap-4">
              <h3 className="font-bold text-lg flex items-center gap-2 text-slate-700 dark:text-slate-200">
                  <i className="fas fa-table text-indigo-500"></i> Production Reports
              </h3>

              <div className="flex items-center bg-gray-100 dark:bg-slate-900 rounded-xl p-1 shadow-inner border border-gray-200 dark:border-slate-700">
                  <button 
                      onClick={() => setViewMode('daily')}
                      className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-xs font-black transition-all ${
                          viewMode === 'daily' 
                          ? 'bg-white dark:bg-slate-700 text-indigo-600 dark:text-indigo-400 shadow-sm' 
                          : 'text-gray-500 hover:text-gray-700 dark:text-gray-400'
                      }`}
                  >
                      <List className="w-3.5 h-3.5" /> DAILY
                  </button>
                  <button 
                      onClick={() => setViewMode('monthly')}
                      className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-xs font-black transition-all ${
                          viewMode === 'monthly' 
                          ? 'bg-white dark:bg-slate-700 text-indigo-600 dark:text-indigo-400 shadow-sm' 
                          : 'text-gray-500 hover:text-gray-700 dark:text-gray-400'
                      }`}
                  >
                      <Calendar className="w-3.5 h-3.5" /> MONTHLY
                  </button>
              </div>

              {/* Date Range Inputs Styled with Black Background */}
              {viewMode === 'daily' && (
                <div className="flex items-center gap-2 bg-slate-900 px-3 py-1 rounded-xl border border-slate-700 shadow-sm">
                  <div className="flex items-center gap-1">
                    <span className="text-[10px] font-black text-slate-500 uppercase">From</span>
                    <input 
                      type="date" 
                      value={dateRange.start}
                      onChange={(e) => setDateRange(prev => ({...prev, start: e.target.value}))}
                      className="text-xs bg-transparent border-none outline-none font-bold text-white appearance-none" 
                    />
                  </div>
                  <div className="w-px h-4 bg-slate-800 mx-1"></div>
                  <div className="flex items-center gap-1">
                    <span className="text-[10px] font-black text-slate-500 uppercase">To</span>
                    <input 
                      type="date" 
                      value={dateRange.end}
                      onChange={(e) => setDateRange(prev => ({...prev, end: e.target.value}))}
                      className="text-xs bg-transparent border-none outline-none font-bold text-white appearance-none" 
                    />
                  </div>
                  {(dateRange.start || dateRange.end) && (
                    <button 
                      onClick={() => setDateRange({start: '', end: ''})}
                      className="ml-1 text-red-500 hover:text-red-700"
                    >
                      <X className="w-3 h-3" />
                    </button>
                  )}
                </div>
              )}
            </div>

            <button 
              onClick={downloadCSV}
              className="flex items-center gap-2 px-5 py-2 bg-emerald-600 text-white text-xs font-black rounded-xl hover:bg-emerald-700 transition shadow-lg shadow-emerald-500/20 uppercase tracking-widest"
            >
              <Download className="w-3.5 h-3.5" /> Export Excel
            </button>
        </div>

        <div className="p-4 flex-1 bg-gray-50/50 dark:bg-slate-900/20">
            {viewMode === 'daily' ? (
              <div className="space-y-4">
                  {dailyGroups.length === 0 && (
                      <div className="flex flex-col items-center justify-center h-48 text-slate-400">
                          <p className="font-bold">No data found for this period.</p>
                      </div>
                  )}

                  {dailyGroups.map((group, groupIdx) => (
                      <div key={`group-${groupIdx}`} className="space-y-2">
                          {/* DATE HEADER - Renders once per group */}
                          <div className={`p-3 bg-slate-900 dark:bg-black flex justify-between items-center rounded-xl border border-slate-800 dark:border-slate-900 shadow-sm ${group.offDay ? 'border-l-4 border-l-red-500' : ''}`}>
                              <div className="flex items-center gap-3">
                                  <span className="font-black text-xs text-slate-900 bg-white px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm uppercase tracking-wide">
                                    {formatDisplayDate(group.date).split(' ')[1]}
                                  </span>
                                  <span className="font-mono text-sm font-bold text-slate-100 tracking-tight">
                                    {group.date}
                                  </span>
                                  {group.offDay && (
                                    <span className="flex items-center gap-2 px-2.5 py-1 bg-red-600 text-white rounded-lg text-[10px] font-black uppercase tracking-widest shadow-md shadow-red-500/20">
                                      <CalendarOff className="w-3.5 h-3.5" /> {group.offDay.description}
                                    </span>
                                  )}
                              </div>
                          </div>

                          {/* ENTRIES FOR THIS DATE */}
                          <div className="space-y-2 pl-4">
                            {group.entries.length === 0 && !group.offDay && (
                                <p className="text-xs text-slate-400 italic">No production recorded.</p>
                            )}
                            {group.entries.map(d => {
                                const eff = d.planQuantity > 0 ? (d.actualQuantity / d.planQuantity) * 100 : 0;
                                const effColor = eff >= 80 ? 'text-emerald-600 dark:text-emerald-400' : 'text-red-500 dark:text-red-400';

                                return (
                                    <div key={d.id} className="bg-white dark:bg-slate-800 rounded-xl overflow-hidden shadow-sm border border-gray-100 dark:border-slate-700/50 hover:shadow-md transition group">
                                        <div className="p-4 grid grid-cols-2 md:grid-cols-6 lg:grid-cols-7 gap-6 items-center text-sm">
                                            <div className="md:col-span-2 lg:col-span-2 flex items-center gap-2">
                                                <span className="px-2 py-0.5 bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 rounded text-[9px] font-black uppercase tracking-widest shrink-0">
                                                  {d.process}
                                                </span>
                                                <div className="font-black text-slate-700 dark:text-slate-200 leading-tight truncate">
                                                  {d.productName}
                                                  <p className="text-[10px] font-bold text-slate-400 uppercase">Product Name</p>
                                                </div>
                                            </div>
                                            <div className="text-right">
                                              <span className="text-[10px] text-slate-400 font-bold block uppercase mb-1">Plan</span>
                                              <span className="font-black text-blue-600 dark:text-blue-400 text-base">{d.planQuantity.toLocaleString()}</span>
                                            </div>
                                            <div className="text-right">
                                              <span className="text-[10px] text-slate-400 font-bold block uppercase mb-1">Actual</span>
                                              <span className="font-black text-emerald-600 dark:text-emerald-400 text-base">{d.actualQuantity.toLocaleString()}</span>
                                            </div>
                                            <div className="text-center bg-gray-50 dark:bg-slate-900/50 py-2 rounded-xl border border-gray-100 dark:border-slate-700">
                                              <span className="text-[10px] text-slate-400 font-bold block uppercase mb-1">Efficiency</span>
                                              <span className={`font-black ${effColor} text-base`}>{eff.toFixed(0)}%</span>
                                            </div>
                                            <div className="text-right">
                                              <span className="text-[10px] text-slate-400 font-bold block uppercase mb-1">Batch #</span>
                                              <span className="font-mono text-[11px] font-bold text-slate-500 dark:text-gray-400 bg-gray-100 dark:bg-slate-700 px-2 py-0.5 rounded">{d.batchNo || '-'}</span>
                                            </div>
                                            <div className="text-right flex items-center justify-end gap-3">
                                              <div className="text-center">
                                                <span className="text-[10px] text-slate-400 font-bold block uppercase mb-1 flex items-center gap-1">
                                                  <UsersIcon className="w-2.5 h-2.5" /> MP
                                                </span>
                                                <span className="font-black text-slate-700 dark:text-slate-200">{d.manpower || 0}</span>
                                              </div>
                                              {hasPermission(['manager', 'admin']) && (
                                                  <button onClick={() => handleDelete(d.id)} className="text-slate-400 hover:text-red-500 transition-colors p-1.5 hover:bg-red-950/20 rounded-lg">
                                                      <i className="fas fa-trash-alt"></i>
                                                  </button>
                                              )}
                                            </div>
                                        </div>
                                    </div>
                                );
                            })}
                          </div>
                      </div>
                  ))}
              </div>
            ) : (
              <div className="overflow-x-auto rounded-xl border border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-800 shadow-sm">
                <table className="w-full text-sm text-left">
                  <thead className="bg-gray-50 dark:bg-slate-900 text-slate-500 dark:text-slate-400 font-black text-[10px] uppercase tracking-widest border-b border-gray-100 dark:border-slate-700">
                    <tr>
                      <th className="px-6 py-4">Month</th>
                      <th className="px-6 py-4">Process Breakdown</th>
                      <th className="px-6 py-4 text-right">Total Plan</th>
                      <th className="px-6 py-4 text-right">Total Actual</th>
