import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { CATEGORIES, PROCESSES } from '../../constants';
import { ProductionEntry, Category, ProcessType } from '../../types';
import { X } from 'lucide-react';

interface InputModalProps {
  onClose: () => void;
  editEntry?: ProductionEntry | null;
}

export const InputModal: React.FC<InputModalProps> = ({ onClose, editEntry }) => {
  const { user, hasPermission } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [tab, setTab] = useState<'Plan' | 'Actual'>('Plan');

  // Form States
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [process, setProcess] = useState<ProcessType>(PROCESSES[0]);
  const [productName, setProductName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [manpower, setManpower] = useState('0');
  const [batchNo, setBatchNo] = useState('');

  // For Actual selection in "Add" mode
  const [plans, setPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  useEffect(() => {
    if (editEntry) {
      setDate(editEntry.date);
      setCategory(editEntry.category);
      setProcess(editEntry.process);
      setProductName(editEntry.productName);
      setQuantity(editEntry.planQuantity.toString());
      setManpower(editEntry.manpower?.toString() || '0');
      setBatchNo(editEntry.batchNo || '');
      // If editing an entry that already has actual data, we default to a simplified update view
      setTab('Plan'); 
    } else {
      if (user?.role === 'operator') setTab('Actual');
      else if (user?.role === 'planner') setTab('Plan');
    }
  }, [editEntry, user]);

  useEffect(() => {
    if (tab === 'Actual' && !editEntry) {
        const all = StorageService.getProductionData();
        const relevant = all.filter(p => p.date === date);
        setPlans(relevant);
        setSelectedPlanId('');
    }
  }, [date, tab, editEntry]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const offDays = StorageService.getOffDays();
    if (!editEntry && offDays.some(od => od.date === date)) {
        alert("Cannot input data on an Off Day!");
        return;
    }

    const currentData = StorageService.getProductionData();

    if (editEntry) {
        // EDIT MODE
        const updated = currentData.map(p => {
            if (p.id === editEntry.id) {
                return { 
                    ...p, 
                    date,
                    category,
                    process,
                    productName,
                    planQuantity: tab === 'Plan' ? parseInt(quantity) : p.planQuantity,
                    actualQuantity: tab === 'Actual' ? parseInt(quantity) : p.actualQuantity,
                    batchNo, 
                    manpower: parseInt(manpower),
                    lastUpdatedBy: user!.id, 
                    updatedAt: new Date().toISOString()
                };
            }
            return p;
        });
        StorageService.saveProductionData(updated);
        StorageService.addLog({ userId: user!.id, userName: user!.name, action: 'EDIT_ENTRY', details: `Edited: ${productName}` });
    } else {
        // ADD MODE
        if (tab === 'Plan') {
            const newEntry: ProductionEntry = {
                id: Date.now().toString(),
                date, category, process,
                productName, planQuantity: parseInt(quantity), actualQuantity: 0,
                lastUpdatedBy: user!.id, updatedAt: new Date().toISOString()
            };
            StorageService.saveProductionData([...currentData, newEntry]);
            StorageService.addLog({ userId: user!.id, userName: user!.name, action: 'ADD_PLAN', details: `Plan: ${productName} (${quantity})` });
        } else {
            if (!selectedPlanId) return alert("Select a plan first");
            const updated = currentData.map(p => {
                if (p.id === selectedPlanId) {
                    return { 
                        ...p, 
                        actualQuantity: parseInt(quantity), 
                        batchNo, manpower: parseInt(manpower),
                        lastUpdatedBy: user!.id, updatedAt: new Date().toISOString()
                    };
                }
                return p;
            });
            StorageService.saveProductionData(updated);
            const pName = plans.find(p=>p.id===selectedPlanId)?.productName;
            StorageService.addLog({ userId: user!.id, userName: user!.name, action: 'ADD_ACTUAL', details: `Actual: ${pName} (${quantity})` });
        }
    }

    triggerRefresh();
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-md shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200 border border-slate-200 dark:border-slate-700">
        <div className="flex border-b border-gray-200 dark:border-slate-700">
            {!editEntry ? (
              <>
                {hasPermission(['admin', 'manager', 'planner']) && (
                    <button onClick={() => setTab('Plan')} 
                        className={`flex-1 py-4 font-bold text-center transition ${tab === 'Plan' ? 'bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600' : 'text-gray-500 hover:bg-gray-50 dark:hover:bg-slate-700'}`}>
                        Input Plan
                    </button>
                )}
                {hasPermission(['admin', 'manager', 'operator']) && (
                    <button onClick={() => setTab('Actual')} 
                        className={`flex-1 py-4 font-bold text-center transition ${tab === 'Actual' ? 'bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600' : 'text-gray-500 hover:bg-gray-50 dark:hover:bg-slate-700'}`}>
                        Input Actual
                    </button>
                )}
              </>
            ) : (
              <div className="flex-1 py-4 font-bold text-center bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600">
                Edit Production Entry
              </div>
            )}
        </div>

        <div className="p-6 relative">
            <button onClick={onClose} className="absolute top-2 right-4 text-gray-400 hover:text-red-500 transition-colors"><X /></button>

            <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                    <label className="block text-xs font-bold uppercase text-gray-500 dark:text-gray-400 mb-1">Date</label>
                    <input type="date" required value={date} onChange={e => setDate(e.target.value)} 
                        className="w-full p-2.5 rounded-lg border border-gray-300 dark:bg-slate-900 dark:border-slate-700 dark:text-white focus:ring-2 focus:ring-indigo-500 outline-none" />
                </div>

                {tab === 'Plan' || editEntry ? (
                    <>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold uppercase text-gray-500 dark:text-gray-400 mb-1">Category</label>
                                <select value={category} onChange={e => setCategory(e.target.value as Category)} className="w-full p-2.5 rounded-lg border border-gray-300 dark:bg-slate-900 dark:border-slate-700 dark:text-white outline-none">
                                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-xs font-bold uppercase text-gray-500 dark:text-gray-400 mb-1">Process</label>
                                <select value={process} onChange={e => setProcess(e.target.value as ProcessType)} className="w-full p-2.5 rounded-lg border border-gray-300 dark:bg-slate-900 dark:border-slate-700 dark:text-white outline-none">
                                    {PROCESSES.map(p => <option key={p} value={p}>{p}</option>)}
                                </select>
                            </div>
                        </div>
                        <div>
                            <label className="block text-xs font-bold uppercase text-gray-500 dark:text-gray-400 mb-1">Product Name</label>
                            <input type="text" required value={productName} onChange={e => setProductName(e.target.value)} placeholder="e.g. Vitamin C"
                                className="w-full p-2.5 rounded-lg border border-gray-300 dark:bg-slate-900 dark:border-slate-700 dark:text-white outline-none" />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-xs font-bold uppercase text-gray-500 dark:text-gray-400 mb-1">Plan Qty</label>
                              <input type="number" required min="1" value={quantity} onChange={e => setQuantity(e.target.value)} 
                                  className="w-full p-2.5 rounded-lg border border-gray-300 dark:bg-slate-900 dark:border-slate-700 dark:text-white outline-none" />
                          </div>
                          {editEntry && (
                            <div>
                                <label className="block text-xs font-bold uppercase text-gray-500 dark:text-gray-400 mb-1">Manpower</label>
                                <input type="number" required min="0" value={manpower} onChange={e => setManpower(e.target.value)} 
                                    className="w-full p-2.5 rounded-lg border border-gray-300 dark:bg-slate-900 dark:border-slate-700 dark:text-white outline-none" />
                            </div>
                          )}
                        </div>
                        {editEntry && (
                          <div>
                              <label className="block text-xs font-bold uppercase text-gray-500 dark:text-gray-400 mb-1">Batch No</label>
                              <input type="text" value={batchNo} onChange={e => setBatchNo(e.target.value)} 
                                  className="w-full p-2.5 rounded-lg border border-gray-300 dark:bg-slate-900 dark:border-slate-700 dark:text-white outline-none" />
                          </div>
                        )}
                    </>
                ) : (
                    <>
                        <div>
                             <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Select Job / Plan</label>
                             {plans.length === 0 ? <div className="text-sm text-gray-400 italic">No plans for this date</div> : (
                                 <div className="max-h-32 overflow-y-auto border rounded-lg p-2 space-y-1 dark:border-slate-700">
                                     {plans.map(p => (
                                         <div key={p.id} onClick={() => setSelectedPlanId(p.id)}
                                            className={`p-2 rounded cursor-pointer text-sm transition ${selectedPlanId === p.id ? 'bg-emerald-100 text-emerald-800 border border-emerald-500 dark:bg-emerald-900/40 dark:text-emerald-300' : 'hover:bg-gray-100 dark:hover:bg-slate-700'}`}>
                                            <div className="font-bold">{p.productName}</div>
                                            <div className="text-xs opacity-70">{p.process} | Plan: {p.planQuantity}</div>
                                         </div>
                                     ))}
                                 </div>
                             )}
                        </div>
                        {selectedPlanId && (
                            <>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Actual Qty</label>
                                        <input type="number" required min="0" value={quantity} onChange={e => setQuantity(e.target.value)} 
                                            className="w-full p-2.5 rounded-lg border dark:bg-slate-900 dark:border-slate-700 dark:text-white outline-none" />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Manpower</label>
                                        <input type="number" required min="1" value={manpower} onChange={e => setManpower(e.target.value)} 
                                            className="w-full p-2.5 rounded-lg border dark:bg-slate-900 dark:border-slate-700 dark:text-white outline-none" />
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Batch No</label>
                                    <input type="text" required value={batchNo} onChange={e => setBatchNo(e.target.value)} 
                                        className="w-full p-2.5 rounded-lg border dark:bg-slate-900 dark:border-slate-700 dark:text-white outline-none" />
                                </div>
                            </>
                        )}
                    </>
                )}

                <button type="submit" className={`w-full py-3 rounded-xl font-bold text-white mt-4 transition shadow-lg
                    ${tab === 'Plan' ? 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-500/30' : 'bg-emerald-600 hover:bg-emerald-700 shadow-emerald-500/30'}
                `}>
                    {editEntry ? 'Update Entry' : `Submit ${tab}`}
                </button>
            </form>
        </div>
      </div>
    </div>
  );
};

