import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { ProductionEntry } from '../../types';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';
import { 
  ClipboardList, CheckCircle, RefreshCw, List, Calendar, 
  ArrowUpRight, TrendingUp, Filter, Download, Users as UsersIcon, X, Pencil, Trash2
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';

export const Dashboard: React.FC = () => {
  const { category, refreshKey, triggerRefresh } = useDashboard();
  const { hasPermission } = useAuth();

  const [viewMode, setViewMode] = useState<'daily' | 'monthly'>('daily');
  const [selectedMonth, setSelectedMonth] = useState<string>(() => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
  });

  const [dateRange, setDateRange] = useState({ start: '', end: '' });

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays()
    };
  }, [refreshKey]);

  const dashboardData = useMemo(() => {
    const relevant = productionData.filter(d => d.category === category);

    const monthlyProcessStats: Record<string, Record<string, { plan: number, actual: number }>> = {};
    let selectedMonthPlan = 0;
    let selectedMonthActual = 0;
    const selectedMonthProcessMap = new Map<string, {process: string, Plan: number, Actual: number}>();

    relevant.forEach(d => {
      const monthKey = d.date.substring(0, 7);
      if (!monthlyProcessStats[monthKey]) monthlyProcessStats[monthKey] = {};
      if (!monthlyProcessStats[monthKey][d.process]) monthlyProcessStats[monthKey][d.process] = { plan: 0, actual: 0 };
      monthlyProcessStats[monthKey][d.process].plan += d.planQuantity;
      monthlyProcessStats[monthKey][d.process].actual += d.actualQuantity;

      if (monthKey === selectedMonth) {
        selectedMonthPlan += d.planQuantity;
        selectedMonthActual += d.actualQuantity;
        if (!selectedMonthProcessMap.has(d.process)) {
          selectedMonthProcessMap.set(d.process, { process: d.process, Plan: 0, Actual: 0 });
        }
        const p = selectedMonthProcessMap.get(d.process)!;
        p.Plan += d.planQuantity;
        p.Actual += d.actualQuantity;
      }
    });

    const sortedSummary = Object.entries(monthlyProcessStats)
      .flatMap(([month, processes]) => 
        Object.entries(processes).map(([process, stats]) => ({
          month,
          process,
          plan: stats.plan,
          actual: stats.actual,
          efficiency: stats.plan > 0 ? (stats.actual / stats.plan) * 100 : 0
        }))
      )
      .sort((a, b) => b.month.localeCompare(a.month) || a.process.localeCompare(b.process));

    return {
      filteredData: relevant.sort((a,b) => b.date.localeCompare(a.date)),
      selectedMonthStats: { 
        plan: selectedMonthPlan, 
        actual: selectedMonthActual,
        efficiency: selectedMonthPlan > 0 ? (selectedMonthActual / selectedMonthPlan) * 100 : 0
      },
      chartData: Array.from(selectedMonthProcessMap.values()),
      monthlySummary: sortedSummary
    };
  }, [productionData, category, selectedMonth]);

  const dailyGroups = useMemo(() => {
    const baseData = dashboardData.filteredData;
    const filteredEntries = baseData.filter(d => {
        const inMonth = d.date.startsWith(selectedMonth);
        const matchStart = !dateRange.start || d.date >= dateRange.start;
        const matchEnd = !dateRange.end || d.date <= dateRange.end;
        return inMonth && matchStart && matchEnd;
    });

    const dates = new Set<string>();
    filteredEntries.forEach(d => dates.add(d.date));
    const sortedDates = Array.from(dates).sort((a, b) => b.localeCompare(a));

    return sortedDates.map(date => {
        const entriesForDate = filteredEntries.filter(d => d.date === date);
        const totalActualForDate = entriesForDate.reduce((sum, entry) => sum + entry.actualQuantity, 0);
        return {
            date,
            totalActualForDate,
            offDay: offDays.find(od => od.date === date),
            entries: entriesForDate
        };
    });
  }, [dashboardData.filteredData, offDays, selectedMonth, dateRange]);

  const handleDelete = (id: string) => {
      if(!window.confirm("Delete this record?")) return;
      const newData = productionData.filter(p => p.id !== id);
      StorageService.saveProductionData(newData);
      triggerRefresh();
  };

  const handleEdit = (entry: ProductionEntry) => {
    window.dispatchEvent(new CustomEvent('edit-production-entry', { detail: entry }));
  };

  const getMonthName = (monthKey: string) => {
    const [y, m] = monthKey.split('-');
    return new Date(parseInt(y), parseInt(m) - 1).toLocaleString('default', { month: 'long', year: 'numeric' });
  };

  return (
    <div className="space-y-8 pb-12">
      {/* Header Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="glass-panel p-6 rounded-3xl border-l-4 border-blue-500 flex justify-between items-center transition shadow-lg">
            <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Target Monthly</p>
                <h3 className="text-3xl font-black mt-1 text-slate-800 dark:text-white">
                  {dashboardData.selectedMonthStats.plan.toLocaleString()}
                </h3>
                <p className="text-[10px] font-bold text-blue-500 mt-2 flex items-center gap-1">
                  <TrendingUp className="w-3 h-3" /> AGGREGATED PLAN
                </p>
            </div>
            <div className="w-14 h-14 bg-blue-50 dark:bg-blue-900/30 rounded-2xl flex items-center justify-center text-blue-500 shadow-inner">
                <ClipboardList className="w-7 h-7" />
            </div>
        </div>
        <div className="glass-panel p-6 rounded-3xl border-l-4 border-emerald-500 flex justify-between items-center transition shadow-lg">
            <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Achieved Monthly</p>
                <h3 className="text-3xl font-black mt-1 text-slate-800 dark:text-white">
                  {dashboardData.selectedMonthStats.actual.toLocaleString()}
                </h3>
                <p className="text-[10px] font-bold text-emerald-500 mt-2 flex items-center gap-1">
                  <CheckCircle className="w-3 h-3" /> AGGREGATED ACTUAL
                </p>
            </div>
            <div className="w-14 h-14 bg-emerald-50 dark:bg-emerald-900/30 rounded-2xl flex items-center justify-center text-emerald-500 shadow-inner">
                <CheckCircle className="w-7 h-7" />
            </div>
        </div>
        <div className="glass-panel p-6 rounded-3xl border-l-4 border-indigo-500 flex justify-between items-center transition shadow-lg">
            <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Avg Efficiency</p>
                <h3 className="text-3xl font-black mt-1 text-slate-800 dark:text-white">
                  {dashboardData.selectedMonthStats.efficiency.toFixed(1)}%
                </h3>
                <div className="w-full bg-gray-100 dark:bg-slate-700 rounded-full h-1.5 mt-3">
                  <div 
                    className={`h-1.5 rounded-full ${dashboardData.selectedMonthStats.efficiency >= 80 ? 'bg-emerald-500' : 'bg-rose-500'}`} 
                    style={{ width: `${Math.min(dashboardData.selectedMonthStats.efficiency, 100)}%` }}
                  ></div>
                </div>
            </div>
            <div className="w-14 h-14 bg-indigo-50 dark:bg-indigo-900/30 rounded-2xl flex items-center justify-center text-indigo-500 shadow-inner">
                <ArrowUpRight className="w-7 h-7" />
            </div>
        </div>
      </div>

      {/* Production Log - THE CARD UI */}
      <div className="space-y-6">
        <div className="flex flex-col lg:flex-row justify-between items-end gap-4 px-2">
            <div>
               <h3 className="text-2xl font-black text-slate-800 dark:text-white tracking-tight flex items-center gap-3">
                  <List className="w-6 h-6 text-indigo-500" />
                  Production Logs
               </h3>
               <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">Detailed daily operations review</p>
            </div>

            <div className="flex flex-wrap items-center gap-3">
              <div className="flex items-center bg-white dark:bg-slate-800 rounded-xl p-1 shadow-sm border border-gray-100 dark:border-slate-700">
                <input 
                  type="month" 
                  value={selectedMonth} 
                  onChange={(e) => setSelectedMonth(e.target.value)}
                  className="px-3 py-1.5 text-xs font-bold bg-transparent outline-none border-none dark:text-white"
                />
              </div>
              <button 
                onClick={triggerRefresh} 
                className="p-2.5 bg-white dark:bg-slate-800 text-slate-500 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 hover:text-indigo-500 transition"
              >
                <RefreshCw className="w-5 h-5" />
              </button>
            </div>
        </div>

        <div className="space-y-8">
            {dailyGroups.length === 0 && (
                <div className="flex flex-col items-center justify-center py-20 bg-white dark:bg-slate-800 rounded-3xl border border-dashed border-slate-300 dark:border-slate-700">
                    <ClipboardList className="w-12 h-12 text-slate-300 mb-4" />
                    <p className="font-bold text-slate-400">No production records for this period.</p>
                </div>
            )}

            {dailyGroups.map((group, groupIdx) => {
                const [y, m, d] = group.date.split('-');
                const dateObj = new Date(parseInt(y), parseInt(m)-1, parseInt(d));
                const dayName = dateObj.toLocaleDateString('en-MY', { weekday: 'long' }).toUpperCase();

                return (
                  <div key={`group-${groupIdx}`} className="bg-[#151e2e] rounded-[2rem] overflow-hidden shadow-2xl border border-slate-800/50">
                      {/* CARD HEADER - MATCHES IMAGE */}
                      <div className="p-6 flex justify-between items-center border-b border-slate-800/50 bg-[#1e293b]/40">
                          <div className="flex items-center gap-4">
                              <div className="p-3 bg-slate-800 rounded-2xl border border-slate-700">
                                <Calendar className="w-6 h-6 text-slate-400" />
                              </div>
                              <div className="flex items-baseline gap-4">
                                <span className="text-2xl font-black text-white tracking-tight">{group.date}</span>
                                <span className="text-sm font-bold text-slate-500 uppercase tracking-[0.2em]">{dayName}</span>
                              </div>
                          </div>
                          <div className="px-6 py-2.5 bg-[#0f172a] rounded-2xl border border-slate-700 text-slate-200 font-bold text-sm shadow-inner">
                            Total Actual: <span className="text-emerald-400 ml-1">{group.totalActualForDate.toLocaleString()}</span>
                          </div>
                      </div>

                      {/* TABLE SECTION */}
                      <div className="overflow-x-auto no-scrollbar">
                          <table className="w-full text-left">
                              <thead>
                                  <tr className="border-b border-slate-800/50 text-[11px] font-black text-slate-500 uppercase tracking-[0.2em] bg-[#0f172a]/20">
                                      <th className="px-8 py-5">Process</th>
                                      <th className="px-8 py-5">Product</th>
                                      <th className="px-8 py-5 text-center">Plan Qty</th>
                                      <th className="px-8 py-5 text-center">Actual Qty</th>
                                      <th className="px-8 py-5 text-center">Efficiency</th>
                                      <th className="px-8 py-5 text-center">Batch No</th>
                                      <th className="px-8 py-5 text-center">Manpower</th>
                                      <th className="px-8 py-5 text-center">Action</th>
                                  </tr>
                              </thead>
                              <tbody className="divide-y divide-slate-800/30">
                                  {group.entries.map(entry => {
                                      const eff = entry.planQuantity > 0 ? (entry.actualQuantity / entry.planQuantity) * 100 : 0;

                                      // EXACT COLORS FROM SCREENSHOT
                                      const effColor = eff >= 100 ? 'text-[#10b981]' : eff >= 75 ? 'text-[#fbbf24]' : 'text-[#f43f5e]';

                                      return (
                                          <tr key={entry.id} className="hover:bg-slate-800/20 transition-colors group">
                                              <td className="px-8 py-6">
                                                  <span className="inline-block px-4 py-1.5 rounded-xl border border-indigo-500/30 bg-indigo-500/5 text-indigo-400 text-[10px] font-black uppercase tracking-widest">
                                                    {entry.process}
                                                  </span>
                                              </td>
                                              <td className="px-8 py-6">
                                                  <span className="text-sm font-black text-white">{entry.productName}</span>
                                              </td>
                                              <td className="px-8 py-6 text-center">
                                                  <span className="text-blue-400 font-black font-mono text-lg">{entry.planQuantity.toLocaleString()}</span>
                                              </td>
                                              <td className="px-8 py-6 text-center">
                                                  <span className="text-emerald-400 font-black font-mono text-lg">{entry.actualQuantity.toLocaleString()}</span>
                                              </td>
                                              <td className="px-8 py-6 text-center">
                                                  <span className={`font-black text-lg ${effColor}`}>{eff.toFixed(0)}%</span>
                                              </td>
                                              <td className="px-8 py-6 text-center">
                                                  <span className="text-slate-500 font-mono text-xs font-bold uppercase tracking-tight">{entry.batchNo || '-'}</span>
                                              </td>
                                              <td className="px-8 py-6 text-center">
                                                  <span className="text-slate-200 font-black text-lg">{entry.manpower || 0}</span>
                                              </td>
                                              <td className="px-8 py-6">
