import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { ProductionEntry } from '../../types';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';
import { 
  ClipboardList, CheckCircle, RefreshCw, List, Calendar, 
  ArrowUpRight, TrendingUp, Filter, Download, Users as UsersIcon, X, Pencil, Trash2
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';

export const Dashboard: React.FC = () => {
  const { category, refreshKey, triggerRefresh } = useDashboard();
  const { hasPermission } = useAuth();

  const [viewMode, setViewMode] = useState<'daily' | 'monthly'>('daily');
  const [selectedMonth, setSelectedMonth] = useState<string>(() => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
  });

  const [dateRange, setDateRange] = useState({ start: '', end: '' });

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays()
    };
  }, [refreshKey]);

  const dashboardData = useMemo(() => {
    const relevant = productionData.filter(d => d.category === category);

    const monthlyProcessStats: Record<string, Record<string, { plan: number, actual: number }>> = {};
    let selectedMonthPlan = 0;
    let selectedMonthActual = 0;
    const selectedMonthProcessMap = new Map<string, {process: string, Plan: number, Actual: number}>();

    relevant.forEach(d => {
      const monthKey = d.date.substring(0, 7);
      if (!monthlyProcessStats[monthKey]) monthlyProcessStats[monthKey] = {};
      if (!monthlyProcessStats[monthKey][d.process]) monthlyProcessStats[monthKey][d.process] = { plan: 0, actual: 0 };
      monthlyProcessStats[monthKey][d.process].plan += d.planQuantity;
      monthlyProcessStats[monthKey][d.process].actual += d.actualQuantity;

      if (monthKey === selectedMonth) {
        selectedMonthPlan += d.planQuantity;
        selectedMonthActual += d.actualQuantity;
        if (!selectedMonthProcessMap.has(d.process)) {
          selectedMonthProcessMap.set(d.process, { process: d.process, Plan: 0, Actual: 0 });
        }
        const p = selectedMonthProcessMap.get(d.process)!;
        p.Plan += d.planQuantity;
        p.Actual += d.actualQuantity;
      }
    });

    return {
      filteredData: relevant.sort((a,b) => b.date.localeCompare(a.date)),
      selectedMonthStats: { 
        plan: selectedMonthPlan, 
        actual: selectedMonthActual,
        efficiency: selectedMonthPlan > 0 ? (selectedMonthActual / selectedMonthPlan) * 100 : 0
      },
      chartData: Array.from(selectedMonthProcessMap.values())
    };
  }, [productionData, category, selectedMonth]);

  const dailyGroups = useMemo(() => {
    const baseData = dashboardData.filteredData;
    const filteredEntries = baseData.filter(d => {
        const inMonth = d.date.startsWith(selectedMonth);
        const matchStart = !dateRange.start || d.date >= dateRange.start;
        const matchEnd = !dateRange.end || d.date <= dateRange.end;
        return inMonth && matchStart && matchEnd;
    });

    const dates = new Set<string>();
    filteredEntries.forEach(d => dates.add(d.date));
    const sortedDates = Array.from(dates).sort((a, b) => b.localeCompare(a));

    return sortedDates.map(date => {
        const entriesForDate = filteredEntries.filter(d => d.date === date);
        const totalActualForDate = entriesForDate.reduce((sum, entry) => sum + entry.actualQuantity, 0);
        return {
            date,
            totalActualForDate,
            entries: entriesForDate
        };
    });
  }, [dashboardData.filteredData, selectedMonth, dateRange]);

  const handleDelete = (id: string) => {
      if(!window.confirm("Delete this record?")) return;
      const newData = productionData.filter(p => p.id !== id);
      StorageService.saveProductionData(newData);
      triggerRefresh();
      window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'Entry deleted successfully' } }));
  };

  const handleEdit = (entry: ProductionEntry) => {
    window.dispatchEvent(new CustomEvent('edit-production-entry', { detail: entry }));
  };

  const downloadCSV = () => {
    // Basic CSV generation logic for export
    const headers = ["Date", "Process", "Product", "Plan", "Actual", "Batch No", "Manpower"];
    const rows = dashboardData.filteredData.map(d => [
      d.date, d.process, d.productName, d.planQuantity, d.actualQuantity, d.batchNo, d.manpower
    ]);
    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `production_report_${category}_${selectedMonth}.csv`);
    document.body.appendChild(link);
    link.click();

    // Notification
    window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'Production data exported successfully!' } }));
  };

  return (
    <div className="space-y-8 pb-12">
      {/* Top Section */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="glass-panel p-6 rounded-3xl border-l-4 border-blue-500 shadow-sm">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Monthly Plan</p>
            <h3 className="text-3xl font-black mt-1 text-slate-800 dark:text-white">{dashboardData.selectedMonthStats.plan.toLocaleString()}</h3>
        </div>
        <div className="glass-panel p-6 rounded-3xl border-l-4 border-emerald-500 shadow-sm">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Monthly Actual</p>
            <h3 className="text-3xl font-black mt-1 text-slate-800 dark:text-white">{dashboardData.selectedMonthStats.actual.toLocaleString()}</h3>
        </div>
        <div className="glass-panel p-6 rounded-3xl border-l-4 border-indigo-500 shadow-sm">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Efficiency</p>
            <h3 className="text-3xl font-black mt-1 text-slate-800 dark:text-white">{dashboardData.selectedMonthStats.efficiency.toFixed(1)}%</h3>
        </div>
      </div>

      {/* Production Report List - CUSTOM DESIGN REQUEST */}
      <div className="space-y-6">
        <div className="flex flex-col md:flex-row justify-between items-end gap-4 px-2">
            <div>
               <h3 className="text-xl font-black text-slate-800 dark:text-white flex items-center gap-2">
                  <List className="w-5 h-5 text-indigo-500" />
                  Daily Production Reports
               </h3>
               <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Operational log for {category}</p>
            </div>

            <div className="flex items-center gap-3">
              <input 
                type="month" 
                value={selectedMonth} 
                onChange={(e) => setSelectedMonth(e.target.value)}
                className="px-4 py-2 text-sm font-bold bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 dark:text-white outline-none"
              />
              <button onClick={downloadCSV} className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 text-white text-xs font-black rounded-xl hover:bg-indigo-700 shadow-lg shadow-indigo-500/20 uppercase tracking-widest transition">
                <Download className="w-4 h-4" /> Export Report
              </button>
            </div>
        </div>

        <div className="space-y-8">
            {dailyGroups.map((group, groupIdx) => {
                const [y, m, d] = group.date.split('-');
                const dateObj = new Date(parseInt(y), parseInt(m)-1, parseInt(d));
                const dayName = dateObj.toLocaleDateString('en-MY', { weekday: 'long' }).toUpperCase();

                return (
                  <div key={`group-${groupIdx}`} className="bg-[#1a2333] rounded-3xl overflow-hidden shadow-2xl border border-slate-700/50">
                      {/* CARD HEADER - MATCHES IMAGE */}
                      <div className="p-6 flex justify-between items-center border-b border-slate-700/50 bg-[#232d3f]">
                          <div className="flex items-center gap-4">
                              <Calendar className="w-7 h-7 text-slate-400" />
                              <div className="flex items-baseline gap-4">
                                <span className="text-2xl font-black text-white tracking-tight">{group.date}</span>
                                <span className="text-xs font-bold text-slate-500 uppercase tracking-[0.2em]">{dayName}</span>
                              </div>
                          </div>
                          <div className="px-6 py-2 bg-[#0f172a] rounded-2xl border border-slate-700 text-slate-300 font-bold text-sm shadow-inner">
                            Total Actual: <span className="text-emerald-400 ml-1">{group.totalActualForDate.toLocaleString()}</span>
                          </div>
                      </div>

                      {/* TABLE SECTION */}
                      <div className="overflow-x-auto no-scrollbar">
                          <table className="w-full text-left">
                              <thead>
                                  <tr className="border-b border-slate-700/50 text-[10px] font-black text-slate-500 uppercase tracking-widest bg-[#0f172a]/20">
                                      <th className="px-8 py-5">Process</th>
                                      <th className="px-8 py-5">Product</th>
                                      <th className="px-8 py-5 text-center">Plan Qty</th>
                                      <th className="px-8 py-5 text-center">Actual Qty</th>
                                      <th className="px-8 py-5 text-center">Efficiency</th>
                                      <th className="px-8 py-5 text-center">Batch No</th>
                                      <th className="px-8 py-5 text-center">Manpower</th>
                                      <th className="px-8 py-5 text-center">Action</th>
                                  </tr>
                              </thead>
                              <tbody className="divide-y divide-slate-800/30">
                                  {group.entries.map(entry => {
                                      const eff = entry.planQuantity > 0 ? (entry.actualQuantity / entry.planQuantity) * 100 : 0;
                                      const effColor = eff >= 100 ? 'text-[#10b981]' : eff >= 75 ? 'text-[#fbbf24]' : 'text-[#f43f5e]';

                                      return (
                                          <tr key={entry.id} className="hover:bg-slate-700/20 transition-colors">
                                              <td className="px-8 py-6">
                                                  <span className="inline-block px-3 py-1.5 rounded-xl border border-indigo-500/30 bg-indigo-500/10 text-indigo-400 text-[10px] font-black uppercase">
                                                    {entry.process}
                                                  </span>
                                              </td>
                                              <td className="px-8 py-6">
                                                  <span className="text-sm font-black text-white">{entry.productName}</span>
                                              </td>
                                              <td className="px-8 py-6 text-center">
                                                  <span className="text-blue-400 font-black font-mono text-lg">{entry.planQuantity.toLocaleString()}</span>
                                              </td>
                                              <td className="px-8 py-6 text-center">
                                                  <span className="text-emerald-400 font-black font-mono text-lg">{entry.actualQuantity.toLocaleString()}</span>
                                              </td>
                                              <td className="px-8 py-6 text-center">
                                                  <span className={`font-black text-lg ${effColor}`}>{eff.toFixed(0)}%</span>
                                              </td>
                                              <td className="px-8 py-6 text-center">
                                                  <span className="text-slate-500 font-mono text-xs font-bold uppercase">{entry.batchNo || '-'}</span>
                                              </td>
                                              <td className="px-8 py-6 text-center">
                                                  <span className="text-slate-200 font-black text-lg">{entry.manpower || 0}</span>
                                              </td>
                                              <td className="px-8 py-6">
                                                  <div className="flex items-center justify-center gap-3">
                                                      {hasPermission(['manager', 'admin']) && (
                                                        <>
                                                          <button onClick={() => handleEdit(entry)} className="p-2 text-indigo-400 hover:bg-indigo-500/20 rounded-xl transition">
                                                              <Pencil className="w-5 h-5" />
                                                          </button>
                                                          <button onClick={() => handleDelete(entry.id)} className="p-2 text-slate-500 hover:text-rose-500 hover:bg-rose-500/20 rounded-xl transition">
                                                              <Trash2 className="w-5 h-5" />
                                                          </button>
                                                        </>
                                                      )}
                                                  </div>
                                              </td>
                                          </tr>
                                      );
                                  })}
                              </tbody>
                          </table>
                      </div>
                  </div>
                );
            })}
        </div>
      </div>
    </div>
  );
