export const generateSeedProductionData = (): ProductionEntry[] => {
  const data: ProductionEntry[] = [];
  const products = ['Pain Relief Gel', 'Minty Fresh', 'Pink Salt Fine', 'Vitamin C', 'Charcoal Paste'];

  // Start from today in Malaysia time
  const now = new Date();
  const utc = now.getTime() + (now.getTimezoneOffset() * 60000);
  const malaysiaTime = new Date(utc + (3600000 * 8));

  for (let i = 0; i < 30; i++) {
    const d = new Date(malaysiaTime);
    d.setDate(malaysiaTime.getDate() - i);

    // Manual format to YYYY-MM-DD to avoid toISOString UTC shift
    const dateStr = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

    products.forEach((prod, idx) => {
      if (Math.random() > 0.8) return;

      const plan = Math.floor(Math.random() * 500) + 500;
      const variance = (Math.random() * 0.4) - 0.1;
      const actual = Math.floor(plan * (1 - variance));

      data.push({
        id: `seed-${i}-${idx}`,
        date: dateStr,
        category: idx % 3 === 0 ? 'Healthcare' : idx % 3 === 1 ? 'Toothpaste' : 'Rocksalt',
        process: PROCESSES[idx % 5],
        productName: prod,
        planQuantity: plan,
        actualQuantity: actual,
        batchNo: `B-${dateStr.replace(/-/g, '')}-${idx}`,
        manpower: Math.floor(Math.random() * 5) + 3,
        lastUpdatedBy: 'u1',
        updatedAt: new Date().toISOString()
      });
    });
  }
  return data;
};

