/**
 * Strictly enforces Malaysia Time (UTC+8) using Intl.DateTimeFormat.
 * This prevents the common bug where data entered in the early morning (12am-8am)
 * or parsed on devices in different timezones shifts to the previous day.
 */

export const getTodayISO = () => {
  // Use en-CA locale because it naturally formats to YYYY-MM-DD
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Kuala_Lumpur',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(new Date());
};

export const getCurrentMonthISO = () => {
  // Returns YYYY-MM for the current month in Malaysia
  const today = getTodayISO();
  return today.substring(0, 7);
};

export const formatDisplayDate = (dateStr: string) => {
  // Input: YYYY-MM-DD (e.g., "2025-12-22")
  // Output: "2025-12-22 MONDAY"
  if (!dateStr) return 'Invalid Date';

  const parts = dateStr.split('-');
  if (parts.length !== 3) return dateStr;

  const [y, m, d] = parts.map(Number);
  // Using the constructor with year/month/day interprets it as LOCAL midnight,
  // which is safer for determining the Day of the Week name.
  const localDate = new Date(y, m - 1, d);

  if (isNaN(localDate.getTime())) return dateStr;

  const dayName = localDate.toLocaleDateString('en-MY', { weekday: 'long' }).toUpperCase();

  return `${dateStr} ${dayName}`;
};

import React, { useMemo, useState } from 'react';
