            <tbody className="divide-y divide-gray-100 dark:divide-slate-700">
              {viewMode === 'daily' ? filteredData.map(entry => {
                    const eff = Number(calculateEfficiency(entry.actualQuantity, entry.planQuantity));
                    return (
                      <tr key={entry.id} className="hover:bg-gray-50 dark:hover:bg-slate-700/50">
                        <td className="px-6 py-3 font-mono text-xs">{entry.date}</td>
