                            </span>
                        </td>
                        {hasPermission(['admin', 'manager']) && (
                            <td className="px-6 py-3 text-center">
                                <button onClick={() => handleDelete(entry.id)} className="text-gray-400 hover:text-red-500"><Trash2 className="w-4 h-4" /></button>
                            </td>
                        )}
                      </tr>
                    );
              }) : monthlyData.map(m => (
                      <tr key={m.month} className="hover:bg-gray-50 dark:hover:bg-slate-700/50 transition">
                          <td className="px-6 py-4 font-bold">{m.month}</td>
                          <td className="px-6 py-4 text-right font-mono text-blue-600">{m.plan.toLocaleString()}</td>
                          <td className="px-6 py-4 text-right font-mono text-emerald-600">{m.actual.toLocaleString()}</td>
                          <td className="px-6 py-4 text-right font-bold">{m.efficiency.toFixed(1)}%</td>
                      </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

/**
 * Strictly enforces Malaysia Time (UTC+8) for all date operations.
 * This prevents the "Yesterday" bug where data entered between 12am - 8am MYT
 * is incorrectly saved as the previous day due to UTC conversion.
 */

export const getTodayISO = () => {
  // 'en-CA' locale (Canada) naturally formats to YYYY-MM-DD
  // timeZone: 'Asia/Kuala_Lumpur' forces the clock to Malaysia time
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Kuala_Lumpur',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(new Date());
};

export const getCurrentMonthISO = () => {
  // Returns YYYY-MM based on current Malaysia time
  const today = getTodayISO();
  return today.substring(0, 7);
};

export const formatDisplayDate = (dateStr: string) => {
  // Input: "2025-12-22"
  // Output: "2025-12-22 MONDAY"
  if (!dateStr) return 'Invalid Date';

  const parts = dateStr.split('-');
  if (parts.length !== 3) return dateStr;

  const [y, m, d] = parts.map(Number);

  // Use the (year, monthIndex, day) constructor. 
  // This is interpreted as local midnight, which is timezone-safe for finding the day name.
  const localDate = new Date(y, m - 1, d);

  if (isNaN(localDate.getTime())) return dateStr;

  const dayName = localDate.toLocaleDateString('en-MY', { weekday: 'long' }).toUpperCase();

  return `${dateStr} ${dayName}`;
};

