 * is incorrectly saved as the previous day due to UTC conversion.
 */

/**
 * Returns YYYY-MM-DD for current date in Malaysia
 * This is the ONLY function you should use for default input values.
 */
export const getTodayISO = (): string => {
  // 'en-CA' locale naturally formats to YYYY-MM-DD
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Kuala_Lumpur',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(new Date());
};

/**
 * Returns YYYY-MM for the current month in Malaysia
 */
export const getCurrentMonthISO = (): string => {
  const today = getTodayISO();
  return today.substring(0, 7);
};

/**
 * Normalizes any date string to YYYY-MM-DD
 */
export const normalizeDate = (dateStr: string): string => {
  if (!dateStr) return '';
  if (dateStr.includes('T')) {
    return dateStr.split('T')[0];
  }
  return dateStr;
};

/**
 * Formats a YYYY-MM-DD string for display with the weekday name
 * e.g., "2025-12-23" -> "2025-12-23 TUESDAY"
 */
export const formatDisplayDate = (dateStr: string): string => {
  if (!dateStr) return 'Invalid Date';

  const cleanDateStr = normalizeDate(dateStr);
  const parts = cleanDateStr.split('-');
  if (parts.length !== 3) return cleanDateStr;

  const [year, month, day] = parts.map(Number);

  // new Date(y, m-1, d) creates a date at midnight in LOCAL browser time.
  // This is safe for day-of-week name extraction.
  const localDate = new Date(year, month - 1, day);

  if (isNaN(localDate.getTime())) return cleanDateStr;

  const dayName = localDate.toLocaleDateString('en-MY', { weekday: 'long' }).toUpperCase();

  return `${cleanDateStr} ${dayName}`;
};

import { User, ProductionEntry, OffDay } from './types';
import { getTodayISO } from './utils/dateUtils';

export const CATEGORIES = ['Healthcare', 'Toothpaste', 'Rocksalt'] as const;
