### Why this fixes it:
1.  **Timezone Lock:** `Intl.DateTimeFormat(..., { timeZone: 'Asia/Kuala_Lumpur' })` ignores the UTC clock and calculates the date based strictly on Malaysia's offset.
2.  **String Consistency:** By using `YYYY-MM-DD` strings throughout the app instead of `Date` objects, we prevent the browser from trying to "correct" the time when saving or loading from LocalStorage.

import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { useNotification } from '../../contexts/NotificationContext';
import { StorageService } from '../../services/storageService';
import type { ProductionEntry } from '../../types';
import { formatDisplayDate, normalizeDate, getTodayISO } from '../../utils/dateUtils'; 
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer 
} from 'recharts';
import { ClipboardList, CheckCircle, RefreshCw, Download, List, Calendar, Trash2, Edit2, CalendarOff } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { EditEntryModal } from '../modals/EditEntryModal';

export const Dashboard: React.FC = () => {
  const { category, refreshKey, triggerRefresh } = useDashboard();
  const { hasPermission } = useAuth();
  const { notify } = useNotification();

  const [viewMode, setViewMode] = useState<'daily' | 'monthly'>('daily');
  const [editingEntry, setEditingEntry] = useState<ProductionEntry | null>(null);

  // Date Range State
  const [dateRange, setDateRange] = useState(() => {
      return { start: '', end: '' }; 
  });

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays()
    };
  }, [refreshKey]);

  // Consolidate data for stats and charts
  const { filteredData, stats, chartData, monthlyData } = useMemo(() => {
    const relevant = productionData.filter(d => d.category === category);

    let totalPlan = 0;
    let totalActual = 0;

    const processMap = new Map<string, {process: string, Plan: number, Actual: number}>();
    const monthlyGroups: Record<string, { plan: number, actual: number }> = {};

    relevant.forEach(d => {
      totalPlan += d.planQuantity;
      totalActual += d.actualQuantity;

      if (!processMap.has(d.process)) {
        processMap.set(d.process, { process: d.process, Plan: 0, Actual: 0 });
      }
      const p = processMap.get(d.process)!;
      p.Plan += d.planQuantity;
      p.Actual += d.actualQuantity;

      // Safe monthly grouping
      const cleanDate = normalizeDate(d.date);
      const monthKey = cleanDate.substring(0, 7); // YYYY-MM

      if (!monthlyGroups[monthKey]) {
          monthlyGroups[monthKey] = { plan: 0, actual: 0 };
      }
      monthlyGroups[monthKey].plan += d.planQuantity;
      monthlyGroups[monthKey].actual += d.actualQuantity;
    });

    const monthlyStats = Object.entries(monthlyGroups)
        .map(([month, s]) => ({
            month,
            plan: s.plan,
            actual: s.actual,
            efficiency: s.plan > 0 ? (s.actual / s.plan) * 100 : 0
        }))
        .sort((a, b) => b.month.localeCompare(a.month));

    return {
      filteredData: relevant,
      stats: { totalPlan, totalActual },
      chartData: Array.from(processMap.values()),
      monthlyData: monthlyStats
    };
  }, [productionData, category]);

  // Group data by Date for Daily View (DATA DRIVEN ONLY)
  const dailyGroups = useMemo(() => {
    if (viewMode === 'monthly') return [];

    // 1. Collect all unique dates from the filtered data AND off days
    const uniqueDates = new Set<string>();

    // Add production dates
    filteredData.forEach(d => {
        const normalized = normalizeDate(d.date);
        // Apply date range filter only if set
        if ((!dateRange.start || normalized >= dateRange.start) && 
            (!dateRange.end || normalized <= dateRange.end)) {
            uniqueDates.add(normalized);
        }
    });

    // Add off day dates
    offDays.forEach(od => {
        const normalized = normalizeDate(od.date);
        if ((!dateRange.start || normalized >= dateRange.start) && 
            (!dateRange.end || normalized <= dateRange.end)) {
            uniqueDates.add(normalized);
        }
    });

    // 2. Sort dates descending (newest first)
    const sortedDates = Array.from(uniqueDates).sort((a, b) => b.localeCompare(a));

    // 3. Create groups
    const groups = sortedDates.map(date => {
        const entries = filteredData.filter(p => normalizeDate(p.date) === date);
        const offDay = offDays.find(od => normalizeDate(od.date) === date);

        return {
            date,
            entries,
            offDay: offDay?.description
        };
    });

    return groups;
  }, [filteredData, offDays, viewMode, dateRange]);

  const handleDelete = (id: string) => {
      if(!window.confirm("Delete this record?")) return;
      const newData = productionData.filter(p => p.id !== id);
      StorageService.saveProductionData(newData);
      triggerRefresh();
      notify('info', 'Record deleted successfully.');
  };

  const calculateEfficiency = (actual: number, plan: number) => {
    if (plan === 0) return 0;
    return ((actual / plan) * 100).toFixed(0);
  };

  const downloadCSV = () => {
    let headers: string[] = [];
    let rows: (string | number)[][] = [];
    let filename = '';

    if (viewMode === 'daily') {
        headers = ["Date", "Day", "Category", "Process", "Product", "Plan", "Actual", "Efficiency %", "Batch No", "Manpower"];
        // For export, we use filteredData directly
        rows = filteredData.map(d => {
            const dateStr = formatDisplayDate(d.date);
            const parts = dateStr.split(' ');
            const datePart = parts[0]; 
            const dayNamePart = parts.slice(1).join(' ');

            return [
              datePart || normalizeDate(d.date),
              dayNamePart || '',
              d.category, 
              d.process, 
              `"${d.productName}"`, 
              d.planQuantity, 
              d.actualQuantity, 
              calculateEfficiency(d.actualQuantity, d.planQuantity), 
              d.batchNo || '', 
              d.manpower || ''
            ];
        });
        filename = `${category}_daily_log_${getTodayISO()}.csv`;
    } else {
        headers = ["Month", "Total Plan", "Total Actual", "Overall Efficiency %"];
        rows = monthlyData.map(m => [
            m.month,
            m.plan,
            m.actual,
            m.efficiency.toFixed(2)
        ]);
        filename = `${category}_monthly_summary_${getTodayISO()}.csv`;
    }

    const csvContent = "data:text/csv;charset=utf-8," 
      + [headers.join(','), ...rows.map(e => e.join(','))].join('\n');

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    notify('success', 'Export successful.');
  };

  return (
    <div className="space-y-6">
      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="glass-panel p-6 rounded-2xl border-l-4 border-blue-500 flex justify-between items-center transform transition hover:scale-[1.01]">
