import { formatDisplayDate, normalizeDate, getCurrentMonthISO, getTodayISO } from '../../utils/dateUtils'; 
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer 
} from 'recharts';
import { 
  ClipboardList, CheckCircle, RefreshCw, Download, List, Calendar, 
  Trash2, Pencil, CalendarOff 
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';

export const Dashboard: React.FC = () => {
  const { category, refreshKey, triggerRefresh } = useDashboard();
  const { hasPermission } = useAuth();

  const [viewMode, setViewMode] = useState<'daily' | 'monthly'>('daily');
  const [selectedMonth, setSelectedMonth] = useState<string>(getCurrentMonthISO());

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays()
    };
  }, [refreshKey]);

  // Consolidate data for stats and charts based on selected month
  const { dashboardStats, chartData, monthlyData, filteredData } = useMemo(() => {
    const relevant = productionData.filter(d => d.category === category);

    let monthPlan = 0;
    let monthActual = 0;

    const processMap = new Map<string, {process: string, Plan: number, Actual: number}>();
    const monthlyGroups: Record<string, { plan: number, actual: number }> = {};

    relevant.forEach(d => {
      const cleanDate = normalizeDate(d.date);
      const monthKey = cleanDate.substring(0, 7); // YYYY-MM

      // Monthly summary data
      if (!monthlyGroups[monthKey]) {
          monthlyGroups[monthKey] = { plan: 0, actual: 0 };
      }
      monthlyGroups[monthKey].plan += d.planQuantity;
      monthlyGroups[monthKey].actual += d.actualQuantity;

      // Current selected month stats & chart
      if (monthKey === selectedMonth) {
          monthPlan += d.planQuantity;
          monthActual += d.actualQuantity;

          if (!processMap.has(d.process)) {
            processMap.set(d.process, { process: d.process, Plan: 0, Actual: 0 });
          }
          const p = processMap.get(d.process)!;
          p.Plan += d.planQuantity;
          p.Actual += d.actualQuantity;
      }
    });

    const monthlySummary = Object.entries(monthlyGroups)
        .map(([month, s]) => ({
            month,
            plan: s.plan,
            actual: s.actual,
            efficiency: s.plan > 0 ? (s.actual / s.plan) * 100 : 0
        }))
        .sort((a, b) => b.month.localeCompare(a.month));

    return {
      filteredData: relevant,
      dashboardStats: { 
          plan: monthPlan, 
          actual: monthActual, 
          efficiency: monthPlan > 0 ? (monthActual / monthPlan) * 100 : 0 
      },
      chartData: Array.from(processMap.values()),
      monthlyData: monthlySummary
    };
  }, [productionData, category, selectedMonth]);

  // Group data by Date for Daily View
  const dailyGroups = useMemo(() => {
    const monthEntries = filteredData.filter(d => normalizeDate(d.date).startsWith(selectedMonth));
    const monthOffDays = offDays.filter(od => normalizeDate(od.date).startsWith(selectedMonth));

    const uniqueDates = new Set<string>();
    monthEntries.forEach(d => uniqueDates.add(normalizeDate(d.date)));
    monthOffDays.forEach(od => uniqueDates.add(normalizeDate(od.date)));

    const sortedDates = Array.from(uniqueDates).sort((a, b) => b.localeCompare(a));

    return sortedDates.map(date => ({
        date,
        entries: monthEntries.filter(p => normalizeDate(p.date) === date),
        offDay: monthOffDays.find(od => normalizeDate(od.date) === date)?.description
    }));
  }, [filteredData, offDays, selectedMonth]);

