  };

  const downloadCSV = () => {
    const headers = ["Date", "Process", "Product", "Plan", "Actual", "Batch No", "Manpower"];
    const rows = filteredData.filter(d => d.date.startsWith(selectedMonth)).map(d => [
      d.date, d.process, d.productName, d.planQuantity, d.actualQuantity, d.batchNo, d.manpower
    ]);
    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `Halagel_Report_${category}_${selectedMonth}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6 pb-10">
      {/* Stats Section */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="glass-panel p-6 rounded-2xl border-l-4 border-blue-500 shadow-sm">
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Monthly Plan ({selectedMonth})</p>
            <h3 className="text-3xl font-black mt-1 text-slate-800 dark:text-white">{dashboardStats.plan.toLocaleString()}</h3>
        </div>
        <div className="glass-panel p-6 rounded-2xl border-l-4 border-emerald-500 shadow-sm">
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Monthly Actual</p>
