        </div>
        <div className="glass-panel p-6 rounded-2xl border-l-4 border-indigo-500 shadow-sm">
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Avg Efficiency</p>
            <h3 className="text-3xl font-black mt-1 text-slate-800 dark:text-white">{dashboardStats.efficiency.toFixed(1)}%</h3>
        </div>
      </div>

      {/* Chart Section */}
      {viewMode === 'daily' && chartData.length > 0 && (
        <div className="glass-panel rounded-2xl p-6">
            <h3 className="font-bold text-lg mb-4">Production by Process</h3>
            <div className="h-64">
                <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={chartData}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} />
                        <XAxis dataKey="process" />
                        <YAxis />
                        <Tooltip />
                        <Legend />
                        <Bar dataKey="Plan" fill="#3b82f6" radius={[4, 4, 0, 0]} />
