                        <td className="px-6 py-3 font-bold text-slate-700 dark:text-slate-200">{entry.productName}</td>
                        <td className="px-6 py-3 text-right font-mono text-blue-600">{entry.planQuantity.toLocaleString()}</td>
                        <td className="px-6 py-3 text-right font-mono text-emerald-600">{entry.actualQuantity.toLocaleString()}</td>
                        <td className="px-6 py-3 text-right">
                            <span className={`px-2 py-0.5 rounded text-xs font-bold ${eff >= 100 ? 'text-emerald-500' : eff >= 80 ? 'text-blue-500' : 'text-red-500'}`}>
                                {eff}%
                            </span>
                        </td>
                        {hasPermission(['admin', 'manager']) && (
                            <td className="px-6 py-3 text-center">
                                <button onClick={() => handleDelete(entry.id)} className="text-gray-400 hover:text-red-500 p-2 rounded-full hover:bg-rose-50 dark:hover:bg-rose-900/20 transition">
                                  <Trash2 className="w-4 h-4" />
                                </button>
                            </td>
                        )}
                      </tr>
                    );
                  })
              ) : (
                  monthlyData.length === 0 ? (
                    <tr>
                      <td colSpan={4} className="px-6 py-10 text-center text-slate-400 italic">No summaries available for current filters</td>
                    </tr>
                  ) : monthlyData.map(m => (
                      <tr key={m.month} className="hover:bg-gray-50 dark:hover:bg-slate-700/50 transition">
                          <td className="px-6 py-4 font-bold text-slate-700 dark:text-slate-200">{m.month}</td>
                          <td className="px-6 py-4 text-right font-mono text-blue-600">{m.plan.toLocaleString()}</td>
                          <td className="px-6 py-4 text-right font-mono text-emerald-600">{m.actual.toLocaleString()}</td>
                          <td className="px-6 py-4 text-right font-bold">
                            <span className={m.efficiency >= 85 ? 'text-emerald-500' : 'text-rose-500'}>
                              {m.efficiency.toFixed(1)}%
                            </span>
                          </td>
                      </tr>
                  ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

