                                                        </button>
                                                        <button onClick={() => handleDelete(entry.id)} className="p-2 text-slate-500 hover:text-rose-500 hover:bg-rose-500/20 rounded-xl transition">
                                                            <Trash2 className="w-5 h-5" />
                                                        </button>
                                                    </div>
                                                </td>
                                              )}
                                          </tr>
                                      );
                                  })}
                              </tbody>
                          </table>
                      </div>
                  </div>
                );
            })}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { CATEGORIES, PROCESSES } from '../../constants';
import { ProductionEntry, Category, ProcessType } from '../../types';
import { X } from 'lucide-react';
import { getTodayISO } from '../../utils/dateUtils';

interface InputModalProps {
  onClose: () => void;
  editEntry?: ProductionEntry | null;
}

export const InputModal: React.FC<InputModalProps> = ({ onClose, editEntry }) => {
  const { user, hasPermission } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [tab, setTab] = useState<'Plan' | 'Actual'>('Plan');

  // FIX: Force initial date state to Malaysia Time YYYY-MM-DD
  const [date, setDate] = useState(getTodayISO());

  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [process, setProcess] = useState<ProcessType>(PROCESSES[0]);
  const [productName, setProductName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [manpower, setManpower] = useState('0');
  const [batchNo, setBatchNo] = useState('');

  const [plans, setPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  const inputClasses = "w-full p-2.5 rounded-lg border border-slate-200 bg-white text-slate-900 font-bold focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all shadow-sm";

  useEffect(() => {
    if (editEntry) {
      setDate(editEntry.date);
      setCategory(editEntry.category);
      setProcess(editEntry.process);
      setProductName(editEntry.productName);
      setQuantity(editEntry.planQuantity.toString());
      setManpower(editEntry.manpower?.toString() || '0');
      setBatchNo(editEntry.batchNo || '');
      setTab('Plan'); 
    } else {
      if (user?.role === 'operator') setTab('Actual');
      else if (user?.role === 'planner') setTab('Plan');
    }
  }, [editEntry, user]);

  useEffect(() => {
    if (tab === 'Actual' && !editEntry) {
        const all = StorageService.getProductionData();
        const relevant = all.filter(p => p.date === date);
        setPlans(relevant);
        setSelectedPlanId('');
    }
  }, [date, tab, editEntry]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const offDays = StorageService.getOffDays();
    if (!editEntry && offDays.some(od => od.date === date)) {
        alert("Cannot input data on an Off Day!");
        return;
    }

    const currentData = StorageService.getProductionData();

    if (editEntry) {
        const updated = currentData.map(p => {
            if (p.id === editEntry.id) {
                return { 
                    ...p, 
                    date, // Save the pure string "YYYY-MM-DD"
                    category, process, productName,
                    planQuantity: tab === 'Plan' ? parseInt(quantity) : p.planQuantity,
                    actualQuantity: tab === 'Actual' ? parseInt(quantity) : p.actualQuantity,
                    batchNo, manpower: parseInt(manpower),
                    lastUpdatedBy: user!.id, updatedAt: new Date().toISOString()
                };
            }
            return p;
        });
        StorageService.saveProductionData(updated);
        window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'Production entry updated!' } }));
    } else {
        if (tab === 'Plan') {
            const newEntry: ProductionEntry = {
                id: Date.now().toString(),
                date, // Pure string "YYYY-MM-DD"
                category, process, productName, 
                planQuantity: parseInt(quantity), actualQuantity: 0,
                lastUpdatedBy: user!.id, updatedAt: new Date().toISOString()
            };
            StorageService.saveProductionData([...currentData, newEntry]);
            window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'New production plan saved!' } }));
        } else {
            if (!selectedPlanId) return alert("Select a plan first");
            const updated = currentData.map(p => {
                if (p.id === selectedPlanId) {
                    return { 
                        ...p, 
                        actualQuantity: parseInt(quantity), batchNo, manpower: parseInt(manpower),
                        lastUpdatedBy: user!.id, updatedAt: new Date().toISOString()
                    };
                }
                return p;
            });
            StorageService.saveProductionData(updated);
            window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'Actual production recorded!' } }));
        }
    }

    triggerRefresh();
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-md shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-700">
        <div className="flex border-b border-gray-200 dark:border-slate-700">
            {!editEntry ? (
              <>
                {hasPermission(['admin', 'manager', 'planner']) && (
                    <button onClick={() => setTab('Plan')} 
                        className={`flex-1 py-4 font-bold text-center transition ${tab === 'Plan' ? 'bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600' : 'text-gray-500 hover:bg-gray-50 dark:hover:bg-slate-700'}`}>
                        Input Plan
                    </button>
                )}
                {hasPermission(['admin', 'manager', 'operator']) && (
                    <button onClick={() => setTab('Actual')} 
                        className={`flex-1 py-4 font-bold text-center transition ${tab === 'Actual' ? 'bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600' : 'text-gray-500 hover:bg-gray-50 dark:hover:bg-slate-700'}`}>
                        Input Actual
                    </button>
                )}
              </>
            ) : (
              <div className="flex-1 py-4 font-bold text-center bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 uppercase tracking-widest text-xs">
                Edit Entry
              </div>
            )}
        </div>

        <div className="p-6 relative">
            <button onClick={onClose} className="absolute top-2 right-4 text-gray-400 hover:text-red-500 transition-colors"><X /></button>

            <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                    <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Production Date</label>
                    <input 
                      type="date" 
                      required 
                      value={date} 
                      onChange={e => setDate(e.target.value)} 
                      className={inputClasses}
                    />
                </div>

                {tab === 'Plan' || editEntry ? (
                    <>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Category</label>
                                <select value={category} onChange={e => setCategory(e.target.value as Category)} className={inputClasses}>
                                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Process</label>
                                <select value={process} onChange={e => setProcess(e.target.value as ProcessType)} className={inputClasses}>
                                    {PROCESSES.map(p => <option key={p} value={p}>{p}</option>)}
                                </select>
                            </div>
                        </div>
                        <div>
                            <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Product Name</label>
                            <input type="text" required value={productName} onChange={e => setProductName(e.target.value)} className={inputClasses} />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Plan Qty</label>
                              <input type="number" required min="1" value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                          </div>
                          {editEntry && (
                            <div>
                                <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Manpower</label>
                                <input type="number" required min="0" value={manpower} onChange={e => setManpower(e.target.value)} className={inputClasses} />
                            </div>
                          )}
                        </div>
                    </>
                ) : (
                    <>
                        <div className="mb-4">
                             <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Select Job</label>
                             {plans.length === 0 ? <div className="text-sm text-gray-400 italic text-center p-4">No plans for this date</div> : (
                                 <div className="max-h-32 overflow-y-auto border rounded-lg p-2 space-y-1 dark:border-slate-700 bg-white/50">
                                     {plans.map(p => (
                                         <div key={p.id} onClick={() => setSelectedPlanId(p.id)}
                                            className={`p-2 rounded cursor-pointer text-sm ${selectedPlanId === p.id ? 'bg-indigo-100 text-indigo-900' : 'text-slate-600 hover:bg-slate-50'}`}>
                                            <div className="font-bold">{p.productName}</div>
                                            <div className="text-xs opacity-70">{p.process} | Plan: {p.planQuantity}</div>
                                         </div>
                                     ))}
                                 </div>
                             )}
                        </div>
                        {selectedPlanId && (
                            <>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Actual Qty</label>
                                        <input type="number" required value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Manpower</label>
                                        <input type="number" required value={manpower} onChange={e => setManpower(e.target.value)} className={inputClasses} />
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Batch No</label>
                                    <input type="text" required value={batchNo} onChange={e => setBatchNo(e.target.value)} className={inputClasses} />
                                </div>
                            </>
                        )}
                    </>
                )}

                <button type="submit" className={`w-full py-3 rounded-xl font-bold text-white mt-4 shadow-lg ${tab === 'Plan' ? 'bg-indigo-600' : 'bg-emerald-600'}`}>
                    {editEntry ? 'Update Record' : `Submit ${tab}`}
                </button>
            </form>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { X, Lock, User as UserIcon } from 'lucide-react';

export const LoginModal: React.FC<{ onClose: () => void }> = ({ onClose }) => {
  const { login } = useAuth();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (login(username, password)) {
      onClose();
    } else {
      setError('Invalid username or password');
    }
  };

  const inputClasses = "w-full pl-10 pr-4 py-3 rounded-xl bg-white text-slate-900 font-bold border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none transition shadow-sm";

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-2xl p-8 w-full max-sm shadow-2xl relative animate-in fade-in zoom-in duration-200">
        <button onClick={onClose} className="absolute top-4 right-4 text-gray-400 hover:text-gray-600"><X /></button>
        <div className="text-center mb-6">
            <div className="inline-flex p-3 bg-indigo-50 dark:bg-indigo-900/30 rounded-full text-indigo-600 dark:text-indigo-400 mb-3">
                <Lock className="w-6 h-6" />
            </div>
            <h3 className="text-2xl font-bold text-slate-800 dark:text-white">Welcome Back</h3>
            <p className="text-sm text-slate-500">Sign in to manage production data</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          {error && <div className="p-3 bg-red-50 text-red-600 text-xs rounded-lg text-center">{error}</div>}

          <div className="relative">
            <UserIcon className="absolute left-3 top-3 w-5 h-5 text-gray-400" />
            <input 
                type="text" placeholder="Username" required
                className={inputClasses}
                value={username} onChange={e => setUsername(e.target.value)}
            />
          </div>
          <div className="relative">
            <Lock className="absolute left-3 top-3 w-5 h-5 text-gray-400" />
            <input 
                type="password" placeholder="Password" required
                className={inputClasses}
                value={password} onChange={e => setPassword(e.target.value)}
            />
          </div>

          <button type="submit" className="w-full bg-indigo-600 text-white py-3 rounded-xl font-bold hover:bg-indigo-700 transition shadow-lg shadow-indigo-500/30">
            Log In
          </button>
        </form>

        <div className="mt-6 pt-4 border-t border-gray-100 dark:border-slate-700 text-center">
             <p className="text-xs text-gray-400 mb-2">Demo Accounts</p>
             <div className="flex justify-center gap-2 flex-wrap">
