import React, { useState } from 'react';
import { StorageService } from '../../services/storageService';
import { User, Role } from '../../types';
import { X, Trash2, Plus } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';

export const UserModal: React.FC<{ onClose: () => void }> = ({ onClose }) => {
  const { user: currentUser } = useAuth();
  const [users, setUsers] = useState<User[]>(StorageService.getUsers());
  const [newUser, setNewUser] = useState({ name: '', username: '', email: '', password: '', role: 'operator' as Role });

  const inputClasses = "p-2 rounded text-sm border border-slate-200 bg-white text-slate-900 font-bold outline-none focus:ring-2 focus:ring-purple-500/20";

  const handleAdd = (e: React.FormEvent) => {
      e.preventDefault();
      // Basic check for duplicate username
      if (users.some(u => u.username.toLowerCase() === newUser.username.toLowerCase())) {
          alert("Username already exists!");
          return;
      }
      const u: User = { 
          id: Date.now().toString(), 
          name: newUser.name, 
          username: newUser.username,
          email: newUser.email, 
          password: newUser.password, 
          role: newUser.role 
      };
      const updated = [...users, u];
      StorageService.saveUsers(updated);
      setUsers(updated);
      setNewUser({ name: '', username: '', email: '', password: '', role: 'operator' });
  };

  const handleDelete = (id: string) => {
      if(!window.confirm("Delete user?")) return;
      const updated = users.filter(u => u.id !== id);
      StorageService.saveUsers(updated);
      setUsers(updated);
  };

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-xl shadow-2xl flex flex-col max-h-[85vh] animate-in fade-in zoom-in duration-200">
        <div className="p-4 border-b border-gray-200 dark:border-slate-700 flex justify-between items-center">
            <h3 className="font-bold text-lg text-purple-600 dark:text-purple-400">User Management</h3>
            <button onClick={onClose}><X className="text-gray-400 hover:text-gray-600" /></button>
        </div>

        <div className="p-4 bg-purple-50 dark:bg-purple-900/10">
            <form onSubmit={handleAdd} className="grid grid-cols-1 md:grid-cols-2 gap-3">
                <input type="text" placeholder="Full Name" required value={newUser.name} onChange={e => setNewUser({...newUser, name: e.target.value})} className={inputClasses} />
                <input type="text" placeholder="Username" required value={newUser.username} onChange={e => setNewUser({...newUser, username: e.target.value})} className={inputClasses} />
                <input type="email" placeholder="Email" required value={newUser.email} onChange={e => setNewUser({...newUser, email: e.target.value})} className={inputClasses} />
                <input type="text" placeholder="Password" required value={newUser.password} onChange={e => setNewUser({...newUser, password: e.target.value})} className={inputClasses} />
                <select value={newUser.role} onChange={e => setNewUser({...newUser, role: e.target.value as Role})} className={inputClasses}>
                    <option value="operator">Operator</option>
                    <option value="planner">Planner</option>
                    <option value="manager">Manager</option>
                    <option value="admin">Admin</option>
                </select>
                <button type="submit" className="md:col-span-2 bg-purple-600 text-white py-2.5 rounded-lg font-bold hover:bg-purple-700 text-sm shadow-md transition">Add New User</button>
            </form>
        </div>

        <div className="flex-1 overflow-y-auto p-2">
            <table className="w-full text-sm text-left">
                <thead className="bg-gray-100 dark:bg-slate-700 font-bold text-gray-500">
                    <tr><th className="p-3">User Details</th><th className="p-3 text-center">Role</th><th className="p-3 text-right">Action</th></tr>
                </thead>
                <tbody className="divide-y divide-gray-100 dark:divide-slate-700">
                    {users.map(u => (
                        <tr key={u.id} className="hover:bg-gray-50 dark:hover:bg-slate-700/30">
                            <td className="p-3">
                                <div className="font-bold text-slate-700 dark:text-slate-200">{u.name}</div>
                                <div className="text-[10px] flex items-center gap-2 mt-1">
                                    <span className="bg-indigo-50 dark:bg-indigo-900/40 text-indigo-600 dark:text-indigo-300 px-1.5 py-0.5 rounded font-mono">@{u.username}</span>
                                    <span className="text-gray-400">{u.email}</span>
                                </div>
                            </td>
                            <td className="p-3 text-center">
                                <span className="bg-gray-100 dark:bg-slate-700 px-2.5 py-1 rounded-full text-[10px] font-black uppercase tracking-widest text-gray-600 dark:text-gray-400">
                                    {u.role}
                                </span>
                            </td>
                            <td className="p-3 text-right">
                                {currentUser?.id !== u.id && (
                                    <button onClick={() => handleDelete(u.id)} className="text-red-400 hover:text-red-600 transition p-2 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg">
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                )}
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { StorageService } from '../../services/storageService';
import { OffDay } from '../../types';
import { X, Trash2, CalendarX } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';

export const OffDayModal: React.FC<{ onClose: () => void }> = ({ onClose }) => {
  const { user } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [offDays, setOffDays] = useState<OffDay[]>(StorageService.getOffDays());
  const [date, setDate] = useState('');
  const [desc, setDesc] = useState('');

  const inputClasses = "w-full p-2 border border-slate-200 bg-white text-slate-900 font-bold rounded outline-none shadow-sm";

  const handleAdd = () => {
      if(!date) return;
      if(offDays.some(od => od.date === date)) return alert('Already off day');
      const newOd: OffDay = { id: Date.now().toString(), date, description: desc || 'Holiday', createdBy: user!.id };
      const updated = [...offDays, newOd].sort((a,b) => a.date.localeCompare(b.date));
      StorageService.saveOffDays(updated);
      setOffDays(updated);
      triggerRefresh();
      setDate(''); setDesc('');
  };

  const handleRemove = (id: string) => {
      const updated = offDays.filter(od => od.id !== id);
      StorageService.saveOffDays(updated);
      setOffDays(updated);
      triggerRefresh();
  };

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-2xl w-96 shadow-2xl p-6 animate-in fade-in zoom-in duration-200">
        <div className="flex justify-between items-center mb-4">
            <h3 className="font-bold text-lg flex items-center gap-2"><CalendarX className="text-red-500"/> Off Days</h3>
            <button onClick={onClose}><X className="text-gray-400 hover:text-red-500" /></button>
        </div>

        <div className="space-y-3 mb-4">
            <input type="date" value={date} onChange={e => setDate(e.target.value)} className={inputClasses} />
            <div className="flex gap-2">
                <input type="text" placeholder="Description" value={desc} onChange={e => setDesc(e.target.value)} className={`${inputClasses} flex-1 text-sm font-normal`} />
                <button onClick={handleAdd} className="bg-indigo-600 text-white px-4 rounded font-bold hover:bg-indigo-700 shadow-md">Add</button>
            </div>
        </div>

        <div className="h-48 overflow-y-auto border border-slate-200 rounded bg-gray-50 dark:bg-slate-900 p-2 space-y-2">
            {offDays.map(od => (
                <div key={od.id} className="flex justify-between items-center bg-white dark:bg-slate-700 p-2 rounded shadow-sm text-sm border border-slate-100 dark:border-slate-600">
                    <div>
                        <span className="font-mono font-bold text-red-500">{od.date}</span>
                        <div className="text-xs text-gray-500 dark:text-gray-300">{od.description}</div>
                    </div>
                    <button onClick={() => handleRemove(od.id)} className="text-gray-400 hover:text-red-500"><Trash2 className="w-4 h-4" /></button>
                </div>
            ))}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { StorageService } from '../../services/storageService';
import { X, Key } from 'lucide-react';

export const ChangePasswordModal: React.FC<{ onClose: () => void }> = ({ onClose }) => {
  const { user } = useAuth();
  const [currPass, setCurrPass] = useState('');
  const [newPass, setNewPass] = useState('');
  const [confirmPass, setConfirmPass] = useState('');

  const inputClasses = "w-full p-2.5 border border-slate-200 bg-white text-slate-900 font-bold rounded-lg outline-none focus:ring-2 focus:ring-indigo-500/20 shadow-sm";

  const handleSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if(newPass !== confirmPass) return alert("Passwords do not match");
      if(user?.password !== currPass) return alert("Incorrect current password");

      const users = StorageService.getUsers();
      const updated = users.map(u => u.id === user.id ? {...u, password: newPass} : u);
      StorageService.saveUsers(updated);
      alert("Password updated!");
      onClose();
  };

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-2xl w-80 shadow-2xl p-6 relative animate-in fade-in zoom-in duration-200">
        <button onClick={onClose} className="absolute top-4 right-4 text-gray-400"><X /></button>
        <h3 className="font-bold text-lg mb-4 flex items-center gap-2"><Key className="text-indigo-500"/> Change Password</h3>

        <form onSubmit={handleSubmit} className="space-y-3">
            <input type="password" placeholder="Current Password" required value={currPass} onChange={e => setCurrPass(e.target.value)} className={inputClasses} />
            <input type="password" placeholder="New Password" required value={newPass} onChange={e => setNewPass(e.target.value)} className={inputClasses} />
            <input type="password" placeholder="Confirm Password" required value={confirmPass} onChange={e => setConfirmPass(e.target.value)} className={inputClasses} />
            <button type="submit" className="w-full bg-indigo-600 text-white py-2.5 rounded-xl font-bold hover:bg-indigo-700 shadow-lg shadow-indigo-500/20 transition">Update</button>
        </form>
      </div>
    </div>
  );
};

import React, { ReactNode, useState, useEffect } from 'react';
