        <div className="p-6 border-b border-gray-100 dark:border-slate-800">
           <h1 className="font-black text-xl tracking-tight text-center">HALA<span className="text-green-600">GEL</span></h1>
           <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-0.5 text-center">Production Dashboard</p>
        </div>

        <nav className="p-4 space-y-1">
          <div className="px-3 py-2 text-[10px] font-black text-slate-400 uppercase tracking-widest">Navigation</div>
          <button
            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 border border-indigo-100 dark:border-indigo-800"
