};

import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { CATEGORIES, PROCESSES } from '../../constants';
import { ProductionEntry, Category, ProcessType } from '../../types';
import { X } from 'lucide-react';
import { getTodayISO } from '../../utils/dateUtils';

interface InputModalProps {
  onClose: () => void;
  editEntry?: ProductionEntry | null;
}

export const InputModal: React.FC<InputModalProps> = ({ onClose, editEntry }) => {
  const { user, hasPermission } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [tab, setTab] = useState<'Plan' | 'Actual'>('Plan');

  // FIX: Force initial date state to Malaysia Time YYYY-MM-DD
  const [date, setDate] = useState(getTodayISO());

  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [process, setProcess] = useState<ProcessType>(PROCESSES[0]);
  const [productName, setProductName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [manpower, setManpower] = useState('0');
  const [batchNo, setBatchNo] = useState('');

  const [plans, setPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  const inputClasses = "w-full p-2.5 rounded-lg border border-slate-200 bg-white text-slate-900 font-bold focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all shadow-sm";

  useEffect(() => {
    if (editEntry) {
      setDate(editEntry.date);
      setCategory(editEntry.category);
      setProcess(editEntry.process);
      setProductName(editEntry.productName);
      setQuantity(editEntry.planQuantity.toString());
      setManpower(editEntry.manpower?.toString() || '0');
      setBatchNo(editEntry.batchNo || '');
      setTab('Plan'); 
    } else {
      if (user?.role === 'operator') setTab('Actual');
      else if (user?.role === 'planner') setTab('Plan');
    }
  }, [editEntry, user]);

  useEffect(() => {
    if (tab === 'Actual' && !editEntry) {
        const all = StorageService.getProductionData();
        const relevant = all.filter(p => p.date === date);
        setPlans(relevant);
        setSelectedPlanId('');
    }
  }, [date, tab, editEntry]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const offDays = StorageService.getOffDays();
    if (!editEntry && offDays.some(od => od.date === date)) {
        alert("Cannot input data on an Off Day!");
        return;
    }

    const currentData = StorageService.getProductionData();

    if (editEntry) {
        const updated = currentData.map(p => {
            if (p.id === editEntry.id) {
                return { 
                    ...p, 
                    date, // Save the pure string "YYYY-MM-DD"
                    category, process, productName,
                    planQuantity: tab === 'Plan' ? parseInt(quantity) : p.planQuantity,
                    actualQuantity: tab === 'Actual' ? parseInt(quantity) : p.actualQuantity,
                    batchNo, manpower: parseInt(manpower),
                    lastUpdatedBy: user!.id, updatedAt: new Date().toISOString()
                };
            }
            return p;
        });
        StorageService.saveProductionData(updated);
        window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'Production entry updated!' } }));
    } else {
        if (tab === 'Plan') {
            const newEntry: ProductionEntry = {
                id: Date.now().toString(),
                date, // Pure string "YYYY-MM-DD"
                category, process, productName, 
                planQuantity: parseInt(quantity), actualQuantity: 0,
                lastUpdatedBy: user!.id, updatedAt: new Date().toISOString()
            };
            StorageService.saveProductionData([...currentData, newEntry]);
            window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'New production plan saved!' } }));
        } else {
            if (!selectedPlanId) return alert("Select a plan first");
            const updated = currentData.map(p => {
                if (p.id === selectedPlanId) {
                    return { 
                        ...p, 
                        actualQuantity: parseInt(quantity), batchNo, manpower: parseInt(manpower),
                        lastUpdatedBy: user!.id, updatedAt: new Date().toISOString()
                    };
                }
                return p;
            });
            StorageService.saveProductionData(updated);
            window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'Actual production recorded!' } }));
        }
    }

    triggerRefresh();
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-md shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-700">
        <div className="flex border-b border-gray-200 dark:border-slate-700">
            {!editEntry ? (
              <>
                {hasPermission(['admin', 'manager', 'planner']) && (
                    <button onClick={() => setTab('Plan')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Plan' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        Production Plan
                    </button>
                )}
                {hasPermission(['admin', 'manager', 'operator']) && (
                    <button onClick={() => setTab('Actual')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Actual' ? 'border-emerald-500 text-emerald-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        Production Actual
                    </button>
                )}
              </>
            ) : (
              <div className="flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center text-indigo-600 border-b-2 border-indigo-600">
                Editing Record
              </div>
            )}
        </div>

        <div className="p-6 relative">
            <button onClick={onClose} className="absolute top-2 right-4 text-slate-300 hover:text-rose-500 transition-colors"><X className="w-5 h-5" /></button>

            <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Production Date</label>
                    <input 
                      type="date" 
                      required 
                      value={date} 
                      onChange={e => setDate(e.target.value)} 
                      className={inputClasses}
                    />
                </div>

                {tab === 'Plan' || editEntry ? (
                    <>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Category</label>
                                <select value={category} onChange={e => setCategory(e.target.value as Category)} className={inputClasses}>
                                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Process</label>
                                <select value={process} onChange={e => setProcess(e.target.value as ProcessType)} className={inputClasses}>
                                    {PROCESSES.map(p => <option key={p} value={p}>{p}</option>)}
                                </select>
                            </div>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Product Name</label>
                            <input type="text" required value={productName} onChange={e => setProductName(e.target.value)} className={inputClasses} placeholder="Enter name..." />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Plan Qty</label>
                              <input type="number" required min="1" value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                          </div>
                          {editEntry && (
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Manpower</label>
                                <input type="number" required min="0" value={manpower} onChange={e => setManpower(e.target.value)} className={inputClasses} />
                            </div>
                          )}
                        </div>
                    </>
                ) : (
                    <>
                        <div className="mb-4">
                             <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Select Active Job</label>
                             {plans.length === 0 ? <div className="text-xs text-slate-400 italic text-center p-6 border-2 border-dashed rounded-xl">No plans scheduled for this date.</div> : (
                                 <div className="max-h-40 overflow-y-auto border rounded-xl p-2 space-y-1 dark:border-slate-700 bg-slate-50 dark:bg-slate-900/50">
                                     {plans.map(p => (
                                         <div key={p.id} onClick={() => setSelectedPlanId(p.id)}
                                            className={`p-3 rounded-lg cursor-pointer transition ${selectedPlanId === p.id ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-600 dark:text-slate-300 hover:bg-white dark:hover:bg-slate-800'}`}>
                                            <div className="font-black text-sm">{p.productName}</div>
                                            <div className={`text-[10px] font-bold uppercase ${selectedPlanId === p.id ? 'text-indigo-100' : 'text-slate-400'}`}>{p.process} • Plan: {p.planQuantity}</div>
                                         </div>
                                     ))}
                                 </div>
                             )}
                        </div>
                        {selectedPlanId && (
                            <>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Actual Qty</label>
                                        <input type="number" required value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                                    </div>
                                    <div>
                                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Manpower</label>
                                        <input type="number" required value={manpower} onChange={e => setManpower(e.target.value)} className={inputClasses} />
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Batch Number</label>
                                    <input type="text" required value={batchNo} onChange={e => setBatchNo(e.target.value)} className={inputClasses} placeholder="Enter batch ID..." />
                                </div>
                            </>
                        )}
                    </>
                )}

                <button type="submit" className={`w-full py-4 rounded-xl font-black text-xs uppercase tracking-[0.2em] text-white mt-6 shadow-xl transition hover:opacity-90 ${tab === 'Plan' ? 'bg-slate-900 dark:bg-indigo-600 shadow-indigo-500/10' : 'bg-emerald-600 shadow-emerald-500/10'}`}>
                    {editEntry ? 'Save Changes' : `Confirm ${tab} Entry`}
                </button>
            </form>
        </div>
      </div>
    </div>
  );
};

import React, { ReactNode, useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { Category, ProductionEntry } from '../../types';
import { CATEGORIES } from '../../constants';
import { LoginModal } from '../modals/LoginModal';
import { InputModal } from '../modals/InputModal';
import { UserModal } from '../modals/UserModal';
import { OffDayModal } from '../modals/OffDayModal';
import { ChangePasswordModal } from '../modals/ChangePasswordModal';
import { 
  Menu, X, Moon, Sun, Plus, LogOut, Key, 
  CalendarX, Users, LayoutDashboard, CheckCircle, Bell, LogIn, Info
} from 'lucide-react';

interface LayoutProps {
  children: ReactNode;
}

export const Layout: React.FC<LayoutProps> = ({ children }) => {
  const { user, logout, hasPermission } = useAuth();
  const { category, setCategory, isDarkMode, toggleDarkMode } = useDashboard();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [notification, setNotification] = useState<{ message: string; type: 'success' | 'info' } | null>(null);

  // Modals state
  const [showLogin, setShowLogin] = useState(false);
  const [showInput, setShowInput] = useState(false);
  const [entryToEdit, setEntryToEdit] = useState<ProductionEntry | null>(null);
  const [showUsers, setShowUsers] = useState(false);
  const [showOffDays, setShowOffDays] = useState(false);
  const [showChangePass, setShowChangePass] = useState(false);

  useEffect(() => {
    const handleNotify = (e: any) => {
      setNotification({ message: e.detail.message, type: e.detail.type || 'success' });
      setTimeout(() => setNotification(null), 4000);
    };
    const handleEditEntry = (e: any) => {
      setEntryToEdit(e.detail);
      setShowInput(true);
    };

    window.addEventListener('app-notification', handleNotify);
    window.addEventListener('edit-production-entry', handleEditEntry);

    return () => {
      window.removeEventListener('app-notification', handleNotify);
      window.removeEventListener('edit-production-entry', handleEditEntry);
    };
  }, []);

  // Show welcome notification once user logs in
  useEffect(() => {
    if (user) {
      setNotification({ message: `Logged in as ${user.name}`, type: 'info' });
      setShowLogin(false);
      setTimeout(() => setNotification(null), 3000);
    }
  }, [user?.id]);

  const closeInputModal = () => {
    setShowInput(false);
    setEntryToEdit(null);
  };

  const handleLogout = () => {
    window.dispatchEvent(new CustomEvent('app-notification', { 
      detail: { message: 'Logged out successfully', type: 'info' } 
    }));
    setTimeout(() => logout(), 500); // Small delay to show notification before clearing context
  };

  return (
    <div className="flex h-screen overflow-hidden bg-gray-50 dark:bg-slate-900 text-slate-800 dark:text-slate-100 font-sans">
      {/* Normal Notification Toast */}
      {notification && (
        <div className="fixed top-4 right-4 z-[100] animate-in fade-in slide-in-from-right-4 duration-300">
          <div className={`flex items-center gap-3 px-5 py-4 rounded-xl shadow-xl border bg-white dark:bg-slate-800 ${
            notification.type === 'success' ? 'border-emerald-500' : 'border-indigo-500'
          }`}>
            <div className={`p-1.5 rounded-full ${notification.type === 'success' ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-100 text-indigo-600'}`}>
              {notification.type === 'success' ? <CheckCircle className="w-4 h-4" /> : <Info className="w-4 h-4" />}
            </div>
            <div>
              <p className="text-xs font-black uppercase text-slate-400 tracking-widest leading-none mb-1">System Message</p>
              <p className="text-sm font-bold text-slate-800 dark:text-white">{notification.message}</p>
            </div>
            <button onClick={() => setNotification(null)} className="ml-4 text-slate-300 hover:text-slate-500">
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}

      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-white dark:bg-slate-850 border-r border-gray-200 dark:border-slate-700 shadow-xl overflow-y-auto transform transition-transform duration-300 ease-in-out
        md:relative md:translate-x-0
        ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-6 border-b border-gray-100 dark:border-slate-800">
           <h1 className="font-black text-xl tracking-tight text-center">HALA<span className="text-green-600">GEL</span></h1>
           <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-0.5 text-center">Production Dashboard</p>
        </div>

        <nav className="p-4 space-y-1">
          <div className="px-3 py-2 text-[10px] font-black text-slate-400 uppercase tracking-widest">Navigation</div>
          <button
            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 border border-indigo-100 dark:border-indigo-800"
          >
            <LayoutDashboard className="w-4 h-4" /> Dashboard
          </button>

          <div className="pt-6 px-3 py-2 text-[10px] font-black text-slate-400 uppercase tracking-widest">Categories</div>
          {CATEGORIES.map(cat => (
            <button
              key={cat}
              onClick={() => { setCategory(cat as Category); setIsMobileMenuOpen(false); }}
              className={`w-full flex items-center justify-between px-4 py-3 rounded-xl text-sm font-bold transition-all ${
                category === cat 
                ? 'bg-slate-100 dark:bg-slate-800 text-indigo-600 dark:text-indigo-400' 
                : 'text-slate-500 hover:bg-gray-50 dark:hover:bg-slate-800'
              }`}
            >
              {cat}
            </button>
          ))}

          {user && (
            <>
              <div className="pt-6 px-3 py-2 text-[10px] font-black text-slate-400 uppercase tracking-widest">Data Management</div>
              <button onClick={() => setShowInput(true)} className="w-full flex items-center gap-3 px-4 py-3 text-sm font-bold text-slate-500 hover:bg-gray-50 dark:hover:bg-slate-800 rounded-xl">
                <Plus className="w-4 h-4 text-emerald-500" /> Input Data
              </button>
              <button onClick={() => setShowOffDays(true)} className="w-full flex items-center gap-3 px-4 py-3 text-sm font-bold text-slate-500 hover:bg-gray-50 dark:hover:bg-slate-800 rounded-xl">
                <CalendarX className="w-4 h-4 text-rose-500" /> Manage Off Days
              </button>

              {hasPermission(['admin']) && (
                <button onClick={() => setShowUsers(true)} className="w-full flex items-center gap-3 px-4 py-3 text-sm font-bold text-slate-500 hover:bg-gray-50 dark:hover:bg-slate-800 rounded-xl">
                  <Users className="w-4 h-4 text-amber-500" /> User Access
                </button>
              )}

              <div className="pt-6 px-3 py-2 text-[10px] font-black text-slate-400 uppercase tracking-widest">Account</div>
              <button onClick={() => setShowChangePass(true)} className="w-full flex items-center gap-3 px-4 py-3 text-sm font-bold text-slate-500 hover:bg-gray-50 dark:hover:bg-slate-800 rounded-xl">
                <Key className="w-4 h-4 text-indigo-500" /> Password
              </button>
              <button onClick={handleLogout} className="w-full flex items-center gap-3 px-4 py-3 text-sm font-bold text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-xl">
                <LogOut className="w-4 h-4" /> Sign Out
              </button>
            </>
          )}
        </nav>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-16 bg-white dark:bg-slate-850 border-b border-gray-200 dark:border-slate-700 flex items-center justify-between px-6 shrink-0 z-20">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsMobileMenuOpen(true)} className="md:hidden p-2 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-lg">
              <Menu className="w-6 h-6" />
            </button>
            <h2 className="font-black text-lg hidden md:block">HALAGEL Manufacturing</h2>
          </div>

          <div className="flex items-center gap-4">
            <button onClick={toggleDarkMode} className="p-2.5 text-slate-500 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-xl transition">
              {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
            </button>

            {user ? (
              <div className="flex items-center gap-3 px-3 py-1.5 bg-gray-50 dark:bg-slate-800 rounded-xl border border-gray-100 dark:border-slate-700">
                 <div className="w-8 h-8 rounded-full bg-indigo-500 flex items-center justify-center text-white text-xs font-bold uppercase shadow-sm">
                   {user.name.charAt(0)}
                 </div>
                 <div className="hidden sm:block text-left">
                    <p className="text-[10px] font-black uppercase text-indigo-500 leading-none">{user.role}</p>
                    <p className="text-xs font-bold">{user.name}</p>
                 </div>
              </div>
            ) : (
              <button 
                onClick={() => setShowLogin(true)}
                className="flex items-center gap-2 px-4 py-2 bg-slate-900 dark:bg-slate-700 text-white text-xs font-bold rounded-xl hover:bg-slate-800 transition shadow-md"
              >
                <LogIn className="w-4 h-4" />
                Login
              </button>
            )}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar">
          {children}
        </div>
      </main>

      {showLogin && <LoginModal onClose={() => setShowLogin(false)} />}
      {showInput && <InputModal onClose={closeInputModal} editEntry={entryToEdit} />}
      {showOffDays && <OffDayModal onClose={() => setShowOffDays(false)} />}
      {showUsers && <UserModal onClose={() => setShowUsers(false)} />}
      {showChangePass && <ChangePasswordModal onClose={() => setShowChangePass(false)} />}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { CATEGORIES, PROCESSES } from '../../constants';
import { ProductionEntry, Category, ProcessType } from '../../types';
import { X } from 'lucide-react';
import { getTodayISO } from '../../utils/dateUtils';

interface InputModalProps {
  onClose: () => void;
  editEntry?: ProductionEntry | null;
}

export const InputModal: React.FC<InputModalProps> = ({ onClose, editEntry }) => {
  const { user, hasPermission } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [tab, setTab] = useState<'Plan' | 'Actual'>('Plan');

  // FIX: Force initial date state to Malaysia Time YYYY-MM-DD
  const [date, setDate] = useState(getTodayISO());

  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [process, setProcess] = useState<ProcessType>(PROCESSES[0]);
  const [productName, setProductName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [manpower, setManpower] = useState('0');
  const [batchNo, setBatchNo] = useState('');

  const [plans, setPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  const inputClasses = "w-full p-2.5 rounded-lg border border-slate-200 bg-white text-slate-900 font-bold focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all shadow-sm";

  useEffect(() => {
    if (editEntry) {
      setDate(editEntry.date);
      setCategory(editEntry.category);
      setProcess(editEntry.process);
      setProductName(editEntry.productName);
      setQuantity(editEntry.planQuantity.toString());
      setManpower(editEntry.manpower?.toString() || '0');
      setBatchNo(editEntry.batchNo || '');
      setTab('Plan'); 
    } else {
      if (user?.role === 'operator') setTab('Actual');
      else if (user?.role === 'planner') setTab('Plan');
    }
  }, [editEntry, user]);

  useEffect(() => {
    if (tab === 'Actual' && !editEntry) {
        const all = StorageService.getProductionData();
        const relevant = all.filter(p => p.date === date);
        setPlans(relevant);
        setSelectedPlanId('');
    }
  }, [date, tab, editEntry]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const offDays = StorageService.getOffDays();
    if (!editEntry && offDays.some(od => od.date === date)) {
        alert("Cannot input data on an Off Day!");
        return;
    }

    const currentData = StorageService.getProductionData();

    if (editEntry) {
        const updated = currentData.map(p => {
            if (p.id === editEntry.id) {
                return { 
                    ...p, 
                    date, // Save the pure string "YYYY-MM-DD"
                    category, process, productName,
                    planQuantity: tab === 'Plan' ? parseInt(quantity) : p.planQuantity,
                    actualQuantity: tab === 'Actual' ? parseInt(quantity) : p.actualQuantity,
                    batchNo, manpower: parseInt(manpower),
                    lastUpdatedBy: user!.id, updatedAt: new Date().toISOString()
                };
            }
            return p;
        });
        StorageService.saveProductionData(updated);
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: 'PRODUCTION DATA SUBMITTED SUCCESSFULLY', type: 'success' } 
        }));
    } else {
        if (tab === 'Plan') {
            const newEntry: ProductionEntry = {
                id: Date.now().toString(),
                date, // Pure string "YYYY-MM-DD"
                category, process, productName, 
                planQuantity: parseInt(quantity), actualQuantity: 0,
                lastUpdatedBy: user!.id, updatedAt: new Date().toISOString()
            };
            StorageService.saveProductionData([...currentData, newEntry]);
            window.dispatchEvent(new CustomEvent('app-notification', { 
                detail: { message: 'PRODUCTION DATA SUBMITTED SUCCESSFULLY', type: 'success' } 
            }));
        } else {
