             <div className="text-center">
               <h1 className="font-extrabold text-2xl tracking-tight text-slate-800 dark:text-white">HALA<span className="text-green-600">GEL</span></h1>
               <p className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.15em]">Manufacturing System</p>
