        </div>

        <div className="grid grid-cols-2 lg:grid-cols-5 gap-4">
          {dashboardData.chartData.map(proc => {
            const eff = proc.Plan > 0 ? (proc.Actual / proc.Plan) * 100 : 0;
            return (
