      {showLogin && <LoginModal onClose={() => setShowLogin(false)} />}
      {showInput && <InputModal onClose={() => { setShowInput(false); setEntryToEdit(null); }} editEntry={entryToEdit} />}
      {showOffDays && <OffDayModal onClose={() => setShowOffDays(false)} />}
      {showUsers && <UserModal onClose={() => setShowUsers(false)} />}
      {showChangePass && <ChangePasswordModal onClose={() => setShowChangePass(false)} />}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { CATEGORIES, PROCESSES } from '../../constants';
import { ProductionEntry, Category, ProcessType } from '../../types';
import { X, Loader2, AlertTriangle, Palmtree } from 'lucide-react';
import { getTodayISO } from '../../utils/dateUtils';

interface InputModalProps {
  onClose: () => void;
  editEntry?: ProductionEntry | null;
}

export const InputModal: React.FC<InputModalProps> = ({ onClose, editEntry }) => {
  const { user, hasPermission } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [tab, setTab] = useState<'Plan' | 'Actual'>('Plan');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [date, setDate] = useState(getTodayISO());
  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [process, setProcess] = useState<ProcessType>(PROCESSES[0]);
  const [productName, setProductName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [manpower, setManpower] = useState('0');
  const [batchNo, setBatchNo] = useState('');

  const [plans, setPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  const offDays = useMemo(() => StorageService.getOffDays(), []);
  const currentOffDay = useMemo(() => offDays.find(od => od.date === date), [date, offDays]);

  const inputClasses = "w-full p-2.5 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-slate-900 dark:text-white font-bold focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all shadow-sm";

  useEffect(() => {
    if (currentOffDay && !editEntry) {
      window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: `PUBLIC HOLIDAY: ${currentOffDay.description}`, type: 'info' } 
      }));
    }
  }, [currentOffDay, editEntry]);

  useEffect(() => {
    if (editEntry) {
      setDate(editEntry.date);
      setCategory(editEntry.category);
      setProcess(editEntry.process);
      setProductName(editEntry.productName);
      setQuantity(editEntry.planQuantity.toString());
      setManpower(editEntry.manpower?.toString() || '0');
      setBatchNo(editEntry.batchNo || '');
      setTab('Plan'); 
    } else {
      if (user?.role === 'operator') setTab('Actual');
      else if (user?.role === 'planner') setTab('Plan');
    }
  }, [editEntry, user]);

  useEffect(() => {
    if (tab === 'Actual' && !editEntry) {
        const all = StorageService.getProductionData();
        const relevant = all.filter(p => p.date === date);
        setPlans(relevant);
        setSelectedPlanId('');
    }
  }, [date, tab, editEntry]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    if (!editEntry && currentOffDay) {
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: `ENTRY RESTRICTED: Today is ${currentOffDay.description}`, type: 'info' } 
        }));
        setIsSubmitting(false);
        return;
    }

    const currentData = StorageService.getProductionData();

    try {
        if (editEntry) {
            const updated = currentData.map(p => {
                if (p.id === editEntry.id) {
                    return { 
                        ...p, 
                        date, category, process, productName,
                        planQuantity: tab === 'Plan' ? parseInt(quantity) : p.planQuantity,
                        actualQuantity: tab === 'Actual' ? parseInt(quantity) : p.actualQuantity,
                        batchNo, manpower: parseInt(manpower),
                        lastUpdatedBy: user!.id, updatedAt: new Date().toISOString()
                    };
                }
                return p;
            });
            StorageService.saveProductionData(updated);
            window.dispatchEvent(new CustomEvent('app-notification', { 
              detail: { message: 'PRODUCTION RECORD UPDATED', type: 'success' } 
            }));
        } else {
            if (tab === 'Plan') {
                const newEntry: ProductionEntry = {
                    id: Date.now().toString(),
                    date, category, process, productName, 
                    planQuantity: parseInt(quantity), actualQuantity: 0,
                    lastUpdatedBy: user!.id, updatedAt: new Date().toISOString()
                };
                StorageService.saveProductionData([...currentData, newEntry]);
                window.dispatchEvent(new CustomEvent('app-notification', { 
                  detail: { message: 'PRODUCTION PLAN SUBMITTED', type: 'success' } 
                }));
            } else {
                if (!selectedPlanId) throw new Error("Please select a plan");
                const updated = currentData.map(p => {
                    if (p.id === selectedPlanId) {
                        return { 
                            ...p, 
                            actualQuantity: parseInt(quantity), batchNo, manpower: parseInt(manpower),
                            lastUpdatedBy: user!.id, updatedAt: new Date().toISOString()
                        };
                    }
                    return p;
                });
                StorageService.saveProductionData(updated);
                window.dispatchEvent(new CustomEvent('app-notification', { 
                  detail: { message: 'ACTUAL PRODUCTION RECORDED', type: 'success' } 
                }));
            }
        }

        triggerRefresh();
        onClose();
    } catch (err: any) {
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: err.message || 'Operation failed', type: 'info' } 
        }));
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-md shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-700 relative">
        {isSubmitting && (
            <div className="absolute inset-0 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm z-10 flex flex-col items-center justify-center">
                <Loader2 className="w-10 h-10 text-indigo-600 animate-spin mb-2" />
                <p className="text-xs font-black uppercase tracking-widest text-indigo-600">Syncing with system...</p>
            </div>
        )}

        <div className="flex border-b border-gray-200 dark:border-slate-700">
            {!editEntry ? (
              <>
                {hasPermission(['admin', 'manager', 'planner']) && (
                    <button onClick={() => setTab('Plan')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Plan' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        Production Plan
                    </button>
                )}
                {hasPermission(['admin', 'manager', 'operator']) && (
                    <button onClick={() => setTab('Actual')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Actual' ? 'border-emerald-500 text-emerald-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        Production Actual
                    </button>
                )}
              </>
            ) : (
              <div className="flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center text-indigo-600 border-b-2 border-indigo-600">
                Editing Record
              </div>
            )}
        </div>

        <div className="p-6 relative">
            <button onClick={onClose} className="absolute top-2 right-4 text-slate-300 hover:text-rose-500 transition-colors"><X className="w-5 h-5" /></button>

            <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Production Date</label>
                    <input type="date" required value={date} onChange={e => setDate(e.target.value)} className={inputClasses} />

                    {currentOffDay && (
                      <div className="mt-3 p-3 bg-amber-50 dark:bg-amber-900/20 border border-amber-300 dark:border-amber-700 rounded-xl flex items-center gap-3 animate-pulse shadow-sm">
                        <div className="p-2 bg-amber-500 text-white rounded-lg shadow-md">
                          <Palmtree className="w-4 h-4" />
                        </div>
                        <div className="flex-1">
                          <p className="text-[10px] font-black text-amber-700 dark:text-amber-400 uppercase tracking-widest leading-none mb-1">System Warning</p>
                          <p className="text-xs font-black text-slate-900 dark:text-amber-50">{currentOffDay.description || 'OFF DAY'}</p>
                        </div>
                        <AlertTriangle className="w-5 h-5 text-amber-500" />
                      </div>
                    )}
                </div>

                {tab === 'Plan' || editEntry ? (
                    <>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Category</label>
                                <select value={category} onChange={e => setCategory(e.target.value as Category)} className={inputClasses}>
                                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Process</label>
                                <select value={process} onChange={e => setProcess(e.target.value as ProcessType)} className={inputClasses}>
                                    {PROCESSES.map(p => <option key={p} value={p}>{p}</option>)}
                                </select>
                            </div>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Product Name</label>
                            <input type="text" required value={productName} onChange={e => setProductName(e.target.value)} className={inputClasses} placeholder="Enter name..." />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Plan Qty</label>
                              <input type="number" required min="1" value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                          </div>
                          {editEntry && (
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Manpower</label>
                                <input type="number" required min="0" value={manpower} onChange={e => setManpower(e.target.value)} className={inputClasses} />
                            </div>
                          )}
                        </div>
                    </>
                ) : (
                    <>
                        <div className="mb-4">
                             <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Select Active Job</label>
                             {plans.length === 0 ? <div className="text-xs text-slate-400 italic text-center p-6 border-2 border-dashed rounded-xl">No plans scheduled for this date.</div> : (
                                 <div className="max-h-40 overflow-y-auto border rounded-xl p-2 space-y-1 dark:border-slate-700 bg-slate-50 dark:bg-slate-900/50">
                                     {plans.map(p => (
                                         <div key={p.id} onClick={() => setSelectedPlanId(p.id)}
                                            className={`p-3 rounded-lg cursor-pointer transition ${selectedPlanId === p.id ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-600 dark:text-slate-300 hover:bg-white dark:hover:bg-slate-800'}`}>
                                            <div className="font-black text-sm">{p.productName}</div>
                                            <div className={`text-[10px] font-bold uppercase ${selectedPlanId === p.id ? 'text-indigo-100' : 'text-slate-400'}`}>{p.process} • Plan: {p.planQuantity}</div>
                                         </div>
                                     ))}
                                 </div>
                             )}
                        </div>
                        {selectedPlanId && (
                            <>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Actual Qty</label>
                                        <input type="number" required value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                                    </div>
                                    <div>
                                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Manpower</label>
                                        <input type="number" required value={manpower} onChange={e => setManpower(e.target.value)} className={inputClasses} />
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Batch Number</label>
                                    <input type="text" required value={batchNo} onChange={e => setBatchNo(e.target.value)} className={inputClasses} placeholder="Enter batch ID..." />
                                </div>
                            </>
                        )}
                    </>
                )}

                <button 
                    type="submit" 
                    disabled={isSubmitting || (!editEntry && !!currentOffDay)} 
                    className={`w-full py-4 rounded-xl font-black text-xs uppercase tracking-[0.2em] text-white mt-6 shadow-xl transition hover:opacity-90 disabled:opacity-50 disabled:cursor-not-allowed ${
                        !!currentOffDay && !editEntry ? 'bg-amber-600' : 
                        tab === 'Plan' ? 'bg-slate-900 dark:bg-indigo-600 shadow-indigo-500/10' : 
                        'bg-emerald-600 shadow-emerald-500/10'
                    }`}
                >
                    {isSubmitting ? 'Syncing...' : (!!currentOffDay && !editEntry ? 'Holiday Entry Locked' : (editEntry ? 'Save Changes' : `Confirm ${tab} Entry`))}
                </button>
            </form>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { CATEGORIES, PROCESSES } from '../../constants';
import { StorageService } from '../../services/storageService';
import { useAuth } from '../../contexts/AuthContext';
import { ProductionEntry } from '../../types';
import { AlertCircle, CheckCircle2, Palmtree } from 'lucide-react';
import { getTodayISO } from '../../utils/dateUtils';

export const InputPlan: React.FC = () => {
  const { user } = useAuth();
  const [formData, setFormData] = useState({
    date: getTodayISO(),
    category: CATEGORIES[0],
    process: PROCESSES[0],
    productName: '',
    quantity: ''
  });
  const [msg, setMsg] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  const offDays = useMemo(() => StorageService.getOffDays(), []);
  const currentOffDay = useMemo(() => offDays.find(od => od.date === formData.date), [formData.date, offDays]);

  useEffect(() => {
    if (currentOffDay) {
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: `HOLIDAY ALERT: ${currentOffDay.description}`, type: 'info' } 
        }));
    }
  }, [currentOffDay]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (currentOffDay) {
      setMsg({ type: 'error', text: `Selected date is an Off Day: ${currentOffDay.description}.` });
      return;
    }

    if (!formData.productName || !formData.quantity) {
      setMsg({ type: 'error', text: 'Please fill all required fields.' });
      return;
    }

    try {
      const entries = StorageService.getProductionData();

      const newEntry: ProductionEntry = {
        id: Date.now().toString(),
        date: formData.date,
        category: formData.category as any,
        process: formData.process as any,
        productName: formData.productName,
        planQuantity: parseInt(formData.quantity),
        actualQuantity: 0,
        lastUpdatedBy: user!.id,
        updatedAt: new Date().toISOString()
      };

      StorageService.saveProductionData([...entries, newEntry]);
      StorageService.addLog({
        userId: user!.id,
        userName: user!.name,
        action: 'ADD_PLAN',
        details: `Planned ${newEntry.planQuantity} for ${newEntry.productName} on ${newEntry.date}`
      });

      setMsg({ type: 'success', text: 'Plan entry added successfully.' });
      setFormData({ ...formData, productName: '', quantity: '' });

      window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: 'PRODUCTION PLAN SUBMITTED', type: 'success' } 
      }));
    } catch (err) {
      setMsg({ type: 'error', text: 'Failed to save data.' });
    }
  };

  return (
    <div className="max-w-2xl mx-auto">
      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 p-8">
        <h2 className="text-2xl font-bold text-gray-800 dark:text-white mb-6">Input Production Plan</h2>

        {msg && (
          <div className={`p-4 rounded-lg mb-6 flex items-center ${msg.type === 'success' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>
            {msg.type === 'success' ? <CheckCircle2 className="w-5 h-5 mr-2" /> : <AlertCircle className="w-5 h-5 mr-2" />}
            {msg.text}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Date</label>
              <input 
                type="date" 
                required
                className="w-full px-4 py-2 border border-gray-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500 dark:bg-slate-900 dark:text-white"
                value={formData.date}
                onChange={e => setFormData({...formData, date: e.target.value})}
              />

              {currentOffDay && (
                <div className="mt-3 p-3 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-xl flex items-center gap-3">
                  <Palmtree className="w-5 h-5 text-amber-500 shrink-0" />
                  <div className="flex-1">
                    <p className="text-[10px] font-black text-amber-600 uppercase tracking-widest leading-none mb-1">Public Holiday</p>
                    <p className="text-xs font-bold text-slate-700 dark:text-amber-100">{currentOffDay.description}</p>
                  </div>
                </div>
              )}
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Category</label>
              <select 
                className="w-full px-4 py-2 border border-gray-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500 dark:bg-slate-900 dark:text-white"
                value={formData.category}
                onChange={e => setFormData({...formData, category: e.target.value as any})}
              >
                {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Process</label>
              <select 
                className="w-full px-4 py-2 border border-gray-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500 dark:bg-slate-900 dark:text-white"
                value={formData.process}
                onChange={e => setFormData({...formData, process: e.target.value as any})}
              >
                {PROCESSES.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Plan Quantity</label>
              <input 
                type="number" 
                min="1"
                required
                className="w-full px-4 py-2 border border-gray-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500 dark:bg-slate-900 dark:text-white"
                value={formData.quantity}
                onChange={e => setFormData({...formData, quantity: e.target.value})}
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Product Name</label>
            <input 
              type="text" 
              required
              placeholder="e.g. Pain Relief Gel 50g"
              className="w-full px-4 py-2 border border-gray-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500 dark:bg-slate-900 dark:text-white"
              value={formData.productName}
              onChange={e => setFormData({...formData, productName: e.target.value})}
            />
          </div>

          <div className="pt-4">
            <button 
              type="submit"
              disabled={!!currentOffDay}
              className="w-full bg-brand-600 text-white font-semibold py-2.5 rounded-lg hover:bg-brand-700 transition-colors shadow-sm disabled:bg-gray-400 disabled:cursor-not-allowed"
            >
              {currentOffDay ? 'Off Day - Entry Locked' : 'Submit Plan'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from '../../services/storageService';
import { useAuth } from '../../contexts/AuthContext';
import { ProductionEntry } from '../../types';
import { AlertCircle, CheckCircle2, Palmtree } from 'lucide-react';
import { getTodayISO } from '../../utils/dateUtils';

export const InputActual: React.FC = () => {
  const { user } = useAuth();
  const [date, setDate] = useState(getTodayISO());

  const [pendingPlans, setPendingPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  const [formData, setFormData] = useState({
    actualQty: '',
    manpower: '',
    batchNo: ''
  });

  const [msg, setMsg] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  const offDays = useMemo(() => StorageService.getOffDays(), []);
  const currentOffDay = useMemo(() => offDays.find(od => od.date === date), [date, offDays]);

  useEffect(() => {
    if (currentOffDay) {
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: `HOLIDAY DETECTED: ${currentOffDay.description}`, type: 'info' } 
        }));
    }
  }, [currentOffDay]);

  useEffect(() => {
    const all = StorageService.getProductionData();
    const forDate = all.filter(p => p.date === date);
    setPendingPlans(forDate);
    setSelectedPlanId('');
    setFormData({ actualQty: '', manpower: '', batchNo: '' });
  }, [date]);

  const handleAutoBatch = () => {
    const r = Math.floor(Math.random() * 10000);
    const b = `B-${date.replace(/-/g, '')}-${r}`;
    setFormData(prev => ({ ...prev, batchNo: b }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (currentOffDay) {
      setMsg({ type: 'error', text: 'Cannot enter data on an Off Day.' });
      return;
    }

    if (!selectedPlanId) {
      setMsg({ type: 'error', text: 'Please select a production plan to update.' });
      return;
    }

    try {
      const allData = StorageService.getProductionData();
      const updatedData = allData.map(entry => {
        if (entry.id === selectedPlanId) {
          return {
            ...entry,
            actualQuantity: parseInt(formData.actualQty),
            manpower: parseInt(formData.manpower),
            batchNo: formData.batchNo,
            lastUpdatedBy: user!.id,
            updatedAt: new Date().toISOString()
          };
        }
        return entry;
      });

      StorageService.saveProductionData(updatedData);

      const target = allData.find(e => e.id === selectedPlanId);
      StorageService.addLog({
        userId: user!.id,
        userName: user!.name,
        action: 'ADD_ACTUAL',
        details: `Updated actuals for ${target?.productName}: ${formData.actualQty} units`
      });

      setMsg({ type: 'success', text: 'Actual data updated successfully.' });

      window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: 'ACTUAL PRODUCTION RECORDED', type: 'success' } 
      }));

      const forDate = updatedData.filter(p => p.date === date);
      setPendingPlans(forDate);
    } catch (err) {
      setMsg({ type: 'error', text: 'Error saving data.' });
    }
  };

  return (
    <div className="max-w-2xl mx-auto">
      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 p-8">
        <h2 className="text-2xl font-bold text-gray-800 dark:text-white mb-6">Input Actual Production</h2>

        {msg && (
          <div className={`p-4 rounded-lg mb-6 flex items-center ${msg.type === 'success' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>
            {msg.type === 'success' ? <CheckCircle2 className="w-5 h-5 mr-2" /> : <AlertCircle className="w-5 h-5 mr-2" />}
            {msg.text}
          </div>
        )}

        <div className="mb-6">
          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Select Date</label>
          <input 
            type="date" 
            className="w-full px-4 py-2 border border-gray-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500 dark:bg-slate-900 dark:text-white font-bold"
            value={date}
            onChange={e => setDate(e.target.value)}
          />

          {currentOffDay && (
            <div className="mt-4 p-4 bg-amber-50 dark:bg-amber-900/30 border border-amber-200 dark:border-amber-800 rounded-2xl flex items-center gap-4">
              <div className="p-3 bg-amber-500 text-white rounded-xl shadow-lg shadow-amber-500/20">
                <Palmtree className="w-6 h-6" />
              </div>
              <div>
                <p className="text-[10px] font-black text-amber-600 uppercase tracking-widest leading-none mb-1">System Restriction</p>
                <p className="text-sm font-black text-slate-800 dark:text-amber-100">Public Holiday: {currentOffDay.description}</p>
                <p className="text-[10px] font-bold text-amber-500 mt-1 uppercase">Production entry is disabled today</p>
              </div>
            </div>
          )}
        </div>

        {!currentOffDay && (
          <>
            <div className="mb-6">
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Select Job / Plan</label>
              {pendingPlans.length === 0 ? (
                <div className="text-sm text-gray-500 italic p-3 border rounded bg-gray-50 dark:bg-slate-900 dark:border-slate-700">No plans found for this date. Ask a planner to input data first.</div>
              ) : (
                <div className="space-y-2 max-h-60 overflow-y-auto border border-gray-200 dark:border-slate-700 rounded-lg p-2">
                  {pendingPlans.map(plan => (
                    <div 
                      key={plan.id}
                      onClick={() => setSelectedPlanId(plan.id)}
                      className={`p-3 rounded-md cursor-pointer border transition-colors ${
                        selectedPlanId === plan.id 
                          ? 'bg-brand-50 border-brand-500 ring-1 ring-brand-500 dark:bg-brand-900/20' 
                          : 'bg-white dark:bg-slate-800 border-gray-200 dark:border-slate-700 hover:bg-gray-50 dark:hover:bg-slate-700'
                      }`}
                    >
                      <div className="flex justify-between items-center">
                        <span className="font-semibold text-gray-800 dark:text-white">{plan.productName}</span>
                        <span className="text-xs bg-gray-100 dark:bg-slate-700 px-2 py-1 rounded text-gray-600 dark:text-gray-400">{plan.category}</span>
                      </div>
                      <div className="text-sm text-gray-500 dark:text-gray-400 flex justify-between mt-1">
                        <span>{plan.process}</span>
                        <span>Plan: {plan.planQuantity}</span>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {selectedPlanId && (
              <form onSubmit={handleSubmit} className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-300">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Actual Quantity</label>
                    <input 
                      type="number" 
                      min="0"
                      required
                      className="w-full px-4 py-2 border border-gray-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500 dark:bg-slate-900 dark:text-white"
                      value={formData.actualQty}
                      onChange={e => setFormData({...formData, actualQty: e.target.value})}
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Manpower</label>
                    <input 
                      type="number" 
                      min="1"
                      required
                      className="w-full px-4 py-2 border border-gray-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500 dark:bg-slate-900 dark:text-white"
                      value={formData.manpower}
                      onChange={e => setFormData({...formData, manpower: e.target.value})}
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Batch Number</label>
                  <div className="flex space-x-2">
                    <input 
                      type="text" 
                      required
                      className="flex-1 px-4 py-2 border border-gray-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500 dark:bg-slate-900 dark:text-white"
                      value={formData.batchNo}
                      onChange={e => setFormData({...formData, batchNo: e.target.value})}
                    />
                    <button
                      type="button"
                      onClick={handleAutoBatch}
                      className="px-4 py-2 bg-gray-100 dark:bg-slate-700 text-gray-700 dark:text-gray-300 font-medium rounded-lg hover:bg-gray-200 dark:hover:bg-slate-600"
                    >
                      Generate
                    </button>
                  </div>
                </div>

                <button 
                  type="submit"
                  className="w-full bg-brand-600 text-white font-semibold py-2.5 rounded-lg hover:bg-brand-700 transition-colors shadow-sm"
                >
                  Update Production Data
                </button>
              </form>
            )}
          </>
        )}
      </div>
    </div>
  );
};

import React, { ReactNode, useState, useEffect, useCallback, useRef } from 'react';
