import React, { useState } from 'react';
import { StorageService } from '../../services/storageService';
import { OffDay } from '../../types';
import { X, Trash2, CalendarX } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';

export const OffDayModal: React.FC<{ onClose: () => void }> = ({ onClose }) => {
  const { user } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [offDays, setOffDays] = useState<OffDay[]>(StorageService.getOffDays());
  const [date, setDate] = useState('');
  const [desc, setDesc] = useState('');

  const inputClasses = "w-full p-2 border border-slate-200 bg-white text-slate-900 font-bold rounded outline-none shadow-sm";

  const handleAdd = () => {
      if(!date) return;
      if(offDays.some(od => od.date === date)) return alert('Already off day');
      const newOd: OffDay = { id: Date.now().toString(), date, description: desc || 'Holiday', createdBy: user!.id };
      const updated = [...offDays, newOd].sort((a,b) => a.date.localeCompare(b.date));
      StorageService.saveOffDays(updated);
      setOffDays(updated);
      triggerRefresh();

      window.dispatchEvent(new CustomEvent('app-notification', { 
          detail: { message: `PUBLIC HOLIDAY SET: ${newOd.description.toUpperCase()} (${newOd.date})`, type: 'success' } 
      }));

      setDate(''); setDesc('');
  };

  const handleRemove = (id: string) => {
      const updated = offDays.filter(od => od.id !== id);
      StorageService.saveOffDays(updated);
      setOffDays(updated);
      triggerRefresh();
      window.dispatchEvent(new CustomEvent('app-notification', { 
          detail: { message: 'HOLIDAY REMOVED FROM SYSTEM', type: 'info' } 
      }));
  };

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-2xl w-96 shadow-2xl p-6 animate-in fade-in zoom-in duration-200">
        <div className="flex justify-between items-center mb-4">
            <h3 className="font-bold text-lg flex items-center gap-2"><CalendarX className="text-red-500"/> Off Days</h3>
            <button onClick={onClose}><X className="text-gray-400 hover:text-red-500" /></button>
        </div>

        <div className="space-y-3 mb-4">
            <input type="date" value={date} onChange={e => setDate(e.target.value)} className={inputClasses} />
            <div className="flex gap-2">
                <input type="text" placeholder="Description" value={desc} onChange={e => setDesc(e.target.value)} className={`${inputClasses} flex-1 text-sm font-normal`} />
                <button onClick={handleAdd} className="bg-indigo-600 text-white px-4 rounded font-bold hover:bg-indigo-700 shadow-md">Add</button>
            </div>
        </div>

        <div className="h-48 overflow-y-auto border border-slate-200 rounded bg-gray-50 dark:bg-slate-900 p-2 space-y-2">
            {offDays.length === 0 ? (
                <div className="text-center p-8 text-slate-400 text-xs italic">No holidays scheduled</div>
            ) : offDays.map(od => (
                <div key={od.id} className="flex justify-between items-center bg-white dark:bg-slate-700 p-2 rounded shadow-sm text-sm border border-slate-100 dark:border-slate-600">
                    <div>
                        <span className="font-mono font-bold text-red-500">{od.date}</span>
                        <div className="text-xs text-gray-500 dark:text-gray-300">{od.description}</div>
                    </div>
                    <button onClick={() => handleRemove(od.id)} className="text-gray-400 hover:text-red-500"><Trash2 className="w-4 h-4" /></button>
                </div>
            ))}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { StorageService } from '../../services/storageService';
import { User, Role } from '../../types';
import { Trash2, Edit2, Check, X, Plus } from 'lucide-react';

export const UserManagement: React.FC = () => {
  const [users, setUsers] = useState<User[]>(StorageService.getUsers());
  const [isAdding, setIsAdding] = useState(false);

  // New User Form State
  const [newUser, setNewUser] = useState<Omit<User, 'id'>>({
      name: '',
      username: '',
      email: '',
      role: 'operator',
      password: ''
  });

  const handleAddUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (users.some(u => u.username.toLowerCase() === newUser.username.toLowerCase())) {
        alert("Username already exists!");
        return;
    }
    const u: User = {
        ...newUser,
        id: Date.now().toString(),
    };
    const updated = [...users, u];
    StorageService.saveUsers(updated);
    setUsers(updated);

    window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: `NEW USER CREATED: ${u.name.toUpperCase()}`, type: 'success' } 
    }));

    setIsAdding(false);
    setNewUser({ name: '', username: '', email: '', role: 'operator', password: '' });
  };

  const handleDelete = (id: string) => {
    if (window.confirm('Delete this user?')) {
        const target = users.find(u => u.id === id);
        const updated = users.filter(u => u.id !== id);
        StorageService.saveUsers(updated);
        setUsers(updated);
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: `USER REMOVED: ${target?.name.toUpperCase()}`, type: 'info' } 
        }));
    }
  };

  return (
    <div className="space-y-6">
        <div className="flex justify-between items-center">
            <h2 className="text-2xl font-bold text-gray-800 dark:text-white">User Management</h2>
            <button 
                onClick={() => setIsAdding(!isAdding)}
                className="bg-brand-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-brand-700 transition shadow-lg shadow-brand-500/20"
            >
                {isAdding ? <X className="w-4 h-4" /> : <Plus className="w-4 h-4" />}
                {isAdding ? 'Cancel' : 'Add User'}
            </button>
        </div>

        {isAdding && (
            <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-sm border border-brand-200 dark:border-slate-700 animate-in fade-in slide-in-from-top-4">
                <h3 className="text-lg font-bold mb-4 dark:text-white">Create New Account</h3>
                <form onSubmit={handleAddUser} className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <input 
                        type="text" placeholder="Full Name" required
                        className="border dark:border-slate-600 dark:bg-slate-900 p-2 rounded focus:ring-2 focus:ring-brand-500 outline-none dark:text-white"
                        value={newUser.name} onChange={e => setNewUser({...newUser, name: e.target.value})}
                    />
                    <input 
                        type="text" placeholder="Username" required
                        className="border dark:border-slate-600 dark:bg-slate-900 p-2 rounded focus:ring-2 focus:ring-brand-500 outline-none dark:text-white"
                        value={newUser.username} onChange={e => setNewUser({...newUser, username: e.target.value})}
                    />
                    <input 
                        type="email" placeholder="Email Address" required
                        className="border dark:border-slate-600 dark:bg-slate-900 p-2 rounded focus:ring-2 focus:ring-brand-500 outline-none dark:text-white"
                        value={newUser.email} onChange={e => setNewUser({...newUser, email: e.target.value})}
                    />
                    <input 
                        type="text" placeholder="Password" required
                        className="border dark:border-slate-600 dark:bg-slate-900 p-2 rounded focus:ring-2 focus:ring-brand-500 outline-none dark:text-white"
                        value={newUser.password} onChange={e => setNewUser({...newUser, password: e.target.value})}
                    />
                    <select 
                        className="border dark:border-slate-600 dark:bg-slate-900 p-2 rounded focus:ring-2 focus:ring-brand-500 outline-none dark:text-white"
                        value={newUser.role} onChange={e => setNewUser({...newUser, role: e.target.value as Role})}
                    >
                        <option value="admin">Admin</option>
                        <option value="manager">Manager</option>
                        <option value="planner">Planner</option>
                        <option value="operator">Operator</option>
                    </select>
                    <div className="md:col-span-2 pt-2">
                        <button type="submit" className="bg-brand-600 text-white px-6 py-2.5 rounded-lg shadow-lg hover:bg-brand-700 transition">Save New User</button>
                    </div>
                </form>
            </div>
        )}

        <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 overflow-hidden">
            <table className="w-full text-left text-sm">
                <thead className="bg-gray-50 dark:bg-slate-900 text-gray-700 dark:text-slate-200 border-b dark:border-slate-700 uppercase font-bold text-[10px] tracking-widest">
                    <tr>
                        <th className="px-6 py-4">Name & Username</th>
                        <th className="px-6 py-4">Email</th>
                        <th className="px-6 py-4">Role</th>
                        <th className="px-6 py-4 text-right">Actions</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-gray-100 dark:divide-slate-700">
                    {users.map(u => (
                        <tr key={u.id} className="hover:bg-gray-50 dark:hover:bg-slate-700/30 transition-colors">
                            <td className="px-6 py-4">
                                <div className="font-bold text-slate-800 dark:text-white">{u.name}</div>
                                <div className="text-xs text-indigo-600 dark:text-indigo-400 font-mono">@{u.username}</div>
                            </td>
                            <td className="px-6 py-4 text-gray-500 dark:text-gray-400">{u.email}</td>
                            <td className="px-6 py-4">
                                <span className="bg-gray-100 dark:bg-slate-900 px-2.5 py-1 rounded text-[10px] uppercase font-black tracking-widest text-gray-600 dark:text-gray-400">
                                    {u.role}
                                </span>
                            </td>
                            <td className="px-6 py-4 text-right">
                                <button 
                                    onClick={() => handleDelete(u.id)}
                                    className="text-red-400 hover:text-red-600 p-2 transition-colors hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg"
                                    disabled={u.role === 'admin' && users.filter(x => x.role === 'admin').length <= 1}
                                    title={u.role === 'admin' ? "Cannot delete last admin" : "Delete"}
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    </div>
  );
};

import React, { ReactNode, useState, useEffect, useCallback, useRef } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { Category, ProductionEntry } from '../../types';
import { CATEGORIES } from '../../constants';
import { LoginModal } from '../modals/LoginModal';
import { InputModal } from '../modals/InputModal';
import { UserModal } from '../modals/UserModal';
import { OffDayModal } from '../modals/OffDayModal';
import { ChangePasswordModal } from '../modals/ChangePasswordModal';
import { GoogleSheetsService } from '../../services/googleSheetsService';
import { StorageService } from '../../services/storageService';
import { Link, useLocation } from 'react-router-dom';
import { 
  Menu, X, Moon, Sun, Plus, LogOut, Database,
  CalendarX, LayoutDashboard, RefreshCw, LogIn, Globe, CheckCircle, Info, Bell,
  ClipboardList, Users, History, Key
} from 'lucide-react';

export const Layout: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { user, logout, hasPermission } = useAuth();
  const { category, setCategory, isDarkMode, toggleDarkMode, triggerRefresh } = useDashboard();
  const location = useLocation();

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [showInput, setShowInput] = useState(false);
  const [showOffDays, setShowOffDays] = useState(false);
  const [showUsers, setShowUsers] = useState(false);
  const [showChangePass, setShowChangePass] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [entryToEdit, setEntryToEdit] = useState<ProductionEntry | null>(null);
  const [notification, setNotification] = useState<{ message: string; type: 'success' | 'info' } | null>(null);

  const timeoutRef = useRef<number | null>(null);

  const handleNotify = useCallback((e: any) => {
    if (timeoutRef.current) window.clearTimeout(timeoutRef.current);

    setNotification({ 
      message: e.detail.message, 
      type: e.detail.type || 'success' 
    });

    timeoutRef.current = window.setTimeout(() => {
      setNotification(null);
      timeoutRef.current = null;
    }, 5000);
  }, []);

  const handleEditEntry = useCallback((e: any) => {
    setEntryToEdit(e.detail);
    setShowInput(true);
  }, []);

  const handleLogout = () => {
    const userName = user?.name || 'User';
    logout();
    window.dispatchEvent(new CustomEvent('app-notification', { 
      detail: { message: `USER LOGOUT SUCCESSFUL: GOODBYE ${userName.toUpperCase()}`, type: 'success' } 
    }));
    setIsMobileMenuOpen(false);
  };

  useEffect(() => {
    window.addEventListener('app-notification', handleNotify);
    window.addEventListener('edit-production-entry', handleEditEntry);
    return () => {
      window.removeEventListener('app-notification', handleNotify);
      window.removeEventListener('edit-production-entry', handleEditEntry);
      if (timeoutRef.current) window.clearTimeout(timeoutRef.current);
    };
  }, [handleNotify, handleEditEntry]);

  const handleSync = async () => {
    if (isSyncing) return;
    setIsSyncing(true);
    try {
      await StorageService.syncWithSheets();
      triggerRefresh();
      window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: 'CLOUD DATA SYNCHRONIZED', type: 'success' } 
      }));
    } catch (e) {
      window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: 'SYNC FAILED - CHECK CONNECTION', type: 'info' } 
      }));
    } finally {
      setIsSyncing(false);
    }
  };

  const navItemClass = (path: string) => `
    w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all
    ${location.pathname === path 
      ? 'bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 border border-indigo-100 dark:border-indigo-800' 
      : 'text-slate-500 hover:bg-gray-50 dark:hover:bg-slate-800'}
  `;

  return (
    <div className={`min-h-screen flex ${isDarkMode ? 'dark' : ''} bg-slate-50 dark:bg-slate-900 transition-colors duration-300 font-sans`}>
      {/* GLOBAL SYSTEM MESSAGE BANNER */}
      {notification && (
