              </button>
            </>
          )}
        </nav>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-16 bg-white dark:bg-slate-850 border-b border-gray-200 dark:border-slate-700 flex items-center justify-between px-6 shrink-0 z-20">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsMobileMenuOpen(true)} className="md:hidden p-2 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-lg">
              <Menu className="w-6 h-6" />
            </button>
            <div className="flex items-center gap-3">
              <h2 className="font-black text-lg hidden md:block text-slate-700 dark:text-white capitalize">{location.pathname.replace('/', '') || 'Dashboard'}</h2>
              <div className={`flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[9px] font-black uppercase tracking-wider border ${
                GoogleSheetsService.isEnabled() ? 'bg-emerald-50 text-emerald-600 border-emerald-200' : 'bg-amber-50 text-amber-600 border-amber-200'
              }`}>
                <Database className="w-3 h-3" />
                {GoogleSheetsService.isEnabled() ? 'Live Sheet' : 'Local Data'}
              </div>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <button onClick={handleSync} disabled={isSyncing} className={`p-2.5 text-slate-500 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-xl transition ${isSyncing ? 'animate-spin text-indigo-500' : ''}`}>
              <RefreshCw className="w-5 h-5" />
            </button>
            <button onClick={toggleDarkMode} className="p-2.5 text-slate-500 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-xl transition">
              {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
            </button>
            {user ? (
              <div className="flex items-center gap-3 px-3 py-1.5 bg-gray-50 dark:bg-slate-800 rounded-xl border border-gray-100 dark:border-slate-700">
                 <div className="w-8 h-8 rounded-full bg-indigo-500 flex items-center justify-center text-white text-xs font-bold uppercase">{user.name.charAt(0)}</div>
                 <div className="hidden sm:block text-left">
                    <p className="text-[10px] font-black uppercase text-indigo-500 leading-none">{user.role}</p>
                    <p className="text-xs font-bold text-slate-700 dark:text-white">{user.name}</p>
                 </div>
              </div>
            ) : (
              <button onClick={() => setShowLogin(true)} className="flex items-center gap-2 px-4 py-2 bg-slate-900 dark:bg-slate-700 text-white text-xs font-bold rounded-xl hover:bg-slate-800 transition">
                <LogIn className="w-4 h-4" /> Admin Login
              </button>
            )}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar">
          {children}
        </div>
      </main>

      {showLogin && <LoginModal onClose={() => setShowLogin(false)} />}
      {showInput && <InputModal onClose={() => { setShowInput(false); setEntryToEdit(null); }} editEntry={entryToEdit} />}
      {showOffDays && <OffDayModal onClose={() => setShowOffDays(false)} />}
      {showUsers && <UserModal onClose={() => setShowUsers(false)} />}
      {showChangePass && <ChangePasswordModal onClose={() => setShowChangePass(false)} />}
    </div>
  );
};

import React, { useState } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { StorageService } from '../../services/storageService';
import { X, Key, ShieldCheck, AlertCircle } from 'lucide-react';

export const ChangePasswordModal: React.FC<{ onClose: () => void }> = ({ onClose }) => {
  const { user } = useAuth();
  const [currPass, setCurrPass] = useState('');
  const [newPass, setNewPass] = useState('');
  const [confirmPass, setConfirmPass] = useState('');
  const [error, setError] = useState('');

  const inputClasses = "w-full p-3 border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-slate-900 dark:text-white font-bold rounded-xl outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 shadow-sm transition-all";

  const handleSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      setError('');

      if (!user) return;

      if(newPass !== confirmPass) {
          setError("New passwords do not match");
          return;
      }

      if(user.password !== currPass) {
          setError("Incorrect current password");
          return;
      }

      if(newPass.length < 6) {
          setError("Password must be at least 6 characters");
          return;
      }

      try {
          const users = StorageService.getUsers();
          const updatedUser = { ...user, password: newPass };
          const updated = users.map(u => u.id === user.id ? updatedUser : u);

          StorageService.saveUsers(updated);
          StorageService.setSession(updatedUser);

          window.dispatchEvent(new CustomEvent('app-notification', { 
              detail: { message: 'PASSWORD UPDATED SUCCESSFULLY', type: 'success' } 
          }));

          onClose();
      } catch (err) {
          setError("Failed to update password. Please try again.");
      }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-3xl w-full max-w-sm shadow-2xl p-8 relative animate-in fade-in zoom-in duration-200 border border-slate-200 dark:border-slate-700">
        <button onClick={onClose} className="absolute top-6 right-6 text-slate-400 hover:text-rose-500 transition-colors">
          <X className="w-5 h-5" />
        </button>

        <div className="mb-8">
            <h3 className="text-2xl font-black text-slate-800 dark:text-white flex items-center gap-3">
                <div className="p-2 bg-indigo-100 dark:bg-indigo-900/30 rounded-xl">
                    <Key className="w-6 h-6 text-indigo-600 dark:text-indigo-400"/>
                </div>
                Security
            </h3>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mt-2">Update Account Password</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
            {error && (
                <div className="p-4 bg-rose-50 dark:bg-rose-900/20 border border-rose-100 dark:border-rose-800 rounded-2xl flex items-center gap-3 animate-pulse">
                    <AlertCircle className="w-5 h-5 text-rose-500 shrink-0" />
                    <p className="text-xs font-bold text-rose-600 dark:text-rose-400">{error}</p>
                </div>
            )}

            <div>
                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 ml-1">Current Password</label>
                <input type="password" required value={currPass} onChange={e => setCurrPass(e.target.value)} className={inputClasses} placeholder="••••••••" />
            </div>

            <div className="pt-2 border-t border-slate-50 dark:border-slate-700/50">
                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 ml-1">New Password</label>
                <input type="password" required value={newPass} onChange={e => setNewPass(e.target.value)} className={inputClasses} placeholder="••••••••" />
            </div>

            <div>
                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 ml-1">Confirm New Password</label>
                <input type="password" required value={confirmPass} onChange={e => setConfirmPass(e.target.value)} className={inputClasses} placeholder="••••••••" />
            </div>

            <button type="submit" className="w-full bg-slate-900 dark:bg-indigo-600 text-white py-4 rounded-2xl font-black hover:opacity-90 shadow-xl shadow-indigo-500/10 uppercase tracking-[0.2em] text-xs mt-4 flex items-center justify-center gap-2 transition-all active:scale-95">
                <ShieldCheck className="w-4 h-4" />
                Update Credentials
            </button>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { CATEGORIES, PROCESSES } from '../../constants';
import { ProductionEntry, Category, ProcessType } from '../../types';
import { X, Loader2, AlertTriangle, Palmtree } from 'lucide-react';
import { getTodayISO } from '../../utils/dateUtils';

interface InputModalProps {
  onClose: () => void;
  editEntry?: ProductionEntry | null;
}

export const InputModal: React.FC<InputModalProps> = ({ onClose, editEntry }) => {
  const { user, hasPermission } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [tab, setTab] = useState<'Plan' | 'Actual'>('Plan');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [date, setDate] = useState(getTodayISO());
  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [process, setProcess] = useState<ProcessType>(PROCESSES[0]);
  const [productName, setProductName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [manpower, setManpower] = useState('0');
  const [batchNo, setBatchNo] = useState('');

  const [plans, setPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  const offDays = useMemo(() => StorageService.getOffDays(), []);
  const currentOffDay = useMemo(() => offDays.find(od => od.date === date), [date, offDays]);

  const inputClasses = "w-full p-2.5 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-slate-900 dark:text-white font-bold focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all shadow-sm";

  useEffect(() => {
    if (currentOffDay && !editEntry) {
      window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: `PUBLIC HOLIDAY: ${currentOffDay.description}`, type: 'info' } 
      }));
    }
  }, [currentOffDay, editEntry]);

  useEffect(() => {
    if (editEntry) {
      setDate(editEntry.date);
      setCategory(editEntry.category);
      setProcess(editEntry.process);
      setProductName(editEntry.productName);
      setQuantity(editEntry.planQuantity.toString());
      setManpower(editEntry.manpower?.toString() || '0');
      setBatchNo(editEntry.batchNo || '');
      setTab('Plan'); 
    } else {
      if (user?.role === 'operator') setTab('Actual');
      else if (user?.role === 'planner') setTab('Plan');
    }
  }, [editEntry, user]);

  useEffect(() => {
    if (tab === 'Actual' && !editEntry) {
        const all = StorageService.getProductionData();
        const relevant = all.filter(p => p.date === date);
        setPlans(relevant);
        setSelectedPlanId('');
    }
  }, [date, tab, editEntry]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    if (!editEntry && currentOffDay) {
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: `ENTRY RESTRICTED: Today is ${currentOffDay.description}`, type: 'info' } 
        }));
        setIsSubmitting(false);
        return;
    }

    const currentData = StorageService.getProductionData();

    try {
        if (editEntry) {
            const updated = currentData.map(p => {
                if (p.id === editEntry.id) {
                    return { 
                        ...p, 
                        date, category, process, productName,
                        planQuantity: tab === 'Plan' ? parseInt(quantity) : p.planQuantity,
                        actualQuantity: tab === 'Actual' ? parseInt(quantity) : p.actualQuantity,
                        batchNo, manpower: parseInt(manpower),
                        lastUpdatedBy: user!.id, updatedAt: new Date().toISOString()
                    };
                }
                return p;
            });
            StorageService.saveProductionData(updated);
            StorageService.addLog({
              userId: user!.id,
              userName: user!.name,
              action: 'EDIT_RECORD',
              details: `Edited ${productName} (${process}) on ${date}`
            });
            window.dispatchEvent(new CustomEvent('app-notification', { 
              detail: { message: 'PRODUCTION RECORD UPDATED', type: 'success' } 
            }));
        } else {
            if (tab === 'Plan') {
                const newEntry: ProductionEntry = {
                    id: Date.now().toString(),
                    date, category, process, productName, 
                    planQuantity: parseInt(quantity), actualQuantity: 0,
                    lastUpdatedBy: user!.id, updatedAt: new Date().toISOString()
                };
                StorageService.saveProductionData([...currentData, newEntry]);
                StorageService.addLog({
                  userId: user!.id,
                  userName: user!.name,
                  action: 'CREATE_PLAN',
                  details: `Created new plan for ${productName}: ${quantity} units`
                });
                window.dispatchEvent(new CustomEvent('app-notification', { 
                  detail: { message: 'PRODUCTION PLAN SUBMITTED', type: 'success' } 
                }));
            } else {
                if (!selectedPlanId) throw new Error("Please select a plan");
                const targetPlan = currentData.find(p => p.id === selectedPlanId);
                const updated = currentData.map(p => {
                    if (p.id === selectedPlanId) {
                        return { 
                            ...p, 
                            actualQuantity: parseInt(quantity), batchNo, manpower: parseInt(manpower),
                            lastUpdatedBy: user!.id, updatedAt: new Date().toISOString()
                        };
                    }
                    return p;
                });
                StorageService.saveProductionData(updated);
                StorageService.addLog({
                  userId: user!.id,
                  userName: user!.name,
                  action: 'RECORD_ACTUAL',
                  details: `Recorded actual production for ${targetPlan?.productName}: ${quantity} units`
                });
                window.dispatchEvent(new CustomEvent('app-notification', { 
                  detail: { message: 'ACTUAL PRODUCTION RECORDED', type: 'success' } 
                }));
            }
        }

        triggerRefresh();
        onClose();
    } catch (err: any) {
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: err.message || 'Operation failed', type: 'info' } 
        }));
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-md shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-700 relative">
        {isSubmitting && (
            <div className="absolute inset-0 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm z-10 flex flex-col items-center justify-center">
                <Loader2 className="w-10 h-10 text-indigo-600 animate-spin mb-2" />
                <p className="text-xs font-black uppercase tracking-widest text-indigo-600">Syncing with system...</p>
            </div>
        )}

        <div className="flex border-b border-gray-200 dark:border-slate-700">
            {!editEntry ? (
              <>
                {hasPermission(['admin', 'manager', 'planner']) && (
                    <button onClick={() => setTab('Plan')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Plan' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        Production Plan
                    </button>
                )}
                {hasPermission(['admin', 'manager', 'operator']) && (
                    <button onClick={() => setTab('Actual')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Actual' ? 'border-emerald-500 text-emerald-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        Production Actual
                    </button>
                )}
              </>
            ) : (
              <div className="flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center text-indigo-600 border-b-2 border-indigo-600">
                Editing Record
              </div>
            )}
        </div>

        <div className="p-6 relative">
            <button onClick={onClose} className="absolute top-2 right-4 text-slate-300 hover:text-rose-500 transition-colors"><X className="w-5 h-5" /></button>

            <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Production Date</label>
                    <input type="date" required value={date} onChange={e => setDate(e.target.value)} className={inputClasses} />

                    {currentOffDay && (
                      <div className="mt-3 p-3 bg-amber-50 dark:bg-amber-900/20 border border-amber-300 dark:border-amber-700 rounded-xl flex items-center gap-3 animate-pulse shadow-sm">
                        <div className="p-2 bg-amber-500 text-white rounded-lg shadow-md">
                          <Palmtree className="w-4 h-4" />
                        </div>
                        <div className="flex-1">
                          <p className="text-[10px] font-black text-amber-700 dark:text-amber-400 uppercase tracking-widest leading-none mb-1">System Warning</p>
                          <p className="text-xs font-black text-slate-900 dark:text-amber-50">{currentOffDay.description || 'OFF DAY'}</p>
                        </div>
                        <AlertTriangle className="w-5 h-5 text-amber-500" />
                      </div>
                    )}
                </div>

                {tab === 'Plan' || editEntry ? (
                    <>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Category</label>
                                <select value={category} onChange={e => setCategory(e.target.value as Category)} className={inputClasses}>
                                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Process</label>
                                <select value={process} onChange={e => setProcess(e.target.value as ProcessType)} className={inputClasses}>
                                    {PROCESSES.map(p => <option key={p} value={p}>{p}</option>)}
                                </select>
                            </div>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Product Name</label>
                            <input type="text" required value={productName} onChange={e => setProductName(e.target.value)} className={inputClasses} placeholder="Enter name..." />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Plan Qty</label>
                              <input type="number" required min="1" value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                          </div>
                          {editEntry && (
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Manpower</label>
                                <input type="number" required min="0" value={manpower} onChange={e => setManpower(e.target.value)} className={inputClasses} />
                            </div>
                          )}
                        </div>
                    </>
                ) : (
                    <>
                        <div className="mb-4">
                             <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Select Active Job</label>
                             {plans.length === 0 ? <div className="text-xs text-slate-400 italic text-center p-6 border-2 border-dashed rounded-xl">No plans scheduled for this date.</div> : (
                                 <div className="max-h-40 overflow-y-auto border rounded-xl p-2 space-y-1 dark:border-slate-700 bg-slate-50 dark:bg-slate-900/50">
                                     {plans.map(p => (
                                         <div key={p.id} onClick={() => setSelectedPlanId(p.id)}
                                            className={`p-3 rounded-lg cursor-pointer transition ${selectedPlanId === p.id ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-600 dark:text-slate-300 hover:bg-white dark:hover:bg-slate-800'}`}>
                                            <div className="font-black text-sm">{p.productName}</div>
                                            <div className={`text-[10px] font-bold uppercase ${selectedPlanId === p.id ? 'text-indigo-100' : 'text-slate-400'}`}>{p.process} • Plan: {p.planQuantity}</div>
                                         </div>
                                     ))}
                                 </div>
                             )}
                        </div>
                        {selectedPlanId && (
                            <>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Actual Qty</label>
                                        <input type="number" required value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                                    </div>
                                    <div>
                                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Manpower</label>
                                        <input type="number" required value={manpower} onChange={e => setManpower(e.target.value)} className={inputClasses} />
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Batch Number</label>
                                    <input type="text" required value={batchNo} onChange={e => setBatchNo(e.target.value)} className={inputClasses} placeholder="Enter batch ID..." />
                                </div>
                            </>
                        )}
                    </>
                )}

                <button 
                    type="submit" 
                    disabled={isSubmitting || (!editEntry && !!currentOffDay)} 
                    className={`w-full py-4 rounded-xl font-black text-xs uppercase tracking-[0.2em] text-white mt-6 shadow-xl transition hover:opacity-90 disabled:opacity-50 disabled:cursor-not-allowed ${
                        !!currentOffDay && !editEntry ? 'bg-amber-600' : 
                        tab === 'Plan' ? 'bg-slate-900 dark:bg-indigo-600 shadow-indigo-500/10' : 
                        'bg-emerald-600 shadow-emerald-500/10'
                    }`}
                >
                    {isSubmitting ? 'Syncing...' : (!!currentOffDay && !editEntry ? 'Holiday Entry Locked' : (editEntry ? 'Save Changes' : `Confirm ${tab} Entry`))}
                </button>
            </form>
        </div>
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { ProductionEntry, OffDay } from '../../types';
import { PROCESSES } from '../../constants';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';
import { 
  ClipboardList, CheckCircle, RefreshCw, List, Calendar, 
  ArrowUpRight, TrendingUp, Download, Pencil, Trash2, BarChart3, Layers,
  Palmtree, AlertTriangle, CalendarOff
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { formatDisplayDate, getCurrentMonthISO } from '../../utils/dateUtils';

export const Dashboard: React.FC = () => {
  const { category, refreshKey, triggerRefresh } = useDashboard();
  const { user, hasPermission } = useAuth();

  const [selectedMonth, setSelectedMonth] = useState<string>(getCurrentMonthISO());

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  const dashboardData = useMemo(() => {
    const relevant = productionData.filter(d => d.category === category);

    let selectedMonthPlan = 0;
    let selectedMonthActual = 0;

    const selectedMonthProcessMap = new Map<string, {process: string, Plan: number, Actual: number}>();
    PROCESSES.forEach(proc => {
      selectedMonthProcessMap.set(proc, { process: proc, Plan: 0, Actual: 0 });
    });

    relevant.forEach(d => {
      const monthKey = d.date.substring(0, 7);
      if (monthKey === selectedMonth) {
        selectedMonthPlan += d.planQuantity;
        selectedMonthActual += d.actualQuantity;

        if (!selectedMonthProcessMap.has(d.process)) {
          selectedMonthProcessMap.set(d.process, { process: d.process, Plan: 0, Actual: 0 });
        }
        const p = selectedMonthProcessMap.get(d.process)!;
        p.Plan += d.planQuantity;
        p.Actual += d.actualQuantity;
      }
    });

    return {
      filteredData: relevant.sort((a,b) => b.date.localeCompare(a.date)),
      selectedMonthStats: { 
        plan: selectedMonthPlan, 
        actual: selectedMonthActual,
        efficiency: selectedMonthPlan > 0 ? (selectedMonthActual / selectedMonthPlan) * 100 : 0
      },
      chartData: Array.from(selectedMonthProcessMap.values())
    };
  }, [productionData, category, selectedMonth]);

  const dailyGroups = useMemo(() => {
    const baseData = dashboardData.filteredData;
    const filteredEntries = baseData.filter(d => d.date.startsWith(selectedMonth));
    const filteredOffDays = offDays.filter(od => od.date.startsWith(selectedMonth));

    const dates = new Set<string>();
    filteredEntries.forEach(d => dates.add(d.date));
    filteredOffDays.forEach(od => dates.add(od.date));

    const sortedDates = Array.from(dates).sort((a, b) => b.localeCompare(a));

    return sortedDates.map(date => {
        const entriesForDate = filteredEntries.filter(d => d.date === date);
        const offDayInfo = filteredOffDays.find(od => od.date === date);
        const totalActualForDate = entriesForDate.reduce((sum, entry) => sum + entry.actualQuantity, 0);
        return {
            date,
            totalActualForDate,
            entries: entriesForDate,
            isOffDay: !!offDayInfo,
            offDayName: offDayInfo?.description || ''
        };
    });
  }, [dashboardData.filteredData, offDays, selectedMonth]);

  const handleDelete = (id: string) => {
      if(!window.confirm("Delete this record?")) return;
      const target = productionData.find(p => p.id === id);
      const newData = productionData.filter(p => p.id !== id);
      StorageService.saveProductionData(newData);
      StorageService.addLog({
        userId: user!.id,
        userName: user!.name,
        action: 'DELETE_RECORD',
        details: `Deleted entry: ${target?.productName} (${target?.date})`
      });
      triggerRefresh();
      window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'ENTRY DELETED SUCCESSFULLY', type: 'info' } }));
  };

  const handleEdit = (entry: ProductionEntry) => {
    window.dispatchEvent(new CustomEvent('edit-production-entry', { detail: entry }));
  };

  const downloadCSV = () => {
    const headers = ["Date", "Status", "Process", "Product", "Plan", "Actual", "Batch No", "Manpower"];
    const rows = dailyGroups.flatMap(g => {
        if (g.entries.length === 0) {
            return [[g.date, g.offDayName || 'Off Day', '-', '-', 0, 0, '-', 0]];
        }
        return g.entries.map(d => [
            d.date, g.isOffDay ? `Holiday (${g.offDayName})` : 'Normal', d.process, d.productName, d.planQuantity, d.actualQuantity, d.batchNo, d.manpower
        ]);
    });
    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `Halagel_Full_Report_${category}_${selectedMonth}.csv`);
    document.body.appendChild(link);
    link.click();

    StorageService.addLog({
      userId: user!.id,
      userName: user!.name,
      action: 'EXPORT_REPORT',
      details: `Exported full report for ${category} (${selectedMonth})`
    });

    window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'REPORT EXPORTED SUCCESSFULLY', type: 'success' } }));
  };

  return (
    <div className="space-y-8 pb-12">
      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="glass-panel p-6 rounded-3xl border-l-4 border-blue-500 shadow-sm relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
               <TrendingUp className="w-16 h-16" />
            </div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Monthly Plan (Total)</p>
            <h3 className="text-3xl font-black mt-1 text-slate-800 dark:text-white">{dashboardData.selectedMonthStats.plan.toLocaleString()}</h3>
        </div>
        <div className="glass-panel p-6 rounded-3xl border-l-4 border-emerald-500 shadow-sm relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
               <CheckCircle className="w-16 h-16" />
            </div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Monthly Actual (Total)</p>
            <h3 className="text-3xl font-black mt-1 text-slate-800 dark:text-white">{dashboardData.selectedMonthStats.actual.toLocaleString()}</h3>
        </div>
        <div className="glass-panel p-6 rounded-3xl border-l-4 border-indigo-500 shadow-sm relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
               <RefreshCw className="w-16 h-16" />
            </div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Overall Efficiency</p>
            <h3 className="text-3xl font-black mt-1 text-slate-800 dark:text-white">{dashboardData.selectedMonthStats.efficiency.toFixed(1)}%</h3>
        </div>
      </div>

      {/* Monthly Breakdown by Process */}
      <div className="space-y-4">
        <div className="flex items-center gap-2 px-2">
          <Layers className="w-5 h-5 text-indigo-500" />
          <h3 className="text-sm font-black text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em]">Monthly Process Breakdown</h3>
        </div>

        <div className="grid grid-cols-2 lg:grid-cols-5 gap-4">
          {dashboardData.chartData.map(proc => {
            const eff = proc.Plan > 0 ? (proc.Actual / proc.Plan) * 100 : 0;
            return (
              <div key={proc.process} className="glass-panel p-4 rounded-2xl border border-gray-100 dark:border-slate-800 shadow-sm hover:shadow-md transition-shadow">
                <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-2">{proc.process}</p>
                <div className="space-y-1">
                  <div className="flex justify-between items-baseline">
                    <span className="text-[9px] font-bold text-slate-400 uppercase">Plan</span>
                    <span className="text-sm font-black text-slate-700 dark:text-slate-200">{proc.Plan.toLocaleString()}</span>
                  </div>
                  <div className="flex justify-between items-baseline">
                    <span className="text-[9px] font-bold text-slate-400 uppercase">Actual</span>
                    <span className="text-sm font-black text-emerald-500">{proc.Actual.toLocaleString()}</span>
                  </div>
                  <div className="pt-2 mt-2 border-t border-gray-50 dark:border-slate-800 flex justify-between items-center">
                    <span className="text-[8px] font-black text-slate-300 uppercase">Eff.</span>
                    <span className={`text-xs font-black ${eff >= 100 ? 'text-emerald-500' : eff >= 75 ? 'text-amber-500' : 'text-rose-500'}`}>
                      {eff.toFixed(1)}%
                    </span>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Production Chart Section */}
      <div className="glass-panel p-8 rounded-3xl shadow-sm">
        <div className="flex items-center justify-between mb-8">
            <div>
              <h3 className="text-xl font-black text-slate-800 dark:text-white flex items-center gap-2">
                <BarChart3 className="w-5 h-5 text-indigo-500" />
                Performance Chart
              </h3>
              <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Plan vs Actual Comparison ({selectedMonth})</p>
            </div>
        </div>

        <div className="h-[350px] w-full">
          {dashboardData.chartData.some(d => d.Plan > 0 || d.Actual > 0) ? (
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={dashboardData.chartData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" opacity={0.5} />
                <XAxis 
                  dataKey="process" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fontSize: 10, fontWeight: 700, fill: '#64748b' }} 
                  dy={10}
                />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fontSize: 10, fontWeight: 700, fill: '#64748b' }}
                />
                <Tooltip 
                  cursor={{ fill: 'rgba(99, 102, 241, 0.05)' }}
                  contentStyle={{ 
                    borderRadius: '16px', 
                    border: 'none', 
                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)',
                    backgroundColor: '#fff',
                    padding: '12px'
                  }}
                  itemStyle={{ fontSize: '12px', fontWeight: 800, padding: '2px 0' }}
                />
                <Legend 
                  verticalAlign="top" 
                  align="right" 
                  iconType="circle"
                  wrapperStyle={{ paddingBottom: '30px', fontSize: '11px', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.05em' }}
                />
                <Bar 
                  dataKey="Plan" 
                  fill="#3b82f6" 
                  radius={[6, 6, 0, 0]} 
                  barSize={32} 
                />
                <Bar 
                  dataKey="Actual" 
                  fill="#10b981" 
                  radius={[6, 6, 0, 0]} 
                  barSize={32} 
                />
              </BarChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-full w-full flex items-center justify-center border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-2xl">
              <p className="text-slate-400 font-bold italic">No data recorded for {selectedMonth}.</p>
            </div>
          )}
        </div>
      </div>

      <div className="space-y-6">
        <div className="flex flex-col md:flex-row justify-between items-end gap-4 px-2">
            <div>
               <h3 className="text-xl font-black text-slate-800 dark:text-white flex items-center gap-2">
                  <List className="w-5 h-5 text-indigo-500" />
                  Daily Production Log
               </h3>
               <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Detailed operational entries</p>
            </div>

            <div className="flex items-center gap-3">
              <input 
                type="month" 
                value={selectedMonth} 
                onChange={(e) => setSelectedMonth(e.target.value)}
                className="px-4 py-2 text-sm font-bold bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 dark:text-white outline-none"
              />
              <button onClick={downloadCSV} className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 text-white text-xs font-black rounded-xl hover:bg-indigo-700 shadow-lg shadow-indigo-500/20 uppercase tracking-widest transition">
                <Download className="w-4 h-4" /> Export Report
              </button>
            </div>
        </div>

        <div className="space-y-8">
            {dailyGroups.length === 0 ? (
               <div className="bg-white dark:bg-slate-850 rounded-3xl p-12 text-center border-2 border-dashed border-gray-100 dark:border-slate-800">
                  <ClipboardList className="w-12 h-12 text-slate-200 mx-auto mb-4" />
                  <p className="text-slate-400 font-bold">No production logs found for the selected month.</p>
               </div>
            ) : dailyGroups.map((group, groupIdx) => {
                const displayDate = formatDisplayDate(group.date);
                const [datePart, dayPart] = displayDate.split(' ');

                return (
                  <div key={`group-${groupIdx}`} className={`bg-white dark:bg-[#1a2333] rounded-3xl overflow-hidden shadow-xl border ${group.isOffDay ? 'border-amber-400/50' : 'border-gray-100 dark:border-slate-700/50'}`}>
                      <div className={`p-6 flex justify-between items-center border-b ${group.isOffDay ? 'bg-amber-50 dark:bg-amber-900/10 border-amber-100 dark:border-amber-900/30' : 'border-gray-100 dark:border-slate-700/50 bg-gray-50/50 dark:bg-[#232d3f]'}`}>
                          <div className="flex items-center gap-4">
                              {group.isOffDay ? <Palmtree className="w-7 h-7 text-amber-500" /> : <Calendar className="w-7 h-7 text-slate-400 dark:text-slate-500" />}
                              <div className="flex items-baseline gap-4">
                                <span className={`text-2xl font-black tracking-tight ${group.isOffDay ? 'text-amber-700 dark:text-amber-400' : 'text-slate-800 dark:text-white'}`}>{datePart}</span>
                                <span className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-[0.2em]">{dayPart}</span>
                              </div>
                              {group.isOffDay && (
                                <span className="flex items-center gap-1.5 px-3 py-1 bg-amber-500 text-white text-[10px] font-black uppercase rounded-full shadow-sm tracking-widest">
                                    <CalendarOff className="w-3 h-3" />
                                    {group.offDayName || 'OFF DAY'}
                                </span>
                              )}
                          </div>
                          <div className="px-6 py-2 bg-white dark:bg-[#0f172a] rounded-2xl border border-gray-100 dark:border-slate-700 text-slate-600 dark:text-slate-300 font-bold text-sm shadow-sm dark:shadow-inner">
                            Total Actual: <span className="text-emerald-600 dark:text-emerald-400 ml-1">{group.totalActualForDate.toLocaleString()}</span>
                          </div>
                      </div>

                      {group.entries.length === 0 ? (
                        <div className="p-12 text-center flex flex-col items-center justify-center gap-3">
                            <div className="p-4 bg-slate-50 dark:bg-slate-900/50 rounded-full text-slate-300 dark:text-slate-700">
                                <Palmtree className="w-10 h-10" />
                            </div>
                            <p className="text-slate-500 font-bold">No production recorded for this Off Day.</p>
                        </div>
                      ) : (
                        <div className="overflow-x-auto no-scrollbar">
                            <table className="w-full text-left">
                                <thead>
                                    <tr className="border-b border-gray-100 dark:border-slate-700/50 text-[10px] font-black text-slate-500 uppercase tracking-widest bg-gray-50 dark:bg-[#0f172a]/20">
                                        <th className="px-8 py-5">Process</th>
                                        <th className="px-8 py-5">Product</th>
                                        <th className="px-8 py-5 text-center">Plan Qty</th>
                                        <th className="px-8 py-5 text-center">Actual Qty</th>
                                        <th className="px-8 py-5 text-center">Efficiency</th>
                                        <th className="px-8 py-5 text-center">Batch No</th>
                                        <th className="px-8 py-5 text-center">Manpower</th>
                                        {hasPermission(['admin', 'manager']) && <th className="px-8 py-5 text-center">Action</th>}
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-50 dark:divide-slate-800/30">
                                    {group.entries.map(entry => {
                                        const eff = entry.planQuantity > 0 ? (entry.actualQuantity / entry.planQuantity) * 100 : 0;
                                        const effColor = eff >= 100 ? 'text-[#10b981]' : eff >= 75 ? 'text-[#fbbf24]' : 'text-[#f43f5e]';

                                        return (
                                            <tr key={entry.id} className={`hover:bg-gray-50/80 dark:hover:bg-slate-700/20 transition-colors ${group.isOffDay ? 'bg-amber-50/20 dark:bg-amber-900/5' : ''}`}>
                                                <td className="px-8 py-6">
                                                    <span className="inline-block px-3 py-1.5 rounded-xl border border-indigo-500/30 bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-[10px] font-black uppercase">
                                                      {entry.process}
                                                    </span>
                                                    {group.isOffDay && (
                                                      <span className="ml-2 inline-block px-2 py-1 rounded-lg bg-red-100 text-red-600 text-[8px] font-black uppercase tracking-tighter">
                                                        Holiday Shift
                                                      </span>
                                                    )}
                                                </td>
                                                <td className="px-8 py-6">
                                                    <span className="text-sm font-black text-slate-800 dark:text-white">{entry.productName}</span>
                                                </td>
                                                <td className="px-8 py-6 text-center">
                                                    <span className="text-blue-600 dark:text-blue-400 font-black font-mono text-lg">{entry.planQuantity.toLocaleString()}</span>
                                                </td>
                                                <td className="px-8 py-6 text-center">
                                                    <span className="text-emerald-600 dark:text-emerald-400 font-black font-mono text-lg">{entry.actualQuantity.toLocaleString()}</span>
                                                </td>
                                                <td className="px-8 py-6 text-center">
                                                    <span className={`font-black text-lg ${effColor}`}>{eff.toFixed(0)}%</span>
                                                </td>
                                                <td className="px-8 py-6 text-center">
                                                    <span className="text-slate-400 dark:text-slate-500 font-mono text-xs font-bold uppercase">{entry.batchNo || '-'}</span>
                                                </td>
                                                <td className="px-8 py-6 text-center">
                                                    <span className="text-slate-700 dark:text-slate-200 font-black text-lg">{entry.manpower || 0}</span>
                                                </td>
                                                {hasPermission(['admin', 'manager']) && (
                                                  <td className="px-8 py-6">
                                                      <div className="flex items-center justify-center gap-3">
                                                          <button onClick={() => handleEdit(entry)} className="p-2 text-indigo-400 hover:bg-indigo-500/20 rounded-xl transition">
                                                              <Pencil className="w-5 h-5" />
                                                          </button>
                                                          <button onClick={() => handleDelete(entry.id)} className="p-2 text-slate-500 hover:text-rose-500 hover:bg-rose-500/20 rounded-xl transition">
                                                              <Trash2 className="w-5 h-5" />
                                                          </button>
                                                      </div>
                                                  </td>
                                                )}
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>
                      )}
                  </div>
                );
            })}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { StorageService } from '../../services/storageService';
import { OffDay } from '../../types';
import { X, Trash2, CalendarX } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';

export const OffDayModal: React.FC<{ onClose: () => void }> = ({ onClose }) => {
  const { user } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [offDays, setOffDays] = useState<OffDay[]>(StorageService.getOffDays());
  const [date, setDate] = useState('');
  const [desc, setDesc] = useState('');

  const inputClasses = "w-full p-2 border border-slate-200 bg-white text-slate-900 font-bold rounded outline-none shadow-sm";

  const handleAdd = () => {
      if(!date) return;
      if(offDays.some(od => od.date === date)) return alert('Already off day');
      const newOd: OffDay = { id: Date.now().toString(), date, description: desc || 'Holiday', createdBy: user!.id };
      const updated = [...offDays, newOd].sort((a,b) => a.date.localeCompare(b.date));
      StorageService.saveOffDays(updated);

      StorageService.addLog({
        userId: user!.id,
        userName: user!.name,
        action: 'ADD_HOLIDAY',
        details: `Scheduled public holiday: ${newOd.description} (${newOd.date})`
      });

      setOffDays(updated);
      triggerRefresh();

      window.dispatchEvent(new CustomEvent('app-notification', { 
          detail: { message: `PUBLIC HOLIDAY SET: ${newOd.description.toUpperCase()} (${newOd.date})`, type: 'success' } 
      }));

      setDate(''); setDesc('');
  };

  const handleRemove = (id: string) => {
      const target = offDays.find(od => od.id === id);
      const updated = offDays.filter(od => od.id !== id);
      StorageService.saveOffDays(updated);

      StorageService.addLog({
        userId: user!.id,
        userName: user!.name,
        action: 'DELETE_HOLIDAY',
        details: `Removed holiday: ${target?.description} (${target?.date})`
      });

      setOffDays(updated);
      triggerRefresh();
      window.dispatchEvent(new CustomEvent('app-notification', { 
          detail: { message: 'HOLIDAY REMOVED FROM SYSTEM', type: 'info' } 
      }));
  };

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-2xl w-96 shadow-2xl p-6 animate-in fade-in zoom-in duration-200">
        <div className="flex justify-between items-center mb-4">
            <h3 className="font-bold text-lg flex items-center gap-2"><CalendarX className="text-red-500"/> Off Days</h3>
            <button onClick={onClose}><X className="text-gray-400 hover:text-red-500" /></button>
        </div>

        <div className="space-y-3 mb-4">
            <input type="date" value={date} onChange={e => setDate(e.target.value)} className={inputClasses} />
            <div className="flex gap-2">
                <input type="text" placeholder="Description" value={desc} onChange={e => setDesc(e.target.value)} className={`${inputClasses} flex-1 text-sm font-normal`} />
                <button onClick={handleAdd} className="bg-indigo-600 text-white px-4 rounded font-bold hover:bg-indigo-700 shadow-md">Add</button>
            </div>
        </div>

        <div className="h-48 overflow-y-auto border border-slate-200 rounded bg-gray-50 dark:bg-slate-900 p-2 space-y-2">
            {offDays.length === 0 ? (
