import React, { createContext, useContext, useState, ReactNode, useEffect } from 'react';
import { Category } from '../types';

interface DashboardContextType {
  category: Category;
  setCategory: (c: Category) => void;
  isDarkMode: boolean;
  toggleDarkMode: () => void;
  refreshKey: number;
  triggerRefresh: () => void;
}

const DashboardContext = createContext<DashboardContextType | undefined>(undefined);

export const DashboardProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [category, setCategory] = useState<Category>('Healthcare');
  const [refreshKey, setRefreshKey] = useState(0);
  const [isDarkMode, setIsDarkMode] = useState(false);

  useEffect(() => {
    if (localStorage.getItem('theme') === 'dark') {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }

    // Cross-tab synchronization
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key && e.key.startsWith('halagel_')) {
        triggerRefresh();
      }
    };

    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, []);

  const toggleDarkMode = () => {
    setIsDarkMode(prev => {
      const newVal = !prev;
      if (newVal) {
        document.documentElement.classList.add('dark');
        localStorage.setItem('theme', 'dark');
      } else {
        document.documentElement.classList.remove('dark');
        localStorage.setItem('theme', 'light');
      }
      return newVal;
    });
  };

  const triggerRefresh = () => setRefreshKey(prev => prev + 1);

  return (
    <DashboardContext.Provider value={{ category, setCategory, isDarkMode, toggleDarkMode, refreshKey, triggerRefresh }}>
      {children}
    </DashboardContext.Provider>
  );
};

export const useDashboard = () => {
  const context = useContext(DashboardContext);
  if (!context) throw new Error('useDashboard must be used within DashboardProvider');
  return context;
};

import { User, ProductionEntry, OffDay, ActivityLog } from '../types';
import { INITIAL_USERS, INITIAL_OFF_DAYS, generateSeedProductionData } from '../constants';
import { GoogleSheetsService } from './googleSheetsService';

const KEYS = {
  USERS: 'halagel_users',
  PRODUCTION: 'halagel_production',
  OFF_DAYS: 'halagel_off_days',
  LOGS: 'halagel_activity_logs',
  CURRENT_USER: 'halagel_current_user_session',
};

const init = () => {
  if (!localStorage.getItem(KEYS.USERS)) {
    localStorage.setItem(KEYS.USERS, JSON.stringify(INITIAL_USERS));
  }
  if (!localStorage.getItem(KEYS.OFF_DAYS)) {
    localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(INITIAL_OFF_DAYS));
  }
  if (!localStorage.getItem(KEYS.PRODUCTION)) {
    localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(generateSeedProductionData()));
  }
  if (!localStorage.getItem(KEYS.LOGS)) {
    localStorage.setItem(KEYS.LOGS, JSON.stringify([]));
  }
};

init();

export const StorageService = {
  // Local CRUD
  getUsers: (): User[] => JSON.parse(localStorage.getItem(KEYS.USERS) || '[]'),
  saveUsers: (users: User[]) => {
    localStorage.setItem(KEYS.USERS, JSON.stringify(users));
    GoogleSheetsService.saveData('saveUsers', users);
  },

  getProductionData: (): ProductionEntry[] => JSON.parse(localStorage.getItem(KEYS.PRODUCTION) || '[]'),
  saveProductionData: (data: ProductionEntry[]) => {
    localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(data));
    GoogleSheetsService.saveData('saveProduction', data);
  },

  /**
   * Deletes a production entry by ID.
   * Uses robust String conversion for ID matching to handle mix of numeric/string IDs.
   */
  deleteProductionEntry: (id: string): { updatedData: ProductionEntry[], deletedItem: ProductionEntry | null } => {
    try {
      const data = StorageService.getProductionData();
      const targetId = String(id);

      const targetItem = data.find(p => String(p.id) === targetId) || null;
      const updatedData = data.filter(p => String(p.id) !== targetId);

      // Save immediately to local storage
      StorageService.saveProductionData(updatedData);

      return { updatedData, deletedItem: targetItem };
    } catch (err) {
      console.error("Storage delete error:", err);
      return { updatedData: StorageService.getProductionData(), deletedItem: null };
    }
  },

  getOffDays: (): OffDay[] => JSON.parse(localStorage.getItem(KEYS.OFF_DAYS) || '[]'),
  saveOffDays: (days: OffDay[]) => {
    localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(days));
    GoogleSheetsService.saveData('saveOffDays', days);
  },

  // Sync Logic
  syncWithSheets: async () => {
    if (!GoogleSheetsService.isEnabled()) return;

    const remoteProduction = await GoogleSheetsService.fetchData<ProductionEntry[]>('getProduction');
    if (remoteProduction) localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(remoteProduction));

    const remoteOffDays = await GoogleSheetsService.fetchData<OffDay[]>('getOffDays');
    if (remoteOffDays) localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(remoteOffDays));
  },

  getLogs: (): ActivityLog[] => JSON.parse(localStorage.getItem(KEYS.LOGS) || '[]'),
  addLog: (log: Omit<ActivityLog, 'id' | 'timestamp'>) => {
    try {
      const logs = StorageService.getLogs();
      const newLog: ActivityLog = {
        ...log,
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
      };
      logs.unshift(newLog);
      if (logs.length > 1000) logs.pop();
      localStorage.setItem(KEYS.LOGS, JSON.stringify(logs));
    } catch (err) {
      console.error("Logging error:", err);
    }
  },

  getSession: (): User | null => {
    const session = localStorage.getItem(KEYS.CURRENT_USER);
    return session ? JSON.parse(session) : null;
  },
  setSession: (user: User | null) => {
    if (user) localStorage.setItem(KEYS.CURRENT_USER, JSON.stringify(user));
    else localStorage.removeItem(KEYS.CURRENT_USER);
  }
};

import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { ProductionEntry, OffDay } from '../../types';
import { PROCESSES } from '../../constants';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';
import { 
  ClipboardList, CheckCircle, RefreshCw, List, Calendar, 
  TrendingUp, Download, Pencil, Trash2, BarChart3, Layers,
  Palmtree, CalendarOff
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { formatDisplayDate, getCurrentMonthISO } from '../../utils/dateUtils';

export const Dashboard: React.FC = () => {
  const { category, refreshKey, triggerRefresh } = useDashboard();
  const { user, hasPermission } = useAuth();

  const [selectedMonth, setSelectedMonth] = useState<string>(getCurrentMonthISO());

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  const dashboardData = useMemo(() => {
    const relevant = productionData.filter(d => d.category === category);

    let selectedMonthPlan = 0;
    let selectedMonthActual = 0;

    const selectedMonthProcessMap = new Map<string, {process: string, Plan: number, Actual: number}>();
    PROCESSES.forEach(proc => {
      selectedMonthProcessMap.set(proc, { process: proc, Plan: 0, Actual: 0 });
    });

    relevant.forEach(d => {
      const monthKey = d.date.substring(0, 7);
      if (monthKey === selectedMonth) {
        selectedMonthPlan += d.planQuantity;
        selectedMonthActual += d.actualQuantity;

        if (!selectedMonthProcessMap.has(d.process)) {
          selectedMonthProcessMap.set(d.process, { process: d.process, Plan: 0, Actual: 0 });
        }
        const p = selectedMonthProcessMap.get(d.process)!;
        p.Plan += d.planQuantity;
        p.Actual += d.actualQuantity;
      }
    });

    return {
      filteredData: relevant.sort((a,b) => b.date.localeCompare(a.date)),
      selectedMonthStats: { 
        plan: selectedMonthPlan, 
        actual: selectedMonthActual,
        efficiency: selectedMonthPlan > 0 ? (selectedMonthActual / selectedMonthPlan) * 100 : 0
      },
      chartData: Array.from(selectedMonthProcessMap.values())
    };
  }, [productionData, category, selectedMonth]);

  const dailyGroups = useMemo(() => {
    const baseData = dashboardData.filteredData;
    const filteredEntries = baseData.filter(d => d.date.startsWith(selectedMonth));
    const filteredOffDays = offDays.filter(od => od.date.startsWith(selectedMonth));

    const dates = new Set<string>();
    filteredEntries.forEach(d => dates.add(d.date));
    filteredOffDays.forEach(od => dates.add(od.date));

    const sortedDates = Array.from(dates).sort((a, b) => b.localeCompare(a));

    return sortedDates.map(date => {
        const entriesForDate = filteredEntries.filter(d => d.date === date);
        const offDayInfo = filteredOffDays.find(od => od.date === date);
        const totalActualForDate = entriesForDate.reduce((sum, entry) => sum + entry.actualQuantity, 0);
        return {
            date,
            totalActualForDate,
            entries: entriesForDate,
            isOffDay: !!offDayInfo,
            offDayName: offDayInfo?.description || ''
        };
    });
  }, [dashboardData.filteredData, offDays, selectedMonth]);

  const handleDelete = (id: string) => {
      if(!window.confirm("Are you sure you want to PERMANENTLY delete this record? This action cannot be undone.")) return;

      // Perform atomic delete and get result
      const { deletedItem } = StorageService.deleteProductionEntry(id);

      if (deletedItem) {
          StorageService.addLog({
            userId: user!.id,
            userName: user!.name,
            action: 'DELETE_RECORD',
            details: `Admin/Manager permanently deleted production record: ${deletedItem.productName} (${deletedItem.date})`
          });

          window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: 'RECORD DELETED SUCCESSFULLY', type: 'info' } 
          }));
      } else {
          window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: 'ERROR: RECORD NOT FOUND', type: 'info' } 
          }));
      }

      // Force UI refresh regardless of log outcome
      triggerRefresh();
  };

  const handleEdit = (entry: ProductionEntry) => {
    window.dispatchEvent(new CustomEvent('edit-production-entry', { detail: entry }));
  };

  const downloadCSV = () => {
    const headers = ["Date", "Status", "Process", "Product", "Plan", "Actual", "Batch No", "Manpower"];
    const rows = dailyGroups.flatMap(g => {
        if (g.entries.length === 0) {
            return [[g.date, g.offDayName || 'Off Day', '-', '-', 0, 0, '-', 0]];
        }
        return g.entries.map(d => [
            d.date, g.isOffDay ? `Holiday (${g.offDayName})` : 'Normal', d.process, d.productName, d.planQuantity, d.actualQuantity, d.batchNo, d.manpower
        ]);
    });
    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `Halagel_Full_Report_${category}_${selectedMonth}.csv`);
    document.body.appendChild(link);
    link.click();

    StorageService.addLog({
      userId: user!.id,
      userName: user!.name,
      action: 'EXPORT_REPORT',
      details: `Exported full report for ${category} (${selectedMonth})`
    });

    window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'REPORT EXPORTED SUCCESSFULLY', type: 'success' } }));
  };

  return (
    <div className="space-y-8 pb-12">
      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="glass-panel p-6 rounded-3xl border-l-4 border-blue-500 shadow-sm relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
               <TrendingUp className="w-16 h-16" />
            </div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Monthly Plan (Total)</p>
            <h3 className="text-3xl font-black mt-1 text-slate-800 dark:text-white">{dashboardData.selectedMonthStats.plan.toLocaleString()}</h3>
        </div>
        <div className="glass-panel p-6 rounded-3xl border-l-4 border-emerald-500 shadow-sm relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
               <CheckCircle className="w-16 h-16" />
            </div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Monthly Actual (Total)</p>
            <h3 className="text-3xl font-black mt-1 text-slate-800 dark:text-white">{dashboardData.selectedMonthStats.actual.toLocaleString()}</h3>
        </div>
        <div className="glass-panel p-6 rounded-3xl border-l-4 border-indigo-500 shadow-sm relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
               <RefreshCw className="w-16 h-16" />
            </div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Overall Efficiency</p>
            <h3 className="text-3xl font-black mt-1 text-slate-800 dark:text-white">{dashboardData.selectedMonthStats.efficiency.toFixed(1)}%</h3>
        </div>
      </div>

      {/* Monthly Breakdown by Process */}
      <div className="space-y-4">
        <div className="flex items-center gap-2 px-2">
          <Layers className="w-5 h-5 text-indigo-500" />
          <h3 className="text-sm font-black text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em]">Monthly Process Breakdown</h3>
        </div>

        <div className="grid grid-cols-2 lg:grid-cols-5 gap-4">
          {dashboardData.chartData.map(proc => {
            const eff = proc.Plan > 0 ? (proc.Actual / proc.Plan) * 100 : 0;
            return (
              <div key={proc.process} className="glass-panel p-4 rounded-2xl border border-gray-100 dark:border-slate-800 shadow-sm hover:shadow-md transition-shadow">
                <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-2">{proc.process}</p>
                <div className="space-y-1">
                  <div className="flex justify-between items-baseline">
                    <span className="text-[9px] font-bold text-slate-400 uppercase">Plan</span>
                    <span className="text-sm font-black text-slate-700 dark:text-slate-200">{proc.Plan.toLocaleString()}</span>
                  </div>
                  <div className="flex justify-between items-baseline">
                    <span className="text-[9px] font-bold text-slate-400 uppercase">Actual</span>
                    <span className="text-sm font-black text-emerald-500">{proc.Actual.toLocaleString()}</span>
                  </div>
                  <div className="pt-2 mt-2 border-t border-gray-50 dark:border-slate-800 flex justify-between items-center">
                    <span className="text-[8px] font-black text-slate-300 uppercase">Eff.</span>
                    <span className={`text-xs font-black ${eff >= 100 ? 'text-emerald-500' : eff >= 75 ? 'text-amber-500' : 'text-rose-500'}`}>
                      {eff.toFixed(1)}%
                    </span>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <div className="space-y-6">
        <div className="flex flex-col md:flex-row justify-between items-end gap-4 px-2">
            <div>
               <h3 className="text-xl font-black text-slate-800 dark:text-white flex items-center gap-2">
                  <List className="w-5 h-5 text-indigo-500" />
                  Daily Production Log
               </h3>
               <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Detailed operational entries</p>
            </div>

            <div className="flex items-center gap-3">
              <input 
                type="month" 
                value={selectedMonth} 
                onChange={(e) => setSelectedMonth(e.target.value)}
                className="px-4 py-2 text-sm font-bold bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 dark:text-white outline-none"
              />
              <button onClick={downloadCSV} className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 text-white text-xs font-black rounded-xl hover:bg-indigo-700 shadow-lg shadow-indigo-500/20 uppercase tracking-widest transition">
                <Download className="w-4 h-4" /> Export Report
              </button>
            </div>
        </div>

        <div className="space-y-8">
            {dailyGroups.length === 0 ? (
               <div className="bg-white dark:bg-slate-850 rounded-3xl p-12 text-center border-2 border-dashed border-gray-100 dark:border-slate-800">
                  <ClipboardList className="w-12 h-12 text-slate-200 mx-auto mb-4" />
                  <p className="text-slate-400 font-bold">No production logs found for the selected month.</p>
               </div>
            ) : dailyGroups.map((group, groupIdx) => {
                const displayDate = formatDisplayDate(group.date);
                const [datePart, dayPart] = displayDate.split(' ');

                return (
                  <div key={`group-${groupIdx}`} className={`bg-white dark:bg-[#1a2333] rounded-3xl overflow-hidden shadow-xl border ${group.isOffDay ? 'border-amber-400/50' : 'border-gray-100 dark:border-slate-700/50'}`}>
                      <div className={`p-6 flex justify-between items-center border-b ${group.isOffDay ? 'bg-amber-50 dark:bg-amber-900/10 border-amber-100 dark:border-amber-900/30' : 'border-gray-100 dark:border-slate-700/50 bg-gray-50/50 dark:bg-[#232d3f]'}`}>
                          <div className="flex items-center gap-4">
                              {group.isOffDay ? <Palmtree className="w-7 h-7 text-amber-500" /> : <Calendar className="w-7 h-7 text-slate-400 dark:text-slate-500" />}
                              <div className="flex items-baseline gap-4">
                                <span className={`text-2xl font-black tracking-tight ${group.isOffDay ? 'text-amber-700 dark:text-amber-400' : 'text-slate-800 dark:text-white'}`}>{datePart}</span>
                                <span className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-[0.2em]">{dayPart}</span>
                              </div>
                              {group.isOffDay && (
                                <span className="flex items-center gap-1.5 px-3 py-1 bg-amber-500 text-white text-[10px] font-black uppercase rounded-full shadow-sm tracking-widest">
                                    <CalendarOff className="w-3 h-3" />
                                    {group.offDayName || 'OFF DAY'}
                                </span>
                              )}
                          </div>
                          <div className="px-6 py-2 bg-white dark:bg-[#0f172a] rounded-2xl border border-gray-100 dark:border-slate-700 text-slate-600 dark:text-slate-300 font-bold text-sm shadow-sm dark:shadow-inner">
                            Total Actual: <span className="text-emerald-600 dark:text-emerald-400 ml-1">{group.totalActualForDate.toLocaleString()}</span>
                          </div>
                      </div>

                      {group.entries.length === 0 ? (
                        <div className="p-12 text-center flex flex-col items-center justify-center gap-3">
                            <div className="p-4 bg-slate-50 dark:bg-slate-900/50 rounded-full text-slate-300 dark:text-slate-700">
                                <Palmtree className="w-10 h-10" />
                            </div>
                            <p className="text-slate-500 font-bold">No production recorded for this Off Day.</p>
                        </div>
                      ) : (
                        <div className="overflow-x-auto no-scrollbar">
                            <table className="w-full text-left">
                                <thead>
                                    <tr className="border-b border-gray-100 dark:border-slate-700/50 text-[10px] font-black text-slate-500 uppercase tracking-widest bg-gray-50 dark:bg-[#0f172a]/20">
                                        <th className="px-8 py-5">Process</th>
                                        <th className="px-8 py-5">Product</th>
                                        <th className="px-8 py-5 text-center">Plan Qty</th>
                                        <th className="px-8 py-5 text-center">Actual Qty</th>
                                        <th className="px-8 py-5 text-center">Efficiency</th>
                                        <th className="px-8 py-5 text-center">Batch No</th>
                                        <th className="px-8 py-5 text-center">Manpower</th>
                                        {hasPermission(['admin', 'manager']) && <th className="px-8 py-5 text-center">Action</th>}
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-50 dark:divide-slate-800/30">
                                    {group.entries.map(entry => {
                                        const eff = entry.planQuantity > 0 ? (entry.actualQuantity / entry.planQuantity) * 100 : 0;
                                        const effColor = eff >= 100 ? 'text-[#10b981]' : eff >= 75 ? 'text-[#fbbf24]' : 'text-[#f43f5e]';

                                        return (
                                            <tr key={entry.id} className={`hover:bg-gray-50/80 dark:hover:bg-slate-700/20 transition-colors ${group.isOffDay ? 'bg-amber-50/20 dark:bg-amber-900/5' : ''}`}>
                                                <td className="px-8 py-6">
                                                    <span className="inline-block px-3 py-1.5 rounded-xl border border-indigo-500/30 bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-[10px] font-black uppercase">
                                                      {entry.process}
                                                    </span>
                                                </td>
                                                <td className="px-8 py-6">
                                                    <span className="text-sm font-black text-slate-800 dark:text-white">{entry.productName}</span>
                                                </td>
                                                <td className="px-8 py-6 text-center">
                                                    <span className="text-blue-600 dark:text-blue-400 font-black font-mono text-lg">{entry.planQuantity.toLocaleString()}</span>
                                                </td>
                                                <td className="px-8 py-6 text-center">
                                                    <span className="text-emerald-600 dark:text-emerald-400 font-black font-mono text-lg">{entry.actualQuantity.toLocaleString()}</span>
                                                </td>
                                                <td className="px-8 py-6 text-center">
                                                    <span className={`font-black text-lg ${effColor}`}>{eff.toFixed(0)}%</span>
                                                </td>
                                                <td className="px-8 py-6 text-center">
                                                    <span className="text-slate-400 dark:text-slate-500 font-mono text-xs font-bold uppercase">{entry.batchNo || '-'}</span>
                                                </td>
                                                <td className="px-8 py-6 text-center">
                                                    <span className="text-slate-700 dark:text-slate-200 font-black text-lg">{entry.manpower || 0}</span>
                                                </td>
                                                {hasPermission(['admin', 'manager']) && (
                                                  <td className="px-8 py-6">
                                                      <div className="flex items-center justify-center gap-3">
                                                          <button onClick={() => handleEdit(entry)} title="Edit Record" className="p-2 text-indigo-400 hover:bg-indigo-500/20 rounded-xl transition">
                                                              <Pencil className="w-5 h-5" />
                                                          </button>
                                                          <button onClick={() => handleDelete(entry.id)} title="Delete Record" className="p-2 text-slate-500 hover:text-rose-500 hover:bg-rose-500/20 rounded-xl transition">
                                                              <Trash2 className="w-5 h-5" />
                                                          </button>
                                                      </div>
                                                  </td>
                                                )}
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>
                      )}
                  </div>
                );
            })}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { StorageService } from '../../services/storageService';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { CATEGORIES, PROCESSES } from '../../constants';
import { ProductionEntry } from '../../types';
import { Trash2, Download, Calendar, List, Filter, XCircle, Palmtree } from 'lucide-react';
import { getTodayISO } from '../../utils/dateUtils';

export const ProductionLog: React.FC = () => {
  const { user, hasPermission } = useAuth();
  const { refreshKey, triggerRefresh } = useDashboard();
  const [data, setData] = useState<ProductionEntry[]>([]);
  const offDays = useMemo(() => StorageService.getOffDays(), []);

  const [viewMode, setViewMode] = useState<'daily' | 'monthly'>('daily');

  const [dateRange, setDateRange] = useState({ start: '', end: '' });
  const [category, setCategory] = useState('All');
  const [processType, setProcessType] = useState('All');

  // Reactively re-fetch production data when the global refreshKey changes
  useEffect(() => {
    setData(StorageService.getProductionData());
  }, [refreshKey]);

  const filteredData = useMemo(() => {
    return data.filter(d => {
      const matchCat = category === 'All' || d.category === category;
      const matchProc = processType === 'All' || d.process === processType;
      const matchStart = !dateRange.start || d.date >= dateRange.start;
      const matchEnd = !dateRange.end || d.date <= dateRange.end;
      return matchCat && matchProc && matchStart && matchEnd;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [data, dateRange, category, processType]);

  const monthlyData = useMemo(() => {
    const groups: Record<string, { plan: number, actual: number, count: number }> = {};

    filteredData.forEach(d => {
        const monthKey = d.date.substring(0, 7); 
        if (!groups[monthKey]) {
            groups[monthKey] = { plan: 0, actual: 0, count: 0 };
        }
        groups[monthKey].plan += d.planQuantity;
        groups[monthKey].actual += d.actualQuantity;
        groups[monthKey].count++;
    });

    return Object.entries(groups)
        .map(([month, stats]) => ({
            month,
            plan: stats.plan,
            actual: stats.actual,
            efficiency: stats.plan > 0 ? (stats.actual / stats.plan) * 100 : 0
        }))
        .sort((a, b) => b.month.localeCompare(a.month)); 
  }, [filteredData]);

  const handleDelete = (id: string) => {
    if (!window.confirm("Are you sure you want to PERMANENTLY delete this entry?")) return;

    // Atomic delete from storage
    const { deletedItem } = StorageService.deleteProductionEntry(id);

    if (deletedItem) {
        StorageService.addLog({
          userId: user!.id,
          userName: user!.name,
          action: 'DELETE_RECORD',
          details: `Record deleted from reports: ${deletedItem.productName} (${deletedItem.date})`
        });

        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: 'RECORD REMOVED SUCCESSFULLY', type: 'info' } 
        }));
    }

    // Always trigger global refresh
    triggerRefresh();
  };

  const resetFilters = () => {
    setDateRange({ start: '', end: '' });
    setCategory('All');
    setProcessType('All');
  };

  const calculateEfficiency = (actual: number, plan: number) => {
    if (plan === 0) return 0;
    return ((actual / plan) * 100).toFixed(1);
  };

  const downloadCSV = () => {
    let headers: string[] = [];
    let rows: (string | number)[][] = [];
    let filename = '';

    const today = getTodayISO();

    if (viewMode === 'daily') {
        headers = ["Date", "Status", "Category", "Process", "Product", "Plan", "Actual", "Efficiency %", "Batch No", "Manpower"];
        rows = filteredData.map(d => {
            const isOff = offDays.some(od => od.date === d.date);
            return [
                d.date, isOff ? 'Holiday Shift' : 'Normal', d.category, d.process, `"${d.productName}"`, d.planQuantity, d.actualQuantity, 
                calculateEfficiency(d.actualQuantity, d.planQuantity), d.batchNo || '', d.manpower || ''
            ];
        });
        filename = `production_log_daily_${today}.csv`;
    } else {
        headers = ["Month", "Total Plan", "Total Actual", "Overall Efficiency %"];
        rows = monthlyData.map(m => [ m.month, m.plan, m.actual, m.efficiency.toFixed(2) ]);
        filename = `production_summary_monthly_${today}.csv`;
    }

    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...rows.map(e => e.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'REPORT EXPORTED SUCCESSFULLY', type: 'success' } }));
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <h2 className="text-2xl font-bold text-gray-800 dark:text-white">Production Reports</h2>

        <div className="flex items-center bg-white dark:bg-slate-800 rounded-lg p-1 border border-gray-200 dark:border-slate-700 shadow-sm">
            <button onClick={() => setViewMode('daily')} className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition ${viewMode === 'daily' ? 'bg-indigo-100 text-indigo-700 dark:bg-indigo-900/40 dark:text-indigo-300' : 'text-gray-500 hover:text-gray-700'}`}>
                <List className="w-4 h-4" /> Daily Log
            </button>
            <button onClick={() => setViewMode('monthly')} className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition ${viewMode === 'monthly' ? 'bg-indigo-100 text-indigo-700 dark:bg-indigo-900/40 dark:text-indigo-300' : 'text-gray-500 hover:text-gray-700'}`}>
                <Calendar className="w-4 h-4" /> Monthly Summary
            </button>
        </div>

        <button onClick={downloadCSV} className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg text-sm font-bold hover:bg-emerald-700 transition">
            <Download className="w-4 h-4" /> Export Excel
        </button>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-xl p-4 shadow-sm border border-gray-100 dark:border-slate-700 flex flex-wrap gap-4 items-end">
        <div className="space-y-1">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1">
            <Filter className="w-3 h-3" /> Start Date
          </label>
          <input 
            type="date" 
            value={dateRange.start} 
            onChange={e => setDateRange(prev => ({...prev, start: e.target.value}))}
            className="px-3 py-2 text-sm bg-gray-50 dark:bg-slate-900 rounded-lg border dark:border-slate-700 outline-none focus:ring-2 focus:ring-indigo-500 w-full sm:w-auto font-bold"
          />
        </div>
        <div className="space-y-1">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1">
            <Filter className="w-3 h-3" /> End Date
          </label>
          <input 
            type="date" 
            value={dateRange.end} 
            onChange={e => setDateRange(prev => ({...prev, end: e.target.value}))}
            className="px-3 py-2 text-sm bg-gray-50 dark:bg-slate-900 rounded-lg border dark:border-slate-700 outline-none focus:ring-2 focus:ring-indigo-500 w-full sm:w-auto font-bold"
          />
        </div>
        <div className="space-y-1">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Category</label>
          <select 
            value={category} 
            onChange={e => setCategory(e.target.value)}
            className="px-3 py-2 text-sm bg-gray-50 dark:bg-slate-900 rounded-lg border dark:border-slate-700 outline-none focus:ring-2 focus:ring-indigo-500 min-w-[120px] font-bold"
          >
            <option value="All">All Categories</option>
            {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>
        <div className="space-y-1">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Process</label>
          <select 
            value={processType} 
            onChange={e => setProcessType(e.target.value)}
            className="px-3 py-2 text-sm bg-gray-50 dark:bg-slate-900 rounded-lg border dark:border-slate-700 outline-none focus:ring-2 focus:ring-indigo-500 min-w-[120px] font-bold"
          >
            <option value="All">All Processes</option>
            {PROCESSES.map(p => <option key={p} value={p}>{p}</option>)}
          </select>
        </div>
        <button 
          onClick={resetFilters}
          className="flex items-center gap-1.5 px-3 py-2 text-xs font-bold text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-lg transition"
        >
          <XCircle className="w-4 h-4" /> Reset Filters
        </button>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left">
            <thead className="bg-gray-50 dark:bg-slate-700 text-gray-700 dark:text-slate-200 font-bold uppercase text-[10px] tracking-widest">
              {viewMode === 'daily' ? (
                  <tr>
                    <th className="px-6 py-4">Date</th>
                    <th className="px-6 py-4">Status</th>
                    <th className="px-6 py-4 text-center">Department</th>
                    <th className="px-6 py-4">Product</th>
                    <th className="px-6 py-4 text-right">Plan</th>
                    <th className="px-6 py-4 text-right">Actual</th>
                    <th className="px-6 py-4 text-right">Eff. %</th>
                    {hasPermission(['admin', 'manager']) && <th className="px-6 py-4 text-center">Actions</th>}
                  </tr>
              ) : (
                  <tr>
                    <th className="px-6 py-4">Month</th>
                    <th className="px-6 py-4 text-right">Total Plan</th>
                    <th className="px-6 py-4 text-right">Total Actual</th>
                    <th className="px-6 py-4 text-right">Overall Efficiency</th>
                  </tr>
              )}
            </thead>
            <tbody className="divide-y divide-gray-100 dark:divide-slate-700">
              {viewMode === 'daily' ? (
                  filteredData.length === 0 ? (
                    <tr>
                      <td colSpan={8} className="px-6 py-10 text-center text-slate-400 italic">No entries found matching filters</td>
                    </tr>
                  ) : filteredData.map(entry => {
                    const eff = Number(calculateEfficiency(entry.actualQuantity, entry.planQuantity));
                    const isOff = offDays.some(od => od.date === entry.date);
                    return (
                      <tr key={entry.id} className={`hover:bg-gray-50 dark:hover:bg-slate-700/50 transition-colors ${isOff ? 'bg-amber-50/20 dark:bg-amber-900/10' : ''}`}>
                        <td className="px-6 py-4 font-mono text-xs font-bold">{entry.date}</td>
                        <td className="px-6 py-4">
                            {isOff ? (
                                <span className="flex items-center gap-1.5 text-[9px] font-black uppercase text-amber-600 dark:text-amber-400">
                                    <Palmtree className="w-3 h-3" /> Holiday Shift
                                </span>
                            ) : (
                                <span className="text-[9px] font-black uppercase text-slate-400">Regular</span>
                            )}
                        </td>
                        <td className="px-6 py-4 text-center">
                          <span className="text-[10px] font-black uppercase px-2 py-0.5 rounded bg-slate-100 dark:bg-slate-900 text-slate-500 border border-slate-200 dark:border-slate-800">
                            {entry.category}
                          </span>
                        </td>
                        <td className="px-6 py-4">
                            <div className="font-bold text-slate-700 dark:text-slate-200">{entry.productName}</div>
                            <div className="text-[9px] font-black uppercase text-indigo-500 tracking-tighter">{entry.process}</div>
                        </td>
                        <td className="px-6 py-4 text-right font-black font-mono text-blue-600">{entry.planQuantity.toLocaleString()}</td>
                        <td className="px-6 py-4 text-right font-black font-mono text-emerald-600">{entry.actualQuantity.toLocaleString()}</td>
                        <td className="px-6 py-4 text-right">
                            <span className={`px-2 py-1 rounded-lg text-xs font-black border ${eff >= 100 ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : eff >= 80 ? 'bg-blue-50 text-blue-600 border-blue-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}>
                                {eff}%
                            </span>
                        </td>
                        {hasPermission(['admin', 'manager']) && (
                            <td className="px-6 py-4 text-center">
                                <button onClick={() => handleDelete(entry.id)} className="text-gray-400 hover:text-red-500 p-2 rounded-xl hover:bg-rose-50 dark:hover:bg-rose-900/20 transition">
                                  <Trash2 className="w-4 h-4" />
                                </button>
                            </td>
                        )}
                      </tr>
                    );
                  })
              ) : (
                  monthlyData.length === 0 ? (
                    <tr>
                      <td colSpan={4} className="px-6 py-10 text-center text-slate-400 italic">No summaries available for current filters</td>
                    </tr>
                  ) : monthlyData.map(m => (
                      <tr key={m.month} className="hover:bg-gray-50 dark:hover:bg-slate-700/50 transition">
                          <td className="px-6 py-4 font-bold text-slate-700 dark:text-slate-200">{m.month}</td>
                          <td className="px-6 py-4 text-right font-mono text-blue-600">{m.plan.toLocaleString()}</td>
                          <td className="px-6 py-4 text-right font-mono text-emerald-600">{m.actual.toLocaleString()}</td>
                          <td className="px-6 py-4 text-right font-bold">
                            <span className={m.efficiency >= 85 ? 'text-emerald-500' : 'text-rose-500'}>
                              {m.efficiency.toFixed(1)}%
                            </span>
                          </td>
                      </tr>
                  ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { StorageService } from '../../services/storageService';
