### 2. The Database Connector Code (Copy this!)

To link your dashboard to a database, follow these steps:

1.  Open [Google Sheets](https://sheets.new).
2.  Click **Extensions** > **Apps Script**.
3.  Delete any existing code and paste this:

```javascript
// Google Apps Script (Database Bridge)

const SS = SpreadsheetApp.getActiveSpreadsheet();

function doGet(e) {
  const action = e.parameter.action;
  const sheetName = getSheetNameForAction(action);
  const data = getSheetData(sheetName);
  return ContentService.createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  const payload = JSON.parse(e.postData.contents);
  const action = payload.action;
  const data = payload.data;
  const sheetName = getSheetNameForAction(action);

  saveSheetData(sheetName, data);
  return ContentService.createTextOutput("Success").setMimeType(ContentService.MimeType.TEXT);
}

function getSheetNameForAction(action) {
  if (action.includes("Production")) return "ProductionData";
  if (action.includes("OffDays")) return "OffDays";
  if (action.includes("Users")) return "Users";
  return "ProductionData";
}

function getSheetData(name) {
  const sheet = getOrCreateSheet(name);
  const data = sheet.getDataRange().getValues();
  if (data.length < 2) return [];
  const headers = data[0];
  return data.slice(1).map(row => {
    let obj = {};
    headers.forEach((h, i) => obj[h] = row[i]);
    return obj;
  });
}

function saveSheetData(name, data) {
  const sheet = getOrCreateSheet(name);
  sheet.clear();
  if (!data || data.length === 0) return;
  const headers = Object.keys(data[0]);
  const values = data.map(item => headers.map(h => item[h]));
  sheet.appendRow(headers);
  sheet.getRange(2, 1, values.length, headers.length).setValues(values);
}

function getOrCreateSheet(name) {
  let sheet = SS.getSheetByName(name);
  if (!sheet) sheet = SS.insertSheet(name);
  return sheet;
}
```

4.  Click **Deploy** > **New Deployment**.
5.  Select **Web App**.
6.  Set **Who has access** to **"Anyone"** (important).
7.  Click **Deploy**, authorize permissions, and **copy the Web App URL**.
8.  Go to your new Dashboard > **User Management** page and paste that URL into the **Database Connection** box.

Your dashboard is now fully linked to a live Google Sheet database! You can open the sheet anytime to see all production entries formatted as a spreadsheet.

