import { ProductionEntry, OffDay } from '../../types';
import { PROCESSES } from '../../constants';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';
import { 
  ClipboardList, CheckCircle, RefreshCw, List, Calendar, 
  TrendingUp, Download, Pencil, Trash2, BarChart3, Layers,
  Palmtree, CalendarOff
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { formatDisplayDate, getCurrentMonthISO } from '../../utils/dateUtils';

export const Dashboard: React.FC = () => {
  const { category, refreshKey, triggerRefresh } = useDashboard();
  const { user, hasPermission } = useAuth();

  const [selectedMonth, setSelectedMonth] = useState<string>(getCurrentMonthISO());

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  const dashboardData = useMemo(() => {
    const relevant = productionData.filter(d => d.category === category);

    let selectedMonthPlan = 0;
    let selectedMonthActual = 0;

    const selectedMonthProcessMap = new Map<string, {process: string, Plan: number, Actual: number}>();
    PROCESSES.forEach(proc => {
      selectedMonthProcessMap.set(proc, { process: proc, Plan: 0, Actual: 0 });
    });

    relevant.forEach(d => {
      const monthKey = d.date.substring(0, 7);
      if (monthKey === selectedMonth) {
        selectedMonthPlan += d.planQuantity;
        selectedMonthActual += d.actualQuantity;

        if (!selectedMonthProcessMap.has(d.process)) {
          selectedMonthProcessMap.set(d.process, { process: d.process, Plan: 0, Actual: 0 });
        }
        const p = selectedMonthProcessMap.get(d.process)!;
        p.Plan += d.planQuantity;
        p.Actual += d.actualQuantity;
      }
    });

    return {
      filteredData: relevant.sort((a,b) => b.date.localeCompare(a.date)),
      selectedMonthStats: { 
        plan: selectedMonthPlan, 
        actual: selectedMonthActual,
        efficiency: selectedMonthPlan > 0 ? (selectedMonthActual / selectedMonthPlan) * 100 : 0
      },
      chartData: Array.from(selectedMonthProcessMap.values())
    };
  }, [productionData, category, selectedMonth]);

  const dailyGroups = useMemo(() => {
    const baseData = dashboardData.filteredData;
    const filteredEntries = baseData.filter(d => d.date.startsWith(selectedMonth));
    const filteredOffDays = offDays.filter(od => od.date.startsWith(selectedMonth));

    const dates = new Set<string>();
    filteredEntries.forEach(d => dates.add(d.date));
    filteredOffDays.forEach(od => dates.add(od.date));

    const sortedDates = Array.from(dates).sort((a, b) => b.localeCompare(a));

    return sortedDates.map(date => {
        const entriesForDate = filteredEntries.filter(d => d.date === date);
        const offDayInfo = filteredOffDays.find(od => od.date === date);
        const totalActualForDate = entriesForDate.reduce((sum, entry) => sum + entry.actualQuantity, 0);
        return {
            date,
            totalActualForDate,
            entries: entriesForDate,
            isOffDay: !!offDayInfo,
            offDayName: offDayInfo?.description || ''
        };
    });
  }, [dashboardData.filteredData, offDays, selectedMonth]);

  const handleDelete = (id: string) => {
      if(!window.confirm("Are you sure you want to PERMANENTLY delete this record? This action cannot be undone.")) return;

      const { deletedItem } = StorageService.deleteProductionEntry(id);

      if (deletedItem) {
          StorageService.addLog({
            userId: user!.id,
            userName: user!.name,
            action: 'DELETE_RECORD',
            details: `Admin/Manager permanently deleted production record: ${deletedItem.productName} (${deletedItem.date})`
          });

          window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: 'RECORD DELETED SUCCESSFULLY', type: 'info' } 
          }));
      }

      triggerRefresh();
  };

  const handleEdit = (entry: ProductionEntry) => {
    window.dispatchEvent(new CustomEvent('edit-production-entry', { detail: entry }));
  };

  const downloadCSV = () => {
    const headers = ["Date", "Status", "Process", "Product", "Plan", "Actual", "Batch No", "Manpower"];
    const rows = dailyGroups.flatMap(g => {
        if (g.entries.length === 0) {
            return [[g.date, g.offDayName || 'Off Day', '-', '-', 0, 0, '-', 0]];
        }
        return g.entries.map(d => [
            d.date, g.isOffDay ? `Holiday (${g.offDayName})` : 'Normal', d.process, d.productName, d.planQuantity, d.actualQuantity, d.batchNo, d.manpower
        ]);
    });
    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `Halagel_Full_Report_${category}_${selectedMonth}.csv`);
    document.body.appendChild(link);
    link.click();

    StorageService.addLog({
      userId: user!.id,
      userName: user!.name,
      action: 'EXPORT_REPORT',
      details: `Exported full report for ${category} (${selectedMonth})`
    });

    window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'REPORT EXPORTED SUCCESSFULLY', type: 'success' } }));
  };

  return (
    <div className="space-y-8 pb-12">
      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="glass-panel p-6 rounded-3xl border-l-4 border-blue-500 shadow-sm relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
               <TrendingUp className="w-16 h-16" />
            </div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Monthly Plan (Total)</p>
            <h3 className="text-3xl font-black mt-1 text-slate-800 dark:text-white">{dashboardData.selectedMonthStats.plan.toLocaleString()}</h3>
        </div>
        <div className="glass-panel p-6 rounded-3xl border-l-4 border-emerald-500 shadow-sm relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
               <CheckCircle className="w-16 h-16" />
            </div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Monthly Actual (Total)</p>
            <h3 className="text-3xl font-black mt-1 text-slate-800 dark:text-white">{dashboardData.selectedMonthStats.actual.toLocaleString()}</h3>
        </div>
        <div className="glass-panel p-6 rounded-3xl border-l-4 border-indigo-500 shadow-sm relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
               <RefreshCw className="w-16 h-16" />
            </div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Overall Efficiency</p>
            <h3 className="text-3xl font-black mt-1 text-slate-800 dark:text-white">{dashboardData.selectedMonthStats.efficiency.toFixed(1)}%</h3>
        </div>
      </div>

      {/* Breakdown Chart */}
      <div className="glass-panel p-8 rounded-[2.5rem] border border-gray-100 dark:border-slate-800 shadow-sm">
        <div className="flex items-center gap-2 mb-8">
          <BarChart3 className="w-5 h-5 text-indigo-500" />
          <h3 className="text-sm font-black text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em]">Process Performance Chart</h3>
        </div>
        <div className="h-80 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={dashboardData.chartData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" opacity={0.5} />
              <XAxis dataKey="process" axisLine={false} tickLine={false} tick={{ fontSize: 10, fontWeight: 800, fill: '#64748b' }} />
              <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 10, fontWeight: 800, fill: '#64748b' }} />
              <Tooltip cursor={{ fill: 'transparent' }} contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)', fontWeight: 800 }} />
              <Legend verticalAlign="top" align="right" iconType="circle" />
              <Bar dataKey="Plan" fill="#818cf8" radius={[6, 6, 0, 0]} />
              <Bar dataKey="Actual" fill="#10b981" radius={[6, 6, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Daily Logs */}
      <div className="space-y-6">
        <div className="flex flex-col md:flex-row justify-between items-end gap-4 px-2">
            <div>
               <h3 className="text-xl font-black text-slate-800 dark:text-white flex items-center gap-2">
                  <List className="w-5 h-5 text-indigo-500" />
                  Daily Production Log
               </h3>
               <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Operational granularity for {selectedMonth}</p>
            </div>

            <div className="flex items-center gap-3">
              <input 
                type="month" 
                value={selectedMonth} 
                onChange={(e) => setSelectedMonth(e.target.value)}
                className="px-4 py-2 text-sm font-bold bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 dark:text-white outline-none"
              />
              <button onClick={downloadCSV} className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 text-white text-xs font-black rounded-xl hover:bg-indigo-700 shadow-lg shadow-indigo-500/20 uppercase tracking-widest transition">
                <Download className="w-4 h-4" /> Export Report
              </button>
            </div>
        </div>

        <div className="space-y-6">
            {dailyGroups.map((group, groupIdx) => {
                const displayDate = formatDisplayDate(group.date);
                const [datePart, dayPart] = displayDate.split(' ');

                return (
                  <div key={`group-${groupIdx}`} className={`bg-white dark:bg-slate-850 rounded-[2rem] overflow-hidden shadow-sm border ${group.isOffDay ? 'border-amber-400/50' : 'border-gray-100 dark:border-slate-800'}`}>
                      <div className={`p-6 flex justify-between items-center border-b ${group.isOffDay ? 'bg-amber-50 dark:bg-amber-900/10 border-amber-100 dark:border-amber-900/30' : 'border-gray-100 dark:border-slate-800 bg-gray-50/50 dark:bg-slate-800/50'}`}>
                          <div className="flex items-center gap-4">
                              {group.isOffDay ? <Palmtree className="w-6 h-6 text-amber-500" /> : <Calendar className="w-6 h-6 text-slate-400" />}
                              <div className="flex items-baseline gap-2">
                                <span className={`text-xl font-black ${group.isOffDay ? 'text-amber-700 dark:text-amber-400' : 'text-slate-800 dark:text-white'}`}>{datePart}</span>
                                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{dayPart}</span>
                              </div>
                              {group.isOffDay && (
                                <span className="px-3 py-1 bg-amber-500 text-white text-[9px] font-black uppercase rounded-full shadow-sm tracking-widest">
                                    {group.offDayName || 'OFF DAY'}
                                </span>
                              )}
                          </div>
                          <div className="px-4 py-1.5 bg-white dark:bg-slate-900 rounded-xl border border-gray-100 dark:border-slate-700 text-slate-600 dark:text-slate-300 font-black text-[11px] uppercase tracking-widest">
                            Actual: <span className="text-emerald-500 ml-1">{group.totalActualForDate.toLocaleString()}</span>
                          </div>
                      </div>

                      {group.entries.length > 0 ? (
                        <div className="overflow-x-auto no-scrollbar">
                            <table className="w-full text-left">
                                <thead>
                                    <tr className="border-b border-gray-50 dark:border-slate-800 text-[9px] font-black text-slate-400 uppercase tracking-widest bg-gray-50/30 dark:bg-slate-900/30">
                                        <th className="px-8 py-4">Process</th>
                                        <th className="px-8 py-4">Product</th>
                                        <th className="px-8 py-4 text-center">Efficiency</th>
                                        <th className="px-8 py-4 text-right">Plan</th>
                                        <th className="px-8 py-4 text-right">Actual</th>
                                        {hasPermission(['admin', 'manager']) && <th className="px-8 py-4 text-center">Control</th>}
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-50 dark:divide-slate-800/30">
                                    {group.entries.map(entry => {
                                        const eff = entry.planQuantity > 0 ? (entry.actualQuantity / entry.planQuantity) * 100 : 0;
                                        return (
                                            <tr key={entry.id} className="hover:bg-gray-50/50 dark:hover:bg-slate-800/30 transition-colors">
                                                <td className="px-8 py-5">
                                                    <span className="text-[10px] font-black text-indigo-600 dark:text-indigo-400 uppercase">{entry.process}</span>
                                                </td>
                                                <td className="px-8 py-5">
                                                    <span className="text-sm font-black text-slate-800 dark:text-white">{entry.productName}</span>
                                                    <div className="text-[9px] font-bold text-slate-400 mt-0.5 uppercase tracking-tighter">{entry.batchNo || 'No Batch'}</div>
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <span className={`text-xs font-black ${eff >= 100 ? 'text-emerald-500' : eff >= 75 ? 'text-amber-500' : 'text-rose-500'}`}>
                                                        {eff.toFixed(0)}%
                                                    </span>
                                                </td>
                                                <td className="px-8 py-5 text-right font-black text-slate-400">{entry.planQuantity.toLocaleString()}</td>
                                                <td className="px-8 py-5 text-right font-black text-emerald-500">{entry.actualQuantity.toLocaleString()}</td>
                                                {hasPermission(['admin', 'manager']) && (
                                                  <td className="px-8 py-5">
                                                      <div className="flex items-center justify-center gap-2">
                                                          <button onClick={() => handleEdit(entry)} className="p-1.5 text-indigo-400 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-lg transition">
                                                              <Pencil className="w-4 h-4" />
                                                          </button>
                                                          <button onClick={() => handleDelete(entry.id)} className="p-1.5 text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/30 rounded-lg transition">
                                                              <Trash2 className="w-4 h-4" />
                                                          </button>
                                                      </div>
                                                  </td>
                                                )}
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>
                      ) : (
                        <div className="p-10 text-center text-slate-400 text-xs italic font-bold uppercase tracking-widest">
                            No production activity recorded for this date.
                        </div>
                      )}
                  </div>
                );
            })}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { CATEGORIES, PROCESSES } from '../../constants';
import { ProductionEntry, Category, ProcessType } from '../../types';
import { X, Loader2, AlertTriangle, Palmtree } from 'lucide-react';
import { getTodayISO } from '../../utils/dateUtils';

interface InputModalProps {
  onClose: () => void;
  editEntry?: ProductionEntry | null;
}

export const InputModal: React.FC<InputModalProps> = ({ onClose, editEntry }) => {
  const { user, hasPermission } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [tab, setTab] = useState<'Plan' | 'Actual'>('Plan');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [date, setDate] = useState(getTodayISO());
  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [process, setProcess] = useState<ProcessType>(PROCESSES[0]);
  const [productName, setProductName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [manpower, setManpower] = useState('0');
  const [batchNo, setBatchNo] = useState('');

  const [plans, setPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  const offDays = useMemo(() => StorageService.getOffDays(), []);
  const currentOffDay = useMemo(() => offDays.find(od => od.date === date), [date, offDays]);

  const inputClasses = "w-full p-2.5 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-slate-900 dark:text-white font-bold focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all shadow-sm";

  useEffect(() => {
    if (currentOffDay && !editEntry) {
      window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: `PUBLIC HOLIDAY: ${currentOffDay.description}`, type: 'info' } 
      }));
    }
  }, [currentOffDay, editEntry]);

  useEffect(() => {
    if (editEntry) {
      setDate(editEntry.date);
      setCategory(editEntry.category);
      setProcess(editEntry.process);
      setProductName(editEntry.productName);
      setQuantity(editEntry.planQuantity.toString());
      setManpower(editEntry.manpower?.toString() || '0');
      setBatchNo(editEntry.batchNo || '');
      setTab(editEntry.actualQuantity > 0 ? 'Actual' : 'Plan'); 
    } else {
      if (user?.role === 'operator') setTab('Actual');
      else if (user?.role === 'planner') setTab('Plan');
    }
  }, [editEntry, user]);

  useEffect(() => {
    if (tab === 'Actual' && !editEntry) {
        const all = StorageService.getProductionData();
        const relevant = all.filter(p => p.date === date);
        setPlans(relevant);
        setSelectedPlanId('');
    }
  }, [date, tab, editEntry]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    const normalizedDate = date.split('T')[0];

    if (!editEntry && currentOffDay) {
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: `ENTRY RESTRICTED: Today is ${currentOffDay.description}`, type: 'info' } 
        }));
        setIsSubmitting(false);
        return;
    }

    const currentData = StorageService.getProductionData();

    try {
        if (editEntry) {
            const updated = currentData.map(p => {
                if (p.id === editEntry.id) {
                    return { 
                        ...p, 
                        date: normalizedDate, 
                        category, process, productName,
                        planQuantity: tab === 'Plan' ? parseInt(quantity) : p.planQuantity,
                        actualQuantity: tab === 'Actual' ? parseInt(quantity) : p.actualQuantity,
                        batchNo, manpower: parseInt(manpower),
                        lastUpdatedBy: user!.id, updatedAt: new Date().toISOString()
                    };
                }
                return p;
            });
            StorageService.saveProductionData(updated);
            StorageService.addLog({
              userId: user!.id,
              userName: user!.name,
              action: 'EDIT_RECORD',
              details: `Edited production record for ${productName} on ${normalizedDate}`
            });
        } else {
            if (tab === 'Plan') {
                const newEntry: ProductionEntry = {
                    id: Date.now().toString(),
                    date: normalizedDate, 
                    category, process, productName, 
                    planQuantity: parseInt(quantity), actualQuantity: 0,
                    lastUpdatedBy: user!.id, updatedAt: new Date().toISOString()
                };
                StorageService.saveProductionData([...currentData, newEntry]);
                StorageService.addLog({
                  userId: user!.id,
                  userName: user!.name,
                  action: 'CREATE_PLAN',
                  details: `Planned ${newEntry.planQuantity} units for ${newEntry.productName} (${normalizedDate})`
                });
            } else {
                if (!selectedPlanId) throw new Error("Please select a plan");
                const targetPlan = currentData.find(p => p.id === selectedPlanId);
                const updated = currentData.map(p => {
                    if (p.id === selectedPlanId) {
                        return { 
                            ...p, 
                            actualQuantity: parseInt(quantity), batchNo, manpower: parseInt(manpower),
                            lastUpdatedBy: user!.id, updatedAt: new Date().toISOString()
                        };
                    }
                    return p;
                });
                StorageService.saveProductionData(updated);
                StorageService.addLog({
                  userId: user!.id,
                  userName: user!.name,
                  action: 'RECORD_ACTUAL',
                  details: `Recorded actual output of ${quantity} units for ${targetPlan?.productName || 'product'}`
                });
            }
        }

        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: 'PRODUCTION RECORD SYNCHRONIZED', type: 'success' } 
        }));

        triggerRefresh();
        onClose();
    } catch (err: any) {
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: err.message || 'Operation failed', type: 'info' } 
        }));
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-md shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-700 relative">
        {isSubmitting && (
            <div className="absolute inset-0 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm z-10 flex flex-col items-center justify-center">
                <Loader2 className="w-10 h-10 text-indigo-600 animate-spin mb-2" />
                <p className="text-xs font-black uppercase tracking-widest text-indigo-600">Uploading to Cloud...</p>
            </div>
        )}

        <div className="flex border-b border-gray-200 dark:border-slate-700">
            {!editEntry ? (
              <>
                {hasPermission(['admin', 'manager', 'planner']) && (
                    <button onClick={() => setTab('Plan')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Plan' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        Production Plan
                    </button>
                )}
                {hasPermission(['admin', 'manager', 'operator']) && (
                    <button onClick={() => setTab('Actual')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Actual' ? 'border-emerald-500 text-emerald-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        Production Actual
                    </button>
                )}
              </>
            ) : (
              <div className="flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center text-indigo-600 border-b-2 border-indigo-600">
                Updating Record
              </div>
            )}
        </div>

        <div className="p-6 relative">
            <button onClick={onClose} className="absolute top-2 right-4 text-slate-300 hover:text-rose-500 transition-colors"><X className="w-5 h-5" /></button>

            <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Production Date</label>
                    <input type="date" required value={date} onChange={e => setDate(e.target.value)} className={inputClasses} />

                    {currentOffDay && (
                      <div className="mt-3 p-3 bg-amber-50 dark:bg-amber-900/20 border border-amber-300 dark:border-amber-700 rounded-xl flex items-center gap-3 animate-pulse shadow-sm">
                        <div className="p-2 bg-amber-500 text-white rounded-lg shadow-md">
                          <Palmtree className="w-4 h-4" />
                        </div>
                        <div className="flex-1">
                          <p className="text-[10px] font-black text-amber-700 dark:text-amber-400 uppercase tracking-widest leading-none mb-1">Public Holiday</p>
                          <p className="text-xs font-black text-slate-900 dark:text-amber-50">{currentOffDay.description || 'OFF DAY'}</p>
                        </div>
                        <AlertTriangle className="w-5 h-5 text-amber-500" />
                      </div>
                    )}
                </div>

                {tab === 'Plan' || editEntry ? (
                    <>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Category</label>
                                <select value={category} onChange={e => setCategory(e.target.value as Category)} className={inputClasses}>
                                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Process</label>
                                <select value={process} onChange={e => setProcess(e.target.value as ProcessType)} className={inputClasses}>
                                    {PROCESSES.map(p => <option key={p} value={p}>{p}</option>)}
                                </select>
                            </div>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Product Name</label>
                            <input type="text" required value={productName} onChange={e => setProductName(e.target.value)} className={inputClasses} placeholder="Enter name..." />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Quantity</label>
                              <input type="number" required min="1" value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                          </div>
                          {editEntry && (
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Manpower</label>
                                <input type="number" required min="0" value={manpower} onChange={e => setManpower(e.target.value)} className={inputClasses} />
                            </div>
                          )}
                        </div>
                        {editEntry && (
                          <div>
                              <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Batch Number</label>
                              <input type="text" value={batchNo} onChange={e => setBatchNo(e.target.value)} className={inputClasses} />
                          </div>
                        )}
                    </>
                ) : (
                    <>
                        <div className="mb-4">
                             <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Select Active Job</label>
                             {plans.length === 0 ? <div className="text-xs text-slate-400 italic text-center p-6 border-2 border-dashed rounded-xl">No plans scheduled for this date.</div> : (
                                 <div className="max-h-40 overflow-y-auto border rounded-xl p-2 space-y-1 dark:border-slate-700 bg-slate-50 dark:bg-slate-900/50">
                                     {plans.map(p => (
                                         <div key={p.id} onClick={() => setSelectedPlanId(p.id)}
                                            className={`p-3 rounded-lg cursor-pointer transition ${selectedPlanId === p.id ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-600 dark:text-slate-300 hover:bg-white dark:hover:bg-slate-800'}`}>
                                            <div className="font-black text-sm">{p.productName}</div>
                                            <div className={`text-[10px] font-bold uppercase ${selectedPlanId === p.id ? 'text-indigo-100' : 'text-slate-400'}`}>{p.process} • Plan: {p.planQuantity}</div>
                                         </div>
                                     ))}
                                 </div>
                             )}
                        </div>
                        {selectedPlanId && (
                            <>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Actual Qty</label>
                                        <input type="number" required value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                                    </div>
                                    <div>
                                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Manpower</label>
                                        <input type="number" required value={manpower} onChange={e => setManpower(e.target.value)} className={inputClasses} />
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Batch Number</label>
                                    <input type="text" required value={batchNo} onChange={e => setBatchNo(e.target.value)} className={inputClasses} placeholder="Enter batch ID..." />
                                </div>
                            </>
                        )}
                    </>
                )}

                <button 
                    type="submit" 
                    disabled={isSubmitting || (!editEntry && !!currentOffDay)} 
                    className={`w-full py-4 rounded-xl font-black text-xs uppercase tracking-[0.2em] text-white mt-6 shadow-xl transition hover:opacity-90 disabled:opacity-50 disabled:cursor-not-allowed ${
                        !!currentOffDay && !editEntry ? 'bg-amber-600' : 
                        tab === 'Plan' ? 'bg-slate-900 dark:bg-indigo-600 shadow-indigo-500/10' : 
                        'bg-emerald-600 shadow-emerald-500/10'
                    }`}
                >
                    {isSubmitting ? 'Syncing...' : (!!currentOffDay && !editEntry ? 'Holiday Entry Locked' : 'Update System')}
                </button>
            </form>
        </div>
      </div>
    </div>
  );
};

