import React, { useEffect, useState } from 'react';
import { StorageService } from '../../services/storageService';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { ActivityLog as LogEntry } from '../../types';
import { History, User, Clock, AlertCircle } from 'lucide-react';

export const ActivityLog: React.FC = () => {
  const { user: authUser } = useAuth();
  const { refreshKey } = useDashboard();
  const [logs, setLogs] = useState<LogEntry[]>([]);

  useEffect(() => {
    // Fetch logs and ensure they are valid objects
    const fetchedLogs = StorageService.getLogs();
    setLogs(Array.isArray(fetchedLogs) ? fetchedLogs : []);
  }, [refreshKey]);

  const formatLogTime = (timestamp: any) => {
    if (!timestamp) return 'NO TIME';
    const date = new Date(timestamp);
    if (isNaN(date.getTime())) return 'TIME ERROR';
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  const formatLogDate = (timestamp: any) => {
    if (!timestamp) return 'NO DATE';
    const date = new Date(timestamp);
    if (isNaN(date.getTime())) return 'INVALID DATE';
    return date.toLocaleDateString();
  };

  if (!authUser) {
    return (
        <div className="p-12 text-center text-slate-400 font-bold">Please log in to view system activity.</div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-black text-slate-800 dark:text-white flex items-center gap-3">
            <History className="w-6 h-6 text-indigo-500" />
            System Activity Log
          </h2>
          <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">Audit trail of all manufacturing operations</p>
        </div>
        <div className="px-3 py-1 bg-indigo-50 dark:bg-indigo-900/30 rounded-full border border-indigo-100 dark:border-indigo-800 text-[10px] font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-tighter">
          {logs.length} Total Actions
        </div>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-sm border border-gray-100 dark:border-slate-700 overflow-hidden">
        <ul className="divide-y divide-gray-100 dark:divide-slate-700">
            {logs.length === 0 ? (
                <li className="p-12 text-center flex flex-col items-center justify-center gap-4">
                   <div className="p-4 bg-slate-50 dark:bg-slate-900 rounded-full text-slate-200">
                      <History className="w-10 h-10" />
                   </div>
                   <p className="text-slate-400 font-bold italic">No system activity recorded yet.</p>
                </li>
            ) : logs.map((log, idx) => (
                <li key={log.id || `log-${idx}`} className="p-6 hover:bg-gray-50 dark:hover:bg-slate-700/50 transition-colors group">
                    <div className="flex justify-between items-start gap-6">
                        <div className="flex gap-4">
                           <div className="w-10 h-10 rounded-xl bg-slate-100 dark:bg-slate-900 flex items-center justify-center text-slate-400 group-hover:bg-indigo-100 group-hover:text-indigo-600 transition-colors">
                              <User className="w-5 h-5" />
                           </div>
                           <div className="min-w-0 flex-1">
                              <div className="flex flex-wrap items-center gap-2 mb-1">
                                <span className="text-sm font-black text-slate-800 dark:text-white truncate max-w-[150px]">
                                  {log.userName || 'SYSTEM'}
                                </span>
                                <span className="text-[10px] font-black uppercase px-2 py-0.5 rounded bg-indigo-50 dark:bg-indigo-900/40 text-indigo-600 dark:text-indigo-400 border border-indigo-100 dark:border-indigo-800 font-mono tracking-tighter">
                                  {log.action || 'ACTION'}
                                </span>
                              </div>
                              <p className="text-sm text-slate-500 dark:text-slate-400 font-medium leading-relaxed break-words">
                                {log.details || 'No details recorded for this entry.'}
                              </p>
                           </div>
                        </div>
                        <div className="text-right flex flex-col items-end gap-1 shrink-0">
                           <div className="flex items-center gap-1.5 text-slate-400">
                              <Clock className="w-3.5 h-3.5" />
                              <span className="text-[10px] font-black uppercase tracking-widest whitespace-nowrap">
                                {formatLogTime(log.timestamp)}
                              </span>
                           </div>
                           <span className="text-[9px] font-bold text-slate-300 uppercase tracking-tighter whitespace-nowrap">
                              {formatLogDate(log.timestamp)}
                           </span>
                        </div>
                    </div>
                </li>
            ))}
        </ul>
      </div>

      {logs.some(l => !l.timestamp) && (
        <div className="flex items-center gap-2 p-4 bg-amber-50 dark:bg-amber-900/20 border border-amber-100 dark:border-amber-800 rounded-2xl">
          <AlertCircle className="w-4 h-4 text-amber-600" />
          <p className="text-[10px] font-bold text-amber-700 dark:text-amber-400 uppercase tracking-widest">
            Some logs have incomplete data from the cloud sync.
          </p>
        </div>
      )}
    </div>
  );
};

import { User, ProductionEntry, OffDay, ActivityLog } from '../types';
import { INITIAL_USERS, INITIAL_OFF_DAYS, generateSeedProductionData } from '../constants';
import { GoogleSheetsService } from './googleSheetsService';

const KEYS = {
  USERS: 'halagel_users',
  PRODUCTION: 'halagel_production',
  OFF_DAYS: 'halagel_off_days',
  LOGS: 'halagel_activity_logs',
  CURRENT_USER: 'halagel_current_user_session',
};

// Helper to ensure an item matches the ActivityLog structure if it comes as an array or malformed object
const normalizeLog = (data: any): ActivityLog => {
  if (Array.isArray(data)) {
    return {
      id: String(data[0] || Date.now()),
      timestamp: String(data[1] || new Date().toISOString()),
      userId: String(data[2] || ''),
      userName: String(data[3] || 'System'),
      action: String(data[4] || 'LOG'),
      details: String(data[5] || '')
    };
  }
  return {
    id: data.id || Date.now().toString(),
    timestamp: data.timestamp || new Date().toISOString(),
    userId: data.userId || '',
    userName: data.userName || data.username || 'System',
    action: data.action || 'ACTION',
    details: data.details || ''
  };
};

const init = () => {
  if (!localStorage.getItem(KEYS.USERS)) {
    localStorage.setItem(KEYS.USERS, JSON.stringify(INITIAL_USERS));
  }
  if (!localStorage.getItem(KEYS.OFF_DAYS)) {
    localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(INITIAL_OFF_DAYS));
  }
  if (!localStorage.getItem(KEYS.PRODUCTION)) {
    localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(generateSeedProductionData()));
  }
  if (!localStorage.getItem(KEYS.LOGS)) {
    localStorage.setItem(KEYS.LOGS, JSON.stringify([]));
  }
};

init();

export const StorageService = {
  // Local CRUD
  getUsers: (): User[] => {
    try {
      return JSON.parse(localStorage.getItem(KEYS.USERS) || '[]');
    } catch { return []; }
  },
  saveUsers: (users: User[]) => {
    localStorage.setItem(KEYS.USERS, JSON.stringify(users));
    GoogleSheetsService.saveData('saveUsers', users);
  },

  getProductionData: (): ProductionEntry[] => {
    try {
      return JSON.parse(localStorage.getItem(KEYS.PRODUCTION) || '[]');
    } catch { return []; }
  },
  saveProductionData: (data: ProductionEntry[]) => {
    localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(data));
    GoogleSheetsService.saveData('saveProduction', data);
  },

  deleteProductionEntry: (id: string): { updatedData: ProductionEntry[], deletedItem: ProductionEntry | null } => {
    try {
      const data = StorageService.getProductionData();
      const targetId = String(id);

      const targetItem = data.find(p => String(p.id) === targetId) || null;
      const updatedData = data.filter(p => String(p.id) !== targetId);

      StorageService.saveProductionData(updatedData);

      return { updatedData, deletedItem: targetItem };
    } catch (err) {
      console.error("Storage delete error:", err);
      return { updatedData: StorageService.getProductionData(), deletedItem: null };
    }
  },

  getOffDays: (): OffDay[] => {
    try {
      return JSON.parse(localStorage.getItem(KEYS.OFF_DAYS) || '[]');
    } catch { return []; }
  },
  saveOffDays: (days: OffDay[]) => {
    localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(days));
    GoogleSheetsService.saveData('saveOffDays', days);
  },

  // Sync Logic
  syncWithSheets: async () => {
    if (!GoogleSheetsService.isEnabled()) return;

    // Pull Production Data
    const remoteProduction = await GoogleSheetsService.fetchData<ProductionEntry[]>('getProduction');
    if (remoteProduction && Array.isArray(remoteProduction)) {
        localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(remoteProduction));
    }

    // Pull Off Days
    const remoteOffDays = await GoogleSheetsService.fetchData<OffDay[]>('getOffDays');
    if (remoteOffDays && Array.isArray(remoteOffDays)) {
        localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(remoteOffDays));
    }

    // Pull Activity Logs with Normalization
    const remoteLogs = await GoogleSheetsService.fetchData<any[]>('getLogs');
    if (remoteLogs && Array.isArray(remoteLogs)) {
        const cleanedLogs = remoteLogs.map(normalizeLog);
        localStorage.setItem(KEYS.LOGS, JSON.stringify(cleanedLogs));
    }

    // Pull Users
    const remoteUsers = await GoogleSheetsService.fetchData<User[]>('getUsers');
    if (remoteUsers && Array.isArray(remoteUsers)) {
        localStorage.setItem(KEYS.USERS, JSON.stringify(remoteUsers));
    }
  },

  getLogs: (): ActivityLog[] => {
    try {
      const raw = localStorage.getItem(KEYS.LOGS);
      return raw ? JSON.parse(raw) : [];
    } catch { return []; }
  },
  addLog: (log: Omit<ActivityLog, 'id' | 'timestamp'>) => {
    try {
      const logs = StorageService.getLogs();
      const newLog: ActivityLog = {
        ...log,
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
      };
      logs.unshift(newLog);
      if (logs.length > 1000) logs.pop();

      // Save locally
      localStorage.setItem(KEYS.LOGS, JSON.stringify(logs));

      // Push to cloud immediately
      GoogleSheetsService.saveData('saveLogs', logs);
    } catch (err) {
      console.error("Logging error:", err);
    }
  },

  getSession: (): User | null => {
    try {
      const session = localStorage.getItem(KEYS.CURRENT_USER);
      return session ? JSON.parse(session) : null;
    } catch { return null; }
  },
  setSession: (user: User | null) => {
    if (user) localStorage.setItem(KEYS.CURRENT_USER, JSON.stringify(user));
    else localStorage.removeItem(KEYS.CURRENT_USER);
  }
};

import { User, ProductionEntry, OffDay, ActivityLog } from '../types';
import { INITIAL_USERS, INITIAL_OFF_DAYS, generateSeedProductionData } from '../constants';
import { GoogleSheetsService } from './googleSheetsService';

const KEYS = {
  USERS: 'halagel_users',
  PRODUCTION: 'halagel_production',
  OFF_DAYS: 'halagel_off_days',
  LOGS: 'halagel_activity_logs',
  CURRENT_USER: 'halagel_current_user_session',
};

// Normalizer for Activity Logs
const normalizeLog = (data: any): ActivityLog => {
  if (Array.isArray(data)) {
    return {
      id: String(data[0] || Date.now()),
      timestamp: String(data[1] || new Date().toISOString()),
      userId: String(data[2] || ''),
      userName: String(data[3] || 'System'),
      action: String(data[4] || 'LOG'),
      details: String(data[5] || '')
    };
  }
  return {
    id: data.id || Date.now().toString(),
    timestamp: data.timestamp || new Date().toISOString(),
    userId: data.userId || '',
    userName: data.userName || data.username || 'System',
    action: data.action || 'ACTION',
    details: data.details || ''
  };
};

// Normalizer for Production Entries
const normalizeProduction = (data: any): ProductionEntry => {
  if (Array.isArray(data)) {
    return {
      id: String(data[0]),
      date: String(data[1]),
      category: String(data[2]) as any,
      process: String(data[3]) as any,
      productName: String(data[4]),
      planQuantity: Number(data[5] || 0),
      actualQuantity: Number(data[6] || 0),
      batchNo: String(data[7] || ''),
      manpower: Number(data[8] || 0),
      lastUpdatedBy: String(data[9] || ''),
      updatedAt: String(data[10] || new Date().toISOString())
    };
  }
  return {
    ...data,
    id: String(data.id),
    planQuantity: Number(data.planQuantity || 0),
    actualQuantity: Number(data.actualQuantity || 0),
    manpower: Number(data.manpower || 0)
  };
};

// Normalizer for Off Days
const normalizeOffDay = (data: any): OffDay => {
  if (Array.isArray(data)) {
    return {
      id: String(data[0]),
      date: String(data[1]),
      description: String(data[2] || 'Holiday'),
      createdBy: String(data[3] || 'System')
    };
  }
  return data;
};

const init = () => {
  if (!localStorage.getItem(KEYS.USERS)) {
    localStorage.setItem(KEYS.USERS, JSON.stringify(INITIAL_USERS));
  }
  if (!localStorage.getItem(KEYS.OFF_DAYS)) {
    localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(INITIAL_OFF_DAYS));
  }
  if (!localStorage.getItem(KEYS.PRODUCTION)) {
    localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(generateSeedProductionData()));
  }
  if (!localStorage.getItem(KEYS.LOGS)) {
    localStorage.setItem(KEYS.LOGS, JSON.stringify([]));
  }
};

init();

