                          <div className="flex items-center gap-4">
                              {group.isOffDay ? <Palmtree className="w-6 h-6 text-amber-500" /> : <Calendar className="w-6 h-6 text-slate-400" />}
                              <div className="flex items-baseline gap-2">
                                <span className={`text-xl font-black ${group.isOffDay ? 'text-amber-700 dark:text-amber-400' : 'text-slate-800 dark:text-white'}`}>{datePart}</span>
                                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{dayPart}</span>
                              </div>
                              {group.isOffDay && (
                                <span className="px-3 py-1 bg-amber-500 text-white text-[9px] font-black uppercase rounded-full shadow-sm tracking-widest">
                                    {group.offDayName || 'OFF DAY'}
                                </span>
                              )}
                          </div>
                          <div className="px-4 py-1.5 bg-white dark:bg-slate-900 rounded-xl border border-gray-100 dark:border-slate-700 text-slate-600 dark:text-slate-300 font-black text-[11px] uppercase tracking-widest">
                            Actual: <span className="text-emerald-500 ml-1">{(group.totalActualForDate || 0).toLocaleString()}</span>
                          </div>
                      </div>

                      {group.entries.length > 0 ? (
                        <div className="overflow-x-auto no-scrollbar">
                            <table className="w-full text-left">
                                <thead>
                                    <tr className="border-b border-gray-50 dark:border-slate-800 text-[9px] font-black text-slate-400 uppercase tracking-widest bg-gray-50/30 dark:bg-slate-900/30">
                                        <th className="px-8 py-4">Process</th>
                                        <th className="px-8 py-4">Product</th>
                                        <th className="px-8 py-4 text-right">Plan Qty</th>
                                        <th className="px-8 py-4 text-right">Actual Qty</th>
                                        <th className="px-8 py-4 text-center">Efficiency</th>
                                        <th className="px-8 py-4 text-center">Batch No</th>
                                        <th className="px-8 py-4 text-center">Manpower</th>
                                        {hasPermission(['admin', 'manager']) && <th className="px-8 py-4 text-center">Action</th>}
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-50 dark:divide-slate-800/30">
                                    {group.entries.map(entry => {
                                        const eff = entry.planQuantity > 0 ? (entry.actualQuantity / entry.planQuantity) * 100 : 0;
                                        return (
                                            <tr key={entry.id} className="hover:bg-gray-50/50 dark:hover:bg-slate-800/30 transition-colors">
                                                <td className="px-8 py-5">
                                                    <span className="text-[10px] font-black text-indigo-600 dark:text-indigo-400 uppercase bg-indigo-50 dark:bg-indigo-900/30 px-2 py-1 rounded-lg border border-indigo-100 dark:border-indigo-800">{entry.process}</span>
                                                </td>
                                                <td className="px-8 py-5">
                                                    <span className="text-sm font-black text-slate-800 dark:text-white">{entry.productName}</span>
                                                </td>
                                                <td className="px-8 py-5 text-right font-black text-indigo-600/80 dark:text-indigo-400/80">{(entry.planQuantity || 0).toLocaleString()}</td>
                                                <td className="px-8 py-5 text-right font-black text-emerald-500">{(entry.actualQuantity || 0).toLocaleString()}</td>
                                                <td className="px-8 py-5 text-center">
                                                    <span className={`text-xs font-black ${eff >= 100 ? 'text-emerald-500' : eff >= 75 ? 'text-amber-500' : 'text-rose-500'}`}>
                                                        {(eff || 0).toFixed(0)}%
                                                    </span>
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <span className="text-[11px] font-bold text-slate-400 uppercase tracking-tighter">{entry.batchNo || '-'}</span>
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <span className="text-base font-black text-slate-800 dark:text-white">{entry.manpower || '0'}</span>
                                                </td>
                                                {hasPermission(['admin', 'manager']) && (
                                                  <td className="px-8 py-5">
                                                      <div className="flex items-center justify-center gap-2">
                                                          <button onClick={() => handleEdit(entry)} className="p-1.5 text-indigo-400 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-lg transition">
                                                              <Pencil className="w-4 h-4" />
                                                          </button>
                                                          <button onClick={() => handleDelete(entry.id)} className="p-1.5 text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/30 rounded-lg transition">
                                                              <Trash2 className="w-4 h-4" />
                                                          </button>
                                                      </div>
                                                  </td>
                                                )}
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>
                      ) : (
                        <div className="p-10 text-center text-slate-400 text-xs italic font-bold uppercase tracking-widest">
                            No production activity recorded for this date.
                        </div>
                      )}
                  </div>
                );
            })}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { StorageService } from '../../services/storageService';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { CATEGORIES, PROCESSES } from '../../constants';
import { ProductionEntry } from '../../types';
import { Trash2, Download, Calendar, List, Filter, XCircle, Palmtree } from 'lucide-react';
import { getTodayISO } from '../../utils/dateUtils';

export const ProductionLog: React.FC = () => {
  const { user, hasPermission } = useAuth();
  const { refreshKey, triggerRefresh } = useDashboard();
  const [data, setData] = useState<ProductionEntry[]>([]);
  const offDays = useMemo(() => StorageService.getOffDays(), []);

  const [viewMode, setViewMode] = useState<'daily' | 'monthly'>('daily');

  const [dateRange, setDateRange] = useState({ start: '', end: '' });
  const [category, setCategory] = useState('All');
  const [processType, setProcessType] = useState('All');

  // Reactively re-fetch production data when the global refreshKey changes
  useEffect(() => {
    setData(StorageService.getProductionData());
  }, [refreshKey]);

  const filteredData = useMemo(() => {
    return data.filter(d => {
      if (!d) return false;
      const matchCat = category === 'All' || d.category === category;
      const matchProc = processType === 'All' || d.process === processType;
      const matchStart = !dateRange.start || (d.date && d.date >= dateRange.start);
      const matchEnd = !dateRange.end || (d.date && d.date <= dateRange.end);
      return matchCat && matchProc && matchStart && matchEnd;
    }).sort((a, b) => (b.date || '').localeCompare(a.date || ''));
  }, [data, dateRange, category, processType]);

  const monthlyData = useMemo(() => {
    const groups: Record<string, { plan: number, actual: number, count: number }> = {};

    filteredData.forEach(d => {
        if (!d.date) return;
        const monthKey = d.date.substring(0, 7); 
        if (!groups[monthKey]) {
            groups[monthKey] = { plan: 0, actual: 0, count: 0 };
        }
        groups[monthKey].plan += (d.planQuantity || 0);
        groups[monthKey].actual += (d.actualQuantity || 0);
        groups[monthKey].count++;
    });

    return Object.entries(groups)
        .map(([month, stats]) => ({
            month,
            plan: stats.plan,
            actual: stats.actual,
            efficiency: stats.plan > 0 ? (stats.actual / stats.plan) * 100 : 0
        }))
        .sort((a, b) => (b.month || '').localeCompare(a.month || '')); 
  }, [filteredData]);

  const handleDelete = (id: string) => {
    if (!window.confirm("Are you sure you want to PERMANENTLY delete this entry?")) return;

    // Atomic delete from storage
    const { deletedItem } = StorageService.deleteProductionEntry(id);

    if (deletedItem) {
        StorageService.addLog({
          userId: user!.id,
          userName: user!.name,
          action: 'DELETE_RECORD',
          details: `Record deleted from reports: ${deletedItem.productName} (${deletedItem.date})`
        });

        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: 'RECORD REMOVED SUCCESSFULLY', type: 'info' } 
        }));
    }

    // Always trigger global refresh
    triggerRefresh();
  };

  const resetFilters = () => {
    setDateRange({ start: '', end: '' });
    setCategory('All');
    setProcessType('All');
  };

  const calculateEfficiency = (actual: number, plan: number) => {
    if (!plan || plan === 0) return 0;
    return ((actual / plan) * 100).toFixed(1);
  };

  const downloadCSV = () => {
    let headers: string[] = [];
    let rows: (string | number)[][] = [];
    let filename = '';

    const today = getTodayISO();

    if (viewMode === 'daily') {
        headers = ["Date", "Status", "Category", "Process", "Product", "Plan", "Actual", "Efficiency %", "Batch No", "Manpower"];
        rows = filteredData.map(d => {
            const isOff = offDays.some(od => od.date === d.date);
            return [
                d.date, isOff ? 'Holiday Shift' : 'Normal', d.category, d.process, `"${d.productName}"`, d.planQuantity || 0, d.actualQuantity || 0, 
                calculateEfficiency(d.actualQuantity || 0, d.planQuantity || 0), d.batchNo || '', d.manpower || ''
            ];
        });
        filename = `production_log_daily_${today}.csv`;
    } else {
        headers = ["Month", "Total Plan", "Total Actual", "Overall Efficiency %"];
        rows = monthlyData.map(m => [ m.month, m.plan || 0, m.actual || 0, (m.efficiency || 0).toFixed(2) ]);
        filename = `production_summary_monthly_${today}.csv`;
    }

    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...rows.map(e => e.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'REPORT EXPORTED SUCCESSFULLY', type: 'success' } }));
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <h2 className="text-2xl font-bold text-gray-800 dark:text-white">Production Reports</h2>

        <div className="flex items-center bg-white dark:bg-slate-800 rounded-lg p-1 border border-gray-200 dark:border-slate-700 shadow-sm">
            <button onClick={() => setViewMode('daily')} className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition ${viewMode === 'daily' ? 'bg-indigo-100 text-indigo-700 dark:bg-indigo-900/40 dark:text-indigo-300' : 'text-gray-500 hover:text-gray-700'}`}>
                <List className="w-4 h-4" /> Daily Log
            </button>
            <button onClick={() => setViewMode('monthly')} className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition ${viewMode === 'monthly' ? 'bg-indigo-100 text-indigo-700 dark:bg-indigo-900/40 dark:text-indigo-300' : 'text-gray-500 hover:text-gray-700'}`}>
                <Calendar className="w-4 h-4" /> Monthly Summary
            </button>
        </div>

        <button onClick={downloadCSV} className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg text-sm font-bold hover:bg-emerald-700 transition">
            <Download className="w-4 h-4" /> Export Excel
        </button>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-xl p-4 shadow-sm border border-gray-100 dark:border-slate-700 flex flex-wrap gap-4 items-end">
        <div className="space-y-1">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1">
            <Filter className="w-3 h-3" /> Start Date
          </label>
          <input 
            type="date" 
            value={dateRange.start} 
            onChange={e => setDateRange(prev => ({...prev, start: e.target.value}))}
            className="px-3 py-2 text-sm bg-gray-50 dark:bg-slate-900 rounded-lg border dark:border-slate-700 outline-none focus:ring-2 focus:ring-indigo-500 w-full sm:w-auto font-bold"
          />
        </div>
        <div className="space-y-1">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1">
            <Filter className="w-3 h-3" /> End Date
          </label>
          <input 
            type="date" 
            value={dateRange.end} 
            onChange={e => setDateRange(prev => ({...prev, end: e.target.value}))}
            className="px-3 py-2 text-sm bg-gray-50 dark:bg-slate-900 rounded-lg border dark:border-slate-700 outline-none focus:ring-2 focus:ring-indigo-500 w-full sm:w-auto font-bold"
          />
        </div>
        <div className="space-y-1">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Category</label>
          <select 
            value={category} 
            onChange={e => setCategory(e.target.value)}
            className="px-3 py-2 text-sm bg-gray-50 dark:bg-slate-900 rounded-lg border dark:border-slate-700 outline-none focus:ring-2 focus:ring-indigo-500 min-w-[120px] font-bold"
          >
            <option value="All">All Categories</option>
            {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>
        <div className="space-y-1">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Process</label>
          <select 
            value={processType} 
            onChange={e => setProcessType(e.target.value)}
            className="px-3 py-2 text-sm bg-gray-50 dark:bg-slate-900 rounded-lg border dark:border-slate-700 outline-none focus:ring-2 focus:ring-indigo-500 min-w-[120px] font-bold"
          >
            <option value="All">All Processes</option>
            {PROCESSES.map(p => <option key={p} value={p}>{p}</option>)}
          </select>
        </div>
        <button 
          onClick={resetFilters}
          className="flex items-center gap-1.5 px-3 py-2 text-xs font-bold text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-lg transition"
        >
          <XCircle className="w-4 h-4" /> Reset Filters
        </button>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left">
            <thead className="bg-gray-50 dark:bg-slate-700 text-gray-700 dark:text-slate-200 font-bold uppercase text-[10px] tracking-widest">
              {viewMode === 'daily' ? (
                  <tr>
                    <th className="px-6 py-4">Date</th>
                    <th className="px-6 py-4">Status</th>
                    <th className="px-6 py-4 text-center">Department</th>
                    <th className="px-6 py-4">Product</th>
                    <th className="px-6 py-4 text-right">Plan</th>
                    <th className="px-6 py-4 text-right">Actual</th>
                    <th className="px-6 py-4 text-right">Eff. %</th>
                    {hasPermission(['admin', 'manager']) && <th className="px-6 py-4 text-center">Actions</th>}
                  </tr>
              ) : (
                  <tr>
                    <th className="px-6 py-4">Month</th>
                    <th className="px-6 py-4 text-right">Total Plan</th>
                    <th className="px-6 py-4 text-right">Total Actual</th>
                    <th className="px-6 py-4 text-right">Overall Efficiency</th>
                  </tr>
              )}
            </thead>
            <tbody className="divide-y divide-gray-100 dark:divide-slate-700">
              {viewMode === 'daily' ? (
                  filteredData.length === 0 ? (
                    <tr>
                      <td colSpan={8} className="px-6 py-10 text-center text-slate-400 italic">No entries found matching filters</td>
                    </tr>
                  ) : filteredData.map(entry => {
                    const eff = Number(calculateEfficiency(entry.actualQuantity || 0, entry.planQuantity || 0));
                    const isOff = entry.date && offDays.some(od => od.date === entry.date);
                    return (
                      <tr key={entry.id} className={`hover:bg-gray-50 dark:hover:bg-slate-700/50 transition-colors ${isOff ? 'bg-amber-50/20 dark:bg-amber-900/10' : ''}`}>
                        <td className="px-6 py-4 font-mono text-xs font-bold">{entry.date || 'N/A'}</td>
                        <td className="px-6 py-4">
                            {isOff ? (
                                <span className="flex items-center gap-1.5 text-[9px] font-black uppercase text-amber-600 dark:text-amber-400">
                                    <Palmtree className="w-3 h-3" /> Holiday Shift
                                </span>
                            ) : (
                                <span className="text-[9px] font-black uppercase text-slate-400">Regular</span>
                            )}
                        </td>
                        <td className="px-6 py-4 text-center">
                          <span className="text-[10px] font-black uppercase px-2 py-0.5 rounded bg-slate-100 dark:bg-slate-900 text-slate-500 border border-slate-200 dark:border-slate-800">
                            {entry.category}
                          </span>
                        </td>
                        <td className="px-6 py-4">
                            <div className="font-bold text-slate-700 dark:text-slate-200">{entry.productName}</div>
                            <div className="text-[9px] font-black uppercase text-indigo-500 tracking-tighter">{entry.process}</div>
                        </td>
                        <td className="px-6 py-4 text-right font-black font-mono text-blue-600">{(entry.planQuantity || 0).toLocaleString()}</td>
                        <td className="px-6 py-4 text-right font-black font-mono text-emerald-600">{(entry.actualQuantity || 0).toLocaleString()}</td>
                        <td className="px-6 py-4 text-right">
                            <span className={`px-2 py-1 rounded-lg text-xs font-black border ${eff >= 100 ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : eff >= 80 ? 'bg-blue-50 text-blue-600 border-blue-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}>
                                {eff}%
                            </span>
                        </td>
                        {hasPermission(['admin', 'manager']) && (
                            <td className="px-6 py-4 text-center">
                                <button onClick={() => handleDelete(entry.id)} className="text-gray-400 hover:text-red-500 p-2 rounded-xl hover:bg-rose-50 dark:hover:bg-rose-900/20 transition">
                                  <Trash2 className="w-4 h-4" />
                                </button>
                            </td>
                        )}
                      </tr>
                    );
                  })
              ) : (
                  monthlyData.length === 0 ? (
                    <tr>
                      <td colSpan={4} className="px-6 py-10 text-center text-slate-400 italic">No summaries available for current filters</td>
                    </tr>
                  ) : monthlyData.map(m => (
                      <tr key={m.month} className="hover:bg-gray-50 dark:hover:bg-slate-700/50 transition">
                          <td className="px-6 py-4 font-bold text-slate-700 dark:text-slate-200">{m.month}</td>
                          <td className="px-6 py-4 text-right font-mono text-blue-600">{(m.plan || 0).toLocaleString()}</td>
                          <td className="px-6 py-4 text-right font-mono text-emerald-600">{(m.actual || 0).toLocaleString()}</td>
                          <td className="px-6 py-4 text-right font-bold">
                            <span className={(m.efficiency || 0) >= 85 ? 'text-emerald-500' : 'text-rose-500'}>
                              {(m.efficiency || 0).toFixed(1)}%
                            </span>
                          </td>
                      </tr>
                  ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import { User, ProductionEntry, OffDay, ActivityLog } from '../types';
import { INITIAL_USERS, INITIAL_OFF_DAYS, generateSeedProductionData } from '../constants';
import { GoogleSheetsService } from './googleSheetsService';

const KEYS = {
  USERS: 'halagel_users',
  PRODUCTION: 'halagel_production',
  OFF_DAYS: 'halagel_off_days',
  LOGS: 'halagel_activity_logs',
  CURRENT_USER: 'halagel_current_user_session',
};

// Normalizer for Production Entries
const normalizeProduction = (data: any): ProductionEntry => {
  if (!data) return {} as ProductionEntry;

  if (Array.isArray(data)) {
    return {
      id: String(data[0] || Date.now()),
      date: String(data[1] || ''),
      category: String(data[2] || 'Healthcare') as any,
      process: String(data[3] || 'Mixing') as any,
      productName: String(data[4] || 'Unknown'),
      planQuantity: Number(data[5] || 0),
      actualQuantity: Number(data[6] || 0),
      batchNo: String(data[7] || ''),
      manpower: Number(data[8] || 0),
      lastUpdatedBy: String(data[9] || ''),
      updatedAt: String(data[10] || new Date().toISOString())
    };
  }
  return {
    ...data,
    id: String(data.id || Date.now()),
    date: String(data.date || ''),
    planQuantity: Number(data.planQuantity || 0),
    actualQuantity: Number(data.actualQuantity || 0),
    manpower: Number(data.manpower || 0)
  };
};

// Normalizer for Activity Logs
const normalizeLog = (data: any): ActivityLog => {
  if (!data) return {} as ActivityLog;

  if (Array.isArray(data)) {
    return {
      id: String(data[0] || Date.now()),
      timestamp: String(data[1] || new Date().toISOString()),
      userId: String(data[2] || ''),
      userName: String(data[3] || 'System'),
      action: String(data[4] || 'LOG'),
      details: String(data[5] || '')
    };
  }
  return {
    ...data,
    id: String(data.id || Date.now())
  };
};

// Normalizer for Off Days
const normalizeOffDay = (data: any): OffDay => {
  if (!data) return {} as OffDay;

  if (Array.isArray(data)) {
    return {
      id: String(data[0] || Date.now()),
      date: String(data[1] || ''),
      description: String(data[2] || 'Holiday'),
      createdBy: String(data[3] || 'System')
    };
  }
  return {
    ...data,
    id: String(data.id || Date.now()),
    date: String(data.date || '')
  };
};

const init = () => {
  if (!localStorage.getItem(KEYS.USERS)) {
    localStorage.setItem(KEYS.USERS, JSON.stringify(INITIAL_USERS));
  }
  if (!localStorage.getItem(KEYS.OFF_DAYS)) {
    localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(INITIAL_OFF_DAYS));
  }
  if (!localStorage.getItem(KEYS.PRODUCTION)) {
    localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(generateSeedProductionData()));
  }
  if (!localStorage.getItem(KEYS.LOGS)) {
    localStorage.setItem(KEYS.LOGS, JSON.stringify([]));
  }
};

init();

export const StorageService = {
  // Local CRUD
  getUsers: (): User[] => {
    try {
      return JSON.parse(localStorage.getItem(KEYS.USERS) || '[]');
    } catch { return []; }
  },
  saveUsers: (users: User[]) => {
    localStorage.setItem(KEYS.USERS, JSON.stringify(users));
    GoogleSheetsService.saveData('saveUsers', users);
  },

  getProductionData: (): ProductionEntry[] => {
    try {
      const data = JSON.parse(localStorage.getItem(KEYS.PRODUCTION) || '[]');
      return Array.isArray(data) ? data.map(normalizeProduction) : [];
    } catch { return []; }
  },
  saveProductionData: (data: ProductionEntry[]) => {
    localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(data));
    GoogleSheetsService.saveData('saveProduction', data);
  },

  deleteProductionEntry: (id: string): { updatedData: ProductionEntry[], deletedItem: ProductionEntry | null } => {
    try {
      const data = StorageService.getProductionData();
      const targetId = String(id);

      const targetItem = data.find(p => String(p.id) === targetId) || null;
      const updatedData = data.filter(p => String(p.id) !== targetId);

      StorageService.saveProductionData(updatedData);

      return { updatedData, deletedItem: targetItem };
    } catch (err) {
      console.error("Storage delete error:", err);
      return { updatedData: StorageService.getProductionData(), deletedItem: null };
    }
  },

  getOffDays: (): OffDay[] => {
    try {
      const data = JSON.parse(localStorage.getItem(KEYS.OFF_DAYS) || '[]');
      return Array.isArray(data) ? data.map(normalizeOffDay) : [];
    } catch { return []; }
  },
  saveOffDays: (days: OffDay[]) => {
    localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(days));
    GoogleSheetsService.saveData('saveOffDays', days);
  },

  // Sync Logic
  syncWithSheets: async () => {
    if (!GoogleSheetsService.isEnabled()) return;

    // Pull Production Data
    const remoteProduction = await GoogleSheetsService.fetchData<any[]>('getProduction');
    if (remoteProduction && Array.isArray(remoteProduction)) {
        const cleaned = remoteProduction.map(normalizeProduction);
        localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(cleaned));
    }

    // Pull Off Days
    const remoteOffDays = await GoogleSheetsService.fetchData<any[]>('getOffDays');
    if (remoteOffDays && Array.isArray(remoteOffDays)) {
        const cleaned = remoteOffDays.map(normalizeOffDay);
        localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(cleaned));
    }

    // Pull Activity Logs
    const remoteLogs = await GoogleSheetsService.fetchData<any[]>('getLogs');
    if (remoteLogs && Array.isArray(remoteLogs)) {
        const cleanedLogs = remoteLogs.map(normalizeLog);
        localStorage.setItem(KEYS.LOGS, JSON.stringify(cleanedLogs));
    }

    // Pull Users
    const remoteUsers = await GoogleSheetsService.fetchData<User[]>('getUsers');
    if (remoteUsers && Array.isArray(remoteUsers)) {
        localStorage.setItem(KEYS.USERS, JSON.stringify(remoteUsers));
    }
  },

  getLogs: (): ActivityLog[] => {
    try {
      const data = JSON.parse(localStorage.getItem(KEYS.LOGS) || '[]');
      return Array.isArray(data) ? data.map(normalizeLog) : [];
    } catch { return []; }
  },
  addLog: (log: Omit<ActivityLog, 'id' | 'timestamp'>) => {
    try {
      const logs = StorageService.getLogs();
      const newLog: ActivityLog = {
        ...log,
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
      };
      logs.unshift(newLog);
      if (logs.length > 1000) logs.pop();

      localStorage.setItem(KEYS.LOGS, JSON.stringify(logs));
      GoogleSheetsService.saveData('saveLogs', logs);
    } catch (err) {
      console.error("Logging error:", err);
    }
  },

  getSession: (): User | null => {
    try {
      const session = localStorage.getItem(KEYS.CURRENT_USER);
      return session ? JSON.parse(session) : null;
    } catch { return null; }
  },
  setSession: (user: User | null) => {
    if (user) localStorage.setItem(KEYS.CURRENT_USER, JSON.stringify(user));
    else localStorage.removeItem(KEYS.CURRENT_USER);
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { CATEGORIES, PROCESSES } from '../../constants';
import { ProductionEntry, Category, ProcessType } from '../../types';
import { X, Loader2, AlertTriangle, Palmtree } from 'lucide-react';
import { getTodayISO } from '../../utils/dateUtils';

interface InputModalProps {
  onClose: () => void;
  editEntry?: ProductionEntry | null;
}

export const InputModal: React.FC<InputModalProps> = ({ onClose, editEntry }) => {
  const { user, hasPermission } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [tab, setTab] = useState<'Plan' | 'Actual'>('Plan');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [date, setDate] = useState(getTodayISO());
  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [process, setProcess] = useState<ProcessType>(PROCESSES[0]);
  const [productName, setProductName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [manpower, setManpower] = useState('0');
  const [batchNo, setBatchNo] = useState('');

  const [plans, setPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  const offDays = useMemo(() => StorageService.getOffDays(), []);
  const currentOffDay = useMemo(() => {
    const inputDate = (date || '').trim().substring(0, 10);
    return offDays.find(od => (od.date || '').trim().substring(0, 10) === inputDate);
  }, [date, offDays]);

  const inputClasses = "w-full p-2.5 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-slate-900 dark:text-white font-bold focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all shadow-sm";

  useEffect(() => {
    if (currentOffDay && !editEntry) {
      window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: `PUBLIC HOLIDAY: ${currentOffDay.description}`, type: 'info' } 
      }));
    }
  }, [currentOffDay, editEntry]);

  useEffect(() => {
    if (editEntry) {
      setDate((editEntry.date || '').trim().substring(0, 10));
      setCategory(editEntry.category);
      setProcess(editEntry.process);
      setProductName(editEntry.productName);
      // Determine which quantity to show in the single input field based on the mode
      const isActualMode = editEntry.actualQuantity > 0;
      setQuantity(isActualMode ? (editEntry.actualQuantity || 0).toString() : (editEntry.planQuantity || 0).toString());
      setManpower(editEntry.manpower?.toString() || '0');
      setBatchNo(editEntry.batchNo || '');
      setTab(isActualMode ? 'Actual' : 'Plan'); 
    } else {
      if (user?.role === 'operator') setTab('Actual');
      else if (user?.role === 'planner') setTab('Plan');
    }
  }, [editEntry, user]);

  useEffect(() => {
    if (tab === 'Actual' && !editEntry) {
        const all = StorageService.getProductionData();
        const normalizedInputDate = (date || '').trim().substring(0, 10);
        const relevant = all.filter(p => (p.date || '').trim().substring(0, 10) === normalizedInputDate);
        setPlans(relevant);
        setSelectedPlanId('');
    }
  }, [date, tab, editEntry]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    // Strict normalization to YYYY-MM-DD
    const normalizedDate = (date || '').trim().split('T')[0].substring(0, 10);

    if (!editEntry && currentOffDay) {
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: `ENTRY RESTRICTED: Today is ${currentOffDay.description}`, type: 'info' } 
        }));
        setIsSubmitting(false);
        return;
    }

    const currentData = StorageService.getProductionData();

    try {
        if (editEntry) {
            // Track what changed for the log
            const changes: string[] = [];
            const newQty = parseInt(quantity || '0');
            const newManpower = parseInt(manpower || '0');

            if (editEntry.date !== normalizedDate) changes.push(`Date (${editEntry.date} → ${normalizedDate})`);
            if (editEntry.productName !== productName) changes.push(`Product (${editEntry.productName} → ${productName})`);
            if (editEntry.category !== category) changes.push(`Category (${editEntry.category} → ${category})`);
            if (editEntry.process !== process) changes.push(`Process (${editEntry.process} → ${process})`);

            if (tab === 'Plan') {
              if (editEntry.planQuantity !== newQty) changes.push(`Plan Qty (${editEntry.planQuantity} → ${newQty})`);
            } else {
              if (editEntry.actualQuantity !== newQty) changes.push(`Actual Qty (${editEntry.actualQuantity} → ${newQty})`);
            }

            if ((editEntry.manpower || 0) !== newManpower) changes.push(`Manpower (${editEntry.manpower || 0} → ${newManpower})`);
            if ((editEntry.batchNo || '') !== batchNo) changes.push(`Batch (${editEntry.batchNo || 'None'} → ${batchNo || 'None'})`);

            const updated = currentData.map(p => {
                if (p.id === editEntry.id) {
                    return { 
                        ...p, 
                        date: normalizedDate, 
                        category, process, productName,
                        planQuantity: tab === 'Plan' ? newQty : p.planQuantity,
                        actualQuantity: tab === 'Actual' ? newQty : p.actualQuantity,
                        batchNo, manpower: newManpower,
                        lastUpdatedBy: user!.id, updatedAt: new Date().toISOString()
                    };
                }
                return p;
            });

            StorageService.saveProductionData(updated);

            // Build Contextual Log Details: "Edited Product (Process) on Date: Changes"
            const logDetails = changes.length > 0 
              ? `Edited ${productName} (${editEntry.process}) on ${editEntry.date}: ${changes.join(', ')}`
              : `Updated record for ${productName} (${editEntry.process}) on ${editEntry.date} (No values changed)`;

            StorageService.addLog({
              userId: user!.id,
              userName: user!.name,
              action: 'EDIT_RECORD',
              details: logDetails
            });
        } else {
            if (tab === 'Plan') {
                const newEntry: ProductionEntry = {
                    id: Date.now().toString(),
                    date: normalizedDate, 
                    category, process, productName, 
                    planQuantity: parseInt(quantity || '0'), actualQuantity: 0,
                    lastUpdatedBy: user!.id, updatedAt: new Date().toISOString()
                };
                StorageService.saveProductionData([...currentData, newEntry]);
                StorageService.addLog({
                  userId: user!.id,
                  userName: user!.name,
                  action: 'CREATE_PLAN',
                  details: `Planned ${newEntry.planQuantity} units for ${newEntry.productName} (${normalizedDate})`
                });
            } else {
                if (!selectedPlanId) throw new Error("Please select a plan");
                const targetPlan = currentData.find(p => p.id === selectedPlanId);
                const updated = currentData.map(p => {
                    if (p.id === selectedPlanId) {
                        return { 
                            ...p, 
                            actualQuantity: parseInt(quantity || '0'), batchNo, manpower: parseInt(manpower || '0'),
                            lastUpdatedBy: user!.id, updatedAt: new Date().toISOString()
                        };
                    }
                    return p;
                });
                StorageService.saveProductionData(updated);
                StorageService.addLog({
                  userId: user!.id,
                  userName: user!.name,
                  action: 'RECORD_ACTUAL',
                  details: `Recorded actual output of ${quantity} units for ${targetPlan?.productName || 'product'}`
                });
            }
        }

        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: 'PRODUCTION RECORD SYNCHRONIZED', type: 'success' } 
        }));

        triggerRefresh();
        onClose();
    } catch (err: any) {
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: err.message || 'Operation failed', type: 'info' } 
        }));
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-md shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-700 relative">
        {isSubmitting && (
            <div className="absolute inset-0 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm z-10 flex flex-col items-center justify-center">
                <Loader2 className="w-10 h-10 text-indigo-600 animate-spin mb-2" />
                <p className="text-xs font-black uppercase tracking-widest text-indigo-600">Uploading to Cloud...</p>
            </div>
        )}

        <div className="flex border-b border-gray-200 dark:border-slate-700">
            {!editEntry ? (
              <>
                {hasPermission(['admin', 'manager', 'planner']) && (
                    <button onClick={() => setTab('Plan')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Plan' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        Production Plan
                    </button>
                )}
                {hasPermission(['admin', 'manager', 'operator']) && (
                    <button onClick={() => setTab('Actual')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Actual' ? 'border-emerald-500 text-emerald-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        Production Actual
                    </button>
                )}
              </>
            ) : (
              <div className="flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center text-indigo-600 border-b-2 border-indigo-600">
                Updating Record
              </div>
            )}
        </div>

        <div className="p-6 relative">
            <button onClick={onClose} className="absolute top-2 right-4 text-slate-300 hover:text-rose-500 transition-colors"><X className="w-5 h-5" /></button>

            <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Production Date</label>
                    <input type="date" required value={date} onChange={e => setDate(e.target.value)} className={inputClasses} />

                    {currentOffDay && (
                      <div className="mt-3 p-3 bg-amber-50 dark:bg-amber-900/20 border border-amber-300 dark:border-amber-700 rounded-xl flex items-center gap-3 animate-pulse shadow-sm">
                        <div className="p-2 bg-amber-500 text-white rounded-lg shadow-md">
                          <Palmtree className="w-4 h-4" />
                        </div>
                        <div className="flex-1">
                          <p className="text-[10px] font-black text-amber-700 dark:text-amber-400 uppercase tracking-widest leading-none mb-1">Public Holiday</p>
                          <p className="text-xs font-black text-slate-900 dark:text-amber-50">{currentOffDay.description || 'OFF DAY'}</p>
                        </div>
                        <AlertTriangle className="w-5 h-5 text-amber-500" />
                      </div>
                    )}
                </div>

                {tab === 'Plan' || editEntry ? (
                    <>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Category</label>
                                <select value={category} onChange={e => setCategory(e.target.value as Category)} className={inputClasses}>
                                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Process</label>
                                <select value={process} onChange={e => setProcess(e.target.value as ProcessType)} className={inputClasses}>
                                    {PROCESSES.map(p => <option key={p} value={p}>{p}</option>)}
                                </select>
                            </div>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Product Name</label>
                            <input type="text" required value={productName} onChange={e => setProductName(e.target.value)} className={inputClasses} placeholder="Enter name..." />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Quantity</label>
                              <input type="number" required min="1" value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                          </div>
                          {editEntry && (
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Manpower</label>
                                <input type="number" required min="0" value={manpower} onChange={e => setManpower(e.target.value)} className={inputClasses} />
                            </div>
                          )}
                        </div>
                        {editEntry && (
                          <div>
                              <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Batch Number</label>
                              <input type="text" value={batchNo} onChange={e => setBatchNo(e.target.value)} className={inputClasses} />
                          </div>
                        )}
                    </>
                ) : (
                    <>
                        <div className="mb-4">
                             <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Select Active Job</label>
                             {plans.length === 0 ? <div className="text-xs text-slate-400 italic text-center p-6 border-2 border-dashed rounded-xl">No plans scheduled for this date.</div> : (
                                 <div className="max-h-40 overflow-y-auto border rounded-xl p-2 space-y-1 dark:border-slate-700 bg-slate-50 dark:bg-slate-900/50">
                                     {plans.map(p => (
                                         <div key={p.id} onClick={() => setSelectedPlanId(p.id)}
                                            className={`p-3 rounded-lg cursor-pointer transition ${selectedPlanId === p.id ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-600 dark:text-slate-300 hover:bg-white dark:hover:bg-slate-800'}`}>
                                            <div className="font-black text-sm">{p.productName}</div>
                                            <div className={`text-[10px] font-bold uppercase ${selectedPlanId === p.id ? 'text-indigo-100' : 'text-slate-400'}`}>{p.process} • Plan: {p.planQuantity}</div>
                                         </div>
                                     ))}
                                 </div>
                             )}
                        </div>
                        {selectedPlanId && (
                            <>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Actual Qty</label>
                                        <input type="number" required value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                                    </div>
                                    <div>
                                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Manpower</label>
                                        <input type="number" required value={manpower} onChange={e => setManpower(e.target.value)} className={inputClasses} />
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Batch Number</label>
                                    <input type="text" required value={batchNo} onChange={e => setBatchNo(e.target.value)} className={inputClasses} placeholder="Enter batch ID..." />
                                </div>
                            </>
                        )}
                    </>
                )}

                <button 
                    type="submit" 
                    disabled={isSubmitting || (!editEntry && !!currentOffDay)} 
                    className={`w-full py-4 rounded-xl font-black text-xs uppercase tracking-[0.2em] text-white mt-6 shadow-xl transition hover:opacity-90 disabled:opacity-50 disabled:cursor-not-allowed ${
                        !!currentOffDay && !editEntry ? 'bg-amber-600' : 
                        tab === 'Plan' ? 'bg-slate-900 dark:bg-indigo-600 shadow-indigo-500/10' : 
                        'bg-emerald-600 shadow-emerald-500/10'
                    }`}
                >
                    {isSubmitting ? 'Syncing...' : (!!currentOffDay && !editEntry ? 'Holiday Entry Locked' : 'Update System')}
                </button>
            </form>
        </div>
      </div>
    </div>
  );
};

import { User, ProductionEntry, OffDay, ActivityLog } from '../types';
import { INITIAL_USERS, INITIAL_OFF_DAYS, generateSeedProductionData } from '../constants';
import { GoogleSheetsService } from './googleSheetsService';

const KEYS = {
  USERS: 'halagel_users',
  PRODUCTION: 'halagel_production',
  OFF_DAYS: 'halagel_off_days',
  LOGS: 'halagel_activity_logs',
  CURRENT_USER: 'halagel_current_user_session',
};

// Normalizer for Production Entries - Ensures NO property is ever undefined/null
const normalizeProduction = (data: any): ProductionEntry => {
  if (!data) return {} as ProductionEntry;

  let entry: Partial<ProductionEntry> = {};

  if (Array.isArray(data)) {
    entry = {
      id: String(data[0] || Date.now()),
      date: String(data[1] || ''),
      category: String(data[2] || 'Healthcare') as any,
      process: String(data[3] || 'Mixing') as any,
      productName: String(data[4] || 'Unknown'),
      planQuantity: Number(data[5] || 0),
      actualQuantity: Number(data[6] || 0),
      batchNo: String(data[7] || ''),
      manpower: Number(data[8] || 0),
      lastUpdatedBy: String(data[9] || ''),
      updatedAt: String(data[10] || new Date().toISOString())
    };
  } else {
    entry = {
      ...data,
      id: String(data.id || Date.now()),
      date: String(data.date || ''),
      productName: String(data.productName || 'Unknown'),
      planQuantity: Number(data.planQuantity || 0),
      actualQuantity: Number(data.actualQuantity || 0),
      manpower: Number(data.manpower || 0),
      batchNo: String(data.batchNo || ''),
      process: String(data.process || 'Mixing') as any,
      category: String(data.category || 'Healthcare') as any
    };
  }
  return entry as ProductionEntry;
};

// Normalizer for Activity Logs
const normalizeLog = (data: any): ActivityLog => {
  if (!data) return {} as ActivityLog;

  if (Array.isArray(data)) {
    return {
      id: String(data[0] || Date.now()),
      timestamp: String(data[1] || new Date().toISOString()),
      userId: String(data[2] || ''),
      userName: String(data[3] || 'System'),
      action: String(data[4] || 'LOG'),
      details: String(data[5] || '')
    };
  }
  return {
    ...data,
    id: String(data.id || Date.now()),
    timestamp: String(data.timestamp || new Date().toISOString()),
    userName: String(data.userName || 'Unknown'),
    details: String(data.details || '')
  };
};

// Normalizer for Off Days
const normalizeOffDay = (data: any): OffDay => {
  if (!data) return {} as OffDay;

  if (Array.isArray(data)) {
    return {
      id: String(data[0] || Date.now()),
      date: String(data[1] || ''),
      description: String(data[2] || 'Holiday'),
      createdBy: String(data[3] || 'System')
    };
  }
  return {
    ...data,
    id: String(data.id || Date.now()),
    date: String(data.date || ''),
    description: String(data.description || 'Holiday')
  };
};

const init = () => {
  if (!localStorage.getItem(KEYS.USERS)) {
    localStorage.setItem(KEYS.USERS, JSON.stringify(INITIAL_USERS));
  }
  if (!localStorage.getItem(KEYS.OFF_DAYS)) {
    localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(INITIAL_OFF_DAYS));
  }
  if (!localStorage.getItem(KEYS.PRODUCTION)) {
    localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(generateSeedProductionData()));
  }
  if (!localStorage.getItem(KEYS.LOGS)) {
    localStorage.setItem(KEYS.LOGS, JSON.stringify([]));
  }
};

init();

export const StorageService = {
  getUsers: (): User[] => {
    try {
      const data = JSON.parse(localStorage.getItem(KEYS.USERS) || '[]');
      return Array.isArray(data) ? data : [];
    } catch { return []; }
  },
  saveUsers: (users: User[]) => {
    localStorage.setItem(KEYS.USERS, JSON.stringify(users));
    GoogleSheetsService.saveData('saveUsers', users);
  },

  getProductionData: (): ProductionEntry[] => {
    try {
      const data = JSON.parse(localStorage.getItem(KEYS.PRODUCTION) || '[]');
      return Array.isArray(data) ? data.map(normalizeProduction).filter(p => p.date && p.date.length > 0) : [];
    } catch { return []; }
  },
  saveProductionData: (data: ProductionEntry[]) => {
    const cleaned = data.map(normalizeProduction).filter(p => p.date && p.date.length > 0);
    localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(cleaned));
    GoogleSheetsService.saveData('saveProduction', cleaned);
  },

  deleteProductionEntry: (id: string): { updatedData: ProductionEntry[], deletedItem: ProductionEntry | null } => {
    try {
      const data = StorageService.getProductionData();
      const targetId = String(id);
      const targetItem = data.find(p => String(p.id) === targetId) || null;
      const updatedData = data.filter(p => String(p.id) !== targetId);
      StorageService.saveProductionData(updatedData);
      return { updatedData, deletedItem: targetItem };
    } catch (err) {
      console.error("Storage delete error:", err);
      return { updatedData: StorageService.getProductionData(), deletedItem: null };
    }
  },

  getOffDays: (): OffDay[] => {
    try {
      const data = JSON.parse(localStorage.getItem(KEYS.OFF_DAYS) || '[]');
      return Array.isArray(data) ? data.map(normalizeOffDay).filter(od => od.date && od.date.length > 0) : [];
    } catch { return []; }
  },
  saveOffDays: (days: OffDay[]) => {
    const cleaned = days.map(normalizeOffDay).filter(od => od.date && od.date.length > 0);
    localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(cleaned));
    GoogleSheetsService.saveData('saveOffDays', cleaned);
  },

  syncWithSheets: async () => {
    if (!GoogleSheetsService.isEnabled()) return;

    // Multi-part sync to ensure logs and data are all updated
    try {
      const results = await Promise.all([
        GoogleSheetsService.fetchData<any[]>('getProduction'),
        GoogleSheetsService.fetchData<any[]>('getOffDays'),
        GoogleSheetsService.fetchData<any[]>('getLogs'),
        GoogleSheetsService.fetchData<User[]>('getUsers')
      ]);

      if (results[0] && Array.isArray(results[0])) {
          const cleaned = results[0].map(normalizeProduction).filter(p => p.date && p.date.length > 0);
          localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(cleaned));
      }

      if (results[1] && Array.isArray(results[1])) {
          const cleaned = results[1].map(normalizeOffDay).filter(od => od.date && od.date.length > 0);
          localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(cleaned));
      }

      if (results[2] && Array.isArray(results[2])) {
          const cleanedLogs = results[2].map(normalizeLog).filter(l => l.timestamp);
          localStorage.setItem(KEYS.LOGS, JSON.stringify(cleanedLogs));
      }

      if (results[3] && Array.isArray(results[3])) {
          localStorage.setItem(KEYS.USERS, JSON.stringify(results[3]));
      }
    } catch (err) {
      console.error("Critical Sync Failure:", err);
      throw err;
    }
  },

  getLogs: (): ActivityLog[] => {
    try {
      const data = JSON.parse(localStorage.getItem(KEYS.LOGS) || '[]');
      return Array.isArray(data) ? data.map(normalizeLog) : [];
    } catch { return []; }
  },
  addLog: (log: Omit<ActivityLog, 'id' | 'timestamp'>) => {
    try {
      const logs = StorageService.getLogs();
      const newLog: ActivityLog = {
        ...log,
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
      };
      logs.unshift(newLog);
      if (logs.length > 500) logs.pop(); // Keep manageable size

      localStorage.setItem(KEYS.LOGS, JSON.stringify(logs));
      GoogleSheetsService.saveData('saveLogs', logs);
    } catch (err) {
      console.error("Logging error:", err);
    }
  },

  getSession: (): User | null => {
    try {
      const session = localStorage.getItem(KEYS.CURRENT_USER);
      return session ? JSON.parse(session) : null;
    } catch { return null; }
  },
  setSession: (user: User | null) => {
    if (user) localStorage.setItem(KEYS.CURRENT_USER, JSON.stringify(user));
    else localStorage.removeItem(KEYS.CURRENT_USER);
  }
};

