export const CATEGORIES = ['Healthcare', 'Toothpaste', 'Rocksalt'] as const;
export const PROCESSES = ['Mixing', 'Encapsulation', 'Filling', 'Sorting', 'Packing'] as const;

export const INITIAL_USERS: User[] = [
