/**
 * GOOGLE SHEETS CONFIGURATION
 * 
 * Replace "PASTE_YOUR_NEW_WEBAPP_URL_HERE" with your unique Google Apps Script deployment URL.
 */
export const HARDCODED_URL = "PASTE_YOUR_NEW_WEBAPP_URL_HERE"; 

const getSheetUrl = () => {
  const savedUrl = localStorage.getItem('halagel_sheets_api_url');
  if (savedUrl && savedUrl.startsWith('https://script.google.com')) return savedUrl;
  if (HARDCODED_URL && HARDCODED_URL.startsWith('https://script.google.com')) return HARDCODED_URL;
  return null;
};

export const GoogleSheetsService = {
  // Only enabled if a valid Google Script URL is provided
  isEnabled: () => !!getSheetUrl(),

  getActiveUrl: () => getSheetUrl(),

  fetchData: async <T>(action: string): Promise<T | null> => {
    const url = getSheetUrl();
    if (!url) {
      console.warn(`Fetch cancelled: No valid Google Script URL configured for ${action}.`);
      return null;
    }

    try {
      const seed = Math.random().toString(36).substring(7);
      const response = await fetch(`${url}?action=${action}&_t=${Date.now()}&_s=${seed}`);

      if (!response.ok) throw new Error(`HTTP ${response.status}`);

      const json = await response.json();
      return json;
    } catch (error) {
      console.error(`Sheets fetch error (${action}):`, error);
      return null;
    }
  },

  saveData: async (action: string, payload: any): Promise<boolean> => {
    const url = getSheetUrl();
    if (!url) {
      console.warn(`Save cancelled: No valid Google Script URL configured for ${action}.`);
      return false;
    }

    try {
      // mode: 'no-cors' is used because Apps Script redirects (302) often fail CORS pre-flight
      // but 'no-cors' allows the request to reach the server even if we can't read the response body.
      await fetch(url, {
        method: 'POST',
        mode: 'no-cors', 
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action, data: payload, timestamp: Date.now() })
      });
      return true;
    } catch (error) {
      console.error(`Sheets save error (${action}):`, error);
      return false;
    }
  }
};

