              <div className="space-y-4">
                  <h3 className="text-2xl font-black tracking-tight">Modern Enterprise Stack</h3>
                  <p className="text-sm text-slate-400 max-w-md font-medium leading-relaxed">
                    Engineered with React 19 and ESM modules for maximum performance and low-latency interaction in industrial environments.
                  </p>
                  <div className="flex flex-wrap gap-3 pt-4">
                      {['React 19', 'Tailwind CSS', 'Vite', 'Google API', 'Recharts'].map(tech => (
                        <span key={tech} className="px-3 py-1 bg-white/10 rounded-lg text-[10px] font-black uppercase tracking-widest border border-white/10">{tech}</span>
