/**
 * HOLIDAY SYNC UTILITY
 * Handles fetching Malaysia public holidays and processing company-specific off-days.
 */

export const fetchMalaysiaHolidays = async (year: number) => {
  try {
    const response = await fetch(`https://date.nager.at/api/v3/PublicHolidays/${year}/MY`);
    if (!response.ok) throw new Error('Failed to fetch holidays');
    const data = await response.json();
    return data.map((h: any) => ({
      id: `sync-${h.date}-${h.name}`,
      date: h.date,
      description: h.localName || h.name,
      createdBy: 'System Sync'
    }));
  } catch (error) {
    console.error('Holiday Sync Error:', error);
    return null;
  }
};

export const parseCompanyCalendar = (text: string) => {
  // Simple parser for "YYYY-MM-DD Description" per line
  const lines = text.split('\n');
  const holidays = [];
  for (const line of lines) {
    const match = line.match(/^(\d{4}-\d{2}-\d{2})\s+(.+)$/);
    if (match) {
      holidays.push({
        id: `custom-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
        date: match[1],
        description: match[2].trim(),
        createdBy: 'Manual Bulk Import'
      });
    }
  }
  return holidays;
};

import React, { useState, useEffect } from 'react';
import { StorageService } from '../../services/storageService';
