export const OffDayModal: React.FC<{ onClose: () => void }> = ({ onClose }) => {
  const { user } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [offDays, setOffDays] = useState<OffDay[]>(StorageService.getOffDays());
  const [date, setDate] = useState('');
  const [desc, setDesc] = useState('');
  const [isSyncing, setIsSyncing] = useState(false);
  const [importText, setImportText] = useState('');
  const [showBulk, setShowBulk] = useState(false);

  const inputClasses = "w-full p-2.5 border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-slate-900 dark:text-white font-bold rounded-xl outline-none shadow-sm focus:ring-2 focus:ring-indigo-500/20";

  const handleAdd = () => {
    if(!date) return;
    if(offDays.some(od => od.date === date)) return alert('This date is already marked as an off day.');
    const newOd: OffDay = { id: Date.now().toString(), date, description: desc || 'Holiday', createdBy: user!.id };
    const updated = [...offDays, newOd].sort((a,b) => (a.date || '').localeCompare(b.date || ''));
    saveAndUpdate(updated, `Manual holiday added: ${newOd.description}`);
    setDate(''); setDesc('');
  };

  const handleSyncHolidays = async () => {
    setIsSyncing(true);
    const year = new Date().getFullYear();
    const synced = await fetchMalaysiaHolidays(year);
    if (synced) {
      const existingDates = new Set(offDays.map(o => o.date));
      const newHolidays = synced.filter((h: OffDay) => !existingDates.has(h.date));
      const updated = [...offDays, ...newHolidays].sort((a,b) => a.date.localeCompare(b.date));
      saveAndUpdate(updated, `Synced ${newHolidays.length} Malaysia Public Holidays for ${year}`);
      window.dispatchEvent(new CustomEvent('app-notification', { 
          detail: { message: `SYNC COMPLETE: ${newHolidays.length} HOLIDAYS ADDED`, type: 'success' } 
      }));
    }
    setIsSyncing(false);
  };

  const handleBulkImport = () => {
    const imported = parseCompanyCalendar(importText);
    if (imported.length > 0) {
      const existingDates = new Set(offDays.map(o => o.date));
      const filtered = imported.filter(h => !existingDates.has(h.date));
      const updated = [...offDays, ...filtered].sort((a,b) => a.date.localeCompare(b.date));
      saveAndUpdate(updated, `Bulk imported ${filtered.length} company off-days`);
      setImportText('');
      setShowBulk(false);
    }
  };

  const saveAndUpdate = (updated: OffDay[], logMsg: string) => {
    StorageService.saveOffDays(updated);
    StorageService.addLog({
      userId: user!.id,
      userName: user!.name,
      action: 'CALENDAR_UPDATE',
      details: logMsg
    });
    setOffDays(updated);
    triggerRefresh();
  };

  const handleRemove = (id: string) => {
    const target = offDays.find(od => od.id === id);
    const updated = offDays.filter(od => od.id !== id);
    saveAndUpdate(updated, `Removed holiday: ${target?.description} (${target?.date})`);
  };

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] w-full max-w-lg shadow-2xl p-8 animate-in fade-in zoom-in duration-300 border border-slate-200 dark:border-slate-700 max-h-[90vh] flex flex-col">
        <div className="flex justify-between items-center mb-6">
