export const generateSeedProductionData = (): ProductionEntry[] => {
  const data: ProductionEntry[] = [];
  const products = ['Pain Relief Gel', 'Minty Fresh', 'Pink Salt Fine', 'Vitamin C', 'Charcoal Paste', 'Herbal Shampoo', 'Skin Repair Cream'];

  const todayStr = getTodayISO();
  const [y, m, d] = todayStr.split('-').map(Number);
  const baseDate = new Date(y, m - 1, d);

  for (let i = 0; i < 30; i++) {
    const d = new Date(baseDate);
    d.setDate(baseDate.getDate() - i);

    const dateStr = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

    products.forEach((prod, idx) => {
      if (Math.random() > 0.8) return;

      const plan = Math.floor(Math.random() * 500) + 500;
      const actual = Math.floor(plan * (0.8 + Math.random() * 0.2));

      data.push({
        id: `seed-${i}-${idx}`,
        date: dateStr,
        category: CATEGORIES[idx % CATEGORIES.length],
        process: PROCESSES[idx % PROCESSES.length],
        productName: prod,
        planQuantity: plan,
        actualQuantity: actual,
        unit: idx % 2 === 0 ? 'KG' : 'PCS',
        batchNo: `B-${dateStr.replace(/-/g, '')}-${idx}`,
        manpower: Math.floor(Math.random() * 5) + 3,
        lastUpdatedBy: 'u1',
        updatedAt: getDbTimestamp()
      });
    });
  }
  return data;
};

/**
 * HOLIDAY SYNC UTILITY
 * Handles fetching Malaysia public holidays and processing company-specific off-days.
 * Robustness update: Validates response body before parsing JSON.
 */

export const fetchMalaysiaHolidays = async (year: number) => {
  try {
    const response = await fetch(`https://date.nager.at/api/v3/PublicHolidays/${year}/MY`);

    if (!response.ok) {
        throw new Error(`HTTP Error: ${response.status}`);
    }

    const text = await response.text();
    if (!text || text.trim().length === 0) {
        console.warn('Holiday Sync: Received empty response from API');
        return [];
    }

    const data = JSON.parse(text);
    return data.map((h: any) => ({
      id: `sync-${h.date}-${h.name}`,
      date: h.date,
      description: h.localName || h.name,
      createdBy: 'System Sync'
    }));
  } catch (error) {
    console.error('Holiday Sync Error:', error);
    return null;
  }
};

export const parseCompanyCalendar = (text: string) => {
  // Simple parser for "YYYY-MM-DD Description" per line
  const lines = text.split('\n');
  const holidays = [];
  for (const line of lines) {
    const match = line.match(/^(\d{4}-\d{2}-\d{2})\s+(.+)$/);
    if (match) {
      holidays.push({
        id: `custom-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
        date: match[1],
        description: match[2].trim(),
        createdBy: 'Manual Bulk Import'
      });
    }
  }
  return holidays;
};

