                                        <th className="px-8 py-4">Process</th>
                                        <th className="px-8 py-4">Product</th>
                                        <th className="px-8 py-4 text-right">Plan</th>
                                        <th className="px-8 py-4 text-right">Actual</th>
                                        <th className="px-8 py-4 text-center">Batch No</th>
                                        {hasPermission(['admin', 'manager']) && <th className="px-8 py-4 text-center">Action</th>}
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-50 dark:divide-slate-800/30">
                                    {group.entries.map(entry => (
                                        <tr key={entry.id} className="hover:bg-gray-50/50 transition-colors">
                                            <td className="px-8 py-5"><span className="text-[10px] font-black text-indigo-600 uppercase bg-indigo-50 px-2 py-1 rounded-lg">{entry.process}</span></td>
                                            <td className="px-8 py-5 text-sm font-black">{entry.productName}</td>
                                            <td className="px-8 py-5 text-right font-mono text-indigo-600/80">{(entry.planQuantity || 0).toLocaleString()}</td>
                                            <td className="px-8 py-5 text-right font-mono text-emerald-500 font-black">{(entry.actualQuantity || 0).toLocaleString()}</td>
                                            <td className="px-8 py-5 text-center font-mono text-[11px] text-slate-400">{entry.batchNo || '-'}</td>
                                            {hasPermission(['admin', 'manager']) && (
                                              <td className="px-8 py-5">
