import React, { useState, useEffect, useMemo } from 'react';
import { StorageService } from '../../services/storageService';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { ProductionEntry } from '../../types';
import { AlertCircle, CheckCircle2, Palmtree, Lock } from 'lucide-react';
import { getTodayISO } from '../../utils/dateUtils';

export const InputActual: React.FC = () => {
  const { user } = useAuth();
  const { triggerRefresh, refreshKey } = useDashboard();
  const [date, setDate] = useState(getTodayISO());

  const [pendingPlans, setPendingPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  const [formData, setFormData] = useState({
    actualQty: '',
    manpower: '',
    batchNo: ''
  });

  const [msg, setMsg] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  // CRITICAL: RefreshKey
  const offDays = useMemo(() => StorageService.getOffDays(), [refreshKey]);
  const currentOffDay = useMemo(() => offDays.find(od => od.date === date), [date, offDays]);

  useEffect(() => {
    if (currentOffDay) {
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: `HOLIDAY LOCK: ${currentOffDay.description}`, type: 'info' } 
        }));
    }
  }, [currentOffDay]);

  useEffect(() => {
    const all = StorageService.getProductionData();
    const forDate = all.filter(p => p.date === date);
    setPendingPlans(forDate);
    setSelectedPlanId('');
    setFormData({ actualQty: '', manpower: '', batchNo: '' });
  }, [date, refreshKey]);

  const handleAutoBatch = () => {
    const r = Math.floor(Math.random() * 10000);
    const b = `B-${date.replace(/-/g, '')}-${r}`;
    setFormData(prev => ({ ...prev, batchNo: b }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (currentOffDay) {
      setMsg({ type: 'error', text: 'Operation Blocked: Cannot record data on holidays.' });
      return;
    }

    if (!selectedPlanId) {
      setMsg({ type: 'error', text: 'Please select a production plan to update.' });
      return;
    }

    try {
      const allData = StorageService.getProductionData();
      const updatedData = allData.map(entry => {
        if (entry.id === selectedPlanId) {
          return {
            ...entry,
            actualQuantity: parseInt(formData.actualQty),
            manpower: parseInt(formData.manpower),
            batchNo: formData.batchNo,
            lastUpdatedBy: user!.id,
            updatedAt: new Date().toISOString()
          };
        }
        return entry;
      });

      StorageService.saveProductionData(updatedData);

      const target = allData.find(e => e.id === selectedPlanId);
      StorageService.addLog({
        userId: user!.id,
        userName: user!.name,
        action: 'RECORD_ACTUAL',
        details: `Updated actuals for ${target?.productName}`
      });

      triggerRefresh();
      setMsg({ type: 'success', text: 'Actual data updated successfully.' });

      window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: 'ACTUAL PRODUCTION RECORDED', type: 'success' } 
      }));

      const forDate = updatedData.filter(p => p.date === date);
      setPendingPlans(forDate);
    } catch (err) {
      setMsg({ type: 'error', text: 'Error saving data.' });
    }
  };

  return (
    <div className="max-w-2xl mx-auto">
      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 p-8">
        <h2 className="text-2xl font-bold text-gray-800 dark:text-white mb-6">Input Actual Production</h2>

        {msg && (
          <div className={`p-4 rounded-lg mb-6 flex items-center ${msg.type === 'success' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>
            {msg.type === 'success' ? <CheckCircle2 className="w-5 h-5 mr-2" /> : <AlertCircle className="w-5 h-5 mr-2" />}
            {msg.text}
          </div>
        )}

        <div className="mb-6">
          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Select Date</label>
          <input 
            type="date" 
            className="w-full px-4 py-2 border border-gray-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500 dark:bg-slate-900 dark:text-white font-bold"
            value={date}
            onChange={e => setDate(e.target.value)}
          />

          {currentOffDay && (
            <div className="mt-4 p-4 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-2xl flex items-center gap-4">
              <div className="p-3 bg-amber-500 text-white rounded-xl shadow-lg shadow-amber-500/20">
                <Lock className="w-6 h-6" />
              </div>
              <div>
                <p className="text-[10px] font-black text-amber-600 uppercase tracking-widest leading-none mb-1">Restriction Active</p>
                <p className="text-sm font-black text-slate-800 dark:text-amber-100">Public Holiday: {currentOffDay.description}</p>
                <p className="text-[10px] font-bold text-amber-500 mt-1 uppercase">Inputs have been locked by the system</p>
              </div>
            </div>
          )}
        </div>

        {!currentOffDay ? (
          <>
            <div className="mb-6">
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Select Job / Plan</label>
              {pendingPlans.length === 0 ? (
                <div className="text-sm text-gray-500 italic p-3 border rounded bg-gray-50 dark:bg-slate-900 dark:border-slate-700">No plans found for this date. Ask a planner to input data first.</div>
              ) : (
                <div className="space-y-2 max-h-60 overflow-y-auto border border-gray-200 dark:border-slate-700 rounded-lg p-2">
                  {pendingPlans.map(plan => (
                    <div 
                      key={plan.id}
                      onClick={() => setSelectedPlanId(plan.id)}
                      className={`p-3 rounded-md cursor-pointer border transition-colors ${
                        selectedPlanId === plan.id 
                          ? 'bg-brand-50 border-brand-500 ring-1 ring-brand-500 dark:bg-brand-900/20' 
                          : 'bg-white dark:bg-slate-800 border-gray-200 dark:border-slate-700 hover:bg-gray-50 dark:hover:bg-slate-700'
                      }`}
                    >
                      <div className="flex justify-between items-center">
                        <span className="font-semibold text-gray-800 dark:text-white">{plan.productName}</span>
                        <span className="text-xs bg-gray-100 dark:bg-slate-700 px-2 py-1 rounded text-gray-600 dark:text-gray-400">{plan.category}</span>
                      </div>
                      <div className="text-sm text-gray-500 dark:text-gray-400 flex justify-between mt-1">
                        <span>{plan.process}</span>
                        <span>Plan: {plan.planQuantity}</span>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {selectedPlanId && (
              <form onSubmit={handleSubmit} className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-300">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Actual Quantity</label>
                    <input 
                      type="number" 
                      min="0"
                      required
                      className="w-full px-4 py-2 border border-gray-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500 dark:bg-slate-900 dark:text-white"
                      value={formData.actualQty}
                      onChange={e => setFormData({...formData, actualQty: e.target.value})}
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Manpower</label>
                    <input 
                      type="number" 
                      min="1"
                      required
                      className="w-full px-4 py-2 border border-gray-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500 dark:bg-slate-900 dark:text-white"
                      value={formData.manpower}
                      onChange={e => setFormData({...formData, manpower: e.target.value})}
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Batch Number</label>
                  <div className="flex space-x-2">
                    <input 
                      type="text" 
                      required
                      className="flex-1 px-4 py-2 border border-gray-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500 dark:bg-slate-900 dark:text-white"
                      value={formData.batchNo}
                      onChange={e => setFormData({...formData, batchNo: e.target.value})}
                    />
                    <button
                      type="button"
                      onClick={handleAutoBatch}
                      className="px-4 py-2 bg-gray-100 dark:bg-slate-700 text-gray-700 dark:text-gray-300 font-medium rounded-lg hover:bg-gray-200 dark:hover:bg-slate-600"
                    >
                      Generate
                    </button>
                  </div>
                </div>

                <button 
                  type="submit"
                  className="w-full bg-brand-600 text-white font-semibold py-2.5 rounded-lg hover:bg-brand-700 transition-colors shadow-sm"
                >
                  Update Production Data
                </button>
              </form>
            )}
          </>
        ) : (
          <div className="p-10 text-center flex flex-col items-center gap-4 bg-slate-50 dark:bg-slate-900/50 rounded-3xl border-2 border-dashed border-slate-200 dark:border-slate-700">
             <Lock className="w-12 h-12 text-slate-300" />
             <div>
                <p className="text-slate-500 font-black uppercase tracking-widest">Entry Forbidden</p>
                <p className="text-xs text-slate-400 mt-1">Please select a working day to record production.</p>
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { ProductionEntry, OffDay } from '../../types';
import { PROCESSES } from '../../constants';
import { 
  ClipboardList, CheckCircle, RefreshCw, List, Calendar, 
  TrendingUp, Download, Pencil, Trash2, Layers,
  Palmtree
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { formatDisplayDate, getCurrentMonthISO } from '../../utils/dateUtils';

export const Dashboard: React.FC = () => {
  const { category, refreshKey, triggerRefresh } = useDashboard();
  const { user, hasPermission } = useAuth();

  const [selectedMonth, setSelectedMonth] = useState<string>(getCurrentMonthISO());

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  const dashboardData = useMemo(() => {
    const relevant = productionData.filter(d => d && d.category === category && d.date);
    let selectedMonthPlan = 0;
    let selectedMonthActual = 0;

    const selectedMonthProcessMap = new Map<string, {process: string, Plan: number, Actual: number}>();
    PROCESSES.forEach(proc => {
      selectedMonthProcessMap.set(proc, { process: proc, Plan: 0, Actual: 0 });
    });

    relevant.forEach(d => {
      const dateStr = (d.date || '').trim().substring(0, 7);
      if (dateStr === selectedMonth) {
        selectedMonthPlan += (d.planQuantity || 0);
        selectedMonthActual += (d.actualQuantity || 0);

        const procName = d.process || 'Other';
        if (selectedMonthProcessMap.has(procName)) {
          const p = selectedMonthProcessMap.get(procName)!;
          p.Plan += (d.planQuantity || 0);
          p.Actual += (d.actualQuantity || 0);
        }
      }
    });

    return {
      filteredData: relevant.sort((a,b) => (b.date || '').localeCompare(a.date || '')),
      selectedMonthStats: { 
        plan: selectedMonthPlan, 
        actual: selectedMonthActual,
        efficiency: selectedMonthPlan > 0 ? (selectedMonthActual / selectedMonthPlan) * 100 : 0
      },
      chartData: Array.from(selectedMonthProcessMap.values())
    };
  }, [productionData, category, selectedMonth]);

  const dailyGroups = useMemo(() => {
    const baseData = dashboardData.filteredData;
    const filteredEntries = baseData.filter(d => d && d.date && d.date.trim().startsWith(selectedMonth));
    const filteredOffDays = offDays.filter(od => od && od.date && od.date.trim().startsWith(selectedMonth));

    const dates = new Set<string>();
    filteredEntries.forEach(d => {
      if (d.date) dates.add(d.date.trim().substring(0, 10));
    });
    filteredOffDays.forEach(od => {
      if (od.date) dates.add(od.date.trim().substring(0, 10));
    });

    const sortedDates = Array.from(dates).sort((a, b) => (b || '').localeCompare(a || ''));

    return sortedDates.map(dateKey => {
        const entriesForDate = filteredEntries.filter(d => d.date && d.date.trim().substring(0, 10) === dateKey);
        const offDayInfo = filteredOffDays.find(od => od.date && od.date.trim().substring(0, 10) === dateKey);
        const totalActualForDate = entriesForDate.reduce((sum, entry) => sum + (entry.actualQuantity || 0), 0);

        return {
            date: dateKey,
            totalActualForDate,
            entries: entriesForDate,
            isOffDay: !!offDayInfo,
            offDayName: offDayInfo?.description || ''
        };
    });
  }, [dashboardData.filteredData, offDays, selectedMonth]);

  const handleDelete = (id: string) => {
      if(!window.confirm("ARE YOU SURE YOU WANT TO PERMANENTLY DELETE THIS RECORD? THIS ACTION CANNOT BE UNDONE.")) return;
      const { deletedItem } = StorageService.deleteProductionEntry(id);
      if (deletedItem) {
          StorageService.addLog({
            userId: user!.id,
            userName: user!.name,
            action: 'DELETE_RECORD',
            details: `ADMIN/MANAGER PERMANENTLY DELETED PRODUCTION RECORD: ${deletedItem.productName.toUpperCase()} (${deletedItem.date})`
          });
          window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: 'RECORD DELETED SUCCESSFULLY', type: 'info' } 
          }));
      }
      triggerRefresh();
  };

  const handleEdit = (entry: ProductionEntry) => {
    window.dispatchEvent(new CustomEvent('edit-production-entry', { detail: entry }));
  };

  const downloadCSV = () => {
    const headers = ["DATE", "STATUS", "PROCESS", "PRODUCT", "PLAN", "ACTUAL", "UNIT", "BATCH NO", "MANPOWER"];
    const rows = dailyGroups.flatMap(g => {
        if (g.entries.length === 0) {
            return [[g.date, g.offDayName.toUpperCase() || 'OFF DAY', '-', '-', 0, 0, '-', '-', 0]];
        }
        return g.entries.map(d => [
            d.date, g.isOffDay ? `HOLIDAY (${g.offDayName.toUpperCase()})` : 'NORMAL', d.process.toUpperCase(), d.productName.toUpperCase(), d.planQuantity, d.actualQuantity, d.unit || 'KG', d.batchNo, d.manpower
        ]);
    });
    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `HALAGEL_FULL_REPORT_${category.toUpperCase()}_${selectedMonth}.csv`);
    document.body.appendChild(link);
    link.click();
    StorageService.addLog({
      userId: user!.id,
      userName: user!.name,
      action: 'EXPORT_REPORT',
      details: `EXPORTED FULL REPORT FOR ${category.toUpperCase()} (${selectedMonth})`
    });
    window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'REPORT EXPORTED SUCCESSFULLY', type: 'success' } }));
  };

  return (
    <div className="space-y-12 pb-12 uppercase">
      {/* KPI Cards - BIG FONT SIZE */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <div className="glass-panel p-8 rounded-[3rem] border-l-8 border-blue-500 shadow-xl relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
               <TrendingUp className="w-24 h-24" />
            </div>
            <p className="text-xs font-black text-slate-400 tracking-[0.3em]">MONTHLY PLAN (TOTAL)</p>
            <h3 className="text-6xl font-black mt-2 text-slate-900 dark:text-white font-mono tracking-tighter">{(dashboardData.selectedMonthStats.plan || 0).toLocaleString()}</h3>
        </div>
        <div className="glass-panel p-8 rounded-[3rem] border-l-8 border-emerald-500 shadow-xl relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
               <CheckCircle className="w-24 h-24" />
            </div>
            <p className="text-xs font-black text-slate-400 tracking-[0.3em]">MONTHLY ACTUAL (TOTAL)</p>
            <h3 className="text-6xl font-black mt-2 text-slate-900 dark:text-white font-mono tracking-tighter">{(dashboardData.selectedMonthStats.actual || 0).toLocaleString()}</h3>
        </div>
        <div className="glass-panel p-8 rounded-[3rem] border-l-8 border-indigo-500 shadow-xl relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
               <RefreshCw className="w-24 h-24" />
            </div>
            <p className="text-xs font-black text-slate-400 tracking-[0.3em]">OVERALL EFFICIENCY</p>
            <h3 className="text-6xl font-black mt-2 text-slate-900 dark:text-white font-mono tracking-tighter">{(dashboardData.selectedMonthStats.efficiency || 0).toFixed(1)}%</h3>
        </div>
      </div>

      {/* MONTHLY PROCESS BREAKDOWN */}
      <div className="space-y-6">
        <div className="flex items-center gap-3 px-2">
            <Layers className="w-6 h-6 text-indigo-500" />
            <h3 className="text-sm font-black text-slate-500 uppercase tracking-[0.4em]">MONTHLY PROCESS BREAKDOWN</h3>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-5 gap-6">
            {dashboardData.chartData.map((item) => {
                const eff = item.Plan > 0 ? (item.Actual / item.Plan) * 100 : 0;
                return (
                    <div key={item.process} className="glass-panel p-8 rounded-[3rem] border border-gray-100 dark:border-slate-800 shadow-lg group hover:border-indigo-500/30 transition-all duration-300">
                        <p className="text-xs font-black text-indigo-600 dark:text-indigo-400 tracking-[0.2em] mb-6">{item.process.toUpperCase()}</p>

                        <div className="space-y-6">
                            <div className="flex justify-between items-baseline">
                                <span className="text-[10px] font-black text-slate-400">PLAN</span>
                                <span className="text-3xl font-black text-slate-900 dark:text-white font-mono">{(item.Plan || 0).toLocaleString()}</span>
                            </div>

                            <div className="flex justify-between items-baseline">
                                <span className="text-[10px] font-black text-slate-400">ACTUAL</span>
