import { CATEGORIES, PROCESSES } from '../../constants';
import { 
  Bar, XAxis, YAxis, CartesianGrid, Tooltip, 
  ResponsiveContainer, Line, ComposedChart, Cell
} from 'recharts';
import { 
  BarChart3, Filter, Calendar, TrendingUp, 
  ArrowUpRight, AlertTriangle
} from 'lucide-react';
import { getTodayISO } from '../../utils/dateUtils';

export const ProcessAnalytics: React.FC = () => {
  const { refreshKey, isDarkMode } = useDashboard();
  const [dateRange, setDateRange] = useState({ 
    start: new Date(new Date().setDate(new Date().getDate() - 30)).toISOString().split('T')[0], 
    end: getTodayISO() 
  });
  const [selectedCategory, setSelectedCategory] = useState('All');

  const productionData = useMemo(() => StorageService.getProductionData(), [refreshKey]);

  const filteredData = useMemo(() => {
    return productionData.filter(d => {
      const matchCat = selectedCategory === 'All' || d.category === selectedCategory;
      const matchStart = !dateRange.start || d.date >= dateRange.start;
      const matchEnd = !dateRange.end || d.date <= dateRange.end;
      return matchCat && matchStart && matchEnd;
    });
  }, [productionData, dateRange, selectedCategory]);

  const processMetrics = useMemo(() => {
    const metrics: Record<string, { process: string, plan: number, actual: number, efficiency: number, manpower: number, intensity: number }> = {};
    PROCESSES.forEach(p => {
      metrics[p] = { process: p, plan: 0, actual: 0, efficiency: 0, manpower: 0, intensity: 0 };
    });

    filteredData.forEach(d => {
      if (metrics[d.process]) {
        metrics[d.process].plan += (d.planQuantity || 0);
        metrics[d.process].actual += (d.actualQuantity || 0);
        metrics[d.process].manpower += (d.manpower || 0);
      }
    });

    return Object.values(metrics).map(m => ({
      ...m,
      efficiency: m.plan > 0 ? Number(((m.actual / m.plan) * 100).toFixed(1)) : 0,
      intensity: m.manpower > 0 ? Number((m.actual / m.manpower).toFixed(1)) : 0
    })).sort((a, b) => b.efficiency - a.efficiency);
  }, [filteredData]);

  const aggregateMetrics = useMemo(() => {
    const totalPlan = processMetrics.reduce((s, m) => s + m.plan, 0);
    const totalActual = processMetrics.reduce((s, m) => s + m.actual, 0);
    const totalManpower = processMetrics.reduce((s, m) => s + m.manpower, 0);
    const avgEff = totalPlan > 0 ? (totalActual / totalPlan) * 100 : 0;
    return { totalPlan, totalActual, totalManpower, avgEff };
  }, [processMetrics]);

  return (
    <div className="space-y-12 pb-20 animate-in fade-in duration-700 uppercase">
      {/* HEADER */}
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-8">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <div className="p-3 bg-indigo-600 rounded-2xl shadow-xl">
              <BarChart3 className="w-6 h-6 text-white" />
            </div>
            <span className="text-xs font-black uppercase tracking-[0.4em] text-indigo-600 dark:text-indigo-400">BOTTLENECK FINDER</span>
          </div>
          <h2 className="text-5xl font-black text-slate-900 dark:text-white tracking-tighter">BOTTLENECK <span className="text-indigo-600">ANALYSIS</span></h2>
        </div>

        <div className="flex flex-wrap items-center gap-4 bg-white dark:bg-slate-800 p-3 rounded-3xl shadow-xl border border-gray-100 dark:border-slate-700">
          <div className="flex items-center gap-3 bg-gray-50 dark:bg-slate-900 px-6 py-3 rounded-2xl border border-gray-100 dark:border-slate-700">
            <Filter className="w-5 h-5 text-slate-400" />
            <select value={selectedCategory} onChange={e => setSelectedCategory(e.target.value)} className="bg-transparent text-sm font-black text-slate-700 dark:text-slate-200 outline-none uppercase tracking-[0.2em] cursor-pointer">
              <option value="All">ALL DEPARTMENTS</option>
              {CATEGORIES.map(c => <option key={c} value={c}>{c.toUpperCase()}</option>)}
            </select>
          </div>
          <div className="flex items-center gap-4 bg-gray-50 dark:bg-slate-900 px-6 py-3 rounded-2xl border border-gray-100 dark:border-slate-700">
            <Calendar className="w-5 h-5 text-slate-400" />
            <input type="date" value={dateRange.start} onChange={e => setDateRange(p => ({...p, start: e.target.value}))} className="bg-transparent text-xs font-black text-slate-700 dark:text-slate-200 outline-none uppercase" />
            <span className="text-slate-400 text-xs font-black">TO</span>
            <input type="date" value={dateRange.end} onChange={e => setDateRange(p => ({...p, end: e.target.value}))} className="bg-transparent text-xs font-black text-slate-700 dark:text-slate-200 outline-none uppercase" />
          </div>
        </div>
      </div>

      {/* SCORECARDS */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
        <div className="bg-white dark:bg-slate-800 p-8 rounded-[3rem] border border-gray-100 dark:border-slate-700 shadow-xl group">
            <p className="text-xs font-black text-slate-400 uppercase tracking-[0.3em] mb-3">AVG SUCCESS RATE</p>
            <div className="flex items-baseline gap-3">
                <h3 className="text-6xl font-black text-slate-900 dark:text-white font-mono tracking-tighter">{aggregateMetrics.avgEff.toFixed(1)}%</h3>
                <span className="text-xs font-black text-emerald-500 flex items-center gap-1">
                    <ArrowUpRight className="w-4 h-4" /> GOOD
                </span>
            </div>
            <div className="mt-6 w-full h-2 bg-gray-100 dark:bg-slate-700 rounded-full overflow-hidden">
                <div className="h-full bg-indigo-600" style={{ width: `${aggregateMetrics.avgEff}%` }} />
            </div>
            <p className="text-[10px] text-slate-400 mt-4 italic font-bold tracking-widest uppercase">PRODUCTION TARGET ACCURACY</p>
        </div>

        <div className="bg-white dark:bg-slate-800 p-8 rounded-[3rem] border border-gray-100 dark:border-slate-700 shadow-xl group">
            <p className="text-xs font-black text-slate-400 uppercase tracking-[0.3em] mb-3">PRODUCTION SPEED</p>
            <h3 className="text-6xl font-black text-slate-900 dark:text-white font-mono tracking-tighter">{aggregateMetrics.totalManpower > 0 ? (aggregateMetrics.totalActual / aggregateMetrics.totalManpower).toFixed(1) : 0}</h3>
            <p className="text-xs font-black text-slate-500 mt-4 tracking-[0.2em] uppercase">UNITS PER WORKER</p>
        </div>

        <div className="bg-white dark:bg-slate-800 p-8 rounded-[3rem] border border-gray-100 dark:border-slate-700 shadow-xl group">
            <p className="text-xs font-black text-slate-400 uppercase tracking-[0.3em] mb-3">TOTAL WORKERS</p>
            <h3 className="text-6xl font-black text-slate-900 dark:text-white font-mono tracking-tighter">{aggregateMetrics.totalManpower.toLocaleString()}</h3>
            <p className="text-xs font-black text-slate-500 mt-4 tracking-[0.2em] uppercase">STAFF LOGGED EFFORT</p>
        </div>

        <div className="bg-white dark:bg-slate-800 p-8 rounded-[3rem] border border-gray-100 dark:border-slate-700 shadow-xl group">
            <p className="text-xs font-black text-slate-400 uppercase tracking-[0.3em] mb-3">REMAINING TARGET</p>
            <h3 className="text-6xl font-black text-slate-900 dark:text-white font-mono tracking-tighter">{Math.max(0, aggregateMetrics.totalPlan - aggregateMetrics.totalActual).toLocaleString()}</h3>
            <p className="text-xs font-black text-slate-500 mt-4 tracking-[0.2em] uppercase">UNIT SHORTFALL</p>
        </div>
      </div>

      {/* CHART SECTION */}
      <div className="bg-white dark:bg-slate-800 p-10 rounded-[4rem] shadow-2xl border border-gray-100 dark:border-slate-700">
        <div className="flex items-center justify-between mb-12">
          <div>
            <h3 className="text-3xl font-black text-slate-900 dark:text-white">SUCCESS VS GOAL MATRIX</h3>
            <p className="text-xs font-black text-slate-400 uppercase tracking-[0.3em] mt-3">TARGET VARIANCE ANALYSIS BY DEPARTMENT</p>
          </div>
          <div className="hidden md:flex items-center gap-3 px-6 py-3 bg-rose-50 dark:bg-rose-900/30 border border-rose-200 dark:border-rose-800 rounded-[1.5rem] shadow-sm">
            <AlertTriangle className="w-5 h-5 text-rose-500" />
            <span className="text-xs font-black text-rose-600 dark:text-rose-400 tracking-[0.2em]">IDENTIFY BOTTLENECKS BY RED BARS</span>
          </div>
        </div>
        <div className="h-[500px] w-full">
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart data={processMetrics} margin={{ top: 0, right: 0, left: -10, bottom: 20 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={isDarkMode ? '#334155' : '#f1f5f9'} />
              <XAxis dataKey="process" axisLine={false} tickLine={false} tick={{ fontSize: 11, fontWeight: 900, fill: '#64748b' }} dy={20} />
              <YAxis yAxisId="left" axisLine={false} tickLine={false} tick={{ fontSize: 11, fontWeight: 900, fill: '#64748b' }} />
              <YAxis yAxisId="right" orientation="right" axisLine={false} tickLine={false} tick={{ fontSize: 11, fontWeight: 900, fill: '#64748b' }} domain={[0, 120]} />
              <Tooltip contentStyle={{ backgroundColor: isDarkMode ? '#1e293b' : '#fff', borderRadius: '30px', border: 'none', boxShadow: '0 25px 50px -12px rgb(0 0 0 / 0.3)', fontSize: '14px', padding: '24px', fontWeight: '900' }} />
              <Bar yAxisId="left" dataKey="actual" name="UNITS PRODUCED" radius={[12, 12, 0, 0]} barSize={60}>
                  {processMetrics.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={entry.efficiency >= 90 ? '#4f46e5' : '#f43f5e'} />
                  ))}
              </Bar>
              <Line yAxisId="right" type="monotone" dataKey="efficiency" name="SUCCESS %" stroke="#f59e0b" strokeWidth={6} dot={{ fill: '#f59e0b', r: 8, stroke: '#fff', strokeWidth: 3 }} />
            </ComposedChart>
          </ResponsiveContainer>
        </div>
        <div className="mt-12 flex items-center gap-12 justify-center">
            <div className="flex items-center gap-3">
                <div className="w-5 h-5 bg-indigo-600 rounded-lg"></div>
                <span className="text-xs font-black text-slate-500 tracking-[0.3em]">TOTAL UNITS MADE</span>
            </div>
            <div className="flex items-center gap-3">
                <div className="w-5 h-5 bg-fuchsia-500 rounded-full shadow-lg"></div>
                <span className="text-xs font-black text-slate-500 tracking-[0.3em]">SUCCESS RATE %</span>
            </div>
        </div>
      </div>

      {/* PROCESS TABLE */}
      <div className="bg-white dark:bg-slate-800 rounded-[4rem] border border-gray-100 dark:border-slate-700 shadow-2xl overflow-hidden">
          <div className="p-10 border-b border-gray-100 dark:border-slate-700 flex items-center justify-between">
              <h3 className="text-3xl font-black text-slate-900 dark:text-white tracking-tighter">LEADERBOARD: DEPARTMENT SUCCESS</h3>
              <span className="text-xs font-black text-slate-500 tracking-[0.3em] bg-gray-50 dark:bg-slate-900 px-6 py-3 rounded-full border border-gray-100 shadow-sm uppercase">SORTED BY PERFORMANCE</span>
          </div>
          <div className="overflow-x-auto no-scrollbar">
              <table className="w-full text-left">
                  <thead>
                      <tr className="text-xs font-black text-slate-400 tracking-[0.4em] bg-gray-50/50 dark:bg-slate-900/50 uppercase">
                          <th className="px-10 py-8">FACTORY STAGE</th>
