                          <th className="px-10 py-8 text-center">SUCCESS RATE</th>
                          <th className="px-10 py-8 text-right">SYSTEM STATUS</th>
                      </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100 dark:divide-slate-700">
                      {processMetrics.map((m) => (
                          <tr key={m.process} className="hover:bg-indigo-50/20 transition-all duration-300 uppercase">
                              <td className="px-10 py-10">
                                  <span className="text-xl font-black text-slate-900 dark:text-white tracking-tighter">{m.process.toUpperCase()}</span>
                              </td>
                              <td className="px-10 py-10">
                                  <div className="font-mono font-black text-slate-800 dark:text-slate-300 text-3xl">{m.actual.toLocaleString()} <span className="text-xs opacity-40 ml-2">UNITS</span></div>
                              </td>
                              <td className="px-10 py-10">
                                  <div className="flex items-center justify-center gap-6">
                                      <span className="text-3xl font-black text-slate-900 dark:text-white font-mono">{m.efficiency}%</span>
                                      <div className="w-48 h-3 bg-gray-100 dark:bg-slate-700 rounded-full hidden lg:block overflow-hidden">
