                                  </div>
                              </td>
                              <td className="px-10 py-10 text-right">
                                  <span className={`px-6 py-3 rounded-2xl text-xs font-black tracking-[0.3em] border shadow-sm ${
                                      m.efficiency >= 95 ? 'bg-emerald-50 text-emerald-600 border-emerald-200' :
                                      m.efficiency >= 85 ? 'bg-indigo-50 text-indigo-600 border-indigo-200' :
                                      'bg-rose-50 text-rose-600 border-rose-200'
                                  }`}>
                                      {m.efficiency >= 95 ? 'OPTIMAL' : m.efficiency >= 85 ? 'STABLE' : 'CRITICAL'}
                                  </span>
                              </td>
                          </tr>
                      ))}
                  </tbody>
              </table>
          </div>
      </div>
    </div>
  );
};

