            <div className={`flex items-center gap-6 px-8 py-5 rounded-3xl shadow-[0_30px_60px_rgba(0,0,0,0.3)] border-2 bg-white dark:bg-slate-800 ${
              notification.type === 'success' ? 'border-emerald-500' : 'border-indigo-500'
            }`}>
              <div className={`p-3 rounded-2xl shadow-inner ${notification.type === 'success' ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-100 text-indigo-600'}`}>
                {notification.type === 'success' ? <CheckCircle className="w-6 h-6" /> : <Info className="w-6 h-6" />}
              </div>
              <div className="flex-1">
                <p className={`text-[10px] font-black uppercase tracking-[0.3em] leading-none mb-2 flex items-center gap-2 ${
