                <p className="text-sm font-black text-slate-900 dark:text-white leading-tight uppercase tracking-tight">{notification.message.toUpperCase()}</p>
              </div>
              <button onClick={() => setNotification(null)} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-xl transition">
                <X className="w-5 h-5 text-slate-400" />
              </button>
            </div>
          </div>
        </div>
