            <LayoutDashboard className="w-5 h-5" /> DASHBOARD
          </Link>
          <Link to="/overview" onClick={() => setIsMobileMenuOpen(false)} className={navItemClass('/overview')}>
            <Presentation className="w-5 h-5" /> SYSTEM OVERVIEW
          </Link>
          <Link to="/reports" onClick={() => setIsMobileMenuOpen(false)} className={navItemClass('/reports')}>
            <ClipboardList className="w-5 h-5" /> PRODUCTION REPORTS
          </Link>
          <Link to="/process-analytics" onClick={() => setIsMobileMenuOpen(false)} className={navItemClass('/process-analytics')}>
            <BarChart3 className="w-5 h-5" /> BOTTLENECK ANALYSIS
          </Link>

          <div className="pt-8 px-4 py-3 text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">DEPARTMENTS</div>
          {CATEGORIES.map(cat => (
            <button key={cat} onClick={() => { setCategory(cat as Category); setIsMobileMenuOpen(false); }}
              className={`w-full flex items-center justify-between px-6 py-4 rounded-2xl text-xs font-black tracking-[0.2em] transition-all uppercase ${
                category === cat ? 'bg-slate-100 dark:bg-slate-800 text-indigo-600 dark:text-indigo-400 border border-slate-200 shadow-sm' : 'text-slate-500 hover:bg-gray-50 dark:hover:bg-slate-800'
              }`}>
              {cat.toUpperCase()}
            </button>
          ))}

          {user && (
            <>
              <div className="pt-8 px-4 py-3 text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">OPERATIONS</div>
              <button onClick={() => { setShowInput(true); setIsMobileMenuOpen(false); }} className="w-full flex items-center gap-4 px-6 py-4 text-xs font-black tracking-[0.2em] text-slate-600 hover:bg-emerald-50 hover:text-emerald-600 dark:hover:bg-emerald-900/20 rounded-2xl transition-all uppercase">
                <Plus className="w-5 h-5 text-emerald-500" /> NEW ENTRY
              </button>

              {hasPermission(['admin', 'manager']) && (
                <button onClick={() => { setShowOffDays(true); setIsMobileMenuOpen(false); }} className="w-full flex items-center gap-4 px-6 py-4 text-xs font-black tracking-[0.2em] text-slate-600 hover:bg-rose-50 hover:text-rose-600 dark:hover:bg-rose-900/20 rounded-2xl transition-all uppercase">
                  <CalendarX className="w-5 h-5 text-rose-500" /> PUBLIC HOLIDAYS
                </button>
              )}

              {hasPermission(['admin']) && (
                <Link to="/users" onClick={() => setIsMobileMenuOpen(false)} className={navItemClass('/users')}>
                  <Users className="w-5 h-5" /> STAFF MANAGEMENT
                </Link>
              )}

              <Link to="/logs" onClick={() => setIsMobileMenuOpen(false)} className={navItemClass('/logs')}>
                <History className="w-5 h-5" /> SYSTEM LOGS
              </Link>

              <div className="pt-8 px-4 py-3 text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">ACCOUNT</div>
              <button onClick={() => { setShowAvatarModal(true); setIsMobileMenuOpen(false); }} className="w-full flex items-center gap-4 px-6 py-4 text-xs font-black tracking-[0.2em] text-slate-500 hover:bg-gray-50 dark:hover:bg-slate-800 rounded-2xl transition-all uppercase">
                <Camera className="w-5 h-5 text-emerald-500" /> PROFILE IDENTITY
              </button>
              <button onClick={() => { setShowChangePass(true); setIsMobileMenuOpen(false); }} className="w-full flex items-center gap-4 px-6 py-4 text-xs font-black tracking-[0.2em] text-slate-500 hover:bg-gray-50 dark:hover:bg-slate-800 rounded-2xl transition-all uppercase">
                <Key className="w-5 h-5 text-indigo-500" /> CHANGE PASSWORD
              </button>
              <button onClick={handleLogout} className="w-full flex items-center gap-4 px-6 py-4 text-xs font-black tracking-[0.2em] text-rose-600 hover:bg-rose-100 dark:hover:bg-rose-900/30 rounded-2xl transition-all uppercase">
                <LogOut className="w-5 h-5" /> SIGN OUT
              </button>
            </>
          )}
        </nav>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-20 bg-white dark:bg-slate-850 border-b border-gray-200 dark:border-slate-700 flex items-center justify-between px-8 shrink-0 z-20">
          <div className="flex items-center gap-6">
            <button onClick={() => setIsMobileMenuOpen(true)} className="md:hidden p-3 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-xl">
              <Menu className="w-7 h-7" />
            </button>
            <div className="flex items-center gap-4">
              <h2 className="font-black text-2xl hidden md:block text-slate-900 dark:text-white uppercase tracking-tighter">{location.pathname.replace('/', '').toUpperCase() || 'DASHBOARD'}</h2>
              <div className={`flex items-center gap-2 px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-[0.3em] border ${
                GoogleSheetsService.isEnabled() ? 'bg-emerald-100 text-emerald-700 border-emerald-200' : 'bg-amber-100 text-amber-700 border-amber-200'
              }`}>
                <Database className="w-4 h-4" />
                {GoogleSheetsService.isEnabled() ? 'CLOUD CONNECTED' : 'LOCAL MODE'}
              </div>
            </div>
          </div>

          <div className="flex items-center gap-6">
            <button onClick={() => handleSync()} disabled={isSyncing} className={`p-3 text-slate-500 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-2xl transition-all ${isSyncing ? 'animate-spin text-indigo-600' : ''}`}>
              <RefreshCw className="w-6 h-6" />
            </button>
            <button onClick={toggleDarkMode} className="p-3 text-slate-500 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-2xl transition-all">
              {isDarkMode ? <Sun className="w-6 h-6" /> : <Moon className="w-6 h-6" />}
            </button>
            {user ? (
              <div 
                onClick={() => setShowAvatarModal(true)} 
                className="flex items-center gap-4 px-5 py-2 bg-gray-50 dark:bg-slate-800 rounded-[1.5rem] border border-gray-100 dark:border-slate-700 cursor-pointer hover:bg-gray-100 dark:hover:bg-slate-700 transition-all shadow-sm"
              >
                 <div className="w-10 h-10 rounded-full bg-indigo-600 flex items-center justify-center text-white overflow-hidden shadow-inner">
                    {user.avatar ? (
                        <img src={user.avatar} alt={user.name} className="w-full h-full object-cover" />
                    ) : (
                        <span className="text-sm font-black uppercase">{user.name.charAt(0)}</span>
                    )}
                 </div>
                 <div className="hidden lg:block text-left uppercase">
                    <p className="text-[10px] font-black text-indigo-600 leading-none mb-1 tracking-widest">{user.role.toUpperCase()}</p>
                    <p className="text-xs font-black text-slate-900 dark:text-white tracking-tight">{user.name.toUpperCase()}</p>
                 </div>
              </div>
            ) : (
              <button onClick={() => setShowLogin(true)} className="flex items-center gap-3 px-6 py-3 bg-slate-900 dark:bg-slate-700 text-white text-xs font-black rounded-2xl hover:bg-slate-800 transition shadow-xl uppercase tracking-widest">
                <LogIn className="w-5 h-5" /> LOGIN
              </button>
            )}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-8 md:p-12 custom-scrollbar">
          {children}
        </div>
      </main>

      {showLogin && <LoginModal onClose={() => setShowLogin(false)} />}
      {showInput && <InputModal onClose={() => { setShowInput(false); setEntryToEdit(null); }} editEntry={entryToEdit} />}
      {showOffDays && <OffDayModal onClose={() => setShowOffDays(false)} />}
      {showChangePass && <ChangePasswordModal onClose={() => setShowChangePass(false)} />}
      {showAvatarModal && <AvatarModal onClose={() => setShowAvatarModal(false)} />}
    </div>
  );
};

import React, { ReactNode, useState, useEffect, useCallback, useRef } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { Category, ProductionEntry } from '../../types';
import { CATEGORIES } from '../../constants';
import { LoginModal } from '../modals/LoginModal';
import { InputModal } from '../modals/InputModal';
import { OffDayModal } from '../modals/OffDayModal';
import { ChangePasswordModal } from '../modals/ChangePasswordModal';
import { AvatarModal } from '../modals/AvatarModal';
import { GoogleSheetsService } from '../../services/googleSheetsService';
import { StorageService } from '../../services/storageService';
import { Link, useLocation } from 'react-router-dom';
import { 
  Menu, X, Moon, Sun, Plus, LogOut, Database,
  CalendarX, LayoutDashboard, RefreshCw, LogIn, CheckCircle, Info,
  ClipboardList, Users, History, Key, BarChart3, Camera, Presentation
} from 'lucide-react';

export const Layout: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { user, logout, hasPermission } = useAuth();
  const { category, setCategory, isDarkMode, toggleDarkMode, triggerRefresh } = useDashboard();
  const location = useLocation();

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [showInput, setShowInput] = useState(false);
  const [showOffDays, setShowOffDays] = useState(false);
  const [showChangePass, setShowChangePass] = useState(false);
  const [showAvatarModal, setShowAvatarModal] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [entryToEdit, setEntryToEdit] = useState<ProductionEntry | null>(null);
  const [notification, setNotification] = useState<{ message: string; type: 'success' | 'info' } | null>(null);

  const timeoutRef = useRef<number | null>(null);

  const handleNotify = useCallback((e: any) => {
    if (timeoutRef.current) window.clearTimeout(timeoutRef.current);
    setNotification({ message: e.detail.message, type: e.detail.type || 'success' });
    timeoutRef.current = window.setTimeout(() => {
      setNotification(null);
      timeoutRef.current = null;
    }, 2000);
  }, []);

  const handleEditEntry = useCallback((e: any) => {
    setEntryToEdit(e.detail);
    setShowInput(true);
  }, []);

  const handleLogout = () => {
    logout();
    setIsMobileMenuOpen(false);
  };

  const handleSync = async (silent = false) => {
    if (!GoogleSheetsService.isEnabled()) return;
    if (!silent) setIsSyncing(true);
    try {
      await StorageService.syncWithSheets();
      triggerRefresh();
    } catch (e) {
      console.error(e);
    } finally {
      if (!silent) setIsSyncing(false);
    }
  };

  useEffect(() => {
    if (GoogleSheetsService.isEnabled()) handleSync(true);
  }, []);

  useEffect(() => {
    window.addEventListener('app-notification', handleNotify);
    window.addEventListener('edit-production-entry', handleEditEntry);
    return () => {
      window.removeEventListener('app-notification', handleNotify);
      window.removeEventListener('edit-production-entry', handleEditEntry);
      if (timeoutRef.current) window.clearTimeout(timeoutRef.current);
    };
  }, [handleNotify, handleEditEntry]);

  const navItemClass = (path: string) => `
    w-full flex items-center gap-6 px-8 py-6 rounded-3xl text-xl font-black transition-all uppercase tracking-[0.1em]
