              notification.type === 'success' ? 'border-emerald-500' : 'border-indigo-500'
            }`}>
              <div className={`p-4 rounded-3xl ${notification.type === 'success' ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-100 text-indigo-600'}`}>
                {notification.type === 'success' ? <CheckCircle className="w-10 h-10" /> : <Info className="w-10 h-10" />}
              </div>
              <div className="flex-1">
                <p className={`text-base font-black uppercase tracking-[0.3em] mb-2 ${notification.type === 'success' ? 'text-emerald-500' : 'text-indigo-500'}`}>ALERT</p>
                <p className="text-2xl font-black text-slate-900 dark:text-white leading-tight">{notification.message.toUpperCase()}</p>
              </div>
            </div>
          </div>
        </div>
      )}

      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-40 md:hidden" onClick={() => setIsMobileMenuOpen(false)} />
