        <div className="p-10 border-b-2 border-gray-100 dark:border-slate-800 text-center">
             <div className="text-5xl font-black tracking-tighter text-slate-900 dark:text-white uppercase">
                HALA<span className="text-emerald-500">GEL</span>
             </div>
             <p className="text-sm font-black text-slate-400 uppercase tracking-[0.5em] mt-3">SYSTEMS PRO</p>
        </div>

        <nav className="p-8 space-y-4 overflow-y-auto max-h-[calc(100vh-200px)] custom-scrollbar uppercase">
          <Link to="/" onClick={() => setIsMobileMenuOpen(false)} className={navItemClass('/')}>
            <LayoutDashboard className="w-7 h-7" /> DASHBOARD
          </Link>
          <Link to="/overview" onClick={() => setIsMobileMenuOpen(false)} className={navItemClass('/overview')}>
            <Presentation className="w-7 h-7" /> OVERVIEW
          </Link>
          <Link to="/reports" onClick={() => setIsMobileMenuOpen(false)} className={navItemClass('/reports')}>
            <ClipboardList className="w-7 h-7" /> REPORTS
          </Link>
          <Link to="/process-analytics" onClick={() => setIsMobileMenuOpen(false)} className={navItemClass('/process-analytics')}>
            <BarChart3 className="w-7 h-7" /> ANALYSIS
          </Link>

          <div className="pt-10 px-6 py-4 text-base font-black text-slate-400 uppercase tracking-[0.4em]">DEPARTMENTS</div>
          {CATEGORIES.map(cat => (
            <button key={cat} onClick={() => { setCategory(cat as Category); setIsMobileMenuOpen(false); }}
              className={`w-full flex items-center justify-between px-8 py-6 rounded-3xl text-xl font-black tracking-[0.1em] transition-all uppercase ${
                category === cat ? 'bg-indigo-50 dark:bg-slate-800 text-indigo-600 border-2 border-indigo-200' : 'text-slate-500 hover:bg-gray-50'
              }`}>
              {cat.toUpperCase()}
