              <button onClick={() => { setShowInput(true); setIsMobileMenuOpen(false); }} className="w-full flex items-center gap-6 px-8 py-6 text-xl font-black text-emerald-600 hover:bg-emerald-50 rounded-3xl transition-all uppercase">
