                 <div className="w-14 h-14 rounded-full bg-indigo-600 flex items-center justify-center text-white overflow-hidden shadow-inner border-2 border-white">
                    {user.avatar ? <img src={user.avatar} className="w-full h-full object-cover" /> : <span className="text-xl font-black">{user.name.charAt(0)}</span>}
                 </div>
                 <div className="hidden xl:block text-left uppercase">
                    <p className="text-xs font-black text-indigo-600 leading-none mb-1 tracking-widest">{user.role}</p>
                    <p className="text-xl font-black text-slate-900 dark:text-white tracking-tight">{user.name}</p>
                 </div>
              </div>
            ) : (
              <button onClick={() => setShowLogin(true)} className="flex items-center gap-4 px-10 py-5 bg-slate-900 dark:bg-indigo-600 text-white text-xl font-black rounded-3xl hover:bg-slate-800 transition shadow-2xl uppercase tracking-widest">
                <LogIn className="w-7 h-7" /> LOGIN
              </button>
            )}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-12 md:p-20 custom-scrollbar">
          {children}
        </div>
      </main>

      {showLogin && <LoginModal onClose={() => setShowLogin(false)} />}
      {showInput && <InputModal onClose={() => { setShowInput(false); setEntryToEdit(null); }} editEntry={entryToEdit} />}
      {showOffDays && <OffDayModal onClose={() => setShowOffDays(false)} />}
      {showChangePass && <ChangePasswordModal onClose={() => setShowChangePass(false)} />}
      {showAvatarModal && <AvatarModal onClose={() => setShowAvatarModal(false)} />}
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { ProductionEntry } from '../../types';
import { PROCESSES } from '../../constants';
import { 
  ClipboardList, CheckCircle, RefreshCw, List, Calendar, 
  TrendingUp, Download, Pencil, Trash2, Layers,
  Palmtree
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { formatDisplayDate, getCurrentMonthISO } from '../../utils/dateUtils';

export const Dashboard: React.FC = () => {
  const { category, refreshKey, triggerRefresh } = useDashboard();
  const { user, hasPermission } = useAuth();

  const [selectedMonth, setSelectedMonth] = useState<string>(getCurrentMonthISO());

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  const dashboardData = useMemo(() => {
    const relevant = productionData.filter(d => d && d.category === category && d.date);
    let selectedMonthPlan = 0;
    let selectedMonthActual = 0;

    const selectedMonthProcessMap = new Map<string, {process: string, Plan: number, Actual: number}>();
    PROCESSES.forEach(proc => {
      selectedMonthProcessMap.set(proc, { process: proc, Plan: 0, Actual: 0 });
    });

    relevant.forEach(d => {
      const dateStr = (d.date || '').trim().substring(0, 7);
      if (dateStr === selectedMonth) {
        selectedMonthPlan += (d.planQuantity || 0);
        selectedMonthActual += (d.actualQuantity || 0);

        const procName = d.process || 'Other';
        if (selectedMonthProcessMap.has(procName)) {
          const p = selectedMonthProcessMap.get(procName)!;
          p.Plan += (d.planQuantity || 0);
          p.Actual += (d.actualQuantity || 0);
        }
      }
    });

    return {
      filteredData: relevant.sort((a,b) => (b.date || '').localeCompare(a.date || '')),
      selectedMonthStats: { 
        plan: selectedMonthPlan, 
        actual: selectedMonthActual,
        efficiency: selectedMonthPlan > 0 ? (selectedMonthActual / selectedMonthPlan) * 100 : 0
      },
      chartData: Array.from(selectedMonthProcessMap.values())
    };
  }, [productionData, category, selectedMonth]);

  const dailyGroups = useMemo(() => {
    const baseData = dashboardData.filteredData;
    const filteredEntries = baseData.filter(d => d && d.date && d.date.trim().startsWith(selectedMonth));
    const filteredOffDays = offDays.filter(od => od && od.date && od.date.trim().startsWith(selectedMonth));

    const dates = new Set<string>();
    filteredEntries.forEach(d => {
      if (d.date) dates.add(d.date.trim().substring(0, 10));
    });
    filteredOffDays.forEach(od => {
      if (od.date) dates.add(od.date.trim().substring(0, 10));
    });

    const sortedDates = Array.from(dates).sort((a, b) => (b || '').localeCompare(a || ''));

    return sortedDates.map(dateKey => {
        const entriesForDate = filteredEntries.filter(d => d.date && d.date.trim().substring(0, 10) === dateKey);
        const offDayInfo = filteredOffDays.find(od => od.date && od.date.trim().substring(0, 10) === dateKey);
        const totalActualForDate = entriesForDate.reduce((sum, entry) => sum + (entry.actualQuantity || 0), 0);

        return {
            date: dateKey,
            totalActualForDate,
            entries: entriesForDate,
            isOffDay: !!offDayInfo,
            offDayName: offDayInfo?.description || ''
        };
    });
  }, [dashboardData.filteredData, offDays, selectedMonth]);

  const handleDelete = (id: string) => {
      if(!window.confirm("ARE YOU SURE? THIS ACTION IS FINAL.")) return;
      StorageService.deleteProductionEntry(id);
      triggerRefresh();
  };

  const handleEdit = (entry: ProductionEntry) => {
    window.dispatchEvent(new CustomEvent('edit-production-entry', { detail: entry }));
  };

  return (
    <div className="space-y-24 pb-32 uppercase">
      {/* KPI Cards - MASSIVE FONT SIZE */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
        <div className="glass-panel p-16 rounded-[4rem] border-l-[20px] border-blue-600 shadow-2xl relative overflow-hidden group">
            <p className="text-2xl font-black text-slate-400 tracking-[0.4em] mb-6">MONTHLY PLAN (TOTAL)</p>
            <h3 className="text-9xl font-black text-slate-900 dark:text-white font-mono tracking-tighter leading-none">{(dashboardData.selectedMonthStats.plan || 0).toLocaleString()}</h3>
            <div className="mt-8 flex items-center gap-4 text-emerald-500 font-black text-xl">
               <TrendingUp className="w-8 h-8" /> TARGET METRIC
            </div>
        </div>
        <div className="glass-panel p-16 rounded-[4rem] border-l-[20px] border-emerald-600 shadow-2xl relative overflow-hidden group">
            <p className="text-2xl font-black text-slate-400 tracking-[0.4em] mb-6">MONTHLY ACTUAL (TOTAL)</p>
            <h3 className="text-9xl font-black text-slate-900 dark:text-white font-mono tracking-tighter leading-none">{(dashboardData.selectedMonthStats.actual || 0).toLocaleString()}</h3>
            <div className="mt-8 flex items-center gap-4 text-emerald-500 font-black text-xl">
               <CheckCircle className="w-8 h-8" /> OUTPUT SUCCESS
            </div>
        </div>
        <div className="glass-panel p-16 rounded-[4rem] border-l-[20px] border-indigo-600 shadow-2xl relative overflow-hidden group">
            <p className="text-2xl font-black text-slate-400 tracking-[0.4em] mb-6">SYSTEM EFFICIENCY</p>
            <h3 className="text-9xl font-black text-slate-900 dark:text-white font-mono tracking-tighter leading-none">{(dashboardData.selectedMonthStats.efficiency || 0).toFixed(0)}%</h3>
            <div className="mt-8 w-full h-4 bg-slate-100 dark:bg-slate-700 rounded-full overflow-hidden">
                <div className="h-full bg-indigo-600" style={{ width: `${dashboardData.selectedMonthStats.efficiency}%` }} />
            </div>
        </div>
      </div>

      {/* PROCESS BREAKDOWN */}
      <div className="space-y-12">
        <div className="flex items-center gap-6">
            <Layers className="w-12 h-12 text-indigo-500" />
            <h3 className="text-3xl font-black text-slate-500 uppercase tracking-[0.6em]">DEPARTMENT PERFORMANCE MATRIX</h3>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-5 gap-10">
            {dashboardData.chartData.map((item) => {
                const eff = item.Plan > 0 ? (item.Actual / item.Plan) * 100 : 0;
                return (
                    <div key={item.process} className="glass-panel p-12 rounded-[4rem] border-4 border-gray-100 dark:border-slate-800 shadow-xl group hover:scale-105 transition-transform duration-500">
                        <p className="text-2xl font-black text-indigo-600 tracking-[0.2em] mb-10 text-center">{item.process.toUpperCase()}</p>

                        <div className="space-y-10">
                            <div className="flex justify-between items-center">
                                <span className="text-base font-black text-slate-400">PLAN</span>
                                <span className="text-5xl font-black text-slate-900 dark:text-white font-mono">{(item.Plan || 0).toLocaleString()}</span>
                            </div>

                            <div className="flex justify-between items-center">
                                <span className="text-base font-black text-slate-400">ACTUAL</span>
                                <span className="text-5xl font-black text-emerald-600 font-mono">{(item.Actual || 0).toLocaleString()}</span>
                            </div>

                            <div className="pt-8 border-t-4 border-gray-100 dark:border-slate-700 flex justify-between items-center">
                                <span className="text-base font-black text-slate-400">EFF.</span>
                                <span className={`text-6xl font-black font-mono ${eff >= 95 ? 'text-emerald-500' : 'text-rose-500'}`}>
                                    {(eff || 0).toFixed(0)}%
                                </span>
                            </div>
                        </div>
                    </div>
                );
            })}
        </div>
      </div>

      {/* DAILY LOGS - BIG TEXT TABLE */}
      <div className="space-y-16">
        <div className="flex flex-col xl:flex-row justify-between items-end gap-12 px-4">
            <div>
               <h3 className="text-6xl font-black text-slate-900 dark:text-white flex items-center gap-8 tracking-tighter">
                  <List className="w-16 h-16 text-indigo-500" />
                  OPERATIONAL LOGS
               </h3>
               <p className="text-xl text-slate-400 font-black tracking-[0.4em] mt-4">DAILY MANUFACTURING GRANULARITY</p>
            </div>

            <div className="flex items-center gap-8">
              <input type="month" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)}
                className="px-10 py-6 text-2xl font-black bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-2xl border-4 border-gray-100 dark:border-slate-700 outline-none"
              />
              <button className="flex items-center gap-6 px-12 py-8 bg-indigo-600 text-white text-xl font-black rounded-[2.5rem] hover:bg-indigo-700 shadow-2xl shadow-indigo-500/30 tracking-[0.2em] transition">
                <Download className="w-8 h-8" /> EXPORT REPORT
              </button>
            </div>
        </div>

        <div className="space-y-16">
            {dailyGroups.map((group, idx) => (
                <div key={idx} className={`bg-white dark:bg-slate-850 rounded-[5rem] overflow-hidden shadow-[0_50px_100px_rgba(0,0,0,0.1)] border-4 ${group.isOffDay ? 'border-amber-400' : 'border-gray-100 dark:border-slate-800'}`}>
                    <div className={`p-12 flex justify-between items-center border-b-4 ${group.isOffDay ? 'bg-amber-50 border-amber-200' : 'bg-gray-50 border-gray-100 dark:bg-slate-800/50'}`}>
                        <div className="flex items-center gap-10">
                            {group.isOffDay ? <Palmtree className="w-12 h-12 text-amber-500" /> : <Calendar className="w-12 h-12 text-slate-400" />}
                            <span className="text-5xl font-black text-slate-900 dark:text-white font-mono tracking-tighter">{group.date}</span>
                            {group.isOffDay && <span className="px-10 py-4 bg-amber-500 text-white text-xl font-black rounded-full tracking-[0.4em]">{group.offDayName}</span>}
                        </div>
                        <div className="text-4xl font-black text-slate-900 dark:text-white">
                           ACTUAL: <span className="text-emerald-600 ml-4">{(group.totalActualForDate || 0).toLocaleString()}</span>
                        </div>
                    </div>

                    <div className="overflow-x-auto no-scrollbar">
                        <table className="w-full text-left">
                            <thead className="bg-gray-50/50 dark:bg-slate-900/50 text-xl font-black text-slate-500 tracking-[0.5em] uppercase border-b-4 border-gray-100">
                                <tr>
                                    <th className="px-16 py-12">PROCESS</th>
                                    <th className="px-16 py-12">PRODUCT</th>
                                    <th className="px-16 py-12 text-right">PLAN</th>
                                    <th className="px-16 py-12 text-right">ACTUAL</th>
                                    <th className="px-16 py-12 text-center">EFF.</th>
                                    {hasPermission(['admin', 'manager']) && <th className="px-16 py-12 text-center">CONTROL</th>}
                                </tr>
                            </thead>
                            <tbody className="divide-y-4 divide-gray-50">
                                {group.entries.map(entry => {
                                    const eff = entry.planQuantity > 0 ? (entry.actualQuantity / entry.planQuantity) * 100 : 0;
                                    return (
                                        <tr key={entry.id} className="hover:bg-indigo-50/50 transition-colors">
                                            <td className="px-16 py-16">
                                                <span className="text-xl font-black text-indigo-700 bg-indigo-50 px-6 py-3 rounded-2xl border-2 border-indigo-200">{entry.process}</span>
                                            </td>
                                            <td className="px-16 py-16">
                                                <span className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter">{entry.productName}</span>
                                            </td>
                                            <td className="px-16 py-16 text-right font-black font-mono text-slate-400 text-4xl">{(entry.planQuantity || 0).toLocaleString()}</td>
                                            <td className="px-16 py-16 text-right font-black font-mono text-emerald-600 text-5xl">{(entry.actualQuantity || 0).toLocaleString()}</td>
                                            <td className="px-16 py-16 text-center">
                                                <span className={`text-5xl font-black font-mono ${eff >= 95 ? 'text-emerald-500' : 'text-rose-500'}`}>{(eff || 0).toFixed(0)}%</span>
