import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { CATEGORIES, PROCESSES } from '../../constants';
import { 
  Bar, XAxis, YAxis, CartesianGrid, Tooltip, 
  ResponsiveContainer, Line, ComposedChart, Cell
} from 'recharts';
import { 
  BarChart3, Filter, Calendar, 
  ArrowUpRight, AlertTriangle
} from 'lucide-react';
import { getTodayISO } from '../../utils/dateUtils';

export const ProcessAnalytics: React.FC = () => {
  const { refreshKey, isDarkMode } = useDashboard();
  const [dateRange, setDateRange] = useState({ 
    start: new Date(new Date().setDate(new Date().getDate() - 30)).toISOString().split('T')[0], 
    end: getTodayISO() 
  });
  const [selectedCategory, setSelectedCategory] = useState('All');

  const productionData = useMemo(() => StorageService.getProductionData(), [refreshKey]);

  const filteredData = useMemo(() => {
    return productionData.filter(d => {
      const matchCat = selectedCategory === 'All' || d.category === selectedCategory;
      const matchStart = !dateRange.start || d.date >= dateRange.start;
      const matchEnd = !dateRange.end || d.date <= dateRange.end;
      return matchCat && matchStart && matchEnd;
    });
  }, [productionData, dateRange, selectedCategory]);

  const processMetrics = useMemo(() => {
    const metrics: Record<string, { process: string, plan: number, actual: number, efficiency: number, manpower: number, intensity: number }> = {};
    PROCESSES.forEach(p => {
      metrics[p] = { process: p, plan: 0, actual: 0, efficiency: 0, manpower: 0, intensity: 0 };
    });

    filteredData.forEach(d => {
      if (metrics[d.process]) {
        metrics[d.process].plan += (d.planQuantity || 0);
        metrics[d.process].actual += (d.actualQuantity || 0);
        metrics[d.process].manpower += (d.manpower || 0);
      }
    });

    return Object.values(metrics).map(m => ({
      ...m,
      efficiency: m.plan > 0 ? Number(((m.actual / m.plan) * 100).toFixed(1)) : 0,
      intensity: m.manpower > 0 ? Number((m.actual / m.manpower).toFixed(1)) : 0
    })).sort((a, b) => b.efficiency - a.efficiency);
  }, [filteredData]);

  const aggregateMetrics = useMemo(() => {
    const totalPlan = processMetrics.reduce((s, m) => s + m.plan, 0);
    const totalActual = processMetrics.reduce((s, m) => s + m.actual, 0);
    const totalManpower = processMetrics.reduce((s, m) => s + m.manpower, 0);
    const avgEff = totalPlan > 0 ? (totalActual / totalPlan) * 100 : 0;
    return { totalPlan, totalActual, totalManpower, avgEff };
  }, [processMetrics]);

  return (
    <div className="space-y-24 pb-32 uppercase">
      {/* HEADER */}
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-12">
        <div className="space-y-4">
          <div className="flex items-center gap-6">
            <div className="p-6 bg-indigo-600 rounded-[2rem] shadow-2xl">
              <BarChart3 className="w-12 h-12 text-white" />
            </div>
            <span className="text-2xl font-black uppercase tracking-[0.5em] text-indigo-600">BOTTLENECK FINDER</span>
          </div>
          <h2 className="text-8xl font-black text-slate-900 dark:text-white tracking-tighter leading-none">BOTTLENECK <br/><span className="text-indigo-600">ANALYSIS</span></h2>
        </div>

        <div className="flex flex-wrap items-center gap-6 bg-white dark:bg-slate-800 p-6 rounded-[3rem] shadow-2xl border-4 border-gray-100">
          <div className="flex items-center gap-6 bg-gray-50 px-10 py-6 rounded-[2rem] border-2 border-gray-100">
            <Filter className="w-8 h-8 text-slate-400" />
            <select value={selectedCategory} onChange={e => setSelectedCategory(e.target.value)} className="bg-transparent text-xl font-black text-slate-700 outline-none uppercase tracking-[0.2em] cursor-pointer">
              <option value="All">ALL DEPARTMENTS</option>
              {CATEGORIES.map(c => <option key={c} value={c}>{c.toUpperCase()}</option>)}
            </select>
          </div>
          <div className="flex items-center gap-8 bg-gray-50 px-10 py-6 rounded-[2rem] border-2 border-gray-100">
            <Calendar className="w-8 h-8 text-slate-400" />
            <input type="date" value={dateRange.start} onChange={e => setDateRange(p => ({...p, start: e.target.value}))} className="bg-transparent text-lg font-black text-slate-700 outline-none uppercase" />
            <span className="text-slate-400 text-lg font-black">TO</span>
            <input type="date" value={dateRange.end} onChange={e => setDateRange(p => ({...p, end: e.target.value}))} className="bg-transparent text-lg font-black text-slate-700 outline-none uppercase" />
          </div>
        </div>
      </div>

      {/* SCORECARDS */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-12">
        <div className="bg-white dark:bg-slate-800 p-16 rounded-[4rem] border-4 border-gray-100 shadow-2xl">
            <p className="text-2xl font-black text-slate-400 uppercase tracking-[0.4em] mb-10">AVG SUCCESS RATE</p>
            <div className="flex items-baseline gap-6">
                <h3 className="text-8xl font-black text-slate-900 dark:text-white font-mono tracking-tighter">{(aggregateMetrics.avgEff || 0).toFixed(0)}%</h3>
                <span className="text-xl font-black text-emerald-500 flex items-center gap-2">
                    <ArrowUpRight className="w-8 h-8" /> STABLE
                </span>
            </div>
            <div className="mt-12 w-full h-4 bg-gray-100 rounded-full overflow-hidden">
                <div className="h-full bg-indigo-600" style={{ width: `${aggregateMetrics.avgEff}%` }} />
            </div>
        </div>

        <div className="bg-white dark:bg-slate-800 p-16 rounded-[4rem] border-4 border-gray-100 shadow-2xl">
            <p className="text-2xl font-black text-slate-400 uppercase tracking-[0.4em] mb-10">SPEED (UNIT/WORKER)</p>
            <h3 className="text-8xl font-black text-slate-900 dark:text-white font-mono tracking-tighter">{aggregateMetrics.totalManpower > 0 ? (aggregateMetrics.totalActual / aggregateMetrics.totalManpower).toFixed(1) : 0}</h3>
            <p className="text-xl font-black text-slate-500 mt-8 tracking-[0.3em]">OPERATIONAL VELOCITY</p>
        </div>

        <div className="bg-white dark:bg-slate-800 p-16 rounded-[4rem] border-4 border-gray-100 shadow-2xl">
            <p className="text-2xl font-black text-slate-400 uppercase tracking-[0.4em] mb-10">STAFF EFFORT</p>
            <h3 className="text-8xl font-black text-slate-900 dark:text-white font-mono tracking-tighter">{aggregateMetrics.totalManpower.toLocaleString()}</h3>
            <p className="text-xl font-black text-slate-500 mt-8 tracking-[0.3em]">MANPOWER LOGGED</p>
        </div>

        <div className="bg-white dark:bg-slate-800 p-16 rounded-[4rem] border-4 border-gray-100 shadow-2xl">
            <p className="text-2xl font-black text-slate-400 uppercase tracking-[0.4em] mb-10">TARGET GAP</p>
            <h3 className="text-8xl font-black text-rose-600 font-mono tracking-tighter">{Math.max(0, aggregateMetrics.totalPlan - aggregateMetrics.totalActual).toLocaleString()}</h3>
            <p className="text-xl font-black text-rose-500 mt-8 tracking-[0.3em]">PENDING UNITS</p>
        </div>
      </div>

      {/* MATRIX CHART */}
      <div className="bg-white dark:bg-slate-800 p-20 rounded-[5rem] shadow-[0_60px_120px_rgba(0,0,0,0.15)] border-4 border-gray-100">
        <div className="flex flex-col xl:flex-row items-center justify-between mb-20 gap-10">
          <div>
            <h3 className="text-6xl font-black text-slate-900 dark:text-white tracking-tighter">SUCCESS MATRIX</h3>
            <p className="text-xl font-black text-slate-400 uppercase tracking-[0.5em] mt-6">OUTPUT VARIANCE BY DEPARTMENT</p>
          </div>
          <div className="flex items-center gap-6 px-12 py-8 bg-rose-50 border-4 border-rose-200 rounded-[3rem] shadow-xl">
            <AlertTriangle className="w-12 h-12 text-rose-500" />
            <span className="text-2xl font-black text-rose-600 tracking-[0.2em]">IDENTIFY RED BOTTLENECKS</span>
          </div>
        </div>
        <div className="h-[600px] w-full">
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart data={processMetrics} margin={{ top: 0, right: 0, left: 0, bottom: 40 }}>
              <CartesianGrid strokeDasharray="5 5" vertical={false} stroke="#e2e8f0" />
              <XAxis dataKey="process" axisLine={false} tickLine={false} tick={{ fontSize: 16, fontWeight: 900, fill: '#64748b' }} dy={40} />
              <YAxis yAxisId="left" axisLine={false} tickLine={false} tick={{ fontSize: 16, fontWeight: 900, fill: '#64748b' }} />
              <YAxis yAxisId="right" orientation="right" axisLine={false} tickLine={false} tick={{ fontSize: 16, fontWeight: 900, fill: '#64748b' }} domain={[0, 120]} />
              <Tooltip contentStyle={{ borderRadius: '40px', border: 'none', boxShadow: '0 40px 80px rgba(0,0,0,0.2)', fontSize: '20px', padding: '40px', fontWeight: '900' }} />
              <Bar yAxisId="left" dataKey="actual" name="UNITS PRODUCED" radius={[20, 20, 0, 0]} barSize={100}>
                  {processMetrics.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={entry.efficiency >= 90 ? '#4f46e5' : '#f43f5e'} />
