import { InputModal } from '../modals/InputModal';
import { OffDayModal } from '../modals/OffDayModal';
import { ChangePasswordModal } from '../modals/ChangePasswordModal';
import { AvatarModal } from '../modals/AvatarModal';
import { GoogleSheetsService } from '../../services/googleSheetsService';
import { StorageService } from '../../services/storageService';
import { Link, useLocation } from 'react-router-dom';
import { 
  Menu, X, Moon, Sun, Plus, LogOut, Database,
  CalendarX, LayoutDashboard, RefreshCw, LogIn, CheckCircle, Info,
  ClipboardList, Users, History, Key, BarChart3, Camera
} from 'lucide-react';

export const Layout: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { user, logout, hasPermission } = useAuth();
  const { category, setCategory, isDarkMode, toggleDarkMode, triggerRefresh } = useDashboard();
  const location = useLocation();

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [showInput, setShowInput] = useState(false);
  const [showOffDays, setShowOffDays] = useState(false);
  const [showChangePass, setShowChangePass] = useState(false);
  const [showAvatarModal, setShowAvatarModal] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [entryToEdit, setEntryToEdit] = useState<ProductionEntry | null>(null);
  const [notification, setNotification] = useState<{ message: string; type: 'success' | 'info' } | null>(null);

  const timeoutRef = useRef<number | null>(null);

  const handleNotify = useCallback((e: any) => {
    if (timeoutRef.current) window.clearTimeout(timeoutRef.current);
    setNotification({ message: e.detail.message, type: e.detail.type || 'success' });
    timeoutRef.current = window.setTimeout(() => {
      setNotification(null);
      timeoutRef.current = null;
    }, 2000);
  }, []);

  const handleEditEntry = useCallback((e: any) => {
    setEntryToEdit(e.detail);
    setShowInput(true);
  }, []);

  const handleLogout = () => {
    logout();
    setIsMobileMenuOpen(false);
  };

  const handleSync = async (silent = false) => {
    if (!GoogleSheetsService.isEnabled()) return;
    if (!silent) setIsSyncing(true);
    try {
      await StorageService.syncWithSheets();
      triggerRefresh();
    } catch (e) {
      console.error(e);
    } finally {
      if (!silent) setIsSyncing(false);
    }
  };

  useEffect(() => {
    if (GoogleSheetsService.isEnabled()) handleSync(true);
  }, []);

  useEffect(() => {
    window.addEventListener('app-notification', handleNotify);
    window.addEventListener('edit-production-entry', handleEditEntry);
    return () => {
      window.removeEventListener('app-notification', handleNotify);
      window.removeEventListener('edit-production-entry', handleEditEntry);
      if (timeoutRef.current) window.clearTimeout(timeoutRef.current);
    };
  }, [handleNotify, handleEditEntry]);

  const navItemClass = (path: string) => `
    w-full flex items-center gap-8 px-10 py-8 rounded-[2.5rem] text-3xl font-black transition-all uppercase tracking-tighter
    ${location.pathname === path 
      ? 'bg-indigo-600 text-white shadow-2xl shadow-indigo-500/40' 
      : 'text-slate-500 hover:bg-gray-100 dark:hover:bg-slate-800'}
  `;

  return (
    <div className={`min-h-screen flex ${isDarkMode ? 'dark' : ''} bg-slate-50 dark:bg-slate-900 transition-colors duration-300 font-sans uppercase`}>
      {notification && (
        <div className="fixed top-28 right-12 z-[10000] pointer-events-none w-full max-w-xl px-4">
          <div className="notification-animate pointer-events-auto">
            <div className={`flex items-center gap-10 px-12 py-10 rounded-[3rem] shadow-[0_60px_120px_rgba(0,0,0,0.5)] border-8 bg-white dark:bg-slate-800 ${
              notification.type === 'success' ? 'border-emerald-500' : 'border-indigo-500'
            }`}>
              <div className={`p-6 rounded-[2rem] ${notification.type === 'success' ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-100 text-indigo-600'}`}>
                {notification.type === 'success' ? <CheckCircle className="w-16 h-16" /> : <Info className="w-16 h-16" />}
              </div>
              <div className="flex-1">
                <p className={`text-xl font-black uppercase tracking-[0.4em] mb-4 ${notification.type === 'success' ? 'text-emerald-500' : 'text-indigo-500'}`}>System Notification</p>
                <p className="text-4xl font-black text-slate-900 dark:text-white leading-tight">{notification.message.toUpperCase()}</p>
              </div>
            </div>
          </div>
        </div>
      )}

      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-xl z-40 md:hidden" onClick={() => setIsMobileMenuOpen(false)} />
      )}

      <aside className={`fixed inset-y-0 left-0 w-[30rem] bg-white dark:bg-slate-850 border-r-4 border-gray-200 dark:border-slate-700 z-50 transform transition-transform duration-300 md:translate-x-0 md:static md:block ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-16 border-b-4 border-gray-100 dark:border-slate-800 text-center">
             <div className="text-7xl font-black tracking-tighter text-slate-900 dark:text-white uppercase">
                HALA<span className="text-emerald-500">GEL</span>
             </div>
             <p className="text-xl font-black text-slate-400 uppercase tracking-[0.6em] mt-4">Production Pro</p>
        </div>

        <nav className="p-10 space-y-6 overflow-y-auto max-h-[calc(100vh-280px)] custom-scrollbar uppercase">
          <Link to="/" onClick={() => setIsMobileMenuOpen(false)} className={navItemClass('/')}>
            <LayoutDashboard className="w-10 h-10" /> Dashboard
          </Link>
          <Link to="/reports" onClick={() => setIsMobileMenuOpen(false)} className={navItemClass('/reports')}>
            <ClipboardList className="w-10 h-10" /> Reports
          </Link>
          <Link to="/process-analytics" onClick={() => setIsMobileMenuOpen(false)} className={navItemClass('/process-analytics')}>
            <BarChart3 className="w-10 h-10" /> Analytics
          </Link>

          <div className="pt-16 px-10 py-6 text-2xl font-black text-slate-400 uppercase tracking-[0.5em]">Departments</div>
          {CATEGORIES.map(cat => (
            <button key={cat} onClick={() => { setCategory(cat as Category); setIsMobileMenuOpen(false); }}
              className={`w-full flex items-center justify-between px-10 py-8 rounded-[2.5rem] text-3xl font-black tracking-tighter transition-all uppercase ${
                category === cat ? 'bg-indigo-50 dark:bg-slate-800 text-indigo-600 border-4 border-indigo-200' : 'text-slate-500 hover:bg-gray-50'
              }`}>
              {cat.toUpperCase()}
            </button>
          ))}

          {user && (
            <>
              <div className="pt-16 px-10 py-6 text-2xl font-black text-slate-400 uppercase tracking-[0.5em]">Operations</div>
              <button onClick={() => { setShowInput(true); setIsMobileMenuOpen(false); }} className="w-full flex items-center gap-8 px-10 py-8 text-3xl font-black text-emerald-600 hover:bg-emerald-50 rounded-[2.5rem] transition-all uppercase">
                <Plus className="w-10 h-10" /> New Data
              </button>

              {hasPermission(['admin', 'manager']) && (
                <button onClick={() => { setShowOffDays(true); setIsMobileMenuOpen(false); }} className="w-full flex items-center gap-8 px-10 py-8 text-3xl font-black text-rose-600 hover:bg-rose-50 rounded-[2.5rem] transition-all uppercase">
                  <CalendarX className="w-10 h-10" /> Holidays
                </button>
              )}

              {hasPermission(['admin']) && (
                <Link to="/users" onClick={() => setIsMobileMenuOpen(false)} className={navItemClass('/users')}>
                  <Users className="w-10 h-10" /> Staff Mgmt
                </Link>
              )}

              <Link to="/logs" onClick={() => setIsMobileMenuOpen(false)} className={navItemClass('/logs')}>
                <History className="w-10 h-10" /> System Logs
              </Link>

              <button onClick={handleLogout} className="w-full flex items-center gap-8 px-10 py-8 text-3xl font-black text-rose-700 hover:bg-rose-100 rounded-[2.5rem] transition-all uppercase mt-16">
                <LogOut className="w-10 h-10" /> Logout
              </button>
            </>
          )}
        </nav>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-40 bg-white dark:bg-slate-850 border-b-4 border-gray-200 dark:border-slate-700 flex items-center justify-between px-20 shrink-0 z-20">
          <div className="flex items-center gap-16">
            <button onClick={() => setIsMobileMenuOpen(true)} className="md:hidden p-6 hover:bg-gray-100 rounded-[2rem]">
              <Menu className="w-16 h-16" />
            </button>
            <div className="flex items-center gap-12">
              <h2 className="font-black text-6xl hidden xl:block text-slate-900 dark:text-white tracking-tighter">{location.pathname.replace('/', '').toUpperCase() || 'Dashboard'}</h2>
              <div className="flex items-center gap-6 px-10 py-4 rounded-full text-2xl font-black uppercase bg-emerald-100 text-emerald-700 border-4 border-emerald-200">
                <Database className="w-10 h-10" /> Cloud Active
              </div>
            </div>
          </div>

          <div className="flex items-center gap-16">
            <button onClick={() => handleSync()} disabled={isSyncing} className={`p-6 text-slate-500 hover:bg-gray-100 rounded-[2.5rem] transition-all ${isSyncing ? 'animate-spin text-indigo-600' : ''}`}>
              <RefreshCw className="w-12 h-12" />
