                 <div className="w-20 h-20 rounded-full bg-indigo-600 flex items-center justify-center text-white overflow-hidden shadow-inner border-4 border-white">
                    {user.avatar ? <img src={user.avatar} className="w-full h-full object-cover" /> : <span className="text-3xl font-black">{user.name.charAt(0)}</span>}
                 </div>
                 <div className="hidden 2xl:block text-left uppercase">
                    <p className="text-sm font-black text-indigo-600 leading-none mb-2 tracking-[0.2em]">{user.role}</p>
