                 </div>
              </div>
            ) : (
              <button onClick={() => setShowLogin(true)} className="flex items-center gap-6 px-16 py-8 bg-slate-900 dark:bg-indigo-600 text-white text-3xl font-black rounded-[3rem] hover:bg-slate-800 transition shadow-[0_30px_60px_rgba(0,0,0,0.3)] uppercase tracking-widest">
