import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { ProductionEntry } from '../../types';
import { PROCESSES } from '../../constants';
import { 
  ClipboardList, CheckCircle, RefreshCw, List, Calendar, 
  TrendingUp, Download, Pencil, Trash2, Layers,
  Palmtree
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { formatDisplayDate, getCurrentMonthISO } from '../../utils/dateUtils';

export const Dashboard: React.FC = () => {
  const { category, refreshKey, triggerRefresh } = useDashboard();
  const { user, hasPermission } = useAuth();

  const [selectedMonth, setSelectedMonth] = useState<string>(getCurrentMonthISO());

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  const dashboardData = useMemo(() => {
    const relevant = productionData.filter(d => d && d.category === category && d.date);
    let selectedMonthPlan = 0;
    let selectedMonthActual = 0;

    const selectedMonthProcessMap = new Map<string, {process: string, Plan: number, Actual: number}>();
    PROCESSES.forEach(proc => {
      selectedMonthProcessMap.set(proc, { process: proc, Plan: 0, Actual: 0 });
    });

    relevant.forEach(d => {
      const dateStr = (d.date || '').trim().substring(0, 7);
      if (dateStr === selectedMonth) {
        selectedMonthPlan += (d.planQuantity || 0);
        selectedMonthActual += (d.actualQuantity || 0);

        const procName = d.process || 'Other';
        if (selectedMonthProcessMap.has(procName)) {
          const p = selectedMonthProcessMap.get(procName)!;
          p.Plan += (d.planQuantity || 0);
          p.Actual += (d.actualQuantity || 0);
        }
      }
    });

    return {
      filteredData: relevant.sort((a,b) => (b.date || '').localeCompare(a.date || '')),
      selectedMonthStats: { 
        plan: selectedMonthPlan, 
        actual: selectedMonthActual,
        efficiency: selectedMonthPlan > 0 ? (selectedMonthActual / selectedMonthPlan) * 100 : 0
      },
      chartData: Array.from(selectedMonthProcessMap.values())
    };
  }, [productionData, category, selectedMonth]);

  const dailyGroups = useMemo(() => {
    const baseData = dashboardData.filteredData;
    const filteredEntries = baseData.filter(d => d && d.date && d.date.trim().startsWith(selectedMonth));
    const filteredOffDays = offDays.filter(od => od && od.date && od.date.trim().startsWith(selectedMonth));

    const dates = new Set<string>();
    filteredEntries.forEach(d => {
      if (d.date) dates.add(d.date.trim().substring(0, 10));
    });
    filteredOffDays.forEach(od => {
      if (od.date) dates.add(od.date.trim().substring(0, 10));
    });

    const sortedDates = Array.from(dates).sort((a, b) => (b || '').localeCompare(a || ''));

    return sortedDates.map(dateKey => {
        const entriesForDate = filteredEntries.filter(d => d.date && d.date.trim().substring(0, 10) === dateKey);
        const offDayInfo = filteredOffDays.find(od => od.date && od.date.trim().substring(0, 10) === dateKey);
        const totalActualForDate = entriesForDate.reduce((sum, entry) => sum + (entry.actualQuantity || 0), 0);

        return {
            date: dateKey,
            totalActualForDate,
            entries: entriesForDate,
            isOffDay: !!offDayInfo,
            offDayName: offDayInfo?.description || ''
        };
    });
  }, [dashboardData.filteredData, offDays, selectedMonth]);

  const handleDelete = (id: string) => {
      if(!window.confirm("ARE YOU SURE? THIS ACTION IS FINAL.")) return;
      StorageService.deleteProductionEntry(id);
      triggerRefresh();
  };

  const handleEdit = (entry: ProductionEntry) => {
    window.dispatchEvent(new CustomEvent('edit-production-entry', { detail: entry }));
  };

  return (
    <div className="space-y-40 pb-48 uppercase">
      {/* KPI Cards - MASSIVE SCALE */}
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-20">
        <div className="glass-panel p-24 rounded-[6rem] border-l-[32px] border-blue-600 shadow-[0_80px_150px_rgba(0,0,0,0.1)] relative overflow-hidden group">
            <p className="text-4xl font-black text-slate-400 tracking-[0.5em] mb-12">Monthly Plan (Total)</p>
            <h3 className="text-[12rem] font-black text-slate-900 dark:text-white font-mono tracking-tighter leading-none">{(dashboardData.selectedMonthStats.plan || 0).toLocaleString()}</h3>
            <div className="mt-16 flex items-center gap-8 text-emerald-500 font-black text-4xl">
               <TrendingUp className="w-16 h-16" /> Target Matrix
            </div>
        </div>
        <div className="glass-panel p-24 rounded-[6rem] border-l-[32px] border-emerald-600 shadow-[0_80px_150px_rgba(0,0,0,0.1)] relative overflow-hidden group">
            <p className="text-4xl font-black text-slate-400 tracking-[0.5em] mb-12">Monthly Actual (Total)</p>
            <h3 className="text-[12rem] font-black text-slate-900 dark:text-white font-mono tracking-tighter leading-none">{(dashboardData.selectedMonthStats.actual || 0).toLocaleString()}</h3>
            <div className="mt-16 flex items-center gap-8 text-emerald-500 font-black text-4xl">
               <CheckCircle className="w-16 h-16" /> Yield Success
            </div>
        </div>
        <div className="glass-panel p-24 rounded-[6rem] border-l-[32px] border-indigo-600 shadow-[0_80px_150px_rgba(0,0,0,0.1)] relative overflow-hidden group">
            <p className="text-4xl font-black text-slate-400 tracking-[0.5em] mb-12">System Efficiency</p>
            <h3 className="text-[12rem] font-black text-slate-900 dark:text-white font-mono tracking-tighter leading-none">{(dashboardData.selectedMonthStats.efficiency || 0).toFixed(0)}%</h3>
            <div className="mt-16 w-full h-8 bg-slate-100 dark:bg-slate-700 rounded-full overflow-hidden">
                <div className="h-full bg-indigo-600" style={{ width: `${dashboardData.selectedMonthStats.efficiency}%` }} />
            </div>
        </div>
      </div>

      {/* Process Matrix Breakdown */}
      <div className="space-y-20">
        <div className="flex items-center gap-10 px-4">
            <Layers className="w-20 h-20 text-indigo-500" />
            <h3 className="text-5xl font-black text-slate-400 uppercase tracking-[0.8em]">Department Performance Matrix</h3>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 2xl:grid-cols-5 gap-16">
            {dashboardData.chartData.map((item) => {
                const eff = item.Plan > 0 ? (item.Actual / item.Plan) * 100 : 0;
                return (
                    <div key={item.process} className="glass-panel p-20 rounded-[5rem] border-8 border-gray-100 dark:border-slate-800 shadow-2xl group hover:scale-110 transition-transform duration-700">
                        <p className="text-4xl font-black text-indigo-600 tracking-[0.3em] mb-16 text-center">{item.process.toUpperCase()}</p>

                        <div className="space-y-16">
                            <div className="flex justify-between items-center">
                                <span className="text-2xl font-black text-slate-400">Plan</span>
                                <span className="text-7xl font-black text-slate-900 dark:text-white font-mono">{(item.Plan || 0).toLocaleString()}</span>
                            </div>

                            <div className="flex justify-between items-center">
                                <span className="text-2xl font-black text-slate-400">Actual</span>
                                <span className="text-7xl font-black text-emerald-600 font-mono">{(item.Actual || 0).toLocaleString()}</span>
                            </div>

                            <div className="pt-12 border-t-8 border-gray-100 dark:border-slate-700 flex justify-between items-center">
                                <span className="text-2xl font-black text-slate-400">Eff.</span>
                                <span className={`text-8xl font-black font-mono ${eff >= 95 ? 'text-emerald-500' : 'text-rose-500'}`}>
                                    {(eff || 0).toFixed(0)}%
                                </span>
                            </div>
                        </div>
                    </div>
                );
            })}
        </div>
      </div>

      {/* Granular Logs Table */}
      <div className="space-y-24">
        <div className="flex flex-col 2xl:flex-row justify-between items-end gap-20 px-8">
            <div>
               <h3 className="text-8xl font-black text-slate-900 dark:text-white flex items-center gap-12 tracking-tighter leading-none">
                  <List className="w-24 h-24 text-indigo-500" />
                  Operational Data Logs
               </h3>
               <p className="text-3xl text-slate-400 font-black tracking-[0.6em] mt-8 uppercase">Manufacturing granularity for {selectedMonth}</p>
            </div>

            <div className="flex items-center gap-12">
              <input type="month" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)}
                className="px-16 py-10 text-4xl font-black bg-white dark:bg-slate-800 rounded-[3rem] shadow-2xl border-8 border-gray-100 dark:border-slate-700 outline-none"
              />
              <button className="flex items-center gap-10 px-20 py-12 bg-indigo-600 text-white text-3xl font-black rounded-[3rem] hover:bg-indigo-700 shadow-[0_50px_100px_rgba(79,70,229,0.4)] tracking-[0.4em] transition">
                <Download className="w-12 h-12" /> Export
              </button>
            </div>
        </div>

        <div className="space-y-32">
            {dailyGroups.map((group, idx) => (group.entries.length > 0 || group.isOffDay) && (
                <div key={idx} className={`bg-white dark:bg-slate-850 rounded-[8rem] overflow-hidden shadow-[0_100px_200px_rgba(0,0,0,0.2)] border-8 ${group.isOffDay ? 'border-amber-400' : 'border-gray-100 dark:border-slate-800'}`}>
                    <div className={`p-20 flex justify-between items-center border-b-8 ${group.isOffDay ? 'bg-amber-50 border-amber-200' : 'bg-gray-50 border-gray-100 dark:bg-slate-800/50'}`}>
