                    <div className="overflow-x-auto no-scrollbar">
                        <table className="w-full text-left">
                            <thead className="bg-gray-50/50 dark:bg-slate-900/50 text-3xl font-black text-slate-500 tracking-[0.8em] uppercase border-b-8 border-gray-100">
