};

import React, { useState, useEffect, useMemo } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { CATEGORIES, PROCESSES, UNITS } from '../../constants';
import { ProductionEntry, Category, ProcessType, UnitType } from '../../types';
import { X, Loader2, AlertTriangle, Palmtree, Lock } from 'lucide-react';
import { getTodayISO, getDbTimestamp } from '../../utils/dateUtils';

interface InputModalProps {
  onClose: () => void;
  editEntry?: ProductionEntry | null;
}

export const InputModal: React.FC<InputModalProps> = ({ onClose, editEntry }) => {
  const { user } = useAuth();
  const { triggerRefresh, refreshKey } = useDashboard();
  const [tab, setTab] = useState<'Plan' | 'Actual'>('Plan');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [date, setDate] = useState(getTodayISO());
  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [process, setProcess] = useState<ProcessType>(PROCESSES[0]);
  const [productName, setProductName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [unit, setUnit] = useState<UnitType>('KG');
  const [manpower, setManpower] = useState('0');
  const [batchNo, setBatchNo] = useState('');

  const [plans, setPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  const offDays = useMemo(() => StorageService.getOffDays(), [refreshKey]);
  const currentOffDay = useMemo(() => {
    if (!date) return null;
    return offDays.find(od => (od.date || '').trim().split(' ')[0] === date);
  }, [date, offDays]);

  const isLocked = !editEntry && !!currentOffDay;

  const inputClasses = `w-full p-10 rounded-[2.5rem] border-8 font-black text-4xl outline-none transition-all shadow-2xl ${
    isLocked 
    ? 'bg-slate-100 border-slate-200 text-slate-300 cursor-not-allowed' 
    : 'bg-white border-slate-200 text-slate-900 focus:ring-[24px] focus:ring-indigo-500/10 focus:border-indigo-600'
  }`;

  useEffect(() => {
    if (editEntry) {
      setDate((editEntry.date || '').trim().split(' ')[0]);
      setCategory(editEntry.category);
      setProcess(editEntry.process);
      setProductName(editEntry.productName);
      setUnit(editEntry.unit || 'KG');
      const isActualMode = editEntry.actualQuantity > 0;
      setQuantity(isActualMode ? (editEntry.actualQuantity || 0).toString() : (editEntry.planQuantity || 0).toString());
      setManpower(editEntry.manpower?.toString() || '0');
      setBatchNo(editEntry.batchNo || '');
      setTab(isActualMode ? 'Actual' : 'Plan'); 
    }
  }, [editEntry]);

  useEffect(() => {
    if (tab === 'Actual' && !editEntry) {
        const all = StorageService.getProductionData();
        const relevant = all.filter(p => p.date === date);
        setPlans(relevant);
        setSelectedPlanId('');
    }
  }, [date, tab, editEntry]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isLocked) return;
    setIsSubmitting(true);
    try {
        const currentData = StorageService.getProductionData();
        if (editEntry) {
            const updated = currentData.map(p => {
                if (p.id === editEntry.id) {
                    return { 
                        ...p, 
                        date, category, process, productName, unit,
                        planQuantity: tab === 'Plan' ? parseInt(quantity) : p.planQuantity,
                        actualQuantity: tab === 'Actual' ? parseInt(quantity) : p.actualQuantity,
                        batchNo, manpower: parseInt(manpower),
                        lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                    };
                }
                return p;
            });
            StorageService.saveProductionData(updated);
        } else {
            if (tab === 'Plan') {
                const newEntry: ProductionEntry = {
                    id: Date.now().toString(),
                    date, category, process, productName, unit,
                    planQuantity: parseInt(quantity), actualQuantity: 0,
                    lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                };
                StorageService.saveProductionData([...currentData, newEntry]);
            } else {
                if (!selectedPlanId) throw new Error("Select Job");
                const updated = currentData.map(p => {
                    if (p.id === selectedPlanId) {
                        return { 
                            ...p, 
                            actualQuantity: parseInt(quantity), batchNo, manpower: parseInt(manpower),
                            lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                        };
                    }
                    return p;
                });
                StorageService.saveProductionData(updated);
            }
        }
        triggerRefresh();
        onClose();
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-3xl z-50 flex items-center justify-center p-12">
      <div className="bg-white dark:bg-slate-800 rounded-[5rem] w-full max-w-7xl shadow-[0_150px_300px_rgba(0,0,0,0.6)] overflow-hidden border-[12px] border-white relative animate-in zoom-in duration-500">
        <div className="flex border-b-[12px] border-gray-100">
            <button onClick={() => setTab('Plan')} disabled={isLocked}
                className={`flex-1 py-20 font-black text-5xl uppercase tracking-[0.4em] text-center transition ${tab === 'Plan' ? 'bg-indigo-600 text-white' : 'bg-gray-100 text-slate-400'}`}>
                {isLocked ? 'SYSTEM LOCKED' : 'Production Plan'}
            </button>
            <button onClick={() => setTab('Actual')} disabled={isLocked}
                className={`flex-1 py-20 font-black text-5xl uppercase tracking-[0.4em] text-center transition ${tab === 'Actual' ? 'bg-emerald-600 text-white' : 'bg-gray-100 text-slate-400'}`}>
                {isLocked ? 'SYSTEM LOCKED' : 'Production Execution'}
            </button>
        </div>

        <div className="p-24 relative overflow-y-auto max-h-[70vh] custom-scrollbar">
            <button onClick={onClose} className="absolute top-12 right-16 text-slate-300 hover:text-rose-500 transition-colors scale-[3.0]"><X className="w-10 h-10" /></button>

            <form onSubmit={handleSubmit} className="space-y-20">
                <div className="grid grid-cols-1 xl:grid-cols-2 gap-20">
                    <div className="space-y-8">
                        <label className="text-3xl font-black text-slate-400 tracking-[0.5em]">Operations Date</label>
                        <input type="date" required value={date} onChange={e => setDate(e.target.value)} className={inputClasses} />
                        {currentOffDay && (
                          <div className="p-12 bg-amber-50 border-8 border-amber-200 rounded-[3rem] flex items-center gap-10">
                            <Palmtree className="w-20 h-20 text-amber-500" />
                            <span className="text-4xl font-black text-amber-700 uppercase">{currentOffDay.description}</span>
                          </div>
                        )}
                    </div>
                    <div className="space-y-8">
                        <label className="text-3xl font-black text-slate-400 tracking-[0.5em]">Manufacturing Dept</label>
                        <select disabled={isLocked} value={category} onChange={e => setCategory(e.target.value as Category)} className={inputClasses}>
                            {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                    </div>
                </div>

                <div className="space-y-8">
                    <label className="text-3xl font-black text-slate-400 tracking-[0.5em]">Product Specification</label>
                    <input disabled={isLocked} type="text" required value={productName} onChange={e => setProductName(e.target.value)} className={inputClasses} placeholder="Enter Product Identity..." />
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-20">
                    <div className="space-y-8">
                        <label className="text-3xl font-black text-slate-400 tracking-[0.5em]">Unit Quantity</label>
                        <input disabled={isLocked} type="number" required value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                    </div>
                    <div className="space-y-8">
                        <label className="text-3xl font-black text-slate-400 tracking-[0.5em]">Unit Metric</label>
                        <select disabled={isLocked} value={unit} onChange={e => setUnit(e.target.value as UnitType)} className={inputClasses}>
                            {UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                        </select>
                    </div>
                    <div className="space-y-8">
                        <label className="text-3xl font-black text-slate-400 tracking-[0.5em]">Staff Count</label>
                        <input disabled={isLocked} type="number" value={manpower} onChange={e => setManpower(e.target.value)} className={inputClasses} />
                    </div>
                </div>

                <button type="submit" disabled={isSubmitting || isLocked} 
                    className={`w-full py-16 rounded-[4rem] font-black text-5xl uppercase tracking-[0.6em] text-white shadow-[0_40px_80px_rgba(0,0,0,0.3)] transition active:scale-95 ${isLocked ? 'bg-slate-300' : 'bg-slate-900 hover:bg-black'}`}>
                    {isSubmitting ? 'Pushing Data...' : 'Commit to Cloud Network'}
                </button>
            </form>
        </div>
      </div>
    </div>
  );
};

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { User, Role } from '../types';
import { StorageService } from '../services/storageService';
import { INITIAL_USERS } from '../constants';
import { GoogleSheetsService } from '../services/googleSheetsService';

interface AuthContextType {
  user: User | null;
  login: (username: string, pass: string) => Promise<boolean>;
  logout: () => void;
  hasPermission: (roles: Role[]) => boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    const session = StorageService.getSession();
    if (session) {
      setUser(session);
    }
    // Attempt to sync users on mount to ensure device is up to date
    if (GoogleSheetsService.isEnabled()) {
      StorageService.syncWithSheets().catch(console.error);
    }
  }, []);

  const login = async (username: string, pass: string) => {
    // 1. SILENT SYNC BEFORE LOGIN ATTEMPT
    // This is crucial for mobile devices that might have stale local storage
    if (GoogleSheetsService.isEnabled()) {
      try {
        await StorageService.syncWithSheets();
      } catch (e) {
        console.warn("LOGIN SYNC FAILED, PROCEEDING WITH LOCAL DATA");
      }
    }

    const cleanUsername = username.trim().toLowerCase();
    const cleanPass = pass.trim();

    const storedUsers = StorageService.getUsers();

    // Combine initial and stored users
    const userMap = new Map<string, User>();
    [...INITIAL_USERS, ...storedUsers].forEach(u => {
      if (u && u.username) {
        userMap.set(u.username.toLowerCase(), u);
      }
    });

    const targetUser = userMap.get(cleanUsername);

    if (targetUser && targetUser.password === cleanPass) {
      setUser(targetUser);
      StorageService.setSession(targetUser);

      StorageService.addLog({
        userId: targetUser.id,
        userName: targetUser.name,
        action: 'LOGIN',
        details: `USER LOGGED IN SUCCESSFULLY VIA ${window.innerWidth < 768 ? 'MOBILE' : 'DESKTOP'}`
      });

      return true;
    }
    return false;
  };

  const logout = () => {
    if (user) {
      StorageService.addLog({
        userId: user.id,
        userName: user.name,
        action: 'LOGOUT',
        details: 'USER SIGNED OUT OF SESSION'
      });
    }
    setUser(null);
    StorageService.setSession(null);
  };

  const hasPermission = (allowedRoles: Role[]) => {
    if (!user) return false;
    return allowedRoles.includes(user.role);
  };

  return (
    <AuthContext.Provider value={{ user, login, logout, hasPermission }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

