import React, { useState, useEffect, useMemo } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { CATEGORIES, PROCESSES, UNITS } from '../../constants';
import { ProductionEntry, Category, ProcessType, UnitType } from '../../types';
import { X, Loader2, AlertTriangle, Palmtree, Lock } from 'lucide-react';
import { getTodayISO, getDbTimestamp } from '../../utils/dateUtils';

interface InputModalProps {
  onClose: () => void;
  editEntry?: ProductionEntry | null;
}

export const InputModal: React.FC<InputModalProps> = ({ onClose, editEntry }) => {
  const { user } = useAuth();
  const { triggerRefresh, refreshKey } = useDashboard();
  const [tab, setTab] = useState<'Plan' | 'Actual'>('Plan');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [date, setDate] = useState(getTodayISO());
  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [process, setProcess] = useState<ProcessType>(PROCESSES[0]);
  const [productName, setProductName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [unit, setUnit] = useState<UnitType>('KG');
  const [manpower, setManpower] = useState('0');
  const [batchNo, setBatchNo] = useState('');

  const [plans, setPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  const offDays = useMemo(() => StorageService.getOffDays(), [refreshKey]);
  const currentOffDay = useMemo(() => {
    if (!date) return null;
    return offDays.find(od => (od.date || '').trim().split(' ')[0] === date);
  }, [date, offDays]);

  const isLocked = !editEntry && !!currentOffDay;

  const inputClasses = `w-full p-6 rounded-2xl border-4 font-black text-xl outline-none transition-all shadow-lg ${
    isLocked 
    ? 'bg-slate-100 border-slate-200 text-slate-300 cursor-not-allowed' 
    : 'bg-white border-slate-200 text-slate-900 focus:ring-8 focus:ring-indigo-500/10 focus:border-indigo-600'
  }`;

  useEffect(() => {
    if (editEntry) {
      setDate((editEntry.date || '').trim().split(' ')[0]);
      setCategory(editEntry.category);
      setProcess(editEntry.process);
      setProductName(editEntry.productName);
      setUnit(editEntry.unit || 'KG');
      const isActualMode = editEntry.actualQuantity > 0;
      setQuantity(isActualMode ? (editEntry.actualQuantity || 0).toString() : (editEntry.planQuantity || 0).toString());
      setManpower(editEntry.manpower?.toString() || '0');
      setBatchNo(editEntry.batchNo || '');
      setTab(isActualMode ? 'Actual' : 'Plan'); 
    }
  }, [editEntry]);

  useEffect(() => {
    if (tab === 'Actual' && !editEntry) {
        const all = StorageService.getProductionData();
        const relevant = all.filter(p => p.date === date);
        setPlans(relevant);
        setSelectedPlanId('');
    }
  }, [date, tab, editEntry]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isLocked) return;
    setIsSubmitting(true);
    try {
        const currentData = StorageService.getProductionData();
        if (editEntry) {
            const updated = currentData.map(p => {
                if (p.id === editEntry.id) {
                    return { 
                        ...p, 
                        date, category, process, productName, unit,
                        planQuantity: tab === 'Plan' ? parseInt(quantity) : p.planQuantity,
                        actualQuantity: tab === 'Actual' ? parseInt(quantity) : p.actualQuantity,
                        batchNo, manpower: parseInt(manpower),
                        lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                    };
                }
                return p;
            });
            StorageService.saveProductionData(updated);
        } else {
            if (tab === 'Plan') {
                const newEntry: ProductionEntry = {
                    id: Date.now().toString(),
                    date, category, process, productName, unit,
                    planQuantity: parseInt(quantity), actualQuantity: 0,
                    lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                };
                StorageService.saveProductionData([...currentData, newEntry]);
            } else {
                if (!selectedPlanId) throw new Error("Select Job");
                const updated = currentData.map(p => {
                    if (p.id === selectedPlanId) {
                        return { 
                            ...p, 
                            actualQuantity: parseInt(quantity), batchNo, manpower: parseInt(manpower),
                            lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                        };
                    }
                    return p;
                });
                StorageService.saveProductionData(updated);
            }
        }
        triggerRefresh();
        onClose();
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-xl z-50 flex items-center justify-center p-8">
      <div className="bg-white dark:bg-slate-800 rounded-[3rem] w-full max-w-2xl shadow-2xl overflow-hidden border-8 border-white relative animate-in zoom-in duration-300">
        <div className="flex border-b-8 border-gray-100">
            <button onClick={() => setTab('Plan')} disabled={isLocked}
                className={`flex-1 py-8 font-black text-2xl uppercase tracking-widest text-center transition ${tab === 'Plan' ? 'bg-indigo-600 text-white' : 'bg-gray-100 text-slate-400'}`}>
                {isLocked ? 'LOCKED' : 'Planning'}
            </button>
            <button onClick={() => setTab('Actual')} disabled={isLocked}
                className={`flex-1 py-8 font-black text-2xl uppercase tracking-widest text-center transition ${tab === 'Actual' ? 'bg-emerald-600 text-white' : 'bg-gray-100 text-slate-400'}`}>
                {isLocked ? 'LOCKED' : 'Execution'}
            </button>
        </div>

        <div className="p-12 relative">
            <button onClick={onClose} className="absolute top-4 right-8 text-slate-300 hover:text-rose-500 transition-colors scale-150"><X className="w-8 h-8" /></button>

            <form onSubmit={handleSubmit} className="space-y-10">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    <div className="space-y-3">
                        <label className="text-sm font-black text-slate-400 tracking-widest uppercase">Date</label>
                        <input type="date" required value={date} onChange={e => setDate(e.target.value)} className={inputClasses} />
                        {currentOffDay && (
                          <div className="p-6 bg-amber-50 border-4 border-amber-200 rounded-xl flex items-center gap-4">
                            <Palmtree className="w-8 h-8 text-amber-500" />
                            <span className="text-lg font-black text-amber-700 uppercase">{currentOffDay.description}</span>
                          </div>
                        )}
                    </div>
                    <div className="space-y-3">
                        <label className="text-sm font-black text-slate-400 tracking-widest uppercase">Dept</label>
                        <select disabled={isLocked} value={category} onChange={e => setCategory(e.target.value as Category)} className={inputClasses}>
                            {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                    </div>
                </div>

                <div className="space-y-3">
                    <label className="text-sm font-black text-slate-400 tracking-widest uppercase">Product</label>
                    <input disabled={isLocked} type="text" required value={productName} onChange={e => setProductName(e.target.value)} className={inputClasses} placeholder="Enter name..." />
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                    <div className="space-y-3">
                        <label className="text-sm font-black text-slate-400 tracking-widest uppercase">Qty</label>
                        <input disabled={isLocked} type="number" required value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                    </div>
                    <div className="space-y-3">
                        <label className="text-sm font-black text-slate-400 tracking-widest uppercase">Unit</label>
                        <select disabled={isLocked} value={unit} onChange={e => setUnit(e.target.value as UnitType)} className={inputClasses}>
                            {UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                        </select>
                    </div>
                    <div className="space-y-3">
                        <label className="text-sm font-black text-slate-400 tracking-widest uppercase">Staff</label>
                        <input disabled={isLocked} type="number" value={manpower} onChange={e => setManpower(e.target.value)} className={inputClasses} />
                    </div>
                </div>

                <button type="submit" disabled={isSubmitting || isLocked} 
                    className={`w-full py-8 rounded-2xl font-black text-2xl uppercase tracking-widest text-white shadow-xl transition ${isLocked ? 'bg-slate-300' : 'bg-slate-900 hover:bg-black'}`}>
                    {isSubmitting ? 'Pushing...' : 'Sync Data'}
                </button>
            </form>
        </div>
      </div>
    </div>
  );
};

import React, { ReactNode, useState, useEffect, useCallback, useRef } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { Category, ProductionEntry } from '../../types';
import { CATEGORIES } from '../../constants';
import { LoginModal } from '../modals/LoginModal';
import { InputModal } from '../modals/InputModal';
import { OffDayModal } from '../modals/OffDayModal';
import { ChangePasswordModal } from '../modals/ChangePasswordModal';
import { AvatarModal } from '../modals/AvatarModal';
import { GoogleSheetsService } from '../../services/googleSheetsService';
import { StorageService } from '../../services/storageService';
import { Link, useLocation } from 'react-router-dom';
import { 
  Menu, X, Moon, Sun, Plus, LogOut, Database,
  CalendarX, LayoutDashboard, RefreshCw, LogIn, CheckCircle, Info,
  ClipboardList, Users, History, Key, BarChart3, Camera
} from 'lucide-react';

export const Layout: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { user, logout, hasPermission } = useAuth();
  const { category, setCategory, isDarkMode, toggleDarkMode, triggerRefresh } = useDashboard();
  const location = useLocation();

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [showInput, setShowInput] = useState(false);
  const [showOffDays, setShowOffDays] = useState(false);
  const [showChangePass, setShowChangePass] = useState(false);
  const [showAvatarModal, setShowAvatarModal] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [entryToEdit, setEntryToEdit] = useState<ProductionEntry | null>(null);
  const [notification, setNotification] = useState<{ message: string; type: 'success' | 'info' } | null>(null);

  const timeoutRef = useRef<number | null>(null);

  const handleNotify = useCallback((e: any) => {
    if (timeoutRef.current) window.clearTimeout(timeoutRef.current);
    setNotification({ message: e.detail.message, type: e.detail.type || 'success' });
    timeoutRef.current = window.setTimeout(() => {
      setNotification(null);
      timeoutRef.current = null;
    }, 2000);
  }, []);

  const handleEditEntry = useCallback((e: any) => {
    setEntryToEdit(e.detail);
    setShowInput(true);
  }, []);

  const handleLogout = () => {
    logout();
    setIsMobileMenuOpen(false);
  };

  const handleSync = async (silent = false) => {
    if (!GoogleSheetsService.isEnabled()) return;
    if (!silent) setIsSyncing(true);
    try {
      await StorageService.syncWithSheets();
      triggerRefresh();
    } catch (e) {
      console.error(e);
    } finally {
      if (!silent) setIsSyncing(false);
    }
  };

  useEffect(() => {
    if (GoogleSheetsService.isEnabled()) handleSync(true);
  }, []);

  useEffect(() => {
    window.addEventListener('app-notification', handleNotify);
    window.addEventListener('edit-production-entry', handleEditEntry);
    return () => {
      window.removeEventListener('app-notification', handleNotify);
      window.removeEventListener('edit-production-entry', handleEditEntry);
      if (timeoutRef.current) window.clearTimeout(timeoutRef.current);
    };
  }, [handleNotify, handleEditEntry]);

  const navItemClass = (path: string) => `
    w-full flex items-center gap-4 px-6 py-4 rounded-2xl text-lg font-black transition-all uppercase tracking-tight
    ${location.pathname === path 
      ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/30' 
      : 'text-slate-500 hover:bg-gray-100 dark:hover:bg-slate-800'}
  `;

  return (
    <div className={`min-h-screen flex ${isDarkMode ? 'dark' : ''} bg-slate-50 dark:bg-slate-900 transition-colors duration-300 font-sans uppercase`}>
      {notification && (
        <div className="fixed top-20 right-8 z-[10000] pointer-events-none w-full max-w-sm px-4">
          <div className="notification-animate pointer-events-auto">
            <div className={`flex items-center gap-6 px-8 py-6 rounded-[2rem] shadow-2xl border-4 bg-white dark:bg-slate-800 ${
              notification.type === 'success' ? 'border-emerald-500' : 'border-indigo-500'
            }`}>
              <div className={`p-4 rounded-2xl ${notification.type === 'success' ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-100 text-indigo-600'}`}>
                {notification.type === 'success' ? <CheckCircle className="w-8 h-8" /> : <Info className="w-8 h-8" />}
              </div>
              <div className="flex-1">
                <p className={`text-xs font-black uppercase tracking-widest mb-1 ${notification.type === 'success' ? 'text-emerald-500' : 'text-indigo-500'}`}>Alert</p>
                <p className="text-xl font-black text-slate-900 dark:text-white leading-tight">{notification.message.toUpperCase()}</p>
              </div>
            </div>
          </div>
        </div>
      )}

      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-40 md:hidden" onClick={() => setIsMobileMenuOpen(false)} />
      )}

      <aside className={`fixed inset-y-0 left-0 w-80 bg-white dark:bg-slate-850 border-r-2 border-gray-200 dark:border-slate-700 z-50 transform transition-transform duration-300 md:translate-x-0 md:static md:block ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-10 border-b-2 border-gray-100 dark:border-slate-800 text-center">
             <div className="text-4xl font-black tracking-tighter text-slate-900 dark:text-white uppercase">
                HALA<span className="text-emerald-500">GEL</span>
             </div>
             <p className="text-xs font-black text-slate-400 uppercase tracking-[0.4em] mt-2">Production Pro</p>
        </div>

        <nav className="p-6 space-y-3 overflow-y-auto max-h-[calc(100vh-200px)] custom-scrollbar uppercase">
          <Link to="/" onClick={() => setIsMobileMenuOpen(false)} className={navItemClass('/')}>
            <LayoutDashboard className="w-6 h-6" /> Dashboard
          </Link>
          <Link to="/reports" onClick={() => setIsMobileMenuOpen(false)} className={navItemClass('/reports')}>
            <ClipboardList className="w-6 h-6" /> Reports
          </Link>
          <Link to="/process-analytics" onClick={() => setIsMobileMenuOpen(false)} className={navItemClass('/process-analytics')}>
            <BarChart3 className="w-6 h-6" /> Analytics
          </Link>

          <div className="pt-8 px-6 py-2 text-xs font-black text-slate-400 uppercase tracking-widest">Departments</div>
