import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { User, Role } from '../types';
import { StorageService } from '../services/storageService';
import { INITIAL_USERS } from '../constants';
import { GoogleSheetsService } from '../services/googleSheetsService';

interface AuthContextType {
  user: User | null;
  login: (username: string, pass: string) => Promise<boolean>;
  logout: () => void;
  hasPermission: (roles: Role[]) => boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    const session = StorageService.getSession();
    if (session) {
      setUser(session);
    }
    // Attempt to sync users on mount to ensure device is up to date
    if (GoogleSheetsService.isEnabled()) {
      StorageService.syncWithSheets().catch(console.error);
    }
  }, []);

  const login = async (username: string, pass: string) => {
    // 1. SILENT SYNC BEFORE LOGIN ATTEMPT
    // This fixes the laptop vs mobile sync problem by forcing the phone to pull latest users first.
    if (GoogleSheetsService.isEnabled()) {
      try {
        await StorageService.syncWithSheets();
      } catch (e) {
        console.warn("LOGIN SYNC FAILED, PROCEEDING WITH LOCAL DATA");
      }
    }

    const cleanUsername = username.trim().toLowerCase();
    const cleanPass = pass.trim();

    const storedUsers = StorageService.getUsers();

    // Combine initial and stored users
    const userMap = new Map<string, User>();
    [...INITIAL_USERS, ...storedUsers].forEach(u => {
      if (u && u.username) {
        userMap.set(u.username.toLowerCase(), u);
      }
    });

    const targetUser = userMap.get(cleanUsername);

    if (targetUser && targetUser.password === cleanPass) {
      setUser(targetUser);
      StorageService.setSession(targetUser);

      StorageService.addLog({
        userId: targetUser.id,
        userName: targetUser.name,
        action: 'LOGIN',
        details: `USER LOGGED IN SUCCESSFULLY VIA ${window.innerWidth < 768 ? 'MOBILE' : 'DESKTOP'}`
      });

      return true;
    }
    return false;
  };

  const logout = () => {
    if (user) {
      StorageService.addLog({
        userId: user.id,
        userName: user.name,
        action: 'LOGOUT',
        details: 'USER SIGNED OUT OF SESSION'
      });
    }
    setUser(null);
    StorageService.setSession(null);
  };

  const hasPermission = (allowedRoles: Role[]) => {
    if (!user) return false;
    return allowedRoles.includes(user.role);
  };

  return (
    <AuthContext.Provider value={{ user, login, logout, hasPermission }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

