import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { ProductionEntry } from '../../types';
import { PROCESSES } from '../../constants';
import { 
  ClipboardList, CheckCircle, RefreshCw, List, Calendar, 
  TrendingUp, Download, Pencil, Trash2, Layers,
  Palmtree
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { formatDisplayDate, getCurrentMonthISO } from '../../utils/dateUtils';

export const Dashboard: React.FC = () => {
  const { category, refreshKey, triggerRefresh } = useDashboard();
  const { user, hasPermission } = useAuth();

  const [selectedMonth, setSelectedMonth] = useState<string>(getCurrentMonthISO());

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  const dashboardData = useMemo(() => {
    const relevant = productionData.filter(d => d && d.category === category && d.date);
    let selectedMonthPlan = 0;
    let selectedMonthActual = 0;

    const selectedMonthProcessMap = new Map<string, {process: string, Plan: number, Actual: number}>();
    PROCESSES.forEach(proc => {
      selectedMonthProcessMap.set(proc, { process: proc, Plan: 0, Actual: 0 });
    });

    relevant.forEach(d => {
      const dateStr = (d.date || '').trim().substring(0, 7);
      if (dateStr === selectedMonth) {
        selectedMonthPlan += (d.planQuantity || 0);
        selectedMonthActual += (d.actualQuantity || 0);

        const procName = d.process || 'Other';
        if (selectedMonthProcessMap.has(procName)) {
          const p = selectedMonthProcessMap.get(procName)!;
          p.Plan += (d.planQuantity || 0);
          p.Actual += (d.actualQuantity || 0);
        }
      }
    });

    return {
      filteredData: relevant.sort((a,b) => (b.date || '').localeCompare(a.date || '')),
      selectedMonthStats: { 
        plan: selectedMonthPlan, 
        actual: selectedMonthActual,
        efficiency: selectedMonthPlan > 0 ? (selectedMonthActual / selectedMonthPlan) * 100 : 0
      },
      chartData: Array.from(selectedMonthProcessMap.values())
    };
  }, [productionData, category, selectedMonth]);

  const dailyGroups = useMemo(() => {
    const baseData = dashboardData.filteredData;
    const filteredEntries = baseData.filter(d => d && d.date && d.date.trim().startsWith(selectedMonth));
    const filteredOffDays = offDays.filter(od => od && od.date && od.date.trim().startsWith(selectedMonth));

    const dates = new Set<string>();
    filteredEntries.forEach(d => {
      if (d.date) dates.add(d.date.trim().substring(0, 10));
    });
    filteredOffDays.forEach(od => {
      if (od.date) dates.add(od.date.trim().substring(0, 10));
    });

    const sortedDates = Array.from(dates).sort((a, b) => (b || '').localeCompare(a || ''));

    return sortedDates.map(dateKey => {
        const entriesForDate = filteredEntries.filter(d => d.date && d.date.trim().substring(0, 10) === dateKey);
        const offDayInfo = filteredOffDays.find(od => od.date && od.date.trim().substring(0, 10) === dateKey);
        const totalActualForDate = entriesForDate.reduce((sum, entry) => sum + (entry.actualQuantity || 0), 0);

        return {
            date: dateKey,
            totalActualForDate,
            entries: entriesForDate,
            isOffDay: !!offDayInfo,
            offDayName: offDayInfo?.description || ''
        };
    });
  }, [dashboardData.filteredData, offDays, selectedMonth]);

  const handleDelete = (id: string) => {
      if(!window.confirm("ARE YOU SURE?")) return;
      StorageService.deleteProductionEntry(id);
      triggerRefresh();
  };

  const handleEdit = (entry: ProductionEntry) => {
    window.dispatchEvent(new CustomEvent('edit-production-entry', { detail: entry }));
  };

  // Roles that are permitted to modify production data (Planning + Actual)
  const canModifyData = hasPermission(['admin', 'manager', 'planner', 'operator']);

  return (
    <div className="space-y-16 pb-32 uppercase">
      {/* KPI Cards - USUAL SCALE */}
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-10">
        <div className="glass-panel p-12 rounded-[3rem] border-l-[16px] border-blue-600 shadow-xl relative overflow-hidden group">
            <p className="text-lg font-black text-slate-400 tracking-widest mb-6">Monthly Plan (Total)</p>
            <h3 className="text-6xl font-black text-slate-900 dark:text-white font-mono tracking-tighter leading-none">{(dashboardData.selectedMonthStats.plan || 0).toLocaleString()}</h3>
            <div className="mt-8 flex items-center gap-4 text-emerald-500 font-black text-xl">
               <TrendingUp className="w-8 h-8" /> Target Matrix
            </div>
        </div>
        <div className="glass-panel p-12 rounded-[3rem] border-l-[16px] border-emerald-600 shadow-xl relative overflow-hidden group">
            <p className="text-lg font-black text-slate-400 tracking-widest mb-6">Monthly Actual (Total)</p>
            <h3 className="text-6xl font-black text-slate-900 dark:text-white font-mono tracking-tighter leading-none">{(dashboardData.selectedMonthStats.actual || 0).toLocaleString()}</h3>
            <div className="mt-8 flex items-center gap-4 text-emerald-500 font-black text-xl">
               <CheckCircle className="w-8 h-8" /> Yield Success
            </div>
        </div>
        <div className="glass-panel p-12 rounded-[3rem] border-l-[16px] border-indigo-600 shadow-xl relative overflow-hidden group">
            <p className="text-lg font-black text-slate-400 tracking-widest mb-6">System Efficiency</p>
            <h3 className="text-6xl font-black text-slate-900 dark:text-white font-mono tracking-tighter leading-none">{(dashboardData.selectedMonthStats.efficiency || 0).toFixed(0)}%</h3>
            <div className="mt-8 w-full h-4 bg-slate-100 dark:bg-slate-700 rounded-full overflow-hidden">
                <div className="h-full bg-indigo-600" style={{ width: `${dashboardData.selectedMonthStats.efficiency}%` }} />
            </div>
        </div>
      </div>

      {/* Process Matrix Breakdown */}
      <div className="space-y-10">
        <div className="flex items-center gap-6 px-4">
            <Layers className="w-10 h-10 text-indigo-500" />
            <h3 className="text-xl font-black text-slate-400 uppercase tracking-widest">Performance Matrix</h3>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-5 gap-8">
            {dashboardData.chartData.map((item) => {
                const eff = item.Plan > 0 ? (item.Actual / item.Plan) * 100 : 0;
                return (
                    <div key={item.process} className="glass-panel p-10 rounded-[2.5rem] border-4 border-gray-100 dark:border-slate-800 shadow-lg group hover:scale-105 transition-transform">
                        <p className="text-xl font-black text-indigo-600 tracking-widest mb-8 text-center">{item.process.toUpperCase()}</p>

                        <div className="space-y-6">
                            <div className="flex justify-between items-center">
                                <span className="text-sm font-black text-slate-400">Plan</span>
                                <span className="text-3xl font-black text-slate-900 dark:text-white font-mono">{(item.Plan || 0).toLocaleString()}</span>
                            </div>

                            <div className="flex justify-between items-center">
                                <span className="text-sm font-black text-slate-400">Actual</span>
                                <span className="text-3xl font-black text-emerald-600 font-mono">{(item.Actual || 0).toLocaleString()}</span>
                            </div>

                            <div className="pt-6 border-t-4 border-gray-100 dark:border-slate-700 flex justify-between items-center">
                                <span className="text-sm font-black text-slate-400">Eff.</span>
                                <span className={`text-4xl font-black font-mono ${eff >= 95 ? 'text-emerald-500' : 'text-rose-500'}`}>
                                    {(eff || 0).toFixed(0)}%
                                </span>
                            </div>
                        </div>
                    </div>
                );
            })}
        </div>
      </div>

      {/* Logs Table */}
      <div className="space-y-12">
        <div className="flex flex-col xl:flex-row justify-between items-end gap-10 px-4">
            <div>
               <h3 className="text-4xl font-black text-slate-900 dark:text-white flex items-center gap-6 tracking-tight">
                  <List className="w-12 h-12 text-indigo-500" />
                  Data Logs
               </h3>
               <p className="text-sm text-slate-400 font-black tracking-widest mt-2 uppercase">Operational granularity for {selectedMonth}</p>
            </div>

            <div className="flex items-center gap-6">
              <input type="month" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)}
                className="px-8 py-4 text-xl font-black bg-white dark:bg-slate-800 rounded-2xl shadow-lg border-4 border-gray-100 dark:border-slate-700 outline-none"
              />
              <button className="flex items-center gap-4 px-10 py-5 bg-indigo-600 text-white text-lg font-black rounded-2xl hover:bg-indigo-700 shadow-xl tracking-widest transition">
                <Download className="w-6 h-6" /> Export
              </button>
            </div>
        </div>

        <div className="space-y-16">
            {dailyGroups.map((group, idx) => (group.entries.length > 0 || group.isOffDay) && (
                <div key={idx} className={`bg-white dark:bg-slate-850 rounded-[3rem] overflow-hidden shadow-xl border-4 ${group.isOffDay ? 'border-amber-400' : 'border-gray-100 dark:border-slate-800'}`}>
                    <div className={`p-10 flex justify-between items-center border-b-4 ${group.isOffDay ? 'bg-amber-50 border-amber-200' : 'bg-gray-50 border-gray-100 dark:bg-slate-800/50'}`}>
                        <div className="flex items-center gap-8">
                            {group.isOffDay ? <Palmtree className="w-10 h-10 text-amber-500" /> : <Calendar className="w-10 h-10 text-slate-400" />}
                            <span className="text-3xl font-black text-slate-900 dark:text-white font-mono tracking-tighter">{group.date}</span>
                            {group.isOffDay && <span className="px-8 py-3 bg-amber-500 text-white text-lg font-black rounded-full tracking-widest">{group.offDayName}</span>}
                        </div>
                        <div className="text-2xl font-black text-slate-900 dark:text-white">
                           Total: <span className="text-emerald-600 ml-4">{(group.totalActualForDate || 0).toLocaleString()}</span>
                        </div>
                    </div>

                    <div className="overflow-x-auto no-scrollbar">
                        <table className="w-full text-left">
                            <thead className="bg-gray-50/50 dark:bg-slate-900/50 text-sm font-black text-slate-500 tracking-widest uppercase border-b-4 border-gray-100">
                                <tr>
                                    <th className="px-10 py-6">Process</th>
                                    <th className="px-10 py-6">Product</th>
                                    <th className="px-10 py-6 text-right">Plan</th>
                                    <th className="px-10 py-6 text-right">Actual</th>
                                    <th className="px-10 py-6 text-center">Eff.</th>
                                    {canModifyData && <th className="px-10 py-6 text-center">Ctrl</th>}
                                </tr>
                            </thead>
                            <tbody className="divide-y-4 divide-gray-50">
                                {group.entries.map(entry => {
                                    const eff = entry.planQuantity > 0 ? (entry.actualQuantity / entry.planQuantity) * 100 : 0;
                                    return (
                                        <tr key={entry.id} className="hover:bg-indigo-50 transition-colors">
                                            <td className="px-10 py-10">
                                                <span className="text-sm font-black text-indigo-700 bg-indigo-50 px-5 py-2 rounded-xl border-2 border-indigo-200">{entry.process}</span>
                                            </td>
                                            <td className="px-10 py-10">
                                                <span className="text-xl font-black text-slate-900 dark:text-white tracking-tight">{entry.productName}</span>
                                            </td>
                                            <td className="px-10 py-10 text-right font-black font-mono text-slate-400 text-2xl">{(entry.planQuantity || 0).toLocaleString()}</td>
                                            <td className="px-10 py-10 text-right font-black font-mono text-emerald-600 text-3xl">{(entry.actualQuantity || 0).toLocaleString()}</td>
                                            <td className="px-10 py-10 text-center">
                                                <span className={`text-2xl font-black font-mono ${eff >= 95 ? 'text-emerald-500' : 'text-rose-500'}`}>{(eff || 0).toFixed(0)}%</span>
                                            </td>
                                            {canModifyData && (
                                              <td className="px-10 py-10 text-center">
                                                  <div className="flex justify-center gap-6">
                                                      <button onClick={() => handleEdit(entry)} className="p-4 text-indigo-500 hover:bg-indigo-50 rounded-xl border-2 border-indigo-100"><Pencil className="w-6 h-6" /></button>
                                                      <button onClick={() => handleDelete(entry.id)} className="p-4 text-rose-500 hover:bg-rose-50 rounded-xl border-2 border-rose-100"><Trash2 className="w-6 h-6" /></button>
                                                  </div>
                                              </td>
                                            )}
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                </div>
            ))}
        </div>
      </div>
    </div>
  );
};

