                        <div className="flex items-center gap-8">
                            {group.isOffDay ? <Palmtree className="w-10 h-10 text-amber-500" /> : <Calendar className="w-10 h-10 text-slate-400" />}
                            <span className="text-3xl font-black text-slate-900 dark:text-white font-mono tracking-tighter">{group.date}</span>
                            {group.isOffDay && <span className="px-8 py-3 bg-amber-500 text-white text-lg font-black rounded-full tracking-widest">{group.offDayName}</span>}
                        </div>
                        <div className="text-2xl font-black text-slate-900 dark:text-white">
                           Total: <span className="text-emerald-600 ml-4">{(group.totalActualForDate || 0).toLocaleString()}</span>
                        </div>
                    </div>

                    <div className="overflow-x-auto no-scrollbar">
                        <table className="w-full text-left">
                            <thead className="bg-gray-50/50 dark:bg-slate-900/50 text-sm font-black text-slate-500 tracking-widest uppercase border-b-4 border-gray-100">
                                <tr>
                                    <th className="px-10 py-6">Process</th>
                                    <th className="px-10 py-6">Product</th>
                                    <th className="px-10 py-6 text-right">Plan</th>
                                    <th className="px-10 py-6 text-right">Actual</th>
                                    <th className="px-10 py-6 text-center">Eff.</th>
                                    {canModifyData && <th className="px-10 py-6 text-center">Ctrl</th>}
                                </tr>
                            </thead>
                            <tbody className="divide-y-4 divide-gray-50">
                                {group.entries.map(entry => {
                                    const eff = entry.planQuantity > 0 ? (entry.actualQuantity / entry.planQuantity) * 100 : 0;
                                    return (
                                        <tr key={entry.id} className="hover:bg-indigo-50 transition-colors">
                                            <td className="px-10 py-10">
                                                <span className="text-sm font-black text-indigo-700 bg-indigo-50 px-5 py-2 rounded-xl border-2 border-indigo-200">{entry.process}</span>
                                            </td>
                                            <td className="px-10 py-10">
                                                <span className="text-xl font-black text-slate-900 dark:text-white tracking-tight">{entry.productName}</span>
                                            </td>
                                            <td className="px-10 py-10 text-right font-black font-mono text-slate-400 text-2xl">{(entry.planQuantity || 0).toLocaleString()}</td>
                                            <td className="px-10 py-10 text-right font-black font-mono text-emerald-600 text-3xl">{(entry.actualQuantity || 0).toLocaleString()}</td>
                                            <td className="px-10 py-10 text-center">
                                                <span className={`text-2xl font-black font-mono ${eff >= 95 ? 'text-emerald-500' : 'text-rose-500'}`}>{(eff || 0).toFixed(0)}%</span>
                                            </td>
                                            {canModifyData && (
                                              <td className="px-10 py-10 text-center">
                                                  <div className="flex justify-center gap-6">
                                                      <button onClick={() => handleEdit(entry)} className="p-4 text-indigo-500 hover:bg-indigo-50 rounded-xl border-2 border-indigo-100"><Pencil className="w-6 h-6" /></button>
                                                      <button onClick={() => handleDelete(entry.id)} className="p-4 text-rose-500 hover:bg-rose-50 rounded-xl border-2 border-rose-100"><Trash2 className="w-6 h-6" /></button>
                                                  </div>
                                              </td>
                                            )}
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                </div>
            ))}
        </div>
      </div>
    </div>
  );
};

import React, { ReactNode, useState, useEffect, useCallback, useRef } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { Category, ProductionEntry } from '../../types';
import { CATEGORIES } from '../../constants';
import { LoginModal } from '../modals/LoginModal';
import { InputModal } from '../modals/InputModal';
import { OffDayModal } from '../modals/OffDayModal';
import { ChangePasswordModal } from '../modals/ChangePasswordModal';
import { AvatarModal } from '../modals/AvatarModal';
import { GoogleSheetsService } from '../../services/googleSheetsService';
import { StorageService } from '../../services/storageService';
import { Link, useLocation } from 'react-router-dom';
import { 
  Menu, X, Moon, Sun, Plus, LogOut, Database,
  CalendarX, LayoutDashboard, RefreshCw, LogIn, CheckCircle, Info,
  ClipboardList, Users, History, Key, BarChart3, Camera
} from 'lucide-react';

export const Layout: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { user, logout, hasPermission } = useAuth();
  const { category, setCategory, isDarkMode, toggleDarkMode, triggerRefresh } = useDashboard();
  const location = useLocation();

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [showInput, setShowInput] = useState(false);
  const [showOffDays, setShowOffDays] = useState(false);
  const [showChangePass, setShowChangePass] = useState(false);
  const [showAvatarModal, setShowAvatarModal] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [entryToEdit, setEntryToEdit] = useState<ProductionEntry | null>(null);
  const [notification, setNotification] = useState<{ message: string; type: 'success' | 'info' } | null>(null);

  const timeoutRef = useRef<number | null>(null);

  const handleNotify = useCallback((e: any) => {
    if (timeoutRef.current) window.clearTimeout(timeoutRef.current);
    setNotification({ message: e.detail.message, type: e.detail.type || 'success' });
    timeoutRef.current = window.setTimeout(() => {
      setNotification(null);
      timeoutRef.current = null;
    }, 2000);
  }, []);

  const handleEditEntry = useCallback((e: any) => {
    setEntryToEdit(e.detail);
    setShowInput(true);
  }, []);

  const handleLogout = () => {
    logout();
    setIsMobileMenuOpen(false);
  };

  const handleSync = async (silent = false) => {
    if (!GoogleSheetsService.isEnabled()) return;
    if (!silent) setIsSyncing(true);
    try {
      await StorageService.syncWithSheets();
      triggerRefresh();
    } catch (e) {
      console.error(e);
    } finally {
      if (!silent) setIsSyncing(false);
    }
  };

  useEffect(() => {
    if (GoogleSheetsService.isEnabled()) handleSync(true);
  }, []);

  useEffect(() => {
    window.addEventListener('app-notification', handleNotify);
    window.addEventListener('edit-production-entry', handleEditEntry);
    return () => {
      window.removeEventListener('app-notification', handleNotify);
      window.removeEventListener('edit-production-entry', handleEditEntry);
      if (timeoutRef.current) window.clearTimeout(timeoutRef.current);
    };
  }, [handleNotify, handleEditEntry]);

  const navItemClass = (path: string) => `
    w-full flex items-center gap-4 px-6 py-4 rounded-2xl text-lg font-black transition-all uppercase tracking-tight
    ${location.pathname === path 
      ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/30' 
      : 'text-slate-500 hover:bg-gray-100 dark:hover:bg-slate-800'}
  `;

  return (
    <div className={`min-h-screen flex ${isDarkMode ? 'dark' : ''} bg-slate-50 dark:bg-slate-900 transition-colors duration-300 font-sans uppercase`}>
      {notification && (
        <div className="fixed top-20 right-8 z-[10000] pointer-events-none w-full max-w-sm px-4">
          <div className="notification-animate pointer-events-auto">
            <div className={`flex items-center gap-6 px-8 py-6 rounded-[2rem] shadow-2xl border-4 bg-white dark:bg-slate-800 ${
              notification.type === 'success' ? 'border-emerald-500' : 'border-indigo-500'
            }`}>
              <div className={`p-4 rounded-2xl ${notification.type === 'success' ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-100 text-indigo-600'}`}>
                {notification.type === 'success' ? <CheckCircle className="w-8 h-8" /> : <Info className="w-8 h-8" />}
              </div>
              <div className="flex-1">
                <p className={`text-xs font-black uppercase tracking-widest mb-1 ${notification.type === 'success' ? 'text-emerald-500' : 'text-indigo-500'}`}>Alert</p>
                <p className="text-xl font-black text-slate-900 dark:text-white leading-tight">{notification.message.toUpperCase()}</p>
              </div>
            </div>
          </div>
        </div>
      )}

      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-40 md:hidden" onClick={() => setIsMobileMenuOpen(false)} />
      )}

      <aside className={`fixed inset-y-0 left-0 w-80 bg-white dark:bg-slate-850 border-r-2 border-gray-200 dark:border-slate-700 z-50 transform transition-transform duration-300 md:translate-x-0 md:static md:block ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-10 border-b-2 border-gray-100 dark:border-slate-800 text-center">
             <div className="text-4xl font-black tracking-tighter text-slate-900 dark:text-white uppercase">
                HALA<span className="text-emerald-500">GEL</span>
             </div>
             <p className="text-xs font-black text-slate-400 uppercase tracking-[0.4em] mt-2">Production Pro</p>
        </div>

        <nav className="p-6 space-y-3 overflow-y-auto max-h-[calc(100vh-200px)] custom-scrollbar uppercase">
          <Link to="/" onClick={() => setIsMobileMenuOpen(false)} className={navItemClass('/')}>
            <LayoutDashboard className="w-6 h-6" /> Dashboard
          </Link>
          <Link to="/reports" onClick={() => setIsMobileMenuOpen(false)} className={navItemClass('/reports')}>
            <ClipboardList className="w-6 h-6" /> Reports
          </Link>
          <Link to="/process-analytics" onClick={() => setIsMobileMenuOpen(false)} className={navItemClass('/process-analytics')}>
            <BarChart3 className="w-6 h-6" /> Analytics
          </Link>

          <div className="pt-8 px-6 py-2 text-xs font-black text-slate-400 uppercase tracking-widest">Departments</div>
          {CATEGORIES.map(cat => (
            <button key={cat} onClick={() => { setCategory(cat as Category); setIsMobileMenuOpen(false); }}
              className={`w-full flex items-center justify-between px-6 py-4 rounded-xl text-lg font-black transition-all uppercase ${
                category === cat ? 'bg-indigo-50 dark:bg-slate-800 text-indigo-600 border-2 border-indigo-200' : 'text-slate-500 hover:bg-gray-50'
              }`}>
              {cat.toUpperCase()}
            </button>
          ))}

          {user && (
            <>
              <div className="pt-8 px-6 py-2 text-xs font-black text-slate-400 uppercase tracking-widest">Operations</div>
              <button onClick={() => { setShowInput(true); setIsMobileMenuOpen(false); }} className="w-full flex items-center gap-4 px-6 py-4 text-lg font-black text-emerald-600 hover:bg-emerald-50 rounded-xl transition-all uppercase">
                <Plus className="w-6 h-6" /> New Data
              </button>

              {hasPermission(['admin', 'manager', 'planner']) && (
                <button onClick={() => { setShowOffDays(true); setIsMobileMenuOpen(false); }} className="w-full flex items-center gap-4 px-6 py-4 text-lg font-black text-rose-600 hover:bg-rose-50 rounded-xl transition-all uppercase">
                  <CalendarX className="w-6 h-6" /> Holidays
                </button>
              )}

              {hasPermission(['admin']) && (
                <Link to="/users" onClick={() => setIsMobileMenuOpen(false)} className={navItemClass('/users')}>
                  <Users className="w-6 h-6" /> Staff
                </Link>
              )}

              <Link to="/logs" onClick={() => setIsMobileMenuOpen(false)} className={navItemClass('/logs')}>
                <History className="w-6 h-6" /> System Logs
              </Link>

              {/* Fix: replaced handleLogout prop with onClick */}
              <button onClick={handleLogout} className="w-full flex items-center gap-4 px-6 py-4 text-lg font-black text-rose-700 hover:bg-rose-100 rounded-xl transition-all uppercase mt-10">
                <LogOut className="w-6 h-6" /> Logout
              </button>
            </>
          )}
        </nav>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-20 bg-white dark:bg-slate-850 border-b-2 border-gray-200 dark:border-slate-700 flex items-center justify-between px-10 shrink-0 z-20">
          <div className="flex items-center gap-8">
            <button onClick={() => setIsMobileMenuOpen(true)} className="md:hidden p-3 hover:bg-gray-100 rounded-xl">
              <Menu className="w-8 h-8" />
            </button>
            <div className="flex items-center gap-6">
              <h2 className="font-black text-3xl hidden md:block text-slate-900 dark:text-white tracking-tight">{location.pathname.replace('/', '').toUpperCase() || 'Dashboard'}</h2>
              <div className="flex items-center gap-3 px-4 py-2 rounded-full text-sm font-black uppercase bg-emerald-100 text-emerald-700 border-2 border-emerald-200">
                <Database className="w-5 h-5" /> Cloud Active
              </div>
            </div>
          </div>

          <div className="flex items-center gap-6">
            <button onClick={() => handleSync()} disabled={isSyncing} className={`p-3 text-slate-500 hover:bg-gray-100 rounded-xl transition-all ${isSyncing ? 'animate-spin text-indigo-600' : ''}`}>
              <RefreshCw className="w-6 h-6" />
            </button>
            <button onClick={toggleDarkMode} className="p-3 text-slate-500 hover:bg-gray-100 rounded-xl transition-all">
              {isDarkMode ? <Sun className="w-6 h-6" /> : <Moon className="w-6 h-6" />}
            </button>
            {user ? (
              <div onClick={() => setShowAvatarModal(true)} className="flex items-center gap-4 px-5 py-2 bg-gray-50 dark:bg-slate-800 rounded-2xl border-2 border-gray-100 dark:border-slate-700 cursor-pointer hover:bg-gray-100 transition-all shadow-sm">
                 <div className="w-10 h-10 rounded-full bg-indigo-600 flex items-center justify-center text-white overflow-hidden shadow-inner border-2 border-white">
                    {user.avatar ? <img src={user.avatar} className="w-full h-full object-cover" /> : <span className="text-lg font-black">{user.name.charAt(0)}</span>}
                 </div>
                 <div className="hidden lg:block text-left uppercase">
                    <p className="text-[10px] font-black text-indigo-600 leading-none mb-1 tracking-widest">{user.role}</p>
                    <p className="text-lg font-black text-slate-900 dark:text-white tracking-tight">{user.name}</p>
                 </div>
              </div>
            ) : (
              <button onClick={() => setShowLogin(true)} className="flex items-center gap-3 px-8 py-3 bg-slate-900 dark:bg-indigo-600 text-white text-lg font-black rounded-xl hover:bg-slate-800 transition shadow-lg uppercase tracking-widest">
                <LogIn className="w-6 h-6" /> Login
              </button>
            )}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-10 md:p-16 custom-scrollbar">
          {children}
        </div>
      </main>

      {showLogin && <LoginModal onClose={() => setShowLogin(false)} />}
      {showInput && <InputModal onClose={() => { setShowInput(false); setEntryToEdit(null); }} editEntry={entryToEdit} />}
      {showOffDays && <OffDayModal onClose={() => setShowOffDays(false)} />}
      {showChangePass && <ChangePasswordModal onClose={() => setShowChangePass(false)} />}
      {showAvatarModal && <AvatarModal onClose={() => setShowAvatarModal(false)} />}
    </div>
  );
};
